window.ACERVO_RAW_DATA = {"project":"Datas e Fatos para a História do Ceará","repository":"https://github.com/walterfr/DatasFatosCE","totalEntries":901,"totalYears":12,"totalMonths":144,"categoryTotals":{"Infraestrutura, Saúde e Sociedade":282,"Necrologia":185,"Política e Instituições":475,"Cultura, Educação e Religião":258,"Legislação e Toponímia":237,"Esportes":100},"years":[{"year":2014,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2014.md","pageUrl":"../2014/","entryCount":75},{"year":2015,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2015.md","pageUrl":"../2015/","entryCount":56},{"year":2016,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2016.md","pageUrl":"../2016/","entryCount":75},{"year":2017,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2017.md","pageUrl":"../2017/","entryCount":97},{"year":2018,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2018.md","pageUrl":"../2018/","entryCount":82},{"year":2019,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2019.md","pageUrl":"../2019/","entryCount":97},{"year":2020,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2020.md","pageUrl":"../2020/","entryCount":57},{"year":2021,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2021.md","pageUrl":"../2021/","entryCount":85},{"year":2022,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2022.md","pageUrl":"../2022/","entryCount":61},{"year":2023,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2023.md","pageUrl":"../2023/","entryCount":71},{"year":2024,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2024.md","pageUrl":"../2024/","entryCount":60},{"year":2025,"githubMdUrl":"https://github.com/walterfr/DatasFatosCE/blob/main/docs/2025.md","pageUrl":"../2025/","entryCount":85}],"entries":[{"id":"ce-2014-01-0001","y":2014,"m":1,"d":"01","h":"Começa a vigorar em todo o país o novo valor do Salário Mínimo nacional (fixado em R$ 724,00 pelo Decreto Federal nº 8.166), gerando reflexos imediatos nas tabelas de remuneração pública estadual, nas convenções do comércio e nas faixas previdenciárias do Ceará.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-01-0002","y":2014,"m":1,"d":"01","h":"Falece tragicamente em Fortaleza, na madrugada de Ano Novo, o advogado Emídio César Viana de Carvalho, conselheiro da Ordem dos Advogados do Brasil - Secção Ceará (OAB-CE). A Associação Cearense de Magistrados (ACM) e a OAB-CE manifestam pesar oficial pela perda do jurista e operador do Direito.","c":["Necrologia"],"l":0},{"id":"ce-2014-01-0003","y":2014,"m":1,"d":"08","h":"Em Sobral, o prefeito José Clodoveu de Arruda Coelho Neto (Veveu Arruda) inaugura o novo Posto de Policiamento Destacado / Grupamento da Polícia Militar no distrito de Taperuaba e formaliza com a Secretaria de Desenvolvimento Social o plano de ampliação de vagas dos cursos profissionalizantes do PRONATEC no município.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-01-0004","y":2014,"m":1,"d":"09","h":"Realizada no município de Itapajé a solenidade de cessão formal de posse do terreno e complexo cultural \"Jardins de Anita\" à Universidade Federal do Ceará (UFC). O imóvel de 80 hectares, arborizado com milhares de mudas, fora idealizado pelo empresário José Maria de Sousa Melo em memória de sua esposa, a letona Anita Inára Bertulis de Melo, sendo doado pela família para abrigar as futuras instalações do Campus da UFC em Itapajé.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-01-0005","y":2014,"m":1,"d":"11","h":"É oficialmente desativada para o transporte regular de passageiros a centenária Estação Ferroviária Professor João Felipe (antiga Estação Central de Fortaleza), após 141 anos ininterruptos de serviços ferroviários prestados ao povo cearense desde a fundação da Estrada de Ferro de Baturité em 1873. O ponto final da Linha Oeste é transferido provisoriamente para a estação Moura Brasil e as operações de integração são absorvidas pela Estação Central–Chico da Silva (Linha Sul), liberando o sítio histórico para os canteiros da futura Linha Leste e posterior restauro para sediar o Complexo Cultural Estação das Artes.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-01-0006","y":2014,"m":1,"d":"14","h":"O Prefeito Municipal de Fortaleza, médico Roberto Cláudio Rodrigues Bezerra (Roberto Cláudio), assina o Decreto Municipal nº 13.286, publicado no Diário Oficial do Município (DOM), que dispõe sobre a criação, delimitação e regulamentação dos Parques Urbanos das Lagoas de Fortaleza, marco urbanístico e ambiental voltado à preservação das microbacias hidrográficas e dos recursos hídricos da capital.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-01-0007","y":2014,"m":1,"d":"16","h":"Aposenta-se, por ato publicado no Diário da Justiça, o desembargador Francisco Auricélio Pontes, integrante da 1ª Câmara Cível do Tribunal de Justiça do Estado do Ceará (TJCE), após extensa folha de serviços prestados à magistratura cearense, abrindo vaga no colegiado a ser provida pelo critério de merecimento.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-01-0008","y":2014,"m":1,"d":"17","h":"Inaugurada no município do Crato, na Região Metropolitana do Cariri, pelo Governador do Estado, Cid Ferreira Gomes (Cid Gomes), a centésima unidade da rede de Escolas Estaduais de Educação Profissional (EEEP) do Ceará, marco representativo da interiorização do ensino técnico em tempo integral.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-01-0009","y":2014,"m":1,"d":"23","h":"Em sessão solene realizada no Palácio Jeremias Arruda, na Rua Barão do Rio Branco nº 1594 (Praça do Carmo), toma posse como sócio efetivo do Instituto do Ceará (Histórico, Geográfico e Antropológico) o médico epidemiologista, economista, professor titular da Universidade Estadual do Ceará (UECE) e escritor Marcelo Gurgel Carlos da Silva.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-01-0010","y":2014,"m":1,"d":"28","h":"Portaria da Corregedoria-Geral de Presídios da Comarca de Fortaleza, chancelada em conjunto com vistorias da Comissão de Direito Penitenciário da OAB-CE, sugere a implantação de Centro de Triagem no Complexo Prisional de Itaitinga e reitera a interdição das instalações físicas precárias da Casa de Privação Provisória de Liberdade Professor Luciano Andrade Lima (CPPL I) e da CPPL de Caucaia.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-01-0011","y":2014,"m":1,"d":"28","h":"Falece no distrito de Bitupitá, município de Barroquinha, no extremo Norte cearense, o líder comunitário e desportista Pedro Laurindo Veras, casado com Maria Fortuna de Sousa Veras, deixando filhos e expressiva atuação no desenvolvimento daquela comunidade pesqueira.","c":["Necrologia"],"l":0},{"id":"ce-2014-01-0012","y":2014,"m":1,"d":"31","h":"Têm início os trabalhos de engenharia subterrânea para a implantação da Linha Leste do Metrô de Fortaleza (Metrofor), com a abertura de poço de ataque e início das estruturas de contenção ao lado da Estação Central para a montagem das tuneladoras (\"tatuzões\") fabricadas pela norte-americana The Robbins Company.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-02-0013","y":2014,"m":2,"d":"10","h":"O Prefeito Roberto Cláudio baixa o Decreto Municipal nº 13.297, veiculado no Diário Oficial do Município (DOM), aperfeiçoando as normas de execução e controle financeiro dos fundos especiais vinculados aos órgãos e entidades da Administração Municipal de Fortaleza.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-02-0014","y":2014,"m":2,"d":"07","h":"A ex-deputada estadual Tânia Gurgel assume a presidência da Fundação da Criança e da Família Cidadã (Funci), órgão da administração indireta da Prefeitura Municipal de Fortaleza encarregado da coordenação e execução das políticas públicas voltadas aos direitos da infância e da juventude na capital.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-02-0015","y":2014,"m":2,"d":"09","h":"Falece na madrugada, em Fortaleza, aos 86 anos de idade, o médico e professor universitário Guilardo Martins Alves (Guilardo Alves). Formado em Medicina pela Faculdade de Medicina da Bahia, foi presidente da Fundação Oswaldo Cruz (Fiocruz) entre 1979 e 1985, período de expressiva modernização e renascimento institucional da entidade na transição para a Nova República. Foi ainda reitor da Universidade Federal da Paraíba (UFPB) em dois mandatos (1964 e 1967–1971), fundador da Faculdade de Medicina daquela universidade, pioneiro na instalação do seu complexo hospitalar universitário e presidente do Conselho de Reitores das Universidades Brasileiras (CRUB). O sepultamento realiza-se em Fortaleza. Nascera no dia 16/06/1927.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-02-0016","y":2014,"m":2,"d":"11","h":"Realiza-se no Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará (ALCE), sob a presidência do deputado José Albuquerque, a sessão solene de abertura dos trabalhos legislativos de 2014, com a apresentação e leitura da mensagem governamental encaminhada pelo chefe do Poder Executivo, governador Cid Ferreira Gomes.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-02-0017","y":2014,"m":2,"d":"14","h":"A Secretaria Municipal de Educação do Crato formaliza no Diário Oficial a Portaria nº 01701001/2014, regulamentando a delegação e o plano de trabalho de docentes da rede cratense para capacitação no Programa Nacional do Livro Didático (PNLD) e na Educação de Jovens e Adultos (EJA).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-02-0018","y":2014,"m":2,"d":"19","h":"A Junta Comercial do Estado do Ceará (Jucec) deflagra em Fortaleza e nos escritórios regionais do Interior o plano operacional de capacitação e suporte para a Rede Nacional para a Simplificação do Registro e da Legalização de Empresas e Negócios (Redesim), modernizando o ambiente de registro mercantil do Estado.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-02-0019","y":2014,"m":2,"d":"19","h":"Aposenta-se, por limite constitucional de idade, o desembargador Francisco José Martins Câmara, após destacada trajetória na magistratura do Estado do Ceará, abrindo vacância no pleno do Tribunal de Justiça do Estado do Ceará (TJCE) a ser provida pelo critério de antiguidade. Nascera em 19/02/1944.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-02-0020","y":2014,"m":2,"d":"21","h":"A Prefeitura Municipal de Fortaleza entrega oficialmente à população o Centro Urbano de Cultura, Arte, Ciência e Esporte (CUCA Jangurussu), situado na confluência da Avenida Castelo de Castro com a Avenida Contorno Sul, no bairro Jangurussu (Regional VI). O complexo sociocultural conta com ginásio poliesportivo coberto, cineteatro com 300 lugares, parque aquático com piscinas olímpica e semiolímpica e ateliês de formação técnica em comunicação audiovisual e artes, consolidando a rede de assistência integral à juventude na periferia de Fortaleza.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-02-0021","y":2014,"m":2,"d":"25","h":"Inaugurado, às 10 horas, na Praia do Iguape, município de Aquiraz, pelo governador Cid Ferreira Gomes (Cid Gomes), o novo Centro das Rendeiras Miriam Porto Mota. Com linhas arquitetônicas inspiradas nos contornos de embarcações pesqueiras tradicionais, projeto assinado pelo arquiteto cearense Antenor Coelho, o complexo artesanal conta com mirante, cafeteria e boxes de comercialização, idealizado pela Secretaria do Trabalho e Desenvolvimento Social (STDS) para valorizar as artesãs e preservar a tradição secular da renda de bilro no litoral leste.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-02-0022","y":2014,"m":2,"d":"27","h":"Sancionada pelo prefeito de Fortaleza, Roberto Cláudio Rodrigues Bezerra (Roberto Cláudio), a Lei Municipal nº 10.158, oriunda de aprovação pelo plenário da Câmara Municipal de Fortaleza, que concede reajuste remuneratório linear aos profissionais do magistério do Município de Fortaleza, assegurando o cumprimento integral do Piso Salarial Profissional Nacional da Educação Básica.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2014-02-0023","y":2014,"m":2,"d":"28","h":"Encerra-se o mandato da 18ª Diretoria da Academia Cearense da Língua Portuguesa (ACLP), que funcionava no Palácio da Luz sob a presidência do professor Antônio Vicente de Alencar, abrindo processo solene de transição para a gestão do biênio subsequente.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-03-0024","y":2014,"m":3,"d":"06","h":"Morre, aos 62 anos de idade, vítima de acidente automobilístico na rodovia PI-114 (na ponte dos Canutos, entre Campo Maior e Cabeceiras do Piauí), o pecuarista e líder político Vicente Mourão Carlos (Vicente Mourão), ex-prefeito dos municípios de Ararendá e Nova Russas. O caminhão de sua propriedade que transportava gado capotou, deixando-o preso às ferragens. O prefeito de Ararendá, Aristeu Alves, decreta luto oficial de três dias e feriado municipal. Nascera em Nova Russas a 14/09/1951.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-03-0025","y":2014,"m":3,"d":"11","h":"Sancionada pelo governador Cid Ferreira Gomes a Lei Estadual nº 15.549, originária de projeto aprovado pela Assembleia Legislativa do Estado do Ceará, que confere denominação toponímica e título honorífico ao município de Juazeiro do Norte como a Capital Cearense das Romarias, oficializando o reconhecimento estadual das peregrinações religiosas e da devoção ao Padre Cícero Romão Batista.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2014-03-0026","y":2014,"m":3,"d":"17","h":"É assassinado na madrugada, aos 33 anos de idade, durante latrocínio na Avenida Washington Soares, em Fortaleza, o delegado de Polícia Civil Lucas Craveiro Alves (Delegado Lucas Craveiro). Nascido em Fortaleza a 12/01/1981, era bacharel em Direito e titular da Delegacia Regional de Esperantina (PI), encontrando-se de férias na capital cearense. Seu corpo foi velado no Complexo Funerário Ternura e sepultado no Cemitério Parque da Paz.","c":["Necrologia"],"l":0},{"id":"ce-2014-03-0027","y":2014,"m":3,"d":"19","h":"No dia consagrado ao padroeiro São José, a presidenta da República Dilma Rousseff e o governador Cid Gomes inauguram em solenidade oficial o Trecho V do Eixão das Águas, canal adutor que assegura a segurança hídrica e a vazão de abastecimento para a Região Metropolitana de Fortaleza e o Complexo Industrial e Portuário do Pecém.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-03-0028","y":2014,"m":3,"d":"21","h":"Falece na madrugada, aos 58 anos de idade, no Hospital Regional da Unimed em Fortaleza, vítima de infarto agudo do miocárdio, a delegada de Polícia Civil Maria Eliane Barbosa (Dra. Eliane Barbosa). Bacharela em Direito com 31 anos de carreira policial, exercia a titularidade do 5º Distrito Policial (Parangaba) e a coordenação seccional da Área Integrada de Segurança 5 (AIS-5). Nascera em 1955. Foi velada na Funerária Ethernus e sepultada às 16h30 no Cemitério São João Batista.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-03-0029","y":2014,"m":3,"d":"25","h":"Comemora-se a Data Magna do Ceará, marcando os 130 anos da abolição da escravidão na província cearense (25 de março de 1884). Em cerimônia no Palácio da Abolição, o governador Cid Gomes outorga a Medalha da Abolição de 2014 ao chanceler da Universidade de Fortaleza (Unifor) e empresário Airton José Vidal Queiroz; ao escultor e gravador cratense Sérvulo Esmeraldo; e, in memoriam, ao jornalista Demócrito Dummar (ex-presidente do Grupo O Povo, falecido em 2008), cuja comenda foi entregue à sua filha Luciana Dummar.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-04-0030","y":2014,"m":4,"d":"05","h":"Morre no Rio de Janeiro, RJ, aos 69 anos de idade, o consagrado ator, diretor, crítico e teatrólogo cearense José Wilker de Almeida (José Wilker), vítima de infarto fulminante em sua residência em Ipanema. Nascera em Juazeiro do Norte, CE, a 20/08/1944. Notabilizou-se no cinema nacional com filmes como Dona Flor e Seus Dois Maridos e Bye Bye Brasil, e na teledramaturgia em telenovelas marcantes como Roque Santeiro e Senhora do Destino. Foi velado no Teatro Ipanema e cremado no Cemitério e Memorial do Carmo, no Caju (RJ).","c":["Necrologia"],"l":0},{"id":"ce-2014-04-0031","y":2014,"m":4,"d":"07","h":"São publicadas no Diário Oficial do Estado (DOE) as Leis Estaduais nº 15.569/2014, 15.570/2014 e 15.571/2014, que reestruturam as carreiras docentes do magistério superior das três universidades estaduais cearenses (UECE, UVA e URCA), disciplinando o afastamento para pós-graduação stricto sensu, regimes de trabalho e a Gratificação de Dedicação Exclusiva (GDE).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-04-0032","y":2014,"m":4,"d":"09","h":"Realiza-se na Arena Castelão a partida final da Copa do Nordeste de 2014, com empate em 1 a 1 entre o Ceará Sporting Club e o Sport Club do Recife (gols de Magno Alves para o Ceará e Neto Baiano para os visitantes) perante 61.280 torcedores, sagrando-se o clube pernambucano campeão regional pela vantagem do placar agregado.","c":["Esportes"],"l":0},{"id":"ce-2014-04-0033","y":2014,"m":4,"d":"13","h":"Fortaleza celebra 288 anos de sua elevação a vila e emancipação política (fundação em 13 de abril de 1726). As comemorações contam com a realização da 12ª Meia Maratona Internacional de Fortaleza na Avenida Beira-Mar, reunindo mais de oito mil atletas locais, nacionais e estrangeiros.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-04-0034","y":2014,"m":4,"d":"23","h":"Ceará Sporting Club empata em 0 a 0 com o Fortaleza Esporte Clube no Estádio Governador Plácido Castelo (Arena Castelão) e conquista o tetracampeonato do Campeonato Cearense de Futebol de 2014 pela vantagem de pontos na fase decisiva, sob comando do técnico Sérgio Soares.","c":["Esportes","Política e Instituições"],"l":0},{"id":"ce-2014-05-0035","y":2014,"m":5,"d":"09","h":"O Pleno do Tribunal de Justiça do Estado do Ceará (TJCE), reunido em sessão pública com votação aberta e fundamentada, escolhe os juízes de Direito José Tarcílio Souza da Silva (por merecimento, na vaga decorrente da aposentadoria do desembargador Francisco Auricélio Pontes ocorrida em 16/01/2014) e Tereze Neumann Duarte Chaves (por aclamação e antiguidade, na vaga da aposentadoria do desembargador Francisco José Martins Câmara, ocorrida em 19/02/2014) para os cargos de desembargadores do Poder Judiciário cearense.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-05-0036","y":2014,"m":5,"d":"16","h":"Sancionada a Lei Estadual nº 15.603 (publicada no Diário Oficial de 16/06/2014), que denomina de Antônio Clemente de Araújo o trecho da rodovia estadual CE-253 que liga a sede do município de Cariré ao distrito de Cacimbas, na Região Norte do Estado.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-05-0037","y":2014,"m":5,"d":"20","h":"Morre assassinado em Fortaleza, aos 35 anos de idade, o sargento da Polícia Militar do Ceará Paulo Henrique de Farias Nobre (Sargento Paulo Nobre), alvejado em assalto no Conjunto Ceará quando transitava com sua família. Nascido em Fortaleza a 15/06/1978, integrava o policiamento ostensivo da capital.","c":["Necrologia"],"l":0},{"id":"ce-2014-05-0038","y":2014,"m":5,"d":"29","h":"Tomam posse solene como novos desembargadores do Tribunal de Justiça do Estado do Ceará (TJCE), no Palácio da Justiça Desembargador Agenor Studart, os magistrados José Tarcílio Souza da Silva e Tereze Neumann Duarte Chaves. A cerimônia foi conduzida pelo vice-presidente da Corte, desembargador Francisco Lincoln Araújo e Silva, com oração oficial de saudação pelo desembargador Mário Parente Teófilo Neto.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-06-0039","y":2014,"m":6,"d":"06","h":"A Prefeitura Municipal de Fortaleza entrega o conjunto de intervenções de mobilidade urbana para a Copa do Mundo no entorno da Arena Castelão: a duplicação viária da Avenida Alberto Craveiro, a requalificação da Avenida Paulino Rocha e o túnel de ligação viária e rotatória de tráfego em frente à praça esportiva.","c":["Esportes"],"l":0},{"id":"ce-2014-06-0040","y":2014,"m":6,"d":"12","h":"O Governo do Estado promulga duas leis de toponímia rodoviária estadual: a Lei nº 15.623, denominando João Rolim de Moura (Joca Bonifácio) a rodovia CE-151 entre Umari e Baixio; e a Lei nº 15.626, denominando Professor Itamar Filgueiras a rodovia CE-451 entre a sede de Guaiúba e o distrito de Itacima.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-06-0041","y":2014,"m":6,"d":"14","h":"Estreia da Arena Castelão na Copa do Mundo da FIFA Brasil 2014 (Grupo D): a Seleção da Costa Rica derrota a Seleção do Uruguai por 3 a 1 (gols de Cavani de pênalti para o Uruguai; Campbell, Duarte e Ureña para os costa-riquenhos), diante de 58.679 torcedores.","c":["Esportes"],"l":0},{"id":"ce-2014-06-0042","y":2014,"m":6,"d":"16","h":"Inaugurado oficialmente e entra em operação o Terminal Marítimo de Passageiros do Porto do Mucuripe, em Fortaleza, recebendo a atracação do navio transatlântico de passageiros MSC Divina com cerca de quatro mil turistas estrangeiros que desembarcam para assistir aos jogos do Mundial.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-06-0043","y":2014,"m":6,"d":"17","h":"Pela segunda rodada do Grupo A da Copa do Mundo na Arena Castelão, a Seleção Brasileira empata em 0 a 0 com a Seleção do México perante 60.342 espectadores, marcada pela histórica atuação do goleiro mexicano Guillermo Ochoa.","c":["Esportes"],"l":0},{"id":"ce-2014-06-0044","y":2014,"m":6,"d":"20","h":"Sancionada a Lei Estadual nº 15.634, que denomina José Pedro da Silveira (Juca Silveira) o trecho da rodovia estadual CE-323 interligando o município de Carnaubal à divisa territorial com o Estado do Piauí.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-06-0045","y":2014,"m":6,"d":"23","h":"Na rodada decisiva do Grupo C da Copa do Mundo, a Seleção da Grécia vence a Seleção da Costa do Marfim por 2 a 1 na Arena Castelão, com gol de Samaras aos 90+3', assegurando a classificação dos gregos às oitavas de final pela primeira vez na história dos Mundiais perante 59.095 torcedores.","c":["Esportes"],"l":0},{"id":"ce-2014-06-0046","y":2014,"m":6,"d":"29","h":"Pelas oitavas de final da Copa do Mundo na Arena Castelão, a Seleção da Holanda derrota a Seleção do México de virada por 2 a 1 perante 58.859 pagantes, jogo que registrou a primeira parada oficial para hidratação (cooling break) autorizada pela FIFA na história das Copas do Mundo em decorência da alta temperatura em Fortaleza.","c":["Esportes"],"l":0},{"id":"ce-2014-06-0047","y":2014,"m":6,"d":"29","h":"Falece pela manhã no Hospital Monte Klinikum em Fortaleza, aos 82 anos de idade, vítima de insuficiência respiratória e complicações pulmonares, o sacerdote católico Manoel de Castro Ferreira (Padre Ferreirinha). Nascido em Petrolina, PE, em 23/05/1932, ordenou-se sacerdote a 04/02/1968. No Ceará, lecionou no Colégio Salesiano em Juazeiro do Norte (1968–1969), foi vigário na Piedade e exerceu o pastoreio como pároco de Nossa Senhora do Patrocínio (no Centro de Fortaleza) e capelão de Santa Edwiges (na Avenida Leste-Oeste) por quatro décadas, notabilizando-se pelo apostolado aos pobres. Agraciado com o título de Cidadão de Fortaleza em 1979, foi velado na Capela de Santa Edwiges e cremado no Cemitério e Crematório Jardim Metropolitano (em Eusébio), repousando suas cinzas na Igreja do Patrocínio e na Paróquia de Santa Edwiges.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-07-0048","y":2014,"m":7,"d":"04","h":"Na Arena Castelão, em Fortaleza, a Seleção Brasileira vence a Seleção da Colômbia por 2 a 1 perante 60.342 espectadores, em confronto válido pelas quartas de final da Copa do Mundo FIFA de 2014, com gols assinalados pelos zagueiros Thiago Silva e David Luiz (descontando James Rodríguez de pênalti para os colombianos). Aos 41 minutos da etapa final, choque violento do lateral colombiano Camilo Zúñiga atinge as costas de Neymar Jr., fraturando a terceira vértebra lombar (L3) do atacante brasileiro e afastando-o da fase final do torneio.","c":["Esportes"],"l":0},{"id":"ce-2014-07-0049","y":2014,"m":7,"d":"05","h":"Encerra-se no Tribunal Regional Eleitoral do Ceará (TRE-CE) o prazo para protocolo do registro de candidaturas às Eleições Gerais de 2014, formalizando as chapas concorrentes ao Palácio da Abolição encabeçadas por Camilo Sobreira de Santana (PT), tendo como vice Maria Izolda Cela de Arruda Coelho (PROS); Eunício Lopes de Oliveira (PMDB), com Roberto Pessoa (PR); Eliane Novais (PSB); e Ailton Lopes (PSOL); além das postulações ao Senado de Tasso Ribeiro Jereissati (PSDB), Mauro Benevides Filho (PROS) e Geovana Cartaxo (PSB).","c":["Política e Instituições"],"l":0},{"id":"ce-2014-07-0050","y":2014,"m":7,"d":"07","h":"Aposenta-se no Tribunal de Justiça do Estado do Ceará (TJCE) o desembargador Francisco Suenon Bastos Mota, abrindo nova vacância no colegiado da corte cearense.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-07-0051","y":2014,"m":7,"d":"14 a 16","h":"Reúnem-se em Fortaleza, no Centro de Eventos do Ceará, os chefes de Estado e de Governo das principais economias emergentes para a VI Cúpula do BRICS, sob o lema \"Crescimento Inclusivo: Soluções Sustentáveis\". No dia 15 de julho, a Presidenta da República Federativa do Brasil, Dilma Rousseff, o Presidente da Federação Russa, Vladimir Putin, o Primeiro-Ministro da Índia, Narendra Modi, o Presidente da República Popular da China, Xi Jinping, e o Presidente da África do Sul, Jacob Zuma, assinam a Declaração de Fortaleza, criando formalmente o Novo Banco de Desenvolvimento (NBD) e instituindo o Arranjo Contingente de Reservas (ACR).","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-07-0052","y":2014,"m":7,"d":"18","h":"Falece em Fortaleza, aos 86 anos de idade, a historiadora, antropóloga, folclorista e professora Valdelice Carneiro Girão. Nascera em Morada Nova, CE, a 28/11/1927, filha do historiador Raimundo Girão e de Maria Carneiro Girão. Graduada em Geografia e História pela Faculdade de Filosofia e pela UECE, com pós-graduação na UFPE, devotou sua vida à etnografia das tradições populares do Ceará. Conservadora do Museu Artur Ramos e do Museu Histórico e Antropológico do Ceará, integrou como sócia efetiva o Instituto do Ceará (Histórico, Geográfico e Antropológico) e a Sociedade Cearense de Geografia e História. Deixou estudos referenciais como A Renda de Bilros e seus Artífices (1966), Cerâmica Indígena do Ceará (1972) e As Oficinas ou Charqueadas no Ceará (1984).","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-07-0053","y":2014,"m":7,"d":"18","h":"Falece em Fortaleza, aos 67 anos de idade, no Hospital São José, vítima de choque séptico, o publicitário Francisco Theophilo (Xyco Theophilo). Nascido em Fortaleza em 1947, foi pioneiro do mercado de agências de propaganda do Estado à frente da agência Terraço e um dos pioneiros da militância pelos direitos e inclusão das pessoas com deficiência física no Ceará, fundando a Associação dos Deficientes Motores do Ceará (ADM-CE). Foi velado no Complexo Funerário Ternura e sepultado no Cemitério Parque da Paz.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-07-0054","y":2014,"m":7,"d":"27","h":"Falece em Fortaleza o sacerdote católico Padre Hemetério Alixandre de Santiago, reitor da histórica Igreja de Nossa Senhora da Conceição do Seminário da Prainha, tradicional templo setecentista da capital e marco de formação de gerações de eclesiásticos cearenses. As exéquias solenes foram concelebradas na Igreja da Prainha pelo clero da Arquidiocese de Fortaleza.","c":["Necrologia","Política e Instituições"],"l":0},{"id":"ce-2014-08-0055","y":2014,"m":8,"d":"13","h":"Ocorre em Santos, SP, o desastre aéreo com o jato executivo Cessna Citation que vitima, aos 49 anos de idade, o economista e ex-governador de Pernambuco Eduardo Henrique Accioly Campos (Eduardo Campos), candidato à Presidência da República pela coligação \"Unidos pelo Brasil\" (PSB/Rede/PPS/PPL/PHS/PRP), juntamente com outros seis passageiros e tripulantes. Nascera no Recife a 10/08/1965, neto de Miguel Arraes. Diante dos vínculos históricos do líder com o Ceará, o Governador Cid Ferreira Gomes e o Prefeito de Fortaleza Roberto Cláudio decretam luto oficial de três dias no Estado e no Município, suspendendo temporariamente os atos de campanha eleitoral de Camilo Santana (PT) e Eunício Oliveira (PMDB).","c":["Política e Instituições"],"l":0},{"id":"ce-2014-08-0056","y":2014,"m":8,"d":"19","h":"Inicia-se em todas as emissoras de rádio e televisão do Ceará a veiculação em cadeia do Horário Gratuito de Propaganda Eleitoral (HGPE) relativo às eleições gerais, intensificando a mobilização na capital e nos polos regionais do Cariri, Sobral e Sertão Central.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-08-0057","y":2014,"m":8,"d":"26","h":"Sancionada a Lei Estadual nº 15.678 (publicada no DOE de 04/09/2014), disciplinando normas procedimentais da administração pública do Estado do Ceará.","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2014-08-0058","y":2014,"m":8,"d":"29","h":"No polo regional de Sobral, a Companhia Cearense de Transportes Metropolitanos (Metrofor) avança na operação assistida experimental dos ramais Norte e Sul do Veículo Leve sobre Trilhos (VLT de Sobral), ligando estações nos bairros Cohab II, Sumaré e Campo dos Velhos.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-09-0059","y":2014,"m":9,"d":"06","h":"Concentram-se na Arena Castelão mais de 60 mil fiéis para o culto solene de comemoração do Centenário da Assembleia de Deus no Estado do Ceará, fundada em solo cearense no ano de 1914, acolhendo caravanas de dezenas de municípios do interior.","c":["Esportes"],"l":0},{"id":"ce-2014-09-0060","y":2014,"m":9,"d":"08 a 15","h":"Reúnem-se em Juazeiro do Norte cerca de 300 mil peregrinos na Romaria de Nossa Senhora das Dores, padroeira do município, com celebrações na Basílica Menor e concentração de romeiros junto à estátua do Padre Cícero na Colina do Horto.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-09-0061","y":2014,"m":9,"d":"09","h":"A Assembleia Legislativa do Estado do Ceará aprova projeto que confere a denominação toponímica de Juracy Girão à rodovia estadual CE-354, no trecho entre a localidade de Bu (CE-065) e Amanari (CE-455), no Município de Maranguape.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-09-0062","y":2014,"m":9,"d":"21","h":"Falece em Fortaleza, aos 91 anos de idade, no Hospital Unimed, vítima de falência múltipla de órgãos decorrente de complicações cardiopulmonares, o escritor, poeta, jurista e ensaísta Artur Eduardo Benevides. Nascera em Pacatuba, CE, a 25/07/1923, filho de Artur Benevides e Maria de Queiroz Benevides. Bacharel pela Faculdade de Direito do Ceará e graduado em Letras Neolatinas, foi Professor Titular da Universidade Federal do Ceará (UFC). Eleito em 1985 \"Príncipe dos Poetas Cearenses\", integrou o histórico Grupo Clã e ocupou a cadeira nº 39 da Academia Cearense de Letras (ACL), sodalício que presidiu por dez anos (1995–2005). Autor de mais de 40 títulos publicados, destacou-se com obras como A Missão do Escritor e a Crise do Espírito (1973) e Oráculo de Delfos (1981). Seu corpo foi velado no Palácio da Luz (sede da ACL) e sepultado no Cemitério Parque da Paz.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-09-0063","y":2014,"m":9,"d":"26","h":"O Theatro José de Alencar sedia a 44ª entrega do Troféu Sereia de Ouro, láurea do Grupo Edson Queiroz. Foram homenageados: o industrial Roberto Proença de Macêdo (ex-presidente da FIEC e do Grupo J. Macêdo), o jurista e tributarista Hugo de Brito Machado (professor emérito da UFC), a desembargadora do trabalho Glaura Férrer Dias Martins e o médico veterinário e líder agropecuário José Ramos Torres de Melo Filho (presidente da FAEC).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-10-0064","y":2014,"m":10,"d":"02","h":"Falece em Fortaleza, aos 95 anos de idade, em sua residência no sítio do bairro Mondubim, o desenhista, pintor, historiador e crítico de arte Nivaldo de Lima Ribeiro (Estrigas). Nascera em Fortaleza a 24/09/1919, filho de Antônio Ribeiro e Maria de Lima Ribeiro. Cirurgião-dentista formado em 1946 pela Faculdade de Odontologia do Ceará, abandonou a profissão para consagrar-se às artes plásticas. Presidiu a Sociedade Cearense de Artes Plásticas (SCAP) em 1953, consolidou o Salão de Abril e fundou em 1969 o Minimuseu Firmeza com sua esposa, a pintora Nice Firmeza. Deixou vasta bibliografia sobre a arte cearense, incluindo Fase Renovadora na Arte Cearense (1983) e A Saga do Pintor Chico da Silva (1988). Foi sepultado no Cemitério Parque da Paz.","c":["Necrologia"],"l":0},{"id":"ce-2014-10-0065","y":2014,"m":10,"d":"05","h":"Realiza-se o primeiro turno das Eleições Gerais no Ceará: Para o Governo do Estado, disputam o segundo turno Eunício Lopes de Oliveira (PMDB), com 2.151.666 votos (46,41%), e Camilo Sobreira de Santana (PT), com 2.039.612 votos (44,01%). Eliane Novais (PSB) obtém 226.477 votos (4,89%) e Ailton Lopes (PSOL) registra 103.581 votos (2,24%). Para o Senado Federal, é eleito o ex-governador Tasso Ribeiro Jereissati (PSDB) com 2.314.097 votos (58,14%), superando Mauro Benevides Filho (PROS), que soma 1.556.521 votos (39,08%). Geovana Cartaxo (PSB) alcança 104.441 votos (2,62%). Para a Câmara dos Deputados, são eleitos 22 deputados federais, liderados por Moroni Torgan (DEM, 277.774 votos), Genecias Noronha (SD, 221.567 votos) e José Guimarães (PT, 209.032 votos). Para a Assembleia Legislativa, o Capitão Wagner (PR) obtém a maior votação nominal, com 194.239 votos.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-10-0066","y":2014,"m":10,"d":"26","h":"Realiza-se o segundo turno das Eleições Gerais: Camilo Sobreira de Santana (PT), candidato da coligação \"Para o Ceará Seguir Mudando\", é eleito Governador do Estado do Ceará com 2.417.668 votos (53,35% dos votos válidos), tendo como vice Maria Izolda Cela de Arruda Coelho (PROS), primeira mulher eleita para a Vice-Governadoria do Estado. Eunício Lopes de Oliveira (PMDB) totaliza 2.113.940 votos (46,65%). Para Presidente da República, a candidata à reeleição Dilma Rousseff (PT) obtém no Ceará 3.522.746 votos (76,75% dos votos válidos do Estado) contra 1.067.096 votos (23,25%) concedidos a Aécio Neves (PSDB).","c":["Política e Instituições"],"l":0},{"id":"ce-2014-10-0067","y":2014,"m":10,"d":"27","h":"Falece em Fortaleza o sacerdote missionário redentorista Padre Estêvão Mc Cabe (C.Ss.R.), religioso irlandês radicado no Ceará e figura de intensa dedicação pastoral e musical junto à Paróquia de São Raimundo, no bairro Rodolfo Teófilo. O sepultamento dá-se no Cemitério Parque da Paz.<br>29 a 02/11 — Juazeiro do Norte sedia a tradicional Romaria de Finados (Romaria da Esperança), atraindo mais de 400 mil fiéis aos templos e santuários do Cariri cearense.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-11-0068","y":2014,"m":11,"d":"03","h":"No Palácio da Abolição, em Fortaleza, o Governador Cid Gomes e o Governador eleito Camilo Santana instalam oficialmente a comissão mista de transição de governo, priorizando o monitoramento das finanças e a execução das obras hídricas de combate à estiagem no semiárido (Cinturão das Águas do Ceará e adutoras emergenciais).","c":["Política e Instituições"],"l":0},{"id":"ce-2014-11-0069","y":2014,"m":11,"d":"18","h":"Falece em Fortaleza, às 14h30min, aos 71 anos de idade, no Hospital do Coração de Messejana, vítima de parada cardiorrespiratória e complicações de neoplasia pulmonar maligna, o cantor e compositor Genival Joaquim dos Santos (Genival Santos). Nascera em Campina Grande, PB, a 10/05/1943. Sapateiro antes da música, radicou-se em Fortaleza e tornou-se um dos ícones da música romântica e do cancioneiro brega no país, comercializando mais de cinco milhões de discos em 28 álbuns gravados, consagrado por sucessos como Eu Te Peguei no Flagra (1977) e Meu Coração Pede Paz (1972). Seu corpo foi sepultado no Cemitério Parque Jardim Metropolitano, no Eusébio.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-11-0070","y":2014,"m":11,"d":"25","h":"Em Quixadá, comitês técnicos da Cogerh e Defesa Civil reúnem lideranças municipais para avaliar a crise de esgotamento das reservas do histórico Açude Cedro e organizar o abastecimento de emergência nos distritos do Sertão Central.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-12-0071","y":2014,"m":12,"d":"19","h":"No Pavilhão Oeste do Centro de Eventos do Ceará, em Fortaleza, o Tribunal Regional Eleitoral do Ceará (TRE-CE), sob a presidência da Desembargadora Maria Iracema Martins do Vale, realiza a sessão solene de diplomação dos mandatários eleitos no pleito de 2014. Foram diplomados o Governador eleito Camilo Santana, a Vice-Governadora eleita Izolda Cela, o Senador da República Tasso Jereissati e seus suplentes Chiquinho Feitosa e Fernando Férrer, bem como os 22 deputados federais e 46 deputados estaduais titulares.","c":["Política e Instituições"],"l":0},{"id":"ce-2014-12-0072","y":2014,"m":12,"d":"22","h":"Falece em Fortaleza, aos 89 anos de idade, vítima de falência circulatória e complicações renais, o jornalista, cronista, redator, escritor e compositor João Guilherme da Silva Neto (Guilherme Neto / \"Guiba\"). Nascera em Fortaleza a 23/04/1925, filho de Francisco de Paula Silva e Francisca Guilherme da Silva. Cognominado \"o último boêmio do Ceará\", dedicou seis décadas à crônica e à imprensa cearense. Dirigiu a Ceará Rádio Clube (1954–1960), integrou a equipe fundadora da TV Ceará (Canal 2) em 1960 e chefiou a Rádio Universitária da UFC a partir de 1981. Autor da primeira telenovela cearense (Poeira Vermelha, 1960) e da célebre coluna \"Arenga\" no Diário do Nordeste. Foi velado e cremado na Funerária Ternura.","c":["Necrologia","Esportes","Cultura, Educação e Religião"],"l":0},{"id":"ce-2014-12-0073","y":2014,"m":12,"d":"22","h":"O Prefeito de Fortaleza, Roberto Cláudio, sanciona a Lei Municipal nº 10.282, veiculada no Diário Oficial do Município (DOM), dispondo sobre normas de ordenamento urbano e alterações cadastrais e toponímicas de logradouros na capital.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2014-12-0074","y":2014,"m":12,"d":"23 a 30","h":"O Governador eleito Camilo Santana anuncia a equipe de secretários de Estado que comporão o primeiro escalão da administração estadual (2015–2018), confirmando Mauro Benevides Filho (Fazenda), Delci Teixeira (Segurança Pública), Maurício Holanda (Educação), Carlile Lavor (Saúde), André Facó (Infraestrutura) e Hugo Figueirêdo (Planejamento e Gestão).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2014-12-0075","y":2014,"m":12,"d":"31","h":"Encerra-se o mandato constitucional de oito anos (2007–2014) de Cid Ferreira Gomes à frente do Governo do Estado do Ceará, oficializando-se os atos de desincompatibilização no Diário Oficial do Estado para a posse do novo governo a 1º de janeiro de 2015.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-01-0076","y":2015,"m":1,"d":"01","h":"No Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará (ALCE), tomam posse solene o agrônomo e professor Camilo Sobreira de Santana (Camilo Santana) no cargo de Governador do Estado e a professora Maria Izolda Cela de Arruda Coelho (Izolda Cela) no cargo de Vice-Governadora. Em seguida, no Palácio da Abolição, o governador cessante Cid Ferreira Gomes (Cid Gomes) realiza a transmissão do cargo e a passagem da faixa governamental. No mesmo ato, são empossados os novos secretários de Estado, destacando-se Carlos Mauro Benevides Filho (Mauro Filho) na Secretaria da Fazenda (Sefaz), Delci Carlos Teixeira (Delci Teixeira) na Secretaria da Segurança Pública e Defesa Social (SSPDS), Ivo Ferreira Gomes (Ivo Gomes) nas Cidades, Inácio Francisco de Assis Nunes Arruda (Inácio Arruda) na Secitece, Maurício Holanda Maia na Educação (Seduc) e Guilherme de Figueiredo Sampaio (Guilherme Sampaio) na Cultura (Secult).","c":["Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-01-0077","y":2015,"m":1,"d":"01","h":"Assume a presidência da Câmara Municipal de Fortaleza (CMFor), para o biênio 2015–2016, o vereador João Salmito Filho (Salmito Filho), integrando a nova Mesa Diretora com José Walter Cavalcante Neves (1º Vice-Presidente), José Acrísio de Sena (2º Vice-Presidente) e Carlos Mesquita (1º Secretário).","c":["Política e Instituições"],"l":0},{"id":"ce-2015-01-0078","y":2015,"m":1,"d":"01","h":"Começa a vigorar em todo o país o novo valor do Salário Mínimo nacional, reajustado para R$ 788,00 por decreto presidencial, com vigência estendida às tabelas salariais de servidores municipais e estaduais no Ceará.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-01-0079","y":2015,"m":1,"d":"12","h":"Morre, no Hospital Regional do Cariri, em Juazeiro do Norte, aos 82 anos de idade, o tocador de pífano e mestre da cultura tradicional popular Antônio José Lourenço da Silva (Mestre Antônio Aniceto), vítima de Acidente Vascular Cerebral (AVC) hemorrágico. Agricultor e decano da secular Banda Cabaçal dos Irmãos Aniceto — fundada no Crato no século XIX por seu ascendente José Lourenço —, preservou toques e danças ancestrais da cultura caririense, tendo sido agraciado com a Ordem do Mérito Cultural em 2007. Seu corpo foi velado em sua residência no bairro Batateiras e sepultado no Cemitério Público de Nossa Senhora da Piedade, no Crato. Nascera no Crato, CE, em 13/06/1932.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-01-0080","y":2015,"m":1,"d":"30","h":"Solenidade de posse da Desembargadora Maria Iracema Martins do Vale (Iracema do Vale) na presidência do Tribunal de Justiça do Estado do Ceará (TJCE) para o biênio 2015–2017, tornando-se a segunda mulher na história a presidir o Poder Judiciário cearense. Na mesma cerimônia tomam posse os Desembargadores Francisco de Assis Filgueira Mendes (Vice-Presidente) e Francisco Lincoln Araújo e Silva (Corregedor-Geral da Justiça).","c":["Política e Instituições"],"l":0},{"id":"ce-2015-02-0081","y":2015,"m":2,"d":"01","h":"Instalação solene da 29ª Legislatura da Assembleia Legislativa do Estado do Ceará (ALCE) com a posse dos 46 deputados estaduais eleitos e reeleição do deputado José Jácome Carneiro Albuquerque (Zezinho Albuquerque) para a presidência da Mesa Diretora no biênio 2015–2016.","c":["Política e Instituições"],"l":0},{"id":"ce-2015-02-0082","y":2015,"m":2,"d":"02","h":"Sessão inaugural dos trabalhos legislativos de 2015 na ALCE, com leitura da Mensagem Governamental pelo Governador Camilo Santana, enfatizando a gestão hídrica, convivência com o semiárido e interiorização dos serviços de saúde.","c":["Política e Instituições"],"l":0},{"id":"ce-2015-02-0083","y":2015,"m":2,"d":"06","h":"Posse do juiz José Maria dos Santos Sales (José Maria Sales) na Diretoria do Fórum Clóvis Beviláqua, da Comarca de Fortaleza, em sessão conduzida pela Presidência do TJCE no 1º Salão do Júri da capital.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-02-0084","y":2015,"m":2,"d":"09","h":"Morre em Fortaleza, aos 93 anos de idade, o jornalista e cronista esportivo José Maria de Castro (Dedé de Castro), decano da imprensa esportiva cearense com destacada atuação nos Diários Associados (Correio do Ceará e Ceará Rádio Clube) e no Diário do Nordeste. Foi velado na Funerária Ethernus e sepultado no Cemitério Parque da Paz. Nascera em Fortaleza, CE, a 15/09/1921.","c":["Necrologia","Esportes"],"l":0},{"id":"ce-2015-02-0085","y":2015,"m":2,"d":"10","h":"O Desembargador Durval Aires Filho é eleito membro titular da Academia Cearense de Letras (ACL) para a Cadeira nº 39 (patronímica de Visconde de Saboia), sucedendo o poeta Artur Eduardo Benevides.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-02-0086","y":2015,"m":2,"d":"14 a 17","h":"Realizam-se os festejos carnavalescos no Ceará, com desfiles de maracatu e blocos na Avenida Domingos Olímpio, Aterro da Praia de Iracema e Benfica em Fortaleza, e concentrações em Guaramiranga (16º Festival Jazz & Blues), Aracati e Camocim.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-02-0087","y":2015,"m":2,"d":"16","h":"Falece em Fortaleza, aos 86 anos de idade, a educadora e professora Maria José Santos Ferreira Gomes (Dona Mazé). Foi primeira-dama de Sobral (1977–1982) ao lado do ex-prefeito José Euclides Ferreira Gomes Júnior e mãe dos líderes políticos Ciro Gomes, Cid Gomes, Ivo Gomes e Lia Gomes. O Governo do Estado decretou luto oficial de três dias. Foi velada na Funerária Ethernus e sepultada no Cemitério São José, em Sobral. Nascera em São Paulo, SP, a 17/07/1928.","c":["Necrologia"],"l":0},{"id":"ce-2015-03-0088","y":2015,"m":3,"d":"07","h":"Morre no Hospital Regional São Francisco, em Canindé, aos 66 anos de idade, o radialista e político Antônio Ximenes Filho (Ximenes Filho), vítima de infarto agudo do miocárdio. Foi comentarista esportivo, vereador, prefeito de Canindé (1993–1997) e deputado estadual. Foi velado no Largo Francisco Xavier de Medeiros e sepultado no Cemitério São Miguel, em Canindé. Nascera em Tamboril, CE, a 15/04/1948.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-03-0089","y":2015,"m":3,"d":"16","h":"O Governador Camilo Santana sanciona a Lei Estadual nº 15.774, publicada no Diário Oficial do Estado (DOE), reestruturando diretrizes de gestão funcional de órgãos públicos estaduais.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2015-03-0090","y":2015,"m":3,"d":"25","h":"Comemoração solene da Data Magna do Ceará, marcando os 131 anos da abolição dos escravizados na província (25 de março de 1884), quatro anos antes da Lei Áurea. Exposições no Palácio da Abolição, Theatro José de Alencar e Centro Dragão do Mar reverenciam a memória de Francisco José do Nascimento (Dragão do Mar).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-03-0091","y":2015,"m":3,"d":"25","h":"O Governo do Estado anuncia os agraciados com a Medalha da Abolição de 2015: a ativista Maria da Penha Maia Fernandes, o médico cirurgião e pioneiro de transplantes hepáticos José Huygens Parente Garcia e o arquiteto, compositor e urbanista Fausto Nilo Costa Júnior.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-04-0092","y":2015,"m":4,"d":"13","h":"Fortaleza celebra os 289 anos de sua fundação e emancipação política (13 de abril de 1726), com programação cultural no Paço Municipal e concertos abertos na orla marítima.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-04-0093","y":2015,"m":4,"d":"25","h":"Morre subitamente em sua residência em Santana do Acaraú, aos 69 anos de idade, vítima de infarto agudo do miocárdio, o escritor, poeta, chargista e artista plástico Audifax Rios. Renomado ilustrador de obras literárias e folclóricas cearenses, foi velado e sepultado no Cemitério Parque Jardim Metropolitano (em Eusébio). Nascera em Santana do Acaraú, CE, em 17/04/1946.","c":["Necrologia"],"l":0},{"id":"ce-2015-04-0094","y":2015,"m":4,"d":"26","h":"Morre em Fortaleza, aos 70 anos de idade, o médico oftalmologista Sylvio Ideburque Carneiro Leal Filho (Dr. Sylvio Leal), ex-presidente da Sociedade Cearense de Oftalmologia (SCO) e continuador das ações assistenciais da Sociedade de Assistência aos Cegos (SAC). Velado na Funerária Ethernus e sepultado no Cemitério São João Batista. Nascera em Fortaleza, CE, a 12/09/1944.","c":["Necrologia"],"l":0},{"id":"ce-2015-04-0095","y":2015,"m":4,"d":"28","h":"Cerimônia no Palácio da Abolição outorga a Medalha da Abolição de 2015 a Maria da Penha Maia Fernandes, José Huygens Parente Garcia e Fausto Nilo Costa Júnior, presidida pelo governador Camilo Santana.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-04-0096","y":2015,"m":4,"d":"29","h":"Na Arena Castelão, perante 63.399 torcedores pagantes, o Ceará Sporting Club consagra-se campeão invicto da Copa do Nordeste de 2015 ao vencer o Esporte Clube Bahia por 2 a 1 (gols de Charles e Gilvan), após ter vencido a partida de ida em Salvador.","c":["Esportes"],"l":0},{"id":"ce-2015-04-0097","y":2015,"m":4,"d":"29","h":"O Governador Camilo Santana promulga a Lei Estadual nº 15.780, reestruturando as carreiras e a distribuição de cargos do quadro efetivo do magistério superior das universidades estaduais (UECE, URCA e UVA).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-05-0098","y":2015,"m":5,"d":"03","h":"Na Arena Castelão, na grande final do Campeonato Cearense de Futebol de 2015, Fortaleza empata em 2 a 2 com o Ceará perante mais de 50 mil espectadores, conquistando o título estadual com gol histórico assinalado pelo atacante Cassiano aos 47 minutos do segundo tempo, sob o comando do técnico Marcelo Chamusca.","c":["Esportes"],"l":0},{"id":"ce-2015-05-0099","y":2015,"m":5,"d":"06","h":"O Governo do Estado sanciona três leis de toponímia rodoviária estadual (DOE de 08/05/2015): a Lei nº 15.786, denominando Antônio Roque de Andrade o trecho da CE-282 entre Icó e Icozinho; a Lei nº 15.788, denominando Dr. José Euclides Ferreira Gomes Júnior a rodovia CE-240 entre Sobral e Miraíma; e a Lei nº 15.791, denominando José Bento Xavier a estrada entre Camocim e a praia de Maceió.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-05-0100","y":2015,"m":5,"d":"20","h":"Morre em Fortaleza, aos 89 anos de idade, o jurista e professor universitário José Alberto Rôla. Professor titular de Direito Privado da Faculdade de Direito da UFC e destacado advogado civilista, teve luto oficial de três dias decretado pela reitoria da UFC. Foi velado e sepultado no Cemitério Parque da Paz. Nascera em Fortaleza a 24/03/1926.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-05-0101","y":2015,"m":5,"d":"28","h":"Sancionada pelo prefeito Roberto Cláudio a Lei Municipal nº 10.354 (DOM nº 15.540 de 11/06/2015), que denomina Posto de Saúde Dr. Francisco Monteiro (Chico Passeata) unidade de atenção básica da capital, homenageando o médico e histórico ativista das liberdades democráticas.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2015-06-0102","y":2015,"m":6,"d":"02","h":"Sancionada a Lei Estadual nº 15.799, denominando José Pereira Rodrigues a rodovia estadual CE-470, no segmento entre Icó (CE-282) e Orós (CE-153).","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-06-0103","y":2015,"m":6,"d":"09","h":"Morre na UTI do Hospital São Mateus, em Fortaleza, aos 68 anos de idade, vítima de choque séptico e meningite bacteriana, o médico, agropecuarista e líder político José Wellington Roberto Landim (Wellington Landim). Foi prefeito de Brejo Santo (1989–1992), deputado estadual por cinco mandatos e presidente da Assembleia Legislativa do Estado do Ceará em dois biênios (1999–2000 e 2001–2002). O Governo Estadual decretou luto oficial de três dias. Seu corpo foi velado no Plenário 13 de Maio da ALCE e sepultado no Cemitério São João Batista, em Brejo Santo. Nascera em Brejo Santo, CE, a 18/08/1946.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-06-0104","y":2015,"m":6,"d":"10","h":"A Academia Cearense de Letras (ACL) realiza sessão magna solene no Palácio da Luz para dar posse ao Desembargador Durval Aires Filho na Cadeira nº 39 da Casa de Juvenal Galeno.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-06-0105","y":2015,"m":6,"d":"22","h":"A Reitoria da Universidade Regional do Cariri (URCA), no Crato, publica o edital de concurso para docentes efetivos, no processo de reestruturação acadêmica que antecedeu a posse solene do reitor José Patrício Pereira Melo.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-06-0106","y":2015,"m":6,"d":"24","h":"O Prefeito de Fortaleza, Roberto Cláudio, sanciona a Lei Municipal nº 10.370, aprovando o Plano Municipal de Educação de Fortaleza (PME 2015–2025), fixando as metas decenais do sistema educacional público da capital.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2015-07-0107","y":2015,"m":7,"d":"17 a 20","h":"Em Juazeiro do Norte, no Cariri, realiza-se a Romaria do Padre Cícero pelo 81º aniversário de falecimento do Patriarca de Juazeiro, reunindo centenas de milhares de romeiros no ciclo litúrgico da Basílica Menor e na missa celebrada na Capela do Socorro.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-07-0108","y":2015,"m":7,"d":"24","h":"Diante do quarto ano consecutivo de seca no semiárido, o Comitê da Bacia do Médio e Baixo Jaguaribe e a Cogerh deliberam cortes e racionamento na liberação de vazões para os perímetros irrigados, registrando o Açude Castanhão volume crítico inferior a 16,5% de sua capacidade e o Açude Orós abaixo de 44%.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-07-0109","y":2015,"m":7,"d":"27","h":"Sancionada pelo governador Camilo Santana a Lei Estadual nº 15.820 (DOE de 30/07/2015), que denomina Mirabor Saldanha a rodovia CE-368 entre os municípios de Jaguaretama e Jaguaribe.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-08-0110","y":2015,"m":8,"d":"11","h":"A OAB-CE realiza sessão comemorativa dos 83 anos de instalação da seccional cearense no Palácio do Comércio, no Centro de Fortaleza, outorgando distinções de mérito a juristas locais.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-08-0111","y":2015,"m":8,"d":"15","h":"Feriado da padroeira de Fortaleza, Nossa Senhora da Assunção. É realizada a 13ª Caminhada com Maria, reunindo cerca de 1 milhão de fiéis ao longo de 12 quilômetros entre o Santuário de Vila Velha e a Catedral Metropolitana de Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-08-0112","y":2015,"m":8,"d":"30","h":"O Açude Castanhão atinge a marca histórica de 16,0% de armazenamento hídrico, aprofundando o quadro de colapso de mananciais no interior e forçando a renovação de decretos de emergência por prefeituras do sertão.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-09-0113","y":2015,"m":9,"d":"01 a 15","h":"Realiza-se em Juazeiro do Norte a Romaria de Nossa Senhora das Dores, acolhendo cerca de 400 mil romeiros com procissões no Centro comercial e celebrações na Basílica Menor.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-09-0114","y":2015,"m":9,"d":"16","h":"Os líderes políticos Ciro Ferreira Gomes e Cid Ferreira Gomes, juntamente com deputados federais e estaduais, assinam filiação solene ao Partido Democrático Trabalhista (PDT), alterando a correlação de forças políticas partidárias no Ceará.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-09-0115","y":2015,"m":9,"d":"24","h":"Inicia-se em Canindé a secular Festa de São Francisco das Chagas, com acolhimento de milhares de caravanas religiosas de todo o Norte e Nordeste.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-09-0116","y":2015,"m":9,"d":"25","h":"Solenidade no Theatro José de Alencar para a 45ª outorga do Troféu Sereia de Ouro, láurea do Grupo Edson Queiroz. Foram agraciados: o ex-governador e ex-ministro da Educação Cid Ferreira Gomes; o médico e provedor da Santa Casa de Sobral Elias Geovani Boutala Salomão; o professor e ex-reitor da UFC Jesualdo Pereira Farias; e a médica oncopediatra Lúcia Maria Alcântara de Albuquerque (fundadora da Associação Peter Pan).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-10-0117","y":2015,"m":10,"d":"04","h":"Encerramento das celebrações de São Francisco das Chagas em Canindé, reunindo mais de 100 mil devotos na procissão solene de São Francisquinho.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-10-0118","y":2015,"m":10,"d":"04","h":"Morre em Fortaleza, aos 62 anos de idade, vítima de complicações de neoplasia, o médico oncologista e professor titular da UFC Ronaldo de Albuquerque Ribeiro (Prof. Ronaldo Ribeiro). Pesquisador 1A do CNPq, pioneiro em estudos de toxicidade oncológica no Hospital Haroldo Juaçaba (ICC) e membro da Academia Cearense de Ciências. Foi velado na Funerária Ternura e sepultado no Cemitério Parque da Paz. Nascera em Fortaleza a 28/05/1953.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-10-0119","y":2015,"m":10,"d":"09","h":"Morre aos 83 anos de idade, em Fortaleza, onde residia, a cantora e compositora Amélia Rocha Barroso (nome artístico: Cláudia Barroso, a \"Rainha da Canção Brega\"). Vítima de insuficiência respiratória em unidade hospitalar. Foi velada e sepultada no Cemitério Parque Jardim Metropolitano (em Eusébio). Nascera em Pirapetinga, MG, a 23/04/1932.","c":["Necrologia"],"l":0},{"id":"ce-2015-10-0120","y":2015,"m":10,"d":"15","h":"Sancionada pelo prefeito Roberto Cláudio a Lei Municipal nº 10.405, que institui o Prêmio Projeto Inovador na administração municipal, e a Lei Complementar nº 0209/2015, dispondo sobre o PCCS do Grupo Tributação da Secretaria Municipal de Finanças (SEFIN).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2015-10-0121","y":2015,"m":10,"d":"20","h":"Sancionada a Lei Estadual nº 15.875, que denomina Evaldo Holanda Maia a Avenida do Contorno Leste de Limoeiro do Norte.","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2015-10-0122","y":2015,"m":10,"d":"20","h":"Morre em Fortaleza, aos 80 anos de idade, o radialista, jornalista e bacharel em Direito José Edilmar Norões Coelho (Edilmar Norões). Pioneiro do rádio e da televisão cearense, diretor-geral de programação do Sistema Verdes Mares, fundador do Diário do Nordeste e titular de sua principal coluna política, presidente da ACERT e membro da Academia Cearense de Literatura e Jornalismo. Foi velado na Funerária Ethernus e sepultado no Cemitério Parque da Paz. Nascera em Barbalha, CE, a 11/08/1935.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-11-0123","y":2015,"m":11,"d":"06","h":"Morre aos 80 anos de idade, na UTI do Hospital Monte Klinikum em Fortaleza, o líder industrial, administrador e homem público Benedito Clayton Veras Alcântara (Beni Veras). Foi presidente do Centro Industrial do Ceará (CIC, 1967–1977), senador da República (1991–1999), Ministro de Estado do Planejamento no governo Itamar Franco (1994–1995, período de elaboração do Plano Real), vice-governador do Ceará (1999–2002) e Governador do Estado do Ceará em 2002. Foi velado no Palácio da Abolição com honras de ex-chefe de Estado e sepultado no Cemitério Jardim Metropolitano, no Eusébio. Nascera em Crateús, CE, a 18/08/1935.<br>11 para 12 - Na noite de 11 e madrugada de 12 de novembro, ocorre o mais grave episódio de violência policial da história da capital, conhecido como a Chacina da Grande Messejana (ou Chacina do Curió). Após o assassinato de um policial militar na Lagoa Redonda, homens encapuzados executaram 11 pessoas (a maioria adolescentes e jovens sem antecedentes) nas ruas do Curió, São Miguel, Alagadiço Novo e Messejana, provocando comoção nacional e o maior processo criminal com mais de 40 policiais denunciados pelo Ministério Público do Ceará.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-11-0124","y":2015,"m":11,"d":"27","h":"Sancionada a Lei Estadual nº 15.893, que altera as tabelas e normas de cobrança do IPVA no Ceará para o exercício de 2016.","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2015-12-0125","y":2015,"m":12,"d":"04","h":"A Assembleia Legislativa aprova o pacote tributário do Executivo pela Lei Estadual nº 15.899/2015, visando preservar a capacidade de investimento diante da recessão econômica e da estiagem prolongada.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2015-12-0126","y":2015,"m":12,"d":"10","h":"O Governo do Estado sanciona a Lei Estadual nº 15.901, reestruturando as tabelas salariais dos professores da rede estadual de ensino (Grupo MAG).","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2015-12-0127","y":2015,"m":12,"d":"11","h":"Sancionada a Lei Estadual nº 15.912, criando o Fundo de Reaparelhamento e Modernização do Ministério Público do Estado do Ceará (FRMMP/CE).","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2015-12-0128","y":2015,"m":12,"d":"15","h":"Sancionada a Lei Estadual nº 15.923, que reorganiza e consolida as normas do Prêmio Escola Nota Dez, vinculado às avaliações de alfabetização do SPAECE.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-12-0129","y":2015,"m":12,"d":"19","h":"Entra em vigor em Fortaleza a Tarifa de Contingência de Água (Resolução nº 007/2015 da ACFOR), instituindo sobretaxa impositiva sobre o consumo excessivo em razão da estiagem prolongada e da iminência de colapso nos mananciais do Jaguaribe.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2015-12-0130","y":2015,"m":12,"d":"25","h":"Falece em Fortaleza, aos 79 anos de idade, o jurista e magistrado José Maria de Melo (Desembargador José Maria de Melo), vitimado por neoplasia maligna. Bacharel em Direito pela UFC (1961), presidiu o Tribunal de Justiça do Estado do Ceará no biênio 1997–1999, foi corregedor-geral da Justiça (1999–2000), presidente do TRE-CE (1988–1990) e presidiu a Associação Cearense de Magistrados (ACM) por 17 anos. Foi velado na sede do TJCE no Cambeba e sepultado no Cemitério Parque da Paz. Nascera em Groaíras, CE, a 06/03/1936.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2015-12-0131","y":2015,"m":12,"d":"31","h":"O Réveillon de Fortaleza, no Aterro da Praia de Iracema, reúne mais de 1,1 milhão de pessoas na celebração de encerramento do primeiro ano de mandato do governador Camilo Santana e do terceiro ano da gestão do prefeito Roberto Cláudio.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-01-0132","y":2016,"m":1,"d":"01","h":"Entra em vigor em todo o território nacional o novo valor do Salário Mínimo, fixado em R$ 880,00 mensais pelo Decreto Federal nº 8.618/2015, repercutindo nos pisos salariais estaduais e municipais do Ceará.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-01-0133","y":2016,"m":1,"d":"01","h":"Toma posse administrativamente, para o triênio 2016–2018, na sede da Rua Lívio Barreto nº 668 (Joaquim Távora), a nova diretoria da Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE), assumindo a presidência o advogado Marcelo Mota Gurgel do Amaral (Marcelo Mota), em sucessão a Valdetário Andrade Monteiro, ao lado da vice-presidente Francisca Roberta Vasques (Roberta Vasques, primeira mulher a ocupar a vice-presidência nos 83 anos da seccional), da secretária-geral Christiane do Vale Leitão, do secretário-geral adjunto Fábio Robson Timbó Silveira e do tesoureiro Gladson Wesley Mota Pereira.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-01-0134","y":2016,"m":1,"d":"02","h":"Morre pela manhã, em sua residência em Fortaleza, de causas naturais, aos 103 anos de idade, o industrial, comerciante, construtor e político Alberto Targino. Seu corpo é velado no Complexo Velatório Ethernus e sepultado às 18 horas no Cemitério Parque da Paz. Fundador da tradicional marca de aguardente Cachaça Colonial (registrada em 1935 inicialmente no Sítio Colégio, em Aquiraz), foi rotariano por quatro décadas, agraciado com a Medalha do Mérito Industrial da FIEC, vereador na década de 1930 e prefeito municipal de Aquiraz por três mandatos (eleito em 1950, 1958 e 1966). Era viúvo de Laís Sidrim Targino. Nascera em Fortaleza, CE, em 24/01/1912.","c":["Necrologia","Política e Instituições"],"l":0},{"id":"ce-2016-01-0135","y":2016,"m":1,"d":"11","h":"Toma posse, na Câmara Municipal de Quixadá, no Sertão Central, a diretoria da Subsecção da OAB-CE de Quixadá para o triênio 2016–2018, presidida pelo advogado Jairo Cidade, instalando-se o primeiro Conselho Subseccional da comarca.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-01-0136","y":2016,"m":1,"d":"13","h":"O prefeito de Fortaleza, Roberto Cláudio Rodrigues Bezerra (Roberto Cláudio), sanciona a Lei Municipal nº 10.440, oficializando a data de fundação e aniversário histórico do bairro Messejana.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-01-0137","y":2016,"m":1,"d":"14","h":"O governador Camilo Sobreira de Santana (Camilo Santana) sanciona a Lei Estadual nº 15.951 (DOE de 18/01/2016), que institui o Bilhete Único Metropolitano na Região Metropolitana de Fortaleza; a Lei Estadual nº 15.952, que aprova o Plano de Cargos, Carreiras e Remuneração (PCCR) dos servidores do DETRAN/CE; e a Lei Estadual nº 15.953, que cria o Conselho Estadual de Promoção da Igualdade Racial do Ceará (COEPIR).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-01-0138","y":2016,"m":1,"d":"20","h":"Realiza-se à noite, no Centro de Eventos do Ceará, a solenidade festiva de posse da diretoria da OAB-CE, do Conselho Seccional, da Caixa de Assistência dos Advogados do Ceará (CAACE) e da Escola Superior de Advocacia (ESA) para o triênio 2016–2018, sob a presidência de Marcelo Mota.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-02-0139","y":2016,"m":2,"d":"01","h":"Tomam posse pela manhã, em Brasília, DF, perante o Conselho Federal da OAB para o triênio 2016–2018, os conselheiros federais da bancada do Ceará: Valdetário Andrade Monteiro, Ricardo Bacelar Paiva e Caio Cesar Vieira Rocha.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-02-0140","y":2016,"m":2,"d":"01","h":"Inicia-se o ano legislativo de 2016 na Câmara Municipal de Fortaleza (CMFor), sob a presidência do vereador Salmito Filho (PDT), e instala-se a 2ª Sessão Legislativa da 29ª Legislatura da Assembleia Legislativa do Estado do Ceará (ALCE), sob a presidência do deputado Zezinho Albuquerque (PDT), com a leitura da Mensagem Governamental pelo governador Camilo Santana.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-02-0141","y":2016,"m":2,"d":"02","h":"Encerra-se em Juazeiro do Norte, no Cariri, a tradicional Romaria de Nossa Senhora das Candeias, reunindo centenas de milhares de romeiros na Procissão da Luz pelas ruas do Centro até a Basílica Menor de Nossa Senhora das Dores.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-02-0142","y":2016,"m":2,"d":"06 a 09","h":"Realiza-se o Carnaval de 2016 em Fortaleza (com desfiles na Avenida Domingos Olímpio e polos na Praia de Iracema, Benfica e Mercado dos Pinhões) e nos polos do interior (Aracati, Paracuru, Camocim, São Benedito, Guaramiranga e Crato). Na apuração oficial da Avenida Domingos Olímpio, sagram-se campeões empatados na categoria Maracatus o Maracatu Vozes da África e o Maracatu Nação Pici (e o Maracatu Nação Iracema na Categoria Especial dos 290 anos de Fortaleza), e a Unidos do Acaracuzinho nas Escolas de Samba.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-02-0143","y":2016,"m":2,"d":"13","h":"O governador Camilo Santana sanciona três leis estaduais de toponímia (DOE de 17/02/2016): a Lei nº 15.960, que denomina Vereador Juvêncio Ricarte Elizeu de Lima o Ginásio Poliesportivo anexo da EEM Adahil Barreto, em Cariús; a Lei nº 15.961, que denomina Francisco Sales de Freitas o trecho da rodovia CE-371 entre Palhano e Itaiçaba; e a Lei nº 15.962, que denomina Deputado José Welington Landim o edifício do Departamento de Saúde e Assistência Social (DSAS) da Assembleia Legislativa do Ceará, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-02-0144","y":2016,"m":2,"d":"23","h":"O presidente da Câmara Municipal de Fortaleza, vereador Salmito Filho, promulga o Decreto Legislativo nº 732, denominando oficialmente Rua Professor Frota Pinto a antiga Rua Efésio, situada no bairro Luciano Cavalcante.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-02-0145","y":2016,"m":2,"d":"25","h":"Em sessão solene histórica no Tribunal de Justiça do Estado do Ceará (TJCE), presidida pela desembargadora Maria Iracema Martins do Vale, tomam posse simultaneamente 76 novos juízes substitutos aprovados em concurso público para prover comarcas do interior cearense, na maior posse conjunta da história da magistratura estadual.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-03-0146","y":2016,"m":3,"d":"03","h":"O governador Camilo Santana sanciona pacote de leis estaduais de toponímia e calendário oficial (DOE de 07/03/2016): a Lei nº 15.970, denominando Prefeito Dário Campos Feijó a Escola de Ensino Médio de Martinópole; a Lei nº 15.971, incluindo a Regata de Jangadas de Majorlândia (Aracati) no Calendário Oficial do Estado; a Lei nº 15.979, denominando Tomé Gomes dos Santos a Escola de Ensino Médio de Paramoti; a Lei nº 15.981, denominando Manoel Raimundo de Medeiros o trecho da rodovia CE-182 entre Monteiros e a Praia do Preá, em Cruz; e a Lei nº 15.983, denominando Vereador Eduardo Araújo Brito o Escritório Regional do DETRAN/CE em Camocim.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-03-0147","y":2016,"m":3,"d":"08","h":"Morre no final da tarde, em Fortaleza, assassinado a tiros durante assalto enquanto caminhava em praça na Rua Bento Albuquerque, no bairro Cocó, aos 77 anos de idade, o magistrado aposentado Edvalson Florêncio Marques Batista. Seu corpo é velado na Funerária Ethernus e sepultado no dia 09 no Cemitério Parque da Paz. Ingressara na magistratura em 1987 como juiz de Mulungu e aposentara-se em 2000 como titular da 2ª Vara de Execuções Penais de Fortaleza. Nascera em 1938.","c":["Necrologia"],"l":0},{"id":"ce-2016-03-0148","y":2016,"m":3,"d":"22","h":"Morre na madrugada, em hospital particular de Fortaleza, vítima de complicações cardiorrespiratórias, aos 80 anos de idade, o pesquisador, memorialista e colecionador Christiano Câmara. Seu corpo é velado na Funerária Ternura e sepultado às 16h30min no Cemitério de São João Batista. Filho de Zuleika Pessoa Câmara e sobrinho de Dom Hélder Câmara, manteve durante seis décadas, ao lado da esposa Douvina Câmara, a Casa de Cultura Christiano Câmara na Rua Baturité (antiga Rua da Escadinha) nº 162, no Centro — um dos mais importantes acervos privados de discos em 78 rotações, gramofones, periódicos e documentos raros da memória fonográfica e radiofônica do Ceará. Nascera em Fortaleza, CE, em 1935.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-03-0149","y":2016,"m":3,"d":"22","h":"Sancionada a Lei Estadual nº 15.986 (DOE de 30/03/2016), que denomina Frei Lucas Dolle a Policlínica Regional do município de Canindé; e sancionada pelo prefeito Roberto Cláudio a Lei Municipal nº 10.450 (DOM de 28/03/2016), autorizando o Município de Fortaleza a receber do DNIT o trecho urbano da rodovia BR-116 (km 0 ao km 10) para municipalização.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-03-0150","y":2016,"m":3,"d":"25","h":"Comemora-se a Data Magna do Ceará (132 anos da Abolição da Escravatura na Província em 25/03/1884), com programação alusiva ao jangadeiro Dragão do Mar no Museu do Ceará e no Museu Sacro de Aquiraz. Na outorga da Medalha da Abolição referente ao biênio 2016–2017, são contemplados pelo Governo do Estado: Ciro Ferreira Gomes, o ministro do STJ Napoleão Nunes Maia Filho, o empresário Carlos Francisco Ribeiro Jereissati, a professora e sindicalista Luiza de Teodoro Vieira, o médico psiquiatra Valton de Miranda Leitão e o músico e fundador da Fundação Casa Grande (Nova Olinda) Francisco Alemberg de Souza Lima (Alemberg Quindins).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-03-0151","y":2016,"m":3,"d":"30","h":"O presidente da Câmara Municipal de Fortaleza, Salmito Filho, promulga o Decreto Legislativo nº 734, que denomina Avenida Comodoro Estácio Brígido a antiga Avenida Norte, no bairro Patriolino Ribeiro; e o Decreto Legislativo nº 737, que altera a denominação da Rua Bauxita para Rua Alfredo, o Rei da Peixada, no bairro Mucuripe.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-04-0152","y":2016,"m":4,"d":"13","h":"Fortaleza celebra os 290 anos de sua elevação a Vila (13 de abril de 1726), com programação nos mercados públicos, Areninhas e grande concerto coletivo Para Cantar Fortaleza no Aterrinho da Praia de Iracema, reunindo dezenas de intérpretes cearenses, Waldonys e Alceu Valença.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-04-0153","y":2016,"m":4,"d":"22","h":"O governador Camilo Santana sanciona a Lei Estadual nº 15.992, estabelecendo regime tributário diferenciado de ICMS para a implantação de Centro Internacional de Conexões de Voos (Hub aéreo) no Aeroporto Internacional Pinto Martins, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-04-0154","y":2016,"m":4,"d":"24","h":"O Guarani Esporte Clube (Guarani de Juazeiro) conquista o título de Campeão Cearense do Interior (Taça Padre Cícero de 2016), ao passo que Fortaleza Esporte Clube e Uniclinic Atlético Clube classificam-se para a decisão estadual.","c":["Esportes"],"l":0},{"id":"ce-2016-05-0155","y":2016,"m":5,"d":"02","h":"O governador Camilo Santana sanciona a Lei Estadual nº 15.999, que denomina José Artur Ribeiro Guimarães a ponte no km 12 da rodovia CE-253, entre Groaíras e Cariré.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-05-0156","y":2016,"m":5,"d":"05","h":"Sancionadas quatro leis estaduais de toponímia para o interior (DOE de 09/05/2016): a Lei nº 16.019, denominando Francisco Mizael Cavalcante a Escola de Ensino Médio do distrito de Marruás, em Tauá; a Lei nº 16.020, denominando Francisco Teles de Lima a Escola de Ensino Médio do distrito de Santa Fé, no Crato; a Lei nº 16.021, denominando Professor Osvaldo Martins de Almeida o auditório da EEEP Dr. José Alves da Silveira, em Quixeramobim; e a Lei nº 16.022, denominando José de Sousa Veneranda a ponte sobre o Rio Banabuiú no km 3 da rodovia CE-458, em Russas.","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-05-0157","y":2016,"m":5,"d":"08","h":"Na Arena Castelão, o Fortaleza Esporte Clube derrota o Uniclinic Atlético Clube por 1 a 0 (gol de Pio), após haver vencido o primeiro jogo por 4 a 1, sagrando-se Bicampeão Cearense de Futebol (2015–2016) e alcançando o 41º título estadual de sua história, sob o comando técnico de Marquinhos Santos.","c":["Esportes"],"l":0},{"id":"ce-2016-05-0158","y":2016,"m":5,"d":"10","h":"Sancionada pelo prefeito Roberto Cláudio a Lei Municipal nº 10.468, instituindo o Estatuto do Pedestre no Município de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-05-0159","y":2016,"m":5,"d":"28 e 29","h":"Inicia-se em Barbalha, no Cariri, a Festa de Santo Antônio de Barbalha de 2016, primeira edição celebrada após o reconhecimento oficial como Patrimônio Cultural Imaterial do Brasil pelo IPHAN, com desfile de 60 grupos de tradição popular e o cortejo do Pau da Bandeira de Santo Antônio carregado até o largo da Igreja Matriz.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-05-0160","y":2016,"m":5,"d":"30","h":"O governador Camilo Santana sanciona a Lei Estadual nº 16.025 (DOE de 01/06/2016), aprovando o Plano Estadual de Educação do Ceará (PEE 2016–2024).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-06-0161","y":2016,"m":6,"d":"01","h":"Entra em vigor na Região Metropolitana de Fortaleza o Bilhete Único Metropolitano; na mesma data, o governador Camilo Santana sanciona a Lei Estadual nº 16.026, instituindo o Plano Estadual de Cultura do Ceará.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-06-0162","y":2016,"m":6,"d":"07 a 09","h":"Percorre o território cearense o revezamento da Tocha Olímpica dos Jogos Olímpicos Rio 2016: no dia 07, a chama passa por Aracati, Aquiraz e Fortaleza (culminando com o acendimento da Pira Olímpica no Aterrinho da Praia de Iracema, com participação da medalhista olímpica Shelda Bedê); no dia 08, percorre Caucaia, Itapajé, Irauçuba, Forquilha e Sobral (com celebração na Margem Esquerda do Rio Acaraú); e no dia 09, atravessa Massapê, Granja, Camocim e Barroquinha rumo ao Piauí.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-06-0163","y":2016,"m":6,"d":"15","h":"Sancionada a Lei Estadual nº 16.029, que denomina Raimundo de Araújo Cabral a rodovia CE-025 (entre a CE-040 e a CE-452, em Aquiraz/Eusébio), e a Lei Estadual nº 16.030, autorizando a doação do imóvel do Campus do Junco, em Sobral, à Universidade Estadual Vale do Acaraú (UVA).","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-06-0164","y":2016,"m":6,"d":"17","h":"Morre às 14 horas, em Fortaleza, vítima de falência múltipla de órgãos, aos 87 anos de idade, a empresária e matriarca Yolanda Pontes Vidal Queiroz (Dona Yolanda Queiroz), presidente do Grupo Edson Queiroz. Seu corpo é cremado à noite no Crematório do Cemitério Jardim Metropolitano, no Eusébio. Filha de Luís Vidal e Maria Pontes Vidal, casou-se com o industrial Edson Queiroz (1925–1982), com quem participou da fundação do conglomerado em 1951. Após o falecimento do marido na Serra da Aratanha em 1982, assumiu a presidência do grupo e conduziu por 34 anos a expansão da Nacional Gás, Indaiá, Minalba, Esmaltec, Sistema Verdes Mares e da Fundação Edson Queiroz / Universidade de Fortaleza (Unifor). Nascera em Fortaleza, CE, em 12/11/1928.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-06-0165","y":2016,"m":6,"d":"24","h":"Morre em São Paulo, SP, no Hospital Israelita Albert Einstein, vítima de complicações de cirurgia cardíaca, aos 81 anos de idade, o industrial cearense Francisco Ivens de Sá Dias Branco (Ivens Dias Branco). Seu corpo é cremado no Cemitério e Crematório Horto da Paz, em Itapecerica da Serra (SP), decretando o Governo do Ceará e a Assembleia Legislativa luto oficial de três dias. Filho de Manuel Dias Branco e Maria Vidal de Sá Branco, ingressou em 1953 na Padaria Imperial, em Fortaleza, transformando-a no grupo M. Dias Branco S.A. Indústria e Comércio de Alimentos (sediado no Eusébio), líder nacional no setor de massas e biscoitos, além de atuar nos ramos imobiliário (Idibra), hoteleiro, cimenteiro e portuário. Agraciado com a Medalha da Abolição, era casado com Maria Consuelo Saraiva Leão Dias Branco, deixando cinco filhos. Nascera em Cedro, CE, em 03/08/1934.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-06-0166","y":2016,"m":6,"d":"27","h":"Sancionada a Lei Estadual nº 16.038 (DOE de 28/06/2016), que denomina Hervano Macedo Júnior o 2º Colégio da Polícia Militar do Ceará, sediado em Juazeiro do Norte.","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2016-06-0167","y":2016,"m":6,"d":"28","h":"Sancionada a Lei Estadual nº 16.040, criando a Superintendência do Sistema Estadual de Atendimento Socioeducativo (SEAS), e a Lei Estadual nº 16.045, denominando Dr. José Euclides Ferreira Gomes Júnior a Escola Estadual de Ensino Médio na sede do município de Miraíma.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-07-0168","y":2016,"m":7,"d":"03","h":"Realiza-se na Abadia de Nossa Senhora da Vitória, em Juazeiro do Norte (primeira abadia beneditina do Ceará), a Bênção Abacial da segunda abadessa da instituição, Madre Maria José dos Santos.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-07-0169","y":2016,"m":7,"d":"07","h":"No quinto ano consecutivo de seca severa (2012–2016), relatório da Cogerh aponta que o volume geral acumulado nos 153 açudes monitorados do Ceará caiu a 12%, enquanto o Açude Castanhão atinge 8,33% de sua capacidade, com 25 açudes totalmente secos e 39 em volume morto no Estado.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-07-0170","y":2016,"m":7,"d":"07","h":"O presidente da Câmara Municipal de Fortaleza, Salmito Filho, promulga o Decreto Legislativo nº 756, que modifica a denominação da Rua Raimundo Frota para Rua Manuel Moura, no bairro Jardim Iracema; e o Decreto Legislativo nº 760, que denomina Rua Álef Sousa Cavalcante a antiga Rua Paisagística, no bairro Jangurussu.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-07-0171","y":2016,"m":7,"d":"17","h":"Em celebração solene na Catedral de Nossa Senhora da Penha, no Crato, presidida pelo bispo Dom Fernando Panico, toma posse canônica Dom Gilberto Pastana de Oliveira como Bispo Coadjutor da Diocese de Crato.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-07-0172","y":2016,"m":7,"d":"20","h":"Culminância da Romaria dos 82 anos de falecimento do Padre Cícero Romão Batista (1844–1934) em Juazeiro do Norte, a primeira romaria de julho celebrada após a reconciliação histórica e o perdão oficial concedido pela Igreja Católica à memória do sacerdote em dezembro de 2015.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-07-0173","y":2016,"m":7,"d":"26","h":"O governador Camilo Santana sanciona a Lei Estadual nº 16.071, denominando Engenheiro Raimundo Josino Pontes o binário no distrito de Várzea do Jiló (CE-187), em Ipu; e a Lei Estadual nº 16.073, denominando Prudêncio Pessoa de Queiroz a Escola de Ensino Médio de Iracema. No dia seguinte (27), sanciona a Lei Estadual nº 16.090, denominando Leandro Custódio de Oliveira e Castro a barragem do Rio Jucá, em Parambu.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-07-0174","y":2016,"m":7,"d":"30","h":"Morre em Fortaleza, aos 87 anos de idade, o advogado Antônio de Pádua Barroso, decano da advocacia e genitor do juiz de Direito Victor Nunes Barroso, sendo sepultado no dia 31 na capital.","c":["Necrologia"],"l":0},{"id":"ce-2016-08-0175","y":2016,"m":8,"d":"01 a 05","h":"Realizam-se as convenções partidárias para as Eleições Municipais de 2016 no Ceará, homologando em Fortaleza oito candidaturas a prefeito: Roberto Cláudio (PDT), Capitão Wagner (PR), Luizianne Lins (PT), Heitor Férrer (PSB), Ronaldo Martins (PRB), João Alfredo (PSOL), Tin Gomes (PHS) e Francisco Gonzaga (PSTU).","c":["Política e Instituições"],"l":0},{"id":"ce-2016-08-0176","y":2016,"m":8,"d":"18","h":"Morre pela manhã, no Hospital Monte Klinikum, em Fortaleza, aos 75 anos de idade, vítima de falência múltipla dos órgãos, o professor universitário, sociólogo, teólogo, advogado, escritor e deputado estadual no exercício do mandato José Teodoro Soares (Professor Teodoro). Filho de Agrípio Teodoro Soares e Maria Palmira Soares, graduou-se em Teologia pela Pontifícia Universidade Gregoriana, em Roma. Foi reitor da Universidade Regional do Cariri – URCA (1987–1990), reitor da Universidade Estadual Vale do Acaraú – UVA, em Sobral, por 16 anos (1990–2006), professor da UFC e da UECE por 45 anos, autor de 32 livros e membro da Academia Sobralense de Letras e da Academia Cearense de Ciências Sociais. Eleito deputado estadual em 2006, 2010 e 2014, presidia a Universidade do Parlamento Cearense (Unipace). O Governo do Estado e a URCA decretaram luto oficial de três dias. Após velório na Assembleia Legislativa, em Fortaleza, e no campus da UVA, em Sobral, foi sepultado em sua terra natal. Nascera em Santa Cruz do Norte (atual Reriutaba), CE, em 28/12/1940.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-09-0177","y":2016,"m":9,"d":"02","h":"O governador Camilo Santana sanciona a Lei Estadual nº 16.103, instituindo a Tarifa de Contingência pelo uso dos recursos hídricos em período de escassez crítica na Região Metropolitana de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-09-0178","y":2016,"m":9,"d":"09","h":"O prefeito Roberto Cláudio sanciona a Lei Municipal nº 10.532, que denomina Posto de Saúde Dr. Pontes Neto a unidade de saúde na 2ª Etapa do bairro Conjunto Ceará; e a Lei Municipal nº 10.537, que regulamenta a Área de Relevante Interesse Ecológico (ARIE) Prof. Abreu Matos.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-09-0179","y":2016,"m":9,"d":"12","h":"Sancionada a Lei Estadual nº 16.105 (DOE de 13/09/2016), criando a Delegacia de Repressão às Ações Criminosas Organizadas (DRACO) na estrutura da Polícia Civil do Ceará.","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2016-09-0180","y":2016,"m":9,"d":"14","h":"Sancionadas três leis estaduais de toponímia (DOE de 16/09/2016): a Lei nº 16.107, denominando Maria Eunice Rocha Lima a estrada entre a sede de Iguatu e os distritos de Baú e Catolé; a Lei nº 16.108, denominando Antonio Valmir Ribeiro a Escola Estadual de Educação Profissional de Farias Brito; e a Lei nº 16.114, denominando Ana de Siqueira Gonçalves a Escola de Ensino Médio do distrito de Monte Sion, em Parambu.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-09-0181","y":2016,"m":9,"d":"15","h":"Culminância da Festa e Romaria de Nossa Senhora das Dores, padroeira de Juazeiro do Norte, com procissão e desfile de carros de romeiros acompanhados por centenas de milhares de fiéis no Cariri.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-09-0182","y":2016,"m":9,"d":"21","h":"Têm início as atividades técnicas de implantação do Hospital Regional do Sertão Central (HRSC), na rodovia CE-060, no município de Quixeramobim.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-09-0183","y":2016,"m":9,"d":"24","h":"Morre em Fortaleza, aos 89 anos de idade, vítima de parada cardiorrespiratória, o radialista, jornalista, servidor público federal e ex-deputado estadual Francisco Olavo Peixoto de Alencar (registrado na ALCE como José Olavo Peixoto de Alencar; consagrado como Peixoto de Alencar). Filho de José Peixoto Filho e Maria Júlia Peixoto, tornou-se ícone do radiojornalismo cearense pelo bordão \"Peixoto de Alencar, quando ele fala, o Ceará escuta\" e pela cobertura de 1960 no Açude Orós, atuando nas rádios Uirapuru, Assunção, Verdes Mares e Dragão do Mar (onde formou dupla com Mardônio Sampaio), além de ter exercido mandato de deputado estadual. Após velório na Funerária Ternura, foi sepultado no dia 25 no Cemitério Parque da Paz. Nascera em Baturité, CE, em 02/01/1927.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-09-0184","y":2016,"m":9,"d":"27","h":"Inicia-se a fase de operação experimental do primeiro trecho de 3,6 km do Veículo Leve sobre Trilhos (VLT) Parangaba–Mucuripe, em Fortaleza, entre a Vila União (Borges de Melo) e a Parangaba.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-09-0185","y":2016,"m":9,"d":"28","h":"Morre em Fortaleza, aos 79 anos de idade, o magistrado Francisco da Rocha Victor, 139º desembargador e ex-presidente do Tribunal de Justiça do Estado do Ceará (TJCE). Filho de Miguel Victor Filho e Altair da Rocha Victor, presidiu o TJCE no biênio 2005–2006 e exerceu interinamente o cargo de Governador do Estado do Ceará em maio de 2006. Após velório na Funerária Ternura, foi sepultado às 16 horas no Cemitério Jardim Metropolitano, no Eusébio. Nascera em Baturité, CE, em 08/11/1936.","c":["Necrologia","Política e Instituições"],"l":0},{"id":"ce-2016-09-0186","y":2016,"m":9,"d":"30","h":"Realiza-se à noite, no Theatro José de Alencar, a 46ª edição do Troféu Sereia de Ouro, outorgado pelo Grupo Edson Queiroz / Sistema Verdes Mares — primeira cerimônia após o falecimento de Dona Yolanda Vidal Queiroz. Foram homenageados: a escritora, professora da UFC e acadêmica da ACL Maria Ângela de Farias Gutiérrez (Ângela Gutiérrez); o médico infectologista e professor Anastácio de Queiroz Sousa; o desembargador do TJCE Teodoro Silva Santos; e o cineasta fortalezense Karim Aïnouz.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-10-0187","y":2016,"m":10,"d":"02","h":"Realiza-se o primeiro turno das Eleições Municipais nos 184 municípios do Ceará:<br><ul class='ef-sublist'><li>Em Fortaleza, qualificam-se para o segundo turno o prefeito Roberto Cláudio Rodrigues Bezerra (PDT), com 524.973 votos (40,81%), e o deputado estadual Wagner Sousa Gomes — Capitão Wagner (PR), com 400.802 votos (31,15%), seguidos por Luizianne de Oliveira Lins (PT, 193.687 votos; 15,06%), Heitor Correia Férrer (PSB, 90.510 votos; 7,04%), Ronaldo Cavalcante Martins (PRB, 51.687 votos; 4,02%), João Alfredo Telles Melo (PSOL, 18.048 votos; 1,40%), Agostinho Frederico Carmo Gomes — Tin Gomes (PHS, 4.616 votos; 0,36%) e Francisco Gonzaga (PSTU, 2.187 votos; 0,17%). Para a Câmara Municipal de Fortaleza são eleitos 43 vereadores, sendo Célio Studart (SD) o mais votado.</li><li>Em Caucaia, a disputa vai pela primeira vez ao segundo turno entre Naumi Gomes de Amorim (PMB, 73.316 votos; 48,10%) e Eduardo de Castro Pessoa Lima (PSDB, 48.450 votos; 31,79%).</li><li>Nos principais polos do interior e Região Metropolitana (eleitos em turno único): em Sobral, elege-se Ivo Ferreira Gomes (PDT, 57.908 votos; 51,44%); em Juazeiro do Norte, elege-se Arnon Cruz Bezerra (PTB, 55.538 votos; 42,72%); no Crato, elege-se José Ailton de Sousa Brasil — Zé Ailton Brasil (PP, 37.740 votos; 58,78%); em Quixadá, elege-se pela quarta vez José Ilário Gonçalves Marques — Ilário Marques (PT, 25.469 votos; 56,94%); em Iguatu, elege-se Ednaldo de Lavor Couras — Ednaldo Lavor (PDT, 31.557 votos; 60,09%); e em Maracanaú, reelege-se José Firmo Camurça Neto — Firmo Camurça (PR, 81.315 votos; 72,10%).</li></ul>","c":["Política e Instituições"],"l":0},{"id":"ce-2016-10-0188","y":2016,"m":10,"d":"14","h":"O governador Camilo Santana sanciona a Lei Estadual nº 16.124, que cria a Delegacia de Defesa da Mulher de Icó; e a Lei Estadual nº 16.128, que amplia a certificação do Selo Município Verde no Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-10-0189","y":2016,"m":10,"d":"20","h":"Morre em sua residência, em Fortaleza, aos 51 anos de idade, vítima de neoplasia cerebral, o radialista, repórter e apresentador de televisão Ergamênio Viana Pinto (consagrado artisticamente como Ênio Carlos). Filho de José Marques Pinto e Maria Izete Pinto, iniciou a carreira na Rádio Cultura de Aracati e atuou em Fortaleza nas rádios Verdes Mares, Assunção e Cidade, na TV Verdes Mares, na Rede Manchete e, desde 1998, na TV Diário, onde comandou por 18 anos o Programa Ênio Carlos. Após velório na Funerária Ethernus, em Fortaleza, o corpo foi sepultado em sua terra natal. Nascera em Aracati, CE, em 25/02/1965.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-10-0190","y":2016,"m":10,"d":"30","h":"Realiza-se o segundo turno das Eleições Municipais em Fortaleza e Caucaia:<br><ul class='ef-sublist'><li>Em Fortaleza, é reeleito prefeito Roberto Cláudio Rodrigues Bezerra (PDT), tendo Moroni Bing Torgan (DEM) como vice-prefeito, com 678.847 votos (53,57% dos votos válidos), superando o deputado estadual Capitão Wagner (PR), que obteve 588.451 votos (46,43%).</li><li>Em Caucaia, é eleito prefeito o deputado estadual Naumi Gomes de Amorim (PMB), tendo Lívia Arruda como vice-prefeita, com 80.756 votos (54,23% dos votos válidos), derrotando Eduardo Pessoa (PSDB, 68.149 votos; 45,77%).</li></ul>","c":["Política e Instituições"],"l":0},{"id":"ce-2016-11-0191","y":2016,"m":11,"d":"01","h":"Morre no Instituto do Câncer do Ceará (ICC), em Fortaleza, aos 73 anos de idade, vítima de câncer renal, o professor universitário, filósofo, teólogo, sociólogo, escritor e ex-reitor Plácido Cidade Nuvens. Graduado em Filosofia pelo Seminário da Prainha, mestre em Teologia pela Pontifícia Universidade Gregoriana (Roma) e doutor em Ciências Sociais pela Pontifícia Universidade Santo Tomás de Aquino (Roma), foi prefeito de Santana do Cariri (1983–1988), gestão na qual fundou em 1985 o Museu de Paleontologia de Santana do Cariri, marco da preservação dos fósseis da Bacia do Araripe e embrião do Geopark Araripe. Na Universidade Regional do Cariri (URCA), foi professor titular, vice-reitor (1996–2003) e reitor (2007–2011). Agraciado com o Troféu Sereia de Ouro (2008), teve seu nome eternizado pela ciência em três espécies fósseis descobertas no Cariri (Santanaraptor placidus, Cearachelys placidoi e Arariphrynus placidoi). Foi sepultado no dia 02 (Dia de Finados) em sua terra natal. Nascera em Santana do Cariri, CE, em 23/10/1943.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-11-0192","y":2016,"m":11,"d":"02","h":"Culminância da tradicional Romaria de Finados (Romaria da Esperança) em Juazeiro do Norte, reunindo cerca de 600 mil romeiros na Capela do Perpétuo Socorro, Basílica de Nossa Senhora das Dores e Colina do Horto.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-11-0193","y":2016,"m":11,"d":"05","h":"O governador Camilo Santana sanciona a Lei Estadual nº 16.133 (DOE de 28/11/2016), que institui a Medalha José de Alencar do Mérito Cultural Cearense.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-11-0194","y":2016,"m":11,"d":"18","h":"O prefeito Roberto Cláudio sanciona a Lei Municipal nº 10.544, instituindo o Sistema de Museus de Fortaleza (SIMFOR), vinculado à Secultfor.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-11-0195","y":2016,"m":11,"d":"23","h":"Sancionadas três leis estaduais de toponímia (DOE de 25/11/2016): a Lei nº 16.136, denominando Francisco Nailton Cavalcante de Lima a Escola de Ensino Médio de Aquiraz; a Lei nº 16.137, denominando José Erivaldo Alves da Costa o Ginásio Poliesportivo da EEM São Sebastião, em Apuiarés; e a Lei nº 16.138, denominando Avenida Maria Muniz Gomes de Mattos o trecho da rodovia CE-386 no Crato (Batateiras). Na mesma data, a Lei Estadual nº 16.135 concede o Título de Cidadão Cearense ao empresário sergipano João Carlos Paes Mendonça, presidente do Grupo JCPM (empreendedor do Shopping RioMar Kennedy, inaugurado em Fortaleza em outubro de 2016).","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-11-0196","y":2016,"m":11,"d":"25","h":"Em solenidade na Reitoria da Universidade Federal do Ceará (UFC), o reitor Henry de Holanda Campos outorga o título de Professor Emérito da UFC ao físico Josué Mendes Filho, primeiro pesquisador da Física no Ceará a alcançar o nível 1A do CNPq.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-12-0197","y":2016,"m":12,"d":"12","h":"O prefeito Roberto Cláudio e o governador Camilo Santana inauguram a primeira etapa do Residencial Alameda das Palmeiras, no bairro Ancuri (Pedras), em Fortaleza, entregando 2.032 unidades habitacionais populares.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-12-0198","y":2016,"m":12,"d":"14","h":"Sancionada pelo governador Camilo Santana a Lei Estadual nº 16.146, que institui a Política Estadual sobre Mudanças Climáticas (PEMC); a Lei Estadual nº 16.148, que denomina José Ciro Nogueira Machado a Escola Estadual de Educação Profissional de Solonópole; e a Lei Estadual nº 16.150, que inclui a Procissão de Nossa Senhora das Candeias (Juazeiro do Norte) no Calendário Turístico Oficial do Ceará.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-12-0199","y":2016,"m":12,"d":"14 a 16","h":"As Juntas Eleitorais do TRE-CE realizam as cerimônias de diplomação dos prefeitos, vice-prefeitos e vereadores eleitos nos polos do interior, incluindo Ednaldo Lavor em Iguatu (dia 14), Zé Ailton Brasil no Crato, Arnon Bezerra em Juazeiro do Norte e Ivo Ferreira Gomes em Sobral (dia 16).","c":["Política e Instituições"],"l":0},{"id":"ce-2016-12-0200","y":2016,"m":12,"d":"19","h":"À tarde, no Centro de Eventos do Ceará, o Tribunal Regional Eleitoral do Ceará (TRE-CE), sob a presidência do desembargador Antônio Abelardo Benevides Moraes, realiza a solenidade de diplomação do prefeito reeleito de Fortaleza Roberto Cláudio Rodrigues Bezerra (PDT), do vice-prefeito eleito Moroni Bing Torgan (DEM) e dos 43 vereadores eleitos para a legislatura 2017–2020.","c":["Política e Instituições"],"l":0},{"id":"ce-2016-12-0201","y":2016,"m":12,"d":"23","h":"Sancionadas duas leis estaduais de toponímia rodoviária: a Lei nº 16.166, denominando José Pereira Rodrigues a rodovia CE-470 entre Icó e Orós; e a Lei nº 16.172, denominando Francisca Josué de Souza Carneiro o trecho da rodovia CE-371 entre Acopiara e Deputado Irapuan Pinheiro.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-12-0202","y":2016,"m":12,"d":"26","h":"Para enfrentar a severa escassez hídrica e garantir o abastecimento da Grande Fortaleza, o Governo do Estado inaugura o Sistema de Captação Pressurizada (estação flutuante) no Açude Gavião, enquanto o Açude Castanhão encerra o ano com cerca de 6% de seu volume total.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2016-12-0203","y":2016,"m":12,"d":"27","h":"Sancionada a Lei Estadual nº 16.173, denominando Paulo Eduardo Queiroz de Aguiar a Escola de Ensino Médio localizada no município de Pacajus.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-12-0204","y":2016,"m":12,"d":"28","h":"O Papa Francisco aceita a renúncia apresentada por Dom Fernando Panico, MSC (que passa à condição de bispo emérito), ao governo pastoral da Diocese de Crato, assumindo automaticamente como sexto bispo diocesano de Crato o então bispo coadjutor Dom Gilberto Pastana de Oliveira. Na mesma data, são sancionadas a Lei Estadual nº 16.184, denominando Professora Rosângela Albuquerque de Couto a EEEP de Itarema, e a Lei Estadual nº 16.194, denominando Maria Helena Russo a EEEP de Redenção.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2016-12-0205","y":2016,"m":12,"d":"29","h":"O governador Camilo Santana sanciona a Lei Estadual nº 16.198, marco da geografia política e cartográfica elaborado pela Assembleia Legislativa, IPECE e IBGE, que fixa por georreferenciamento os novos limites intermunicipais de 133 municípios do Estado do Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2016-12-0206","y":2016,"m":12,"d":"30","h":"O prefeito Roberto Cláudio inaugura a última etapa do complexo viário da Avenida Raul Barbosa, no bairro Aerolândia/Tauape, em Fortaleza, entregando a rotatória central e a passarela sobre o Canal do Lagamar, junto aos dois viadutos e à ponte estaiada.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-01-0207","y":2017,"m":1,"d":"01","h":"Entra em vigor em todo o território nacional o novo valor do Salário Mínimo de R$ 937,00 mensais, fixado pelo Decreto Federal nº 8.948/2016, repercutindo nas tabelas de remuneração pública estadual e municipal do Ceará.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-01-0208","y":2017,"m":1,"d":"01","h":"No Plenário Fausto Arruda da Câmara Municipal de Fortaleza, tomam posse solene o médico Roberto Cláudio Rodrigues Bezerra (Roberto Cláudio, PDT) no cargo de Prefeito Municipal de Fortaleza, para o segundo mandato consecutivo, e o delegado federal e ex-deputado federal Moroni Bing Torgan (Moroni Torgan, DEM) no cargo de Vice-Prefeito, juntamente com os 43 vereadores eleitos para a 18ª Legislatura (2017–2020), inicialmente presidida pelo vereador mais votado, Célio Studart (SD). No mesmo ato, o vereador João Salmito Filho (Salmito Filho, PDT) é reeleito, por unanimidade, Presidente da Mesa Diretora da Câmara Municipal para o biênio 2017–2018.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-01-0209","y":2017,"m":1,"d":"01","h":"Nos principais municípios polos do interior cearense e da Região Metropolitana, tomam posse os novos chefes do Poder Executivo e as respectivas Câmaras Municipais para o quadriênio 2017–2020: em Sobral, o ex-deputado estadual Ivo Ferreira Gomes (Ivo Gomes, PDT) e a vice-prefeita Christianne Marie Aguiar Coelho (PT); em Juazeiro do Norte, o médico e ex-deputado federal José Arnon Cruz Bezerra de Menezes (Arnon Bezerra, PTB) e o vice Giovanni Sampaio Gondim (PSD); no Crato, o administrador José Ailton de Sousa Brasil (Zé Ailton Brasil, PP) e o vice Raimundo André de Sousa Barreto (André Barreto, PDT); em Barbalha, Argemiro Sampaio Neto (PSDB) e o vice Francisco Sandoval Barreto de Alencar (DEM); em Caucaia, o ex-deputado estadual Naumi Gomes de Amorim (PMB); em Quixadá, o advogado e ex-deputado José Ilário Gonçalves Marques (Ilário Marques, PT); em Iguatu, o empresário Ednaldo de Lavor Couras (Ednaldo Lavor, PDT) e o vice Marcos Sobreira; e em Russas, o prefeito reeleito Raimundo Weber de Araújo (Weber Araújo, PRB).","c":["Política e Instituições"],"l":0},{"id":"ce-2017-01-0210","y":2017,"m":1,"d":"10","h":"No Palácio da Luz, sede histórica da Academia Cearense de Letras (ACL), toma posse solene como sócio efetivo o médico neurocirurgião, professor da Faculdade de Medicina da Universidade Federal do Ceará (UFC), membro da Academia Cearense de Medicina e escritor Francisco Flávio Leitão de Carvalho (Flávio Leitão). O novel acadêmico passa a ocupar a Cadeira nº 34, patroneada pelo médico e escritor Samuel Uchoa, preenchendo a vaga aberta com o falecimento de José Telles da Silva (José Telles). Nascera em Fortaleza, CE, a 21/04/1939.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-01-0211","y":2017,"m":1,"d":"13","h":"O Governador Camilo Sobreira de Santana edita o Decreto Estadual nº 32.130, instituindo a Carta Eletrônica de Serviços ao Cidadão e denominando Acesso Cidadão o portal unificado de controle social e serviços públicos estaduais.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-01-0212","y":2017,"m":1,"d":"16","h":"Falece no município de São Gonçalo do Amarante, na Região Metropolitana de Fortaleza, o capitão da reserva do Exército Brasileiro Francisco Elinor Procópio de Castro. Foi líder histórico e articulador do movimento cívico de emancipação do distrito do Pecém e expressiva figura comunitária do Litoral Oeste cearense.","c":["Necrologia"],"l":0},{"id":"ce-2017-01-0213","y":2017,"m":1,"d":"17","h":"Falece aos 87 anos de idade, no Hospital São Camilo de Crateús, o sacerdote católico, professor e memorialista José Helênio Oliveira Pereira (Padre Helênio). Ordenado sacerdote em 1953, foi um dos pilares históricos e coordenador de pastoral da Diocese de Crateús durante o bispado de Dom Antônio Batista Fragoso, atuando no magistério e na defesa das comunidades sertanejas em Novo Oriente, Tamboril e Crateús. O velório realiza-se na Igreja Matriz de Senhor do Bonfim e o sepultamento na Cripta dos Sacerdotes do Cemitério São Miguel, em Crateús. Era natural de Cariré, CE, nascido a 15/04/1929.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-01-0214","y":2017,"m":1,"d":"19","h":"Falece pela manhã, em Fortaleza, aos 86 anos de idade, o sacerdote da Congregação da Missão (Lazaristas) Hendrikus Gerardus Mestrom (Padre Hermano Mestrom). Ordenado na Holanda em 1956, chegou ao Ceará em 1957, atuando no Seminário Cura d'Ars (Limoeiro do Norte), na conclusão do Colégio São Vicente de Paulo (Antônio Bezerra, Fortaleza), como vigário de Santo Antônio de Quixeramobim (a partir de 1967) e por quase três décadas como pároco da Igreja de Nossa Senhora dos Remédios, no tradicional bairro do Benfica, destacando-se pela ação evangelizadora e de apoio social às famílias da capital. Após velório na Capela São José Operário (Parque Araxá), foi sepultado em Fortaleza. Era natural de Geleen, Limburgo, Holanda, nascido em 10/03/1930.","c":["Necrologia"],"l":0},{"id":"ce-2017-01-0215","y":2017,"m":1,"d":"31","h":"Em sessão solene realizada no Palácio da Justiça Desembargador Agenor Studart, no Centro Administrativo do Cambeba, toma posse a nova cúpula diretiva do Tribunal de Justiça do Estado do Ceará (TJCE) para o biênio 2017–2019. Assume a Presidência o desembargador Francisco Gladyson Pontes (Gladyson Pontes, natural de Jaguaruana, CE), tendo como Vice-Presidente o desembargador Washington Luis Bezerra de Araújo e como Corregedor-Geral da Justiça o desembargador Francisco Darival Beserra Primo, sucedendo à gestão da desembargadora Maria Iracema Martins do Vale.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-02-0216","y":2017,"m":2,"d":"01","h":"No Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará (ALCE), toma posse a Mesa Diretora para o biênio 2017–2018: o deputado José Jácome Carneiro Albuquerque (Zezinho Albuquerque, PDT) assume a Presidência da Casa pelo terceiro biênio consecutivo, tendo como 1º Vice-Presidente Tin Gomes (PHS), 2º Vice-Presidente Manoel Duca (PDT) e 1º Secretário Audic Mota (PMDB).","c":["Política e Instituições"],"l":0},{"id":"ce-2017-02-0217","y":2017,"m":2,"d":"01","h":"Falece às 20h, aos 87 anos de idade, no Hospital Monte Klinikum, em Fortaleza, em decorrência de complicações de acidente vascular cerebral, o escultor, desenhista, gravador e ilustrador Sérvulo Esmeraldo. Iniciou sua trajetória na década de 1940 na Sociedade Cearense de Artes Plásticas (SCAP) e radicou-se em Paris em 1957, consagrando-se internacionalmente como mestre da escultura geométrica e da arte cinética (criador dos Excitables). Integrou o patrimônio visual cearense com dezenas de monumentos públicos em Fortaleza e no Cariri, com destaque para o Monumento ao Barco na Avenida Beira-Mar e as esculturas na Praça da Sé, Praça Portugal e Parque do Cocó. O velório ocorre na Capela do Palácio da Abolição, com honras de Estado, e o sepultamento no Cemitério Parque da Paz. O Governador do Estado decreta luto oficial de três dias. Era cearense do Crato, nascido a 27/02/1929.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-02-0218","y":2017,"m":2,"d":"02","h":"No Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará (ALCE), sob a presidência do deputado José Albuquerque, realiza-se a sessão solene de abertura dos trabalhos legislativos do ano de 2017, com a leitura da mensagem governamental pelo Governador Camilo Sobreira de Santana (Camilo Santana), prestando contas das ações do Executivo e detalhando as metas para a segurança e convivência com a estiagem.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-02-0219","y":2017,"m":2,"d":"02","h":"Encerra-se em Juazeiro do Norte, na Região do Cariri, a tradicional Romaria de Nossa Senhora das Candeias, reunindo cerca de 250 mil romeiros procedentes de diversos estados nordestinos, com a solene procissão da luz pelas principais artérias da cidade.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-02-0220","y":2017,"m":2,"d":"15","h":"Falece no bairro Bom Jardim, em Fortaleza, aos 42 anos de idade, vítima de brutal homicídio qualificado praticado por grupo de agressores, a travesti Dandara dos Santos (Dandara Kettley). A violência do crime, registrada em vídeo e veiculada internacionalmente, gera profunda comoção social e repercussão jurídica mundial, transformando-se em marco na mobilização de direitos humanos, impulsionando políticas estaduais e municipais de proteção à população LGBTQIA+ no Ceará e resultando na condenação dos agressores pelo Tribunal do Júri de Fortaleza.","c":["Necrologia"],"l":0},{"id":"ce-2017-02-0221","y":2017,"m":2,"d":"23","h":"O Governador Camilo Santana sanciona a Lei Estadual nº 16.200, regulamentando o Fundo Penitenciário do Estado do Ceará (FUNPEN/CE). No dia seguinte (24), é promulgada em Fortaleza a Lei Municipal nº 10.559, instituindo a Política Municipal de Proteção dos Direitos da Pessoa com Transtorno do Espectro Autista (TEA).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-02-0222","y":2017,"m":2,"d":"24","h":"O Governo do Estado do Ceará entrega as obras de duplicação do trecho da rodovia estadual CE-040 compreendido entre a sede do município de Beberibe e a localidade de Paripueira, totalizando 32 quilômetros de pistas duplicadas e pontes sobre os rios locais, melhoria estruturante para o Litoral Leste cearense.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-02-0223","y":2017,"m":2,"d":"25 a 28","h":"Realiza-se o Carnaval de Fortaleza de 2017, com polos oficiais na Praia de Iracema, Praça do Ferreira, Mercado dos Pinhões e o tradicional desfile na Avenida Domingos Olímpio, sagrando-se campeões o Maracatu Nação Iracema (sábado), o Maracatu Vozes da África (domingo), o Afoxé Filhos de Oyá, o Cordão Vampiros da Princesa, o Bloco A Turma do Mamão e a Escola de Samba Unidos do Acaracuzinho.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-03-0224","y":2017,"m":3,"d":"02","h":"A Companhia Cearense de Transportes Metropolitanos (Metrofor) amplia em uma hora diária a operação comercial das 18 estações da Linha Sul do Metrô de Fortaleza (entre o Centro e Pacatuba).","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-03-0225","y":2017,"m":3,"d":"04","h":"Em sessão magna realizada no Palácio Jeremias Arruda, na Praça do Carmo em Fortaleza, toma posse formal a nova Diretoria do Instituto do Ceará (Histórico, Geográfico e Antropológico) para a gestão do biênio 2017–2019. Assume a Presidência da Casa do Barão de Studart o médico, escritor, memorialista e ex-governador do Estado Lúcio Gonçalo de Alcântara (Lúcio Alcântara), tendo como Vice-Presidente a professora e historiadora Angela Maria Rossas Mota de Gutiérrez e como Secretário-Geral o médico e economista Marcelo Gurgel Carlos da Silva.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-03-0226","y":2017,"m":3,"d":"10","h":"Inaugurado oficialmente na Rua Frederico Borges nº 545, no bairro Varjota, em Fortaleza, o Museu da Fotografia Fortaleza (MFF). Idealizado e mantido pela Fundação Paula e Silvio Frota, o equipamento cultural ocupa prédio de cinco pavimentos com projeto arquitetônico moderno assinado por Marcus Novais, abrigando um dos acervos mais expressivos da América Latina, com obras originais de mestres como Sebastião Salgado, Henri Cartier-Bresson, Steve McCurry e Chico Albuquerque.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-03-0227","y":2017,"m":3,"d":"14","h":"Falece em Fortaleza, aos 78 anos de idade, o médico e ex-deputado estadual Francisco Neves Osterno (Toba Osterno). Liderança política de destacada atuação na Região Norte do Estado, foi prefeito municipal de Marco e exerceu mandatos parlamentares na Assembleia Legislativa do Ceará, sendo sepultado em sua terra natal.","c":["Necrologia","Política e Instituições"],"l":0},{"id":"ce-2017-03-0228","y":2017,"m":3,"d":"16","h":"Na Bolsa de Valores B3, em São Paulo, o consórcio alemão Fraport AG Frankfurt Airport Services Worldwide sagra-se vencedor do leilão internacional de concessão do Aeroporto Internacional de Fortaleza (Aeroporto Pinto Martins), com oferta de R$ 425 milhões em outorga inicial e compromisso de investimentos na ampliação do terminal de passageiros e extensão da pista de pouso.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-03-0229","y":2017,"m":3,"d":"16","h":"Falece na cidade do Rio de Janeiro, aos 98 anos de idade, o jurista, magistrado e Procurador de Justiça aposentado Francisco Habib Otoch. Formado pela Faculdade de Direito do Ceará, exerceu destacada folha de serviços na consultoria jurídica e no Ministério Público fluminense, mantendo vínculos com a terra natal. Nascera em Fortaleza, CE, em 04/07/1918.","c":["Necrologia"],"l":0},{"id":"ce-2017-03-0230","y":2017,"m":3,"d":"17","h":"O Governador Camilo Santana sanciona a Lei Estadual nº 16.207 (DOE de 10/04/2017), reestruturando o sistema remuneratório da Polícia Militar (PMCE) e do Corpo de Bombeiros Militar do Ceará (CBMCE).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-03-0231","y":2017,"m":3,"d":"20","h":"Falece na madrugada, na Região do Cariri, aos 52 anos de idade, vítima de câncer, a arqueóloga, historiadora, cantora e gestora cultural Rosiane Limaverde Vilar Mendonça (Rosiane Limaverde). Graduada em História pela URCA e doutora em Arqueologia pela Universidade de Coimbra, fundou em 1992, em Nova Olinda (CE), ao lado do companheiro Francisco Alemberg de Souza Lima (Alemberg Quindins), a Fundação Casa Grande – Memorial do Homem Kariri, referência internacional em educação patrimonial e arqueologia social inclusiva, tendo recebido a Ordem do Mérito Cultural (2004). Seu corpo foi velado no Cariri e cremado no dia 21. Nascera no Crato, CE, em 19/12/1964.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-03-0232","y":2017,"m":3,"d":"25 e 26","h":"Comemora-se a Data Magna dos 133 anos da Abolição da Escravidão no Ceará (25 de março de 1884). No Palácio da Abolição, o Governador Camilo Santana preside a entrega conjunta da Medalha da Abolição, agraciando as personalidades dos biênios 2016 e 2017: o ex-governador e ex-ministro Ciro Ferreira Gomes (Ciro Gomes); o ministro do Superior Tribunal de Justiça (STJ) Napoleão Nunes Maia Filho; o empresário industrial Carlos Francisco Ribeiro Jereissati (Carlos Jereissati); a jornalista e educadora Luiza de Teodoro Vieira; o médico psiquiatra e ensaísta Valton de Miranda Leitão; e o compositor, folclorista e criador da Fundação Casa Grande de Nova Olinda, Francisco Alemberg de Souza Lima (Alemberg Quindins).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-03-0233","y":2017,"m":3,"d":"30","h":"A Assembleia Legislativa expede o Autógrafo de Lei nº 24/2017 (convertido na Lei Estadual nº 16.229/2017), denominando Rodovia Padre José Maria Cavalcante Costa o trecho da rodovia CE-464 entre a sede de Ocara e o distrito de Antônio Diogo, em Redenção.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-03-0234","y":2017,"m":3,"d":"31","h":"Em sessão solene no Plenário Fausto Arruda da Câmara Municipal de Fortaleza, presidida pelo vereador Salmito Filho, é conferida a Medalha Boticário Ferreira ao Promotor de Justiça Marcus Renan Palácio de Morais Claro dos Santos, titular da 1ª Promotoria de Justiça do Júri da Comarca de Fortaleza, em reconhecimento à sua atuação no Ministério Público do Estado do Ceará.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-04-0235","y":2017,"m":4,"d":"03","h":"Sancionada pelo Governador Camilo Santana a Lei Estadual nº 16.208, reformando a organização administrativa do Tribunal de Justiça do Ceará (TJCE), da Diretoria do Fórum Clóvis Beviláqua e da Escola Superior da Magistratura do Ceará (ESMEC).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-04-0236","y":2017,"m":4,"d":"03","h":"Falece à tarde, em Fortaleza, aos 68 anos de idade, vítima de complicações cardíacas, o radialista Oséas Moraes, com longa atuação na Rádio Campo Maior AM de Quixeramobim e na imprensa da capital, sendo sepultado no dia 04 no Cemitério São João Batista.","c":["Necrologia"],"l":0},{"id":"ce-2017-04-0237","y":2017,"m":4,"d":"11","h":"Falece na madrugada, em Fortaleza, aos 72 anos de idade, o físico, pesquisador e Professor Emérito da Universidade Federal do Ceará (UFC) Josué Mendes Filho. Graduado em Física pela UFC (1967), mestre pela UnB e doutor pela Unicamp (1984), fundou o laboratório de Espectroscopia Raman da UFC, consolidou a pós-graduação em Física no nível máximo da CAPES (nota 7), foi o primeiro físico no Ceará a atingir o nível 1A do CNPq e recebeu a Ordem Nacional do Mérito Científico (2010). A Reitoria da UFC decretou luto oficial de três dias, sendo sepultado no Cemitério Parque da Paz. Nascera em 1945.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-04-0238","y":2017,"m":4,"d":"13","h":"Fortaleza comemora os 291 anos de sua elevação a Vila (13 de abril de 1726), com show aberto de Raimundo Fagner no Aterrinho da Praia de Iracema. Na mesma data, o Prefeito Roberto Cláudio assina e faz publicar no Diário Oficial do Município (DOM) o Decreto Municipal que formaliza o tombamento preventivo e as diretrizes de preservação do patrimônio histórico-cultural da orla marítima e do sítio arquitetônico do bairro Praia de Iracema.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-04-0239","y":2017,"m":4,"d":"17","h":"O Governador Camilo Santana sanciona duas leis estaduais de toponímia (publicadas no DOE de 19/04/2017): a Lei nº 16.218, que denomina Empresário Mauro Petri Gonçalves Feitosa o viaduto da Avenida Maestro Lisboa (rodovia CE-025) sobre a Avenida Washington Soares, em Fortaleza; e a Lei nº 16.223, que denomina Monsenhor José Aloysio Pinto a Escola Estadual de Educação Profissional (EEEP) localizada no município de Sobral.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-04-0240","y":2017,"m":4,"d":"20","h":"Em meio a uma sequência de ataques criminosos contra o transporte coletivo na periferia de Fortaleza, um ônibus da empresa Viação Siará Grande (Linha 382 - Parque Jerusalém) é atacado e incendiado no bairro Canindezinho. O cobrador José Nunes de Sousa Neto, usuário de cadeira de rodas que exercia suas funções no veículo, sofre graves queimaduras em 90% do corpo ao não conseguir evacuar a tempo, falecendo dias depois no Instituto Doutor José Frota (IJF), fato que deflagra paralisações e reforço de segurança nos terminais.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-04-0241","y":2017,"m":4,"d":"30","h":"Falece às 06h, aos 70 anos de idade, no Hospital Santa Cruz, no município de Santa Cruz do Sul, no Rio Grande do Sul, vítima de rompimento de um aneurisma da aorta, o cantor, compositor, poeta e artista plástico Antônio Carlos Gomes Belchior Fontenelle Fernandes (Belchior). Integrante basilar do célebre movimento sociocultural do \"Pessoal do Ceará\" na década de 1970, ao lado de Fagner, Ednardo e Amelinha, consagrou-se como uma das vozes poéticas mais universais e contundentes da Música Popular Brasileira, autor do álbum Alucinação (1976) e de clássicos atemporais como Como Nossos Pais, Mucuripe, Apenas um Rapaz Latino-Americano, Velha Roupa Colorida, Medo de Avião e Paralelas. O Governador Camilo Santana decreta luto oficial de três dias em todo o Estado do Ceará. O corpo é trasladado em voo fretado, sendo velado inicialmente no Theatro São João, em Sobral, e em seguida sob grande comoção de milhares de admiradores no Theatro José de Alencar, em Fortaleza, com celebração exequial por Dom José Antônio Aparecido Tosi Marques e no Centro Dragão do Mar. O sepultamento realiza-se no dia 2 de maio no Cemitério Parque da Paz, no jazigo da família. Nascera em Sobral, CE, em 26/10/1946.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-05-0242","y":2017,"m":5,"d":"01 e 02","h":"Realizam-se as honras fúnebres populares de despedida do poeta e compositor Belchior no Theatro São João (em Sobral), no Theatro José de Alencar e no Centro Dragão do Mar (em Fortaleza), culminando com o sepultamento no Cemitério Parque da Paz sob o canto coletivo de milhares de admiradores.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-05-0243","y":2017,"m":5,"d":"03","h":"Na Arena Castelão, em Fortaleza, perante 40.311 espectadores, o Ceará Sporting Club conquista o título de Campeão Cearense de 2017 ao derrotar o Ferroviário Atlético Clube por 2 a 0 na partida de volta da grande final (gols de Wallace Pernambucano e Raul Cáceres), após haver vencido o jogo de ida por 1 a 0, assegurando o seu 44º troféu estadual sob o comando técnico de Givanildo Oliveira.","c":["Esportes"],"l":0},{"id":"ce-2017-05-0244","y":2017,"m":5,"d":"05","h":"Falece aos 76 anos de idade, em Fortaleza, o professor e ensaísta Marcondes Rosa de Sousa. Docente aposentado do Departamento de Letras Vernáculas da Universidade Federal do Ceará (UFC), teve relevante trajetória no movimento docente cearense e na fundação do Partido da Social Democracia Brasileira (PSDB) no Estado, desempenhando funções de liderança política e assessoria técnica em administrações estaduais e municipais.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-05-0245","y":2017,"m":5,"d":"10","h":"Falece pela manhã, aos 83 anos de idade, no Hospital Regional da Unimed em Fortaleza, em decorrência de complicações respiratórias, a desembargadora Águeda Passos Rodrigues Martins. Figura pioneira no Judiciário cearense, foi a segunda mulher a ingressar como Desembargadora do Tribunal de Justiça do Estado do Ceará (TJCE) e a primeira a assumir a Presidência do Tribunal Regional Eleitoral do Ceará (TRE-CE), no biênio 1999–2000, além de ter exercido a direção da Escola Superior da Magistratura do Estado do Ceará (Esmec). O velório ocorre com honras fúnebres na Capela Nossa Senhora de Fátima, no Palácio da Justiça, e o sepultamento no Cemitério Parque da Paz. O Tribunal de Justiça decreta luto oficial de três dias. Era natural de Viçosa do Ceará, nascida a 21/07/1933.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-05-0246","y":2017,"m":5,"d":"12","h":"Falece aos 89 anos de idade (90 anos incompletos), em Fortaleza, o desembargador aposentado Francisco de Assis Nogueira (Assis Nogueira). Ingressou na magistratura cearense em 1958, judicando em comarcas do interior como Coreaú, Tianguá, Massapê, Crateús e Crato, e nas 6ª e 9ª Varas Criminais de Fortaleza, até ascender a desembargador do Tribunal de Justiça do Estado do Ceará (TJCE) em 1989, onde permaneceu até a aposentadoria em 1997. Sepultamento no Cemitério Parque da Paz. Nascera em Elesbão Veloso, PI, em 04/10/1927.","c":["Necrologia","Política e Instituições"],"l":0},{"id":"ce-2017-05-0247","y":2017,"m":5,"d":"15","h":"O Governador Camilo Santana inaugura a Estação Juscelino Kubitschek, na Avenida João Pessoa nº 6.460 (Demócrito Rocha/Parangaba), 19ª estação da Linha Sul do Metrô de Fortaleza (Metrofor).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-05-0248","y":2017,"m":5,"d":"18","h":"A Prefeitura Municipal de Fortaleza e a Secretaria da Cultura de Fortaleza (Secultfor) inauguram na Praia de Iracema o Centro Cultural Belchior (CCBel), instalado em imóvel histórico requalificado no Calçadão da Praia de Iracema, destinado à memória do compositor sobralense e a atividades musicais e culturais da juventude da capital.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-05-0249","y":2017,"m":5,"d":"21","h":"Falece aos 58 anos de idade, em Fortaleza, o sacerdote católico Francisco José dos Santos Chaves (Padre Franzé). Incardinado na Arquidiocese de Fortaleza, exerceu expressivo trabalho de evangelização e assistência aos enfermos em paróquias e pastorais das cidades de Fortaleza, Caucaia e Maracanaú, destacando-se como capelão hospitalar. O sepultamento dá-se no Cemitério São João Batista.","c":["Necrologia"],"l":0},{"id":"ce-2017-05-0250","y":2017,"m":5,"d":"25","h":"Falece em Fortaleza o Procurador Regional da República e professor universitário Francisco de Araújo Macedo Filho. Titular do Departamento de Direito Público da Faculdade de Direito da Universidade Federal do Ceará (UFC), exerceu por longos anos o Ministério Público Federal (MPF) na Seção Judiciária do Ceará e como Procurador Regional Eleitoral junto ao TRE-CE. A Faculdade de Direito da UFC decretou luto oficial de três dias, sendo sepultado no Cemitério Parque Jardim Metropolitano, no Eusébio.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-05-0251","y":2017,"m":5,"d":"26","h":"Falece pela manhã, aos 80 anos de idade, em sua residência no bairro Meireles, em Fortaleza, o jurista, filósofo, advogado e professor emérito Arnaldo Vasconcelos. Titular fundador da Cadeira nº 1 da Academia Cearense da Língua Portuguesa (ACLP) e membro do Instituto do Ceará, foi livre-docente da Faculdade de Direito da Universidade Federal do Ceará (UFC) e fundador e diretor do Programa de Pós-Graduação em Direito da Universidade de Fortaleza (Unifor). Considerado internacionalmente um dos expoentes da Filosofia e Epistemologia do Direito no Brasil, formulador de leituras originais da obra de Hans Kelsen e autor de obras consagradas como Teoria Pura do Direito: Repensando a Teoria Kelseniana e Direito, Humanismo e Democracia. O velório realiza-se na Funerária Ternura e o sepultamento no Cemitério Parque da Paz. Era cearense de Camocim, nascido a 18/04/1937.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-05-0252","y":2017,"m":5,"d":"29","h":"Falece pela manhã, em hospital de Fortaleza, aos 71 anos de idade, vítima de insuficiência renal aguda, o sanfoneiro e subtenente reformado da Banda de Música da PMCE Clementino Moura, consagrado no meio musical cearense como o Rei da Gafieira.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-06-0253","y":2017,"m":6,"d":"04","h":"O Governador Camilo Santana assina o Decreto Estadual nº 32.248, oficializando a regulamentação definitiva da poligonal e a consolidação do Parque Estadual do Cocó como Unidade de Conservação de Proteção Integral. Com área delimitada de 1.571 hectares cruzando diversos bairros de Fortaleza, o ato histórico atende a mais de quatro décadas de lutas ambientalistas, unificando os ecossistemas de manguezal e dunas sob salvaguarda do Estado.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-06-0254","y":2017,"m":6,"d":"04","h":"Realiza-se em Barbalha, no Cariri, o solene cortejo e o hasteamento do mastro na tradicional Festa do Pau da Bandeira de Santo Antônio de Barbalha, reconhecida como Patrimônio Cultural Imaterial Brasileiro pelo IPHAN, reunindo mais de 300 mil pessoas.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-06-0255","y":2017,"m":6,"d":"05","h":"No Salão do Pleno do Tribunal de Justiça do Estado do Ceará, toma posse solene a nova Presidência do Tribunal Regional Eleitoral do Ceará (TRE-CE) para o biênio 2017–2019. Assume a Presidência a desembargadora Maria Nailde Pinheiro Nogueira (Nailde Pinheiro), tendo como Vice-Presidente e Corregedor Regional Eleitoral o desembargador Haroldo Correia de Oliveira Máximo, sucedendo à diretoria presidida pelo desembargador Antônio Abelardo Benevides Moraes.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-06-0256","y":2017,"m":6,"d":"12","h":"A Prefeitura Municipal de Fortaleza entrega oficialmente ao tráfego o viaduto da Avenida Engenheiro Santana Júnior sobre a Avenida Padre Antônio Tomás, obra de arte viária complementar aos binários da Aldeota e Papicu, liberando o fluxo de veículos para o corredor de ônibus leste-oeste e eliminando semáforos históricos na entrada do Parque do Cocó.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-06-0257","y":2017,"m":6,"d":"19","h":"Falece às 21h18min, no Hospital Cura d'Ars, em Fortaleza, aos 94 anos de idade, o sacerdote católico e professor universitário Monsenhor Antônio Souto Ribeiro da Silva (Monsenhor Souto). Ordenado no Seminário da Prainha em 1946 por Dom Antônio de Almeida Lustosa, foi pároco de Pacatuba (1948–1964), reitor do Seminário Menor (1964–1967), pároco de São Vicente de Paulo (1971–1980) e de Messejana (1980–1990), professor da UFC, Vigário-Geral da Arquidiocese de Fortaleza por quase 18 anos (1990–2008) e Administrador Arquidiocesano durante a sede vacante de 1998–1999. Foi velado na Capela de Nossa Senhora da Conceição do Seminário da Prainha. Nascera em Teresina, PI, em 13/06/1923.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-06-0258","y":2017,"m":6,"d":"21","h":"Falece às 10h20min, no Hospital Monte Klinikum, em Fortaleza, aos 84 anos de idade, vítima de parada cardiorrespiratória, a advogada, procuradora federal aposentada, jornalista e escritora Wanda Palhano Xavier Pereira (Wanda Palhano), diretora-presidente do jornal O Estado. Filha de Joacy Gonçalves Palhano e Cecy de Holanda, graduou-se em Direito pela UFC e em Jornalismo pelo CEUB, tornando-se a primeira mulher a exercer o cargo de Procuradora-Geral do DNOCS e a primeira mulher eleita para o Conselho Seccional da OAB-CE. Assumiu a presidência do jornal O Estado em 1996 (após o falecimento do esposo Venelouis Xavier Pereira) e ocupava a Cadeira nº 7 da Academia Cearense de Literatura e Jornalismo (ACLJ). Após velório na Funerária Ethernus, foi sepultada no dia 22 no Cemitério Parque da Paz. Nascera em Jataizinho, PR, em 1932.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-06-0259","y":2017,"m":6,"d":"26","h":"O Prefeito Roberto Cláudio sanciona a Lei Municipal nº 10.591, criando o Conselho Municipal de Proteção Urbana de Fortaleza (CMPFOR).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-06-0260","y":2017,"m":6,"d":"30","h":"Inaugurado oficialmente em Fortaleza, nas dependências históricas do campus do Benfica, o Memorial do Instituto Federal de Educação, Ciência e Tecnologia do Ceará (IFCE) - Dr. Raimundo César Gadelha Alencar Araripe, reunindo mais de um século de acervo bibliográfico, maquinários e documentos da secular Escola de Aprendizes Artífices, criada em 1909 por decreto do presidente Nilo Peçanha.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-07-0261","y":2017,"m":7,"d":"02","h":"Falece às 23h30min, aos 70 anos de idade, no Hospital Monte Klinikum, em Fortaleza, em decorrência de complicações de câncer pulmonar e parada cardiorrespiratória, o economista, industrial, mecenas e dirigente educacional Airton José Vidal Queiroz (Chanceler Airton Queiroz). Primogênito dos fundadores Edson Queiroz e Yolanda Vidal Queiroz, presidiu o Grupo Edson Queiroz e atuou por 35 anos como Chanceler da Universidade de Fortaleza (Unifor), transformando-a em polo acadêmico de excelência. Notabilizou-se como um dos maiores colecionadores e mecenas de artes visuais do país, responsável pela criação do Espaço Cultural Unifor e do Teatro Celina Queiroz, e por trazer ao Ceará exposições internacionais de mestres da pintura e escultura, recebendo em 2011 o título de Doutor Honoris Causa pela Universidade do Havre (França). O velório realiza-se no Complexo Velatório Jardim Metropolitano, no Eusébio, e o Governador do Estado decreta luto oficial de três dias em todo o Ceará. Era natural de Fortaleza, nascido a 14/08/1946.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-07-0262","y":2017,"m":7,"d":"13","h":"Inaugura-se no Núcleo de Pesquisa e Desenvolvimento de Medicamentos (NPDM) da Faculdade de Medicina da UFC, em Fortaleza, sob a coordenação dos médicos e pesquisadores Manoel Odorico de Moraes Filho e Edmar Maciel Lima Júnior, o primeiro Banco de Pele Animal do Brasil, voltado ao processamento de pele de tilápia-do-nilo para tratamento de vítimas de queimaduras no Instituto Dr. José Frota (IJF).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-07-0263","y":2017,"m":7,"d":"14","h":"O Prefeito de Fortaleza, Roberto Cláudio, assina a ordem de serviço para o início das escavações do túnel longitudinal da Avenida Santos Dumont sob a Avenida Desembargador Moreira e entrega as intervenções viárias do binário das avenidas Dom Luís e Santos Dumont, modernizando a circulação no polo financeiro da Aldeota.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-07-0264","y":2017,"m":7,"d":"20","h":"Em Juazeiro do Norte, celebra-se a missa e a solene romaria em memória dos 83 anos de falecimento do Padre Cícero Romão Batista, atraindo mais de 350 mil peregrinos de todo o Nordeste à Colina do Horto e à Basílica Menor de Nossa Senhora das Dores.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-07-0265","y":2017,"m":7,"d":"21","h":"Toma posse na Academia Cearense de Retórica (ACR), em sessão solene no Palácio da Luz, o desembargador aposentado Ademar Mendes Bezerra.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-07-0266","y":2017,"m":7,"d":"25","h":"Inicia-se em Fortaleza a Operação Assistida com passageiros do Veículo Leve sobre Trilhos (VLT) Parangaba–Mucuripe (Linha Nordeste), operando inicialmente ao longo de 5 km e quatro estações entre a Parangaba e a Avenida Borges de Melo, com composições fabricadas pela empresa cearense Bom Sinal, de Barbalha.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-08-0267","y":2017,"m":8,"d":"02","h":"Toma posse a nova gestão superior da Fundação Edson Queiroz, em Fortaleza, assumindo a presidência Lenise Queiroz Rocha, a vice-presidência Manoela Queiroz Bacelar e o cargo de Chanceler da Universidade de Fortaleza (Unifor) o administrador Edson Queiroz Neto.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-08-0268","y":2017,"m":8,"d":"11","h":"A Ordem dos Advogados do Brasil - Secção Ceará (OAB-CE) celebra no Theatro José de Alencar a solenidade magna do Dia do Advogado e os 84 anos de instalação da seccional no Estado, outorgando a Medalha Advogado Padrão a veteranos juristas da capital e do interior com mais de três décadas de conduta ilibada na advocacia.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-08-0269","y":2017,"m":8,"d":"11","h":"O Prefeito Roberto Cláudio sanciona a Lei Complementar Municipal nº 236 (DOM nº 16.078), instituindo a nova Lei de Parcelamento, Uso e Ocupação do Solo (LPUOS) do Município de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-08-0270","y":2017,"m":8,"d":"14","h":"Sancionado pelo Prefeito Roberto Cláudio pacote de leis municipais de toponímia e patrimônio cultural: a Lei nº 10.596, denominando José Cabral da Silva o CRAS do bairro Mucuripe; a Lei nº 10.598, declarando Patrimônio Cultural Imaterial de Fortaleza a tradicional Caminhada com Maria (realizada anualmente a 15 de agosto, dia da padroeira Nossa Senhora da Assunção); a Lei nº 10.599, denominando Regina Maria da Silva Severino o Posto de Saúde do bairro Parque Jerusalém; e a Lei nº 10.600, denominando Maria Cirino de Souza o Posto de Saúde do bairro Moura Brasil.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-08-0271","y":2017,"m":8,"d":"16","h":"A Mesa Diretora da Assembleia Legislativa do Estado do Ceará promulga a histórica Emenda Constitucional Estadual nº 92 (DOE de 21/08/2017), que extingue definitivamente o Tribunal de Contas dos Municípios do Estado do Ceará (TCM-CE), transferindo seu acervo, servidores e competências de fiscalização das prefeituras e câmaras municipais para o Tribunal de Contas do Estado do Ceará (TCE-CE).","c":["Política e Instituições"],"l":0},{"id":"ce-2017-08-0272","y":2017,"m":8,"d":"18","h":"O Governador Camilo Santana entrega a nova sede do Batalhão de Policiamento de Rondas e Ações Intensivas e Ostensivas (BPRaio) no município de Iguatu, no Centro-Sul cearense, consolidando a estratégia de interiorização de grupamentos táticos motorizados em cidades polo com mais de 50 mil habitantes.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-08-0273","y":2017,"m":8,"d":"30","h":"No ápice do sexto ano consecutivo de seca severa (2012–2017) — a mais longa estiagem da série histórica cearense —, os 155 açudes monitorados pela Cogerh operam com média geral de 10,8% da capacidade, enquanto o Açude Castanhão atinge a marca crítica de 4,34% de seu volume total.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-09-0274","y":2017,"m":9,"d":"09","h":"Falece à noite, em São Paulo, SP, aos 44 anos de idade, vítima de câncer de medula óssea, o empresário e político Eduardo de Castro Pessoa Lima (Eduardo Pessoa). Natural da localidade de Carauçanga, em Caucaia, exerceu quatro mandatos de vereador e disputou o segundo turno da eleição para prefeito de Caucaia em 2016 pelo PSDB.","c":["Necrologia","Política e Instituições"],"l":0},{"id":"ce-2017-09-0275","y":2017,"m":9,"d":"13","h":"O Governador Camilo Santana sanciona a Lei Estadual nº 16.322, instituindo o Plano de Cultura Infância do Ceará; e a Lei Estadual nº 16.331, denominando Rodovia Deputado Chagas Vasconcelos o trecho da rodovia CE-232 entre Ipaguassu Mirim (Massapê) e a sede de Santana do Acaraú.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-09-0276","y":2017,"m":9,"d":"15","h":"Culmina em Juazeiro do Norte a tradicional Romaria de Nossa Senhora das Dores, padroeira do município, com solene procissão de carros andores e bênção do chapéu presidida pelo bispo diocesano Dom Gilberto Pastana de Oliveira.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-09-0277","y":2017,"m":9,"d":"22 a 29","h":"No Theatro José de Alencar, realiza-se a solenidade da 47ª edição do Troféu Sereia de Ouro, promovida pelo Sistema Verdes Mares e Grupo Edson Queiroz. São agraciados com a tradicional comenda: a biofarmacêutica e ativista Maria da Penha Maia Fernandes (Maria da Penha); o arquiteto, urbanista, historiador e professor emérito da UFC José Liberal de Castro; o médico cirurgião e pioneiro de transplantes hepáticos no Ceará Dr. José Huygens Parente Garcia; e o Ministro-Presidente do Superior Tribunal Militar (STM) José Coêlho Ferreira.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-09-0278","y":2017,"m":9,"d":"23","h":"Em Minas Gerais, o Fortaleza Esporte Clube enfrenta o Tupi (MG) na partida de volta das quartas de final e, com o placar agregado de 2 a 1, assegura o acesso à Série B do Campeonato Brasileiro após oito temporadas consecutivas na terceira divisão nacional, desencadeando massiva celebração popular pelas ruas da capital cearense, sob a presidência de Luís Eduardo Girão e o comando técnico de Antônio Carlos Zago.","c":["Esportes"],"l":0},{"id":"ce-2017-09-0279","y":2017,"m":9,"d":"25","h":"O Prefeito Roberto Cláudio dá posse a 288 diretores escolares da rede pública municipal de ensino de Fortaleza, aprovados mediante seleção pública de mérito técnico.","c":["Política e Instituições"],"l":0},{"id":"ce-2017-10-0280","y":2017,"m":10,"d":"03","h":"Falece aos 64 anos de idade, em sua residência em Fortaleza, vítima de infarto agudo do miocárdio, o compositor, cantor, pianista e arranjador Sérgio de Souza Sá (Sérgio Sá). Cego de nascença, foi considerado um dos mais prodigiosos instrumentistas e arranjadores cearenses, autor de canções de grande sucesso gravadas por Tim Maia, Roberto Carlos, Simone, Vanusa e Fábio Jr., destacando-se ainda pelo trabalho em defesa da acessibilidade e inclusão cultural de pessoas com deficiência. Era cearense de Fortaleza, nascido a 20/09/1953.","c":["Necrologia"],"l":0},{"id":"ce-2017-10-0281","y":2017,"m":10,"d":"04","h":"Encerra-se em Canindé, no Sertão Central, a tradicional Festa e Romaria de São Francisco das Chagas, com a multitudinária procissão de São Francisquinho acompanhada por centenas de milhares de devotos.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-10-0282","y":2017,"m":10,"d":"06","h":"O Prefeito Roberto Cláudio inaugura as obras de requalificação urbanística e viária da Rua José Avelino e da Avenida Alberto Nepomuceno, no Centro Histórico de Fortaleza.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-10-0283","y":2017,"m":10,"d":"10","h":"Sancionada pelo Prefeito Roberto Cláudio a Lei Municipal nº 10.619, veiculada no Diário Oficial do Município (DOM), dispondo sobre o Plano de Áreas Verdes e a instituição dos Parques Naturais Municipais de Fortaleza, estabelecendo diretrizes obrigatórias de arborização em loteamentos e obras públicas na capital.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-10-0284","y":2017,"m":10,"d":"11","h":"O Governador Camilo Santana sanciona a Lei Estadual nº 16.362, estendendo o Passe Livre Intermunicipal aos acompanhantes de pessoas com deficiência; e a Lei Estadual nº 16.372, autorizando o ingresso de sócio estratégico no capital social da Companhia de Desenvolvimento do Complexo Industrial e Portuário do Pecém (CIPP S.A.), marco legal que viabilizou a parceria com o Porto de Roterdã (Países Baixos).","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-10-0285","y":2017,"m":10,"d":"16","h":"O Governador Camilo Santana e o prefeito Naumi Amorim inauguram a nova Unidade de Pronto Atendimento (UPA 24h) da Grande Jurema, em Caucaia, elevando para 23 o total de UPAs em operação no Ceará.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-10-0286","y":2017,"m":10,"d":"21","h":"Após empatar em 0 a 0 com o CSA no Estádio Rei Pelé, em Maceió (AL), o Fortaleza Esporte Clube encerra o Campeonato Brasileiro da Série C de 2017 como vice-campeão nacional.","c":["Esportes"],"l":0},{"id":"ce-2017-10-0287","y":2017,"m":10,"d":"24","h":"Realiza-se em Santana do Cariri a 14ª Romaria da Menina Benigna Cardoso da Silva (1928–1941), reunindo cerca de 20 mil devotos na Matriz de Senhora Sant'Ana e no Memorial de Inhumas.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-11-0288","y":2017,"m":11,"d":"01","h":"O Prefeito Roberto Cláudio sanciona a Lei Municipal nº 10.638, denominando Laís de Sousa Vieira Nobre o Centro de Educação Infantil (CEI) localizado no bairro Ancuri.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-11-0289","y":2017,"m":11,"d":"02","h":"Culmina em Juazeiro do Norte a tradicional Romaria de Finados (Romaria da Esperança), reunindo centenas de milhares de romeiros na Capela do Socorro, Basílica de Nossa Senhora das Dores e Colina do Horto.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-11-0290","y":2017,"m":11,"d":"06","h":"Sancionada a Lei Ordinária Municipal nº 10.639, regulamentando os instrumentos urbanísticos e as diretrizes do Programa Municipal de Regularização Fundiária de Interesse Social (Reurb-S) de Fortaleza, permitindo a titulação cartorária definitiva de moradias para famílias de baixa renda em Zonas Especiais de Interesse Social (ZEIS).","c":["Legislação e Toponímia"],"l":0},{"id":"ce-2017-11-0291","y":2017,"m":11,"d":"14","h":"Publicada no Diário Oficial a Lei Estadual nº 16.397, que institui o novo Código de Divisão e Organização Judiciária do Estado do Ceará, aprovado pela Assembleia Legislativa a partir de proposta encaminhada pelo Pleno do Tribunal de Justiça (TJCE), redefinindo a jurisdição de comarcas vinculadas, criando novas varas especializadas e elevando a Comarca do Crato à condição de entrância final.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-11-0292","y":2017,"m":11,"d":"17","h":"Sancionada pelo Governador Camilo Santana a Lei Estadual nº 16.404 (DOE de 21/11/2017), que denomina Generino Trajano Feitosa o trecho da rodovia CE-288 que liga o município de Granjeiro à Rodovia Padre Cícero.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-11-0293","y":2017,"m":11,"d":"18 e 25","h":"O Ceará Sporting Club conquista o acesso à Série A do Campeonato Brasileiro de Futebol (retornando à elite nacional após seis temporadas na Série B), sob a presidência de Robinson de Castro e o comando técnico de Marcelo Chamusca: garantido matematicamente no dia 18 com o empate em 1 a 1 diante do Criciúma (SC), o Alvinegro celebra a promoção no day 25, na Arena Castelão, diante de 56.005 pagantes, ao vencer o ABC de Natal por 1 a 0 (gol de Pedro Ken).","c":["Esportes"],"l":0},{"id":"ce-2017-11-0294","y":2017,"m":11,"d":"26","h":"Falece às 17h15min, no Hospital Público Municipal São Sebastião, em sua terra natal, Pedra Branca, no Sertão Central, aos 79 anos de idade, vítima de pneumonia associada à doença de Alzheimer, o bispo emérito de Iguatu Dom José Doth de Oliveira (Dom José Doth). Estudou no Seminário da Prainha e foi ordenado sacerdote em 1964. Nomeado bispo coadjutor de Palmares (PE) em 1989 e de Iguatu em 1991, assumiu como 2º Bispo Diocesano de Iguatu em 26/07/2000 (sucedendo a Dom José Mauro Ramalho), permanecendo até janeiro de 2009 e legando a construção da monumental Sé Catedral de São José de Iguatu (inaugurada em 2006). Foi sepultado no dia 29 na Sé Catedral de São José, em Iguatu, após missa exequial presidida pelo arcebispo Dom José Antonio Tosi Marques. Nascera em Pedra Branca, CE, em 01/03/1938.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-11-0295","y":2017,"m":11,"d":"30","h":"Sancionada a Lei Estadual nº 16.426 (DOE de 04/12/2017), denominando Professora Maria Neli Sobreira de Oliveira o viaduto localizado na vertente da rodovia CE-060 sobre a Avenida Paulo Maia, no município de Juazeiro do Norte.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-12-0296","y":2017,"m":12,"d":"05","h":"Sancionada a Lei Estadual nº 16.430, que denomina Francisca Pinto dos Santos a Escola de Educação Básica do Campo situada no Assentamento Antônio Conselheiro, no município de Ocara.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-12-0297","y":2017,"m":12,"d":"09","h":"O Governador Camilo Santana e o prefeito Ilário Marques inauguram em Quixadá, na Rua Pascoal Crispino nº 167 (Centro), a Casa de Saberes Cego Aderaldo, equipamento cultural da Secretaria da Cultura do Estado dedicado à memória do poeta popular Cego Aderaldo (1878–1967) e às tradições do Sertão Central.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-12-0298","y":2017,"m":12,"d":"12","h":"Sancionada pelo Governador Camilo Santana a Lei Estadual nº 16.448, que institui o Prêmio Foco na Aprendizagem para bonificação de servidores e docentes da rede estadual com base nos índices do Spaece.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-12-0299","y":2017,"m":12,"d":"19","h":"O Governador Camilo Santana sanciona importante bloco de leis estruturantes e de toponímia para o Estado (publicadas no DOE de 26 e 28/12/2017): a Lei nº 16.455, criando os Centros Cearenses de Idiomas (CCI) na rede pública estadual; a Lei nº 16.467, instituindo o Plano de Cargos, Carreira e Vencimentos (PCCV) dos servidores técnico-administrativos das três universidades estaduais (UECE, URCA e UVA); a Lei nº 16.484, denominando Rodovia Deputado Joaquim Noronha Mota a rodovia CE-010 em toda a sua extensão; a Lei nº 16.489, denominando Francisco Gomes da Silva Louro o trecho da rodovia CE-166 entre Cariús e Farias Brito; a Lei nº 16.495, denominando Francisco Assis Alves (Chico Maia) a rodovia CE-166/475 no trecho entre Senador Pompeu, Piquet Carneiro e Acopiara; a Lei nº 16.496, denominando Francisco Miguel de Andrade a Escola de Ensino Médio de Campos Sales; e a Lei nº 16.498, denominando José Barbosa Filho o açude Umari, na localidade de Salgadinho, no município de Madalena.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2017-12-0300","y":2017,"m":12,"d":"20","h":"O Prefeito Roberto Cláudio sanciona a Lei Municipal nº 10.651, denominando Aírton José Vidal Queiroz o Centro de Educação Infantil (CEI) localizado no bairro Alto da Balança, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-12-0301","y":2017,"m":12,"d":"20","h":"Falece aos 87 anos de idade, em Fortaleza, em decorrência de complicações de saúde e causas naturais, o escritor, poeta, jornalista, ensaísta e professor emérito Carlos Neves d'Alge (Carlos d'Alge). Radicado no Brasil aos 6 anos de idade, graduou-se em Direito, Letras e Educação pela Universidade Federal do Ceará (UFC), onde foi chefe de gabinete do reitor fundador Antônio Martins Filho, professor titular de Literatura Portuguesa, diretor do Centro de Humanidades, fundador da Casa de Cultura Portuguesa e o primeiro Pró-Reitor de Extensão da história da UFC (1969–1971). Ex-presidente da Academia Cearense da Língua Portuguesa (ACLP) e membro efetivo da Academia Cearense de Letras (ACL), teve intensa atividade na crítica literária e na preservação da memória luso-brasileira, autor de obras consagradas como Aspectos da Nova Literatura Portuguesa, Terra do Mar Grande, A Experiência Futurista e a Geração de Orpheu e O Sal da Escrita, tendo recebido o grau de Comendador da Ordem da Instrução Pública de Portugal (1987) e o Título de Cidadão Cearense (2001). Após velório na Funerária Ternura, o sepultamento realiza-se no Cemitério Parque da Paz, tendo a UFC decretado luto oficial de três dias. Nascera em Chaves, Distrito de Vila Real (Trás-os-Montes), Portugal, a 24/07/1930.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2017-12-0302","y":2017,"m":12,"d":"22","h":"O Governador Camilo Santana sanciona a Lei Estadual nº 16.468 (DOE da mesma data), que estima a receita e fixa a despesa do Estado do Ceará para o exercício financeiro de 2018 (LOA 2018); na mesma data, o Governo do Estado entrega 560 unidades habitacionais populares no bairro Jangurussu, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":0},{"id":"ce-2017-12-0303","y":2017,"m":12,"d":"28","h":"A Prefeitura Municipal de Fortaleza entrega oficialmente à população o novo viaduto da Avenida Aguanambi sobre a Avenida Dom Manuel, intervenção viária de grande porte com pistas exclusivas para transporte coletivo e passagem inferior de tráfego, eliminando congestionamentos históricos no acesso ao Centro de Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-01-0304","y":2018,"m":1,"d":"01","h":"Entra em vigor em todo o território nacional o novo valor do Salário Mínimo de R$ 954,00 mensais, fixado pelo Decreto Federal nº 9.255, de 29 de dezembro de 2017, com impacto direto nas tabelas salariais estaduais e municipais do Ceará.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-01-0305","y":2018,"m":1,"d":"04","h":"Toma posse em sessão solene do Colégio de Procuradores de Justiça, reconduzido ao cargo de Procurador-Geral de Justiça do Estado do Ceará (<a href=\"https://mpce.mp.br/placido-rios-toma-posse-como-procurador-geral-de-justica-e-anuncia-prioridades-para-o-proximo-bienio/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">MPCE</a>) para o biênio 2018–2019, o procurador Plácido Barroso Rios.","c":["Política e Instituições"],"l":1},{"id":"ce-2018-01-0306","y":2018,"m":1,"d":"08","h":"O prefeito de Fortaleza, Roberto Cláudio Rodrigues Bezerra (Roberto Cláudio), assina decreto de tombamento definitivo do imóvel do antigo Lord Hotel, situado na Praça José de Alencar, no Centro da Capital, assegurando a preservação da arquitetura moderna da década de 1950 e destinando o edifício para equipamentos públicos de cidadania e assistência social.","c":["Política e Instituições"],"l":0},{"id":"ce-2018-01-0307","y":2018,"m":1,"d":"27","h":"Na madrugada, no estabelecimento comercial de festas \"Forró do Gago\", na Rua Madre Tereza de Calcutá, no bairro Cajazeiras, em Fortaleza, ocorre a maior chacina da história da segurança pública do Ceará, resultando no assassinato a tiros de 14 pessoas e ferimentos em outras 15 em decorrência de confronto territorial entre facções criminosas. O episódio gera intensa comoção e repercussão nacional, motivando o envio de reforços federais e profunda reestruturação nas ações de inteligência e ocupação policial das periferias de Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-02-0308","y":2018,"m":2,"d":"01","h":"A Assembleia Legislativa do Estado do Ceará (ALCE) realiza no Plenário 13 de Maio a sessão solene de abertura dos trabalhos legislativos do ano de 2018, sob a presidência do deputado José Albuquerque (Zezinho Albuquerque, PDT), recebendo a mensagem governamental do governador Camilo Sobreira de Santana (Camilo Santana), prestando contas dos investimentos estaduais em educação e anunciando pacote extraordinário de medidas para a segurança pública.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-02-0309","y":2018,"m":2,"d":"02","h":"Culmina em Juazeiro do Norte a tradicional Romaria de Nossa Senhora das Candeias, reunindo cerca de 200 mil fiéis em torno da Basílica Menor de Nossa Senhora das Dores e no Memorial Padre Cícero.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-02-0310","y":2018,"m":2,"d":"10 a 13","h":"Realiza-se o Carnaval de Fortaleza de 2018 com apresentações dos blocos tradicionais na Praça da Gentilândia, Mocinha e Aterro da Praia de Iracema, além dos desfiles oficiais dos maracatus cearenses, blocos, cordões, afoxés e escolas de samba na Avenida Domingos Olímpio.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-02-0311","y":2018,"m":2,"d":"15","h":"Na reserva indígena dos Tapebas, próxima à Lagoa da Encantada, no município de Aquiraz, na Região Metropolitana de Fortaleza, são executados em emboscada planejada Rogério Jeremias de Simone (\"Gegê do Mangue\") e Fabiano Alves de Souza (\"Paca\"), principais lideranças nacionais da facção criminosa paulista Primeiro Comando da Capital (PCC). A execução com uso de helicóptero tem repercussão nacional imediata e deflagra operações conjuntas da Polícia Civil do Ceará e da Polícia Federal sobre a lavagem de dinheiro no litoral cearense.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-02-0312","y":2018,"m":2,"d":"22","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16505\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.505</a>, de 22 de fevereiro de 2018, que altera a Organização Judiciária do Estado para criar a Vara de Delitos de Organizações Criminosas na Comarca de Fortaleza e disciplinar a instalação da Vara Única da Comarca de Ocara (<a href=\"https://www.tjce.jus.br/noticias/juiz-promovido-por-criterio-de-merecimento-toma-posse-no-forum-clovis-bevilaqua/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TJCE</a>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2018-03-0313","y":2018,"m":3,"d":"03 e 04","h":"O governador Camilo Santana inaugura as primeiras unidades do <a href=\"https://g1.globo.com/ce/ceara/noticia/centros-de-idiomas-terao-aulas-de-lingua-estrangeiras-gratuitas-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro Cearense de Idiomas (CCI)</a>, instaladas no Shopping Benfica, em Fortaleza, e no Centro de Crateús, dando início à rede estadual gratuita de ensino de línguas estrangeiras (inglês, espanhol e francês) para estudantes da rede pública.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-03-0314","y":2018,"m":3,"d":"08","h":"A Secretaria da Justiça e Cidadania (Sejus), sob gestão da secretária Socorro França, inaugura em Juazeiro do Norte as novas instalações do <a href=\"https://www.ce.gov.br/sap/2018/03/06/sejus-inaugura-em-juazeiro-do-norte-novo-nucleo-de-tornozelamento/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Núcleo de Monitoração Eletrônica da Região do Cariri</a>, integrando a rede interiorizada ao lado das unidades de Quixadá, Sobral e Iguatu.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-03-0315","y":2018,"m":3,"d":"09","h":"No bairro Benfica, tradicional polo universitário e cultural de Fortaleza, ataque a tiros perpetrado em diferentes vias do entorno da Praça da Gentilândia e da sede da torcida organizada Cearamor deixa sete pessoas mortas e três feridas, na denominada Chacina do Benfica. O fato desencadeia manifestações da comunidade acadêmica da Universidade Federal do Ceará (UFC) e reforço contínuo do policiamento ostensivo no bairro.","c":["Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-03-0316","y":2018,"m":3,"d":"12","h":"O governador Camilo Santana sanciona, no Palácio da Abolição, a <a href=\"https://www.ce.gov.br/2018/03/12/governador-sanciona-lei-que-garante-adicional-de-insalubridade-de-20-para-agentes-de-saude-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">lei estadual que garante o pagamento de adicional de insalubridade de 20%</a> aos cerca de 9 mil agentes comunitários de saúde vinculados ao Estado em 183 municípios cearenses.","c":["Política e Instituições"],"l":1},{"id":"ce-2018-03-0317","y":2018,"m":3,"d":"19","h":"Morre em Fortaleza, aos 66 anos, vítima de infarto fulminante, o empresário, advogado, presidente do Grupo Cidade de Comunicação (TV Cidade) e 1º suplente de senador <a href=\"https://diariodonordeste.verdesmares.com.br/metro/morre-miguel-dias-de-souza-presidente-do-grupo-cidade-de-comunicacao-1.1910926\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Miguel Dias de Souza</a>. No dia 20 de março, a Assembleia Legislativa do Ceará decreta luto oficial de três dias em sua memória.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2018-03-0318","y":2018,"m":3,"d":"23","h":"O governador Camilo Santana e o prefeito Roberto Cláudio entregam <a href=\"https://www.ce.gov.br/2018/03/22/governador-e-prefeito-entregam-944-apartamentos-do-residencial-jose-euclides-ferreira-gomes/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">944 apartamentos da 3ª etapa do Residencial José Euclides Ferreira Gomes</a>, no bairro Jangurussu, em Fortaleza, totalizando 2.992 unidades habitacionais no complexo.","c":["Política e Instituições"],"l":1},{"id":"ce-2018-03-0319","y":2018,"m":3,"d":"24","h":"No Palácio da Abolição e nos equipamentos culturais do Estado, realizam-se as solenidades alusivas à Data Magna do Ceará e à <a href=\"https://pt.wikipedia.org/wiki/Medalha_da_Aboli%C3%A7%C3%A3o\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha da Abolição</a> (cuja outorga referente ao ciclo bienal 2018–2019 foi entregue em 29 de novembro de 2019).","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-03-0320","y":2018,"m":3,"d":"25","h":"Comemora-se a Data Magna do Ceará (134 anos da Abolição da Escravidão no Ceará em 25 de março de 1884), com solenidades em Redenção, berço abolicionista, e conferências na Casa de Juvenal Galeno e no Instituto do Ceará.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-03-0321","y":2018,"m":3,"d":"26","h":"Morre no Hospital de Messejana, em Fortaleza, aos 76 anos, em decorrência de falência múltipla dos órgãos após complicações de pneumonia, o cantor e compositor cearense de forró <a href=\"https://pt.wikipedia.org/wiki/Messias_Holanda\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Manuel Messias Holanda da Silva (Messias Holanda)</a>, imortalizado pelos clássicos Pra Tirar Coco e Mariá. Nascera em Missão Velha, CE, em janeiro de 1942.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-03-0322","y":2018,"m":3,"d":"28","h":"Pela manhã, em Fortaleza, o governador Camilo Santana, o prefeito Roberto Cláudio e o ministro das Cidades Alexandre Baldy inauguram 2.960 apartamentos da 2ª etapa do Residencial Alameda das Palmeiras, no bairro Ancuri; à tarde, no município de Quixadá, inauguram o <a href=\"https://www.ce.gov.br/2018/03/28/sertao-central-cerca-de-seis-mil-pessoas-recebem-moradias-em-quixada/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Residencial Rachel de Queiroz</a>, conjunto habitacional com 1.454 casas, escola, creche e CRAS para cerca de 6 mil moradores no Sertão Central.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-03-0323","y":2018,"m":3,"d":"28","h":"Morre aos 84 anos de idade, em Fortaleza, o desembargador aposentado <a href=\"https://www.tjce.jus.br/noticias/nota-de-falecimento-29/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Ari Cisne</a>. Graduado em Direito pela UFC (1961), ingressou na magistratura em 1962 como juiz em Boa Viagem, ascendeu ao Tribunal de Justiça do Estado do Ceará (TJCE) em 1990, dirigiu o Fórum Clóvis Beviláqua (1992), presidiu o TJCE no biênio 1995–1996 e exerceu a Corregedoria-Geral da Justiça em 1997 (<a href=\"https://acmag.org.br/2018/03/nota-de-falecimento-jose-ari-cisne/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ACM</a>). O velório realiza-se no Palácio da Justiça e o sepultamento no Cemitério Parque da Paz. Nascera em Fortaleza, CE, a 03 de abril de 1933.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-04-0324","y":2018,"m":4,"d":"02","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16530.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.530</a>, de 2 de abril de 2018, que reestrutura o modelo de assistência à saúde do Instituto de Saúde dos Servidores do Estado do Ceará (ISSEC).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2018-04-0325","y":2018,"m":4,"d":"06","h":"Em cumprimento ao prazo de desincompatibilização estabelecido pela legislação eleitoral para quem pretende disputar as eleições gerais de 2018, diversos secretários de Estado e dirigentes de autarquias deixam seus cargos no Governo do Estado do Ceará. O governador Camilo Santana e a vice-governadora Izolda Cela confirmam permanência nos postos para concorrer à reeleição no pleito de outubro.","c":["Política e Instituições"],"l":0},{"id":"ce-2018-04-0326","y":2018,"m":4,"d":"08","h":"Na Arena Castelão, o Ceará Sporting Club sagra-se bicampeão estadual ao vencer o Fortaleza Esporte Clube por 2 a 1 na finalíssima do Campeonato Cearense de 2018, diante de mais de 40 mil torcedores.","c":["Esportes"],"l":0},{"id":"ce-2018-04-0327","y":2018,"m":4,"d":"13","h":"Comemoração dos 292 anos de elevação de Fortaleza à categoria de Vila (1726), com eventos culturais no Passeio Público e entrega de comendas no Teatro São José.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-04-0328","y":2018,"m":4,"d":"13","h":"Morre aos 61 anos de idade, em Fortaleza, a desembargadora <a href=\"https://www.tjce.jus.br/noticias/comissao-de-seguranca-presta-homenagem-in-memoriam-a-desembargadora-helena-lucia/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Helena Lúcia Soares</a>. Bacharela em Direito pela UFC (1979), ingressou na magistratura em 1986 como juíza em Bela Cruz, atuou em Pacatuba, Granja e na 15ª Vara Criminal de Fortaleza, e integrava a 4ª Câmara de Direito Privado do Tribunal de Justiça do Estado do Ceará (TJCE) desde outubro de 2014. O sepultamento ocorreu no Cemitério Parque da Paz. Nascera em Caucaia, CE, a 05 de janeiro de 1957, filha de Raimundo Nonato Soares e Terezinha David Soares. Na mesma data, morre em Fortaleza, aos 52 anos, o juiz de Direito <a href=\"https://www.tjce.jus.br/noticias/nota-de-falecimento-30/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Aristófanes Vieira Coutinho Júnior</a>, titular da 35ª Vara Cível da Comarca de Fortaleza, nascido a 18 de maio de 1965.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-05-0329","y":2018,"m":5,"d":"03","h":"Entra oficialmente em operação no Aeroporto Internacional Pinto Martins, em Fortaleza (sob administração da concessionária alemã Fraport Brasil), o Centro de Conexões (<a href=\"https://g1.globo.com/ce/ceara/noticia/centro-de-conexoes-da-air-france-klm-e-gol-comeca-a-operar-em-fortaleza-com-voos-internacionais.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hub Nordeste</a>) das companhias Air France-KLM e Gol Linhas Aéreas, consolidando a capital cearense como porta de entrada de voos entre a Europa e o Norte/Nordeste brasileiro (<a href=\"https://www.fortaleza.ce.gov.br/noticias/fortaleza-recebe-voos-inaugurais-do-hub-do-aeroporto-pinto-martins\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Fortaleza</a>). O marco inaugural é celebrado na pista com o batismo do voo direto da KLM procedente de Amsterdã (pousado às 16h58min) e do voo da Joon/Air France vindo de Paris (pousado às 17h22min, trazendo a bordo o governador Camilo Santana).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-05-0330","y":2018,"m":5,"d":"18","h":"É inaugurada oficialmente pelo Governo do Estado a nova sede da Delegacia de Defesa da Mulher (DDM) de Fortaleza, instalada nas dependências da Casa da Mulher Brasileira, no bairro Couto Fernandes. O complexo pioneiro unifica serviços da Polícia Civil, Tribunal de Justiça, Defensoria Pública, Ministério Público e acolhimento psicossocial para atendimento integral a mulheres em situação de violência.","c":["Política e Instituições"],"l":0},{"id":"ce-2018-05-0331","y":2018,"m":5,"d":"19","h":"Em Sobral, o governador Camilo Santana e o prefeito Ivo Gomes inauguram a 1ª etapa das obras de requalificação da <a href=\"https://www.cidades.ce.gov.br/2018/05/21/governo-do-ceara-inaugura-avenida-perimetral-de-sobral-e-anuncia-mais-investimentos-para-a-regiao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Avenida Perimetral de Sobral</a>, modernizando o principal corredor de tráfego e escoamento urbano da cidade, em solenidade realizada na Praça da Coluna da Hora.","c":["Política e Instituições"],"l":1},{"id":"ce-2018-05-0332","y":2018,"m":5,"d":"21","h":"Pela manhã, no município do Crato, o governador Camilo Santana e o prefeito Zé Ailton Brasil inauguram o <a href=\"https://www.ce.gov.br/cidades/2018/05/21/shopping-popular-e-inaugurado-no-crato/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Shopping Popular Belizário de Souza</a>, erguido para abrigar permissionários e feirantes no centro comercial cratense. No fim da tarde, em Juazeiro do Norte, Camilo Santana e o prefeito Arnon Bezerra inauguram a unidade caririense do <a href=\"https://www.newscariri.com.br/2018/05/centro-cearense-de-idiomas-cci-inaugurado-em-juazeiro-do-norte\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro Cearense de Idiomas (CCI)</a>, instalada no prédio requalificado do antigo Ginásio Municipal Antônio Xavier de Oliveira, no bairro São Miguel.","c":["Política e Instituições"],"l":1},{"id":"ce-2018-05-0333","y":2018,"m":5,"d":"22","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16562.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.562</a>, de 22 de maio de 2018, que cria a Superintendência de Pesquisa e Estratégia de Segurança Pública do Estado do Ceará (SUPESP), vinculada à SSPDS.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-05-0334","y":2018,"m":5,"d":"24","h":"É deflagrada em todo o país a greve dos caminhoneiros autônomos, provocando bloqueios em rodovias federais e estaduais no Ceará (BR-116, BR-222 e CE-040). O movimento paralisa por onze dias o transporte de cargas, gerando desabastecimento crítico de combustíveis nos postos, escassez de gás de cozinha e racionamento de frotas de ônibus na Capital e nas principais cidades do interior até a formalização de acordo para corredores sanitários de emergência.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-06-0335","y":2018,"m":6,"d":"03","h":"Em Barbalha, realiza-se o tradicional cortejo do Pau da Bandeira de Santo Antônio de Barbalha, reunindo devotos e pesquisadores da cultura popular no Cariri cearense.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-06-0336","y":2018,"m":6,"d":"08","h":"Toma posse em sessão solene na sede da Corte, como presidente do <a href=\"https://www.trt7.jus.br/index.php?option=com_content&view=article&id=3523:desembargador-plauto-da-silva-porto-toma-posse-como-presidente-do-trt-ce-nesta-sexta-feira-8-6&catid=152&Itemid=885\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Tribunal Regional do Trabalho da 7ª Região (TRT-CE)</a> para o biênio 2018–2020, o desembargador Plauto Carneiro Porto, ao lado da desembargadora Regina Gláucia Cavalcante Nepomuceno (vice-presidente) e do desembargador Emmanuel Teófilo Furtado (corregedor-regional).","c":["Política e Instituições"],"l":1},{"id":"ce-2018-06-0337","y":2018,"m":6,"d":"10","h":"Morre em Fortaleza, aos 85 anos, o cirurgião-dentista e professor <a href=\"https://diariodonordeste.verdesmares.com.br/metro/morre-jorio-da-escossia-renomado-dentista-do-ceara-1.1952639\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Jório Almir da Escóssia</a> (nascido em 1933), integrante da primeira turma graduada pela Faculdade de Odontologia da UFC e pioneiro da implantodontia osseointegrada no Ceará, sendo sepultado no Cemitério Parque da Paz.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-06-0338","y":2018,"m":6,"d":"11","h":"Morre aos 53 anos o sacerdote <a href=\"https://www.arquidiocesedefortaleza.org.br/nota-de-falecimento-do-padre-abner/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Pe. Abner Moreira de Almeida</a>, pároco da Paróquia de São João Batista em Acarape e vigário episcopal da Região Nossa Senhora da Palma. Nascera em Aquiraz, CE, a 15 de maio de 1965.","c":["Necrologia"],"l":1},{"id":"ce-2018-06-0339","y":2018,"m":6,"d":"13","h":"Entra em funcionamento no município de Iguatu, nas instalações reformadas do antigo CVT/Centec, no bairro Areias, a unidade centro-sul do <a href=\"https://maisfm.com/centro-cearense-de-idiomas-oferta-cursos-gratuitos-de-ingles-e-espanhol/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro Cearense de Idiomas (CCI)</a>.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-06-0340","y":2018,"m":6,"d":"17","h":"Morre em Fortaleza, aos 86 anos, o sacerdote missionário holandês <a href=\"https://www.arquidiocesedefortaleza.org.br/nota-de-falecimento-5/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Pe. Teodoro</a>, fundador e primeiro pároco da Paróquia Santíssima Trindade, criada em 1971 no Conjunto Prefeito José Walter.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2018-06-0341","y":2018,"m":6,"d":"21","h":"O prefeito Roberto Cláudio sanciona a <a href=\"https://urbanismoemeioambiente.fortaleza.ce.gov.br/images/urbanismo-e-meio-ambiente/legislacao-municipal/lei_complementar_n%C2%BA_250_de_03_de_julho_de_2018.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Municipal nº 10.754</a>, de 21 de junho de 2018, instituindo no Calendário Oficial de Fortaleza a Semana da Castração de Cães e Gatos.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2018-06-0342","y":2018,"m":6,"d":"26","h":"O prefeito Roberto Cláudio e a vice-governadora Izolda Cela inauguram, no bairro Mondubim, em Fortaleza, a <a href=\"https://www.ce.gov.br/vicegov/2018/06/26/vice-governadora-inaugura-escola-municipal-de-tempo-integral-no-mondubim/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Escola Municipal de Tempo Integral (ETI) Professora Hildete Brasil de Sá Cavalcante</a>.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-06-0343","y":2018,"m":6,"d":"27","h":"O Governo do Ceará inaugura as novas instalações da <a href=\"https://www.ce.gov.br/seduc/2018/06/27/governo-do-ceara-inaugura-nova-sede-da-escola-otavio-terceiro-de-farias-no-jose-walter/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Escola de Ensino Médio Otávio Terceiro de Farias</a>, no Conjunto Prefeito José Walter, em Fortaleza.","c":["Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-06-0344","y":2018,"m":6,"d":"28","h":"Realiza-se a sessão solene de encerramento do primeiro período da 4ª Sessão Legislativa da 29ª Legislatura na Assembleia Legislativa do Estado do Ceará e na Câmara Municipal de Fortaleza, com a aprovação da Lei de Diretrizes Orçamentárias (LDO) para o exercício de 2019 e balanço dos projetos de combate à seca e investimentos em mobilidade urbana.","c":["Política e Instituições"],"l":0},{"id":"ce-2018-06-0345","y":2018,"m":6,"d":"29","h":"O Governo do Estado, por meio da Secretaria dos Recursos Hídricos (SRH) e da Sohidra, inaugura a <a href=\"https://www.ce.gov.br/srh/governo-do-estado-realiza-ultima-inauguracao-do-ano-com-a-nova-adutora-em-independencia/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">nova adutora de montagem rápida do município de Independência</a>, com 27,6 km de extensão nos Sertões de Crateús.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-06-0346","y":2018,"m":6,"d":"30","h":"No Crato, o governador Camilo Santana, o prefeito Zé Ailton Brasil e o bispo diocesano Dom Gilberto Pastana inauguram as obras de urbanização e requalificação do entorno do <a href=\"https://www.ce.gov.br/2018/07/01/crato-horto-de-nossa-senhora-de-fatima-recebe-milhares-de-fieis-em-inauguracao-de-novo-espaco/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Santuário e Monumento de Nossa Senhora de Fátima</a>, no bairro Barro Branco (Horto do Crato).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-06-0347","y":2018,"m":6,"d":"30","h":"Falece em Brasília, DF, aos 81 anos de idade, o coronel da reserva do Exército <a href=\"http://academiacearense.blogspot.com/2018/07/nota-de-falecimento-clodoaldo-pinto.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Clodoaldo Pinto Filho</a>, filho do jurista, catedrático, ex-diretor da Faculdade de Direito da UFC e acadêmico Clodoaldo Pinto de Mesquita (1896–1979) e de Maria Nilda Saraiva, ex-chefe do Centro de Comunicação Social do Exército e diretor da Casa do Ceará em Brasília, sendo sepultado no Cemitério Campo da Esperança. Nascera em Fortaleza, CE, em 1937.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-07-0348","y":2018,"m":7,"d":"02","h":"O governador Camilo Santana e o prefeito Roberto Cláudio inauguram o novo <a href=\"https://fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-e-governador-camilo-santana-entregam-tunel-da-avenida-borges-de-melo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">túnel da Avenida Borges de Melo</a>, construído sob a via férrea do VLT Parangaba–Mucuripe, no bairro de Fátima, em Fortaleza. Na mesma data, morre em Fortaleza, aos 92 anos, o empresário <a href=\"https://photon.com.br/nota-de-falecimento-gerardo-bastos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Gerardo Gusmão Bastos (Gerardo Bastos)</a>, natural de Itapajé, CE, e decano do comércio automotivo no Estado (fundador do Centro Automotivo Gerardo Bastos em 1967).","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-07-0349","y":2018,"m":7,"d":"03","h":"O prefeito Roberto Cláudio sanciona a <a href=\"https://urbanismoemeioambiente.fortaleza.ce.gov.br/images/urbanismo-e-meio-ambiente/legislacao-municipal/lei_complementar_n%C2%BA_250_de_03_de_julho_de_2018.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Complementar Municipal nº 250</a>, de 3 de julho de 2018, atualizando dispositivos do Plano Diretor Participativo do Município de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2018-07-0350","y":2018,"m":7,"d":"05","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16588.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.588</a> (DOE de 09/07/2018), que institui o Dia Estadual do Trabalhador da Construção Civil em 24 de novembro, e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16602.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.602</a>, que institui a Política Estadual Cultura Viva.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-07-0351","y":2018,"m":7,"d":"06","h":"Pela manhã, em Quixadá, o governador Camilo Santana e o prefeito Ilário Marques inauguram a 4ª base fixa da <a href=\"https://revistacentral.com.br/dia-historico-quixada-e-regiao-central-ganham-base-da-ciopaer-com-helicoptero-altamente-equipado/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Coordenadoria Integrada de Operações Aéreas (Ciopaer)</a> no Ceará (3ª do interior, após Juazeiro do Norte e Sobral), instalada junto ao Aeroporto Regional do Sertão Central. À tarde, em Fortaleza, Camilo Santana e o prefeito Roberto Cláudio inauguram a expansão da operação assistida da <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeitura-e-governo-entregam-oito-das-dez-estacoes-do-vlt\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Linha Nordeste do VLT Parangaba–Mucuripe</a>, entregando mais 6,1 km de via férrea e quatro novas estações no trecho entre Borges de Melo e Papicu (São João do Tauape, Pontes Vieira, Antônio Sales e Papicu), totalizando 8 das 10 estações em funcionamento (<a href=\"https://www.ce.gov.br/metrofor/vltparangabamucuripe/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Metrofor</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-07-0352","y":2018,"m":7,"d":"16","h":"A Academia Cearense de Letras (ACL), sob a presidência do acadêmico Ubiratan Aguiar, realiza sessão especial no Palácio da Luz em comemoração aos 124 anos de fundação da instituição (fundada em 15 de agosto de 1894 como a pioneira do gênero no Brasil), promovendo lançamentos literários e conferência comemorativa sobre a literatura e a historiografia cearense.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-07-0353","y":2018,"m":7,"d":"19","h":"É sancionada a <a href=\"https://jurisnauta.com/vade-mecum/ceara/lei-estadual-ceara-16615-2018\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.615</a> (DOE de 19/07/2018), que denomina Abelardo Gurgel Costa Lima a rodovia CE-263, no trecho compreendido entre os municípios de Aracati e Jaguaruana, importante corredor agropecuário do Vale do Jaguaribe.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-07-0354","y":2018,"m":7,"d":"20","h":"Mais de 300 mil fiéis reúnem-se em Juazeiro do Norte para a celebração da tradicional Romaria do Padre Cícero, marcando o 84º aniversário de seu falecimento ocorrido em 1934.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-07-0355","y":2018,"m":7,"d":"27","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16644.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.644</a> (DOE de 27/07/2018), que denomina Maria Zenóbia Rodrigues Braga a Escola de Ensino Médio situada na Avenida das Dunas, no município de Caucaia. Na mesma data, toma posse como juiz titular da 35ª Vara Cível do Fórum Clóvis Beviláqua o magistrado <a href=\"https://www.tjce.jus.br/noticias/juiz-toma-posse-como-titular-da-35a-vara-civel-do-forum-clovis-bevilaqua-2/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maurício Fernandes Gomes.</a>","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-08-0356","y":2018,"m":8,"d":"04","h":"Falece aos 91 anos de idade, em Fortaleza, o poeta, jornalista, ensaísta e crítico literário <a href=\"https://academiacearensedeletras.org.br/membros/f-s-nascimento/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco de Sousa Nascimento (F. S. Nascimento)</a>. Titular da Cadeira nº 38 da Academia Cearense de Letras (ACL), foi editorialista e redator histórico dos jornais O Povo e Correio do Ceará, além de diretor da Biblioteca Pública Governador Menezes Pimentel. Autor de vasta bibliografia poética e memorialística, com destaque para as obras Cantos da Tarde e Presença da Poesia Cearense. O sepultamento realiza-se no Cemitério São João Batista. Nascera em Serrita, PE, a 14/10/1926, tendo sido criado no Crato e radicado em Fortaleza.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-08-0357","y":2018,"m":8,"d":"11","h":"A Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE) celebra a Sessão Solene do Dia do Advogado no Theatro José de Alencar, outorgando a Medalha Advogado Padrão a decanos da advocacia cearense.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-08-0358","y":2018,"m":8,"d":"13","h":"Morre em Fortaleza, aos 81 anos, o professor e ex-sacerdote <a href=\"https://www.arquidiocesedefortaleza.org.br/faleceu-hoje-everaldo-bezerra-fialho/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Everaldo Bezerra Fialho</a>, ordenado presbítero no Seminário da Prainha e ex-secretário municipal de Educação de Redenção. Nascera em Independência, CE, a 28 de julho de 1937.","c":["Necrologia"],"l":1},{"id":"ce-2018-08-0359","y":2018,"m":8,"d":"23","h":"Morre em Fortaleza, aos 59 anos, o líder comunitário e ativista esportivo <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-jose-sarto-entrega-novo-complexo-esportivo-e-de-lazer-no-bairro-jangurussu\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Raimundo Nonato de Jesus Cavalcante (\"Careca\")</a>, figura histórica das lutas sociais no Conjunto Sítio São João, no bairro Jangurussu. Nascera em Pacatuba, CE, a 03 de janeiro de 1959.","c":["Necrologia"],"l":1},{"id":"ce-2018-08-0360","y":2018,"m":8,"d":"28","h":"O Governo do Estado do Ceará entrega as obras de requalificação técnica e restauração artística do histórico Cine Teatro São Luiz, na Praça do Ferreira, no Centro de Fortaleza. As intervenções preservam os painéis e acabamentos do edifício inaugurado em 1958 e modernizam os sistemas de projeção cinematográfica digital e acústica teatral.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-08-0361","y":2018,"m":8,"d":"28","h":"Morre em Fortaleza, aos 77 anos, o contabilista e político <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/cmfor-decreta-luto-oficial-pelo-falecimento-do-ex-presidente-narcilio-andrade\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Raimundo Narcílio Andrade (Narcílio Andrade)</a>, vereador de Fortaleza por sete mandatos consecutivos (a partir de 1976) e presidente da Câmara Municipal de Fortaleza no biênio 1989–1990, durante a promulgação da Lei Orgânica do Município. A Câmara Municipal decretou luto oficial de três dias. Nascera no distrito de Juatama, em Quixadá, CE, a 10 de março de 1941.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2018-09-0362","y":2018,"m":9,"d":"02","h":"Falece aos 83 anos de idade, em Fortaleza, em decorrência de complicações renais e cardiovasculares, o professor universitário, escritor, poeta e ficcionista <a href=\"https://academiacearensedeletras.org.br/membros/horacio-didimo/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Horácio Dídimo Pereira Barbosa Vieira (Horácio Dídimo)</a>. Ocupante da Cadeira nº 8 da Academia Cearense de Letras (ACL) e da Cadeira nº 26 da Academia Cearense da Língua Portuguesa (ACLP), foi professor titular do Departamento de Letras Vernáculas da Universidade Federal do Ceará (UFC), ensaísta e pioneiro dos estudos acadêmicos sobre literatura infantojuvenil no Nordeste (<a href=\"https://pt.wikipedia.org/wiki/Hor%C3%A1cio_D%C3%ADdimo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Autor consagrado de obras como Tempo de Chuva, Tijolo de Barro, O Passarinho Carrancudo e As Histórias do Filho do Homem. O velório realiza-se no Complexo Ethernus e o sepultamento no Cemitério Parque da Paz. Nascera em Fortaleza, CE, em 23/03/1935.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-09-0363","y":2018,"m":9,"d":"11","h":"Falece aos 78 anos de idade, em Fortaleza, o médico neurologista, fisiatra, professor e escritor <a href=\"http://acm.med.br/membro-view/180\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maurício Cabral Benevides</a>. Presidente da Academia Cearense de Retórica e membro titular da Cadeira nº 58 da Academia Cearense de Medicina, atuou como docente na Faculdade de Medicina da UFC e nos principais hospitais neurológicos do Estado, dedicando-se à pesquisa clínica e à bioética (<a href=\"https://reporterceara.com.br/2018/09/11/cearense-mauricio-cabral-benevides-morre-aos-78-anos-de-idade/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Repórter Ceará</a>). O sepultamento realiza-se no Cemitério Parque da Paz. Nascera em Fortaleza, CE, em 01/04/1940, filho do ex-deputado Carlos Eduardo Benevides e de Antônia Cabral Benevides.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-09-0364","y":2018,"m":9,"d":"13","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16659.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.659</a> (DOE de 21/09/2018), que denomina José Teles de Moraes o trecho da rodovia CE-253 entre a sede de Redenção e o distrito de Gassi, e Antônio Marçal Pinto de Castro o trecho da mesma CE-253 entre o distrito de Gassi e o município de Pacoti, no Maciço de Baturité.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-09-0365","y":2018,"m":9,"d":"15","h":"Encerra-se em Juazeiro do Norte a Romaria de Nossa Senhora das Dores, padroeira do município, com solene celebração eucarística e bênção dos romeiros.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2018-09-0366","y":2018,"m":9,"d":"22","h":"Morre em Fortaleza o promotor de Justiça do Ministério Público do Estado do Ceará (MPCE) <a href=\"https://mpce.mp.br/missa-de-7-dia-de-promotor-paulo-roberto-barreto-sera-nesta-quinta-27/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dr. Paulo Roberto Barreto de Almeida.</a><br><a href=\"https://mpce.mp.br/missa-de-7-dia-de-promotor-paulo-roberto-barreto-sera-nesta-quinta-27/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">25 — O prefeito Roberto Cláudio sancion</a>a a <a href=\"https://servidor.sepog.fortaleza.ce.gov.br/images/pdf/LEGISLACAO/REAJUSTE/Lei_108012018_-_Reajuste_do_Magistrio_-_Alterada.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Municipal nº 10.798</a> (DOM nº 16.353, de 28/09/2018), alterando a denominação da EMEIF Dois de Dezembro para Escola Municipal de Ensino Fundamental Audifax Rios, em homenagem ao escritor, historiador e artista plástico cearense falecido em 2017.","c":["Necrologia","Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-09-0367","y":2018,"m":9,"d":"28","h":"Realiza-se no Theatro José de Alencar a solenidade da <a href=\"https://www1.sfiec.org.br/fiec-noticias/118904/beto-studart-recebe-trofeu-sereia-de-ouro-nesta-sexta-feira-289\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">48ª edição do Troféu Sereia de Ouro</a>, promovida pelo Sistema Verdes Mares e Grupo Edson Queiroz, condecorando quatro personalidades de destaque no desenvolvimento econômico, jurídico, científico e artístico do Ceará: o pintor, escultor e músico <a href=\"https://mauc.ufc.br/pt/descartes-gadelha/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Descartes Marques Gadelha</a>; o médico oncologista, pesquisador e professor titular de Farmacologia da UFC <a href=\"https://ppgfarmacologia.ufc.br/pt/professor-odorico-de-moraes-recebe-o-trofeu-sereia-de-ouro/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Manoel Odorico de Moraes Filho</a>; o industrial e presidente da FIEC <a href=\"https://www1.sfiec.org.br/fiec-noticias/117282/beto-studart-sera-agraciado-com-trofeu-sereia-de-ouro\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Jorge Alberto Vieira Studart Gomes (Beto Studart)</a>; e a ministra do Tribunal Superior do Trabalho (TST) e escritora <a href=\"https://www.trt7.jus.br/index.php/noticias/todas-as-noticias/16842-ministra-do-tribunal-superior-do-trabalho-katia-magalhaes-arruda-homenageada-na-alece\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Kátia Magalhães Arruda</a> (natural de Ipaumirim, CE).","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-09-0368","y":2018,"m":9,"d":"29","h":"Falece aos 80 anos de idade, em Fortaleza, em virtude de pneumonia e complicações de saúde, o advogado, educador, escritor, poeta e contista <a href=\"https://academiacearensedeletras.org.br/membros/genuino-sales/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Genuíno Francisco de Sales (Genuíno Sales)</a>. Titular da Cadeira nº 9 da Academia Cearense de Letras (ACL), Presidente da Academia Cearense da Língua Portuguesa (ACLP) e diretor de ensino da Organização Educacional Farias Brito, teve sólida atuação na advocacia trabalhista e nas letras nordestinas, autor de livros de contos premiados como O Cantor de Soluços. Sepultamento no Cemitério Parque da Paz. Nascera em Pedro II, PI, a 15/04/1938.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-10-0369","y":2018,"m":10,"d":"07","h":"Realiza-se o primeiro turno das Eleições Gerais de 2018 em todo o Ceará. O agrônomo e professor Camilo Sobreira de Santana (Camilo Santana, PT) é reeleito Governador do Estado com 79,96% dos votos válidos (3.457.556 votos), ao lado da vice-governadora Maria Izolda Cela de Arruda Coelho (Izolda Cela, PDT), estabelecendo a maior votação percentual da história política cearense. Para o Senado Federal, são eleitos o ex-governador Cid Ferreira Gomes (Cid Gomes, PDT), com 3.228.533 votos, e o empresário Luís Eduardo Falcão Girão (Eduardo Girão, PROS), com 1.325.786 votos. São eleitos ainda 22 deputados federais e 46 deputados estaduais.","c":["Política e Instituições"],"l":0},{"id":"ce-2018-10-0370","y":2018,"m":10,"d":"18","h":"Comemora-se em todo o Estado o <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/benigno-destaca-celebracao-do-centenario-do-fortaleza-esporte-clube\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centenário de Fundação do Fortaleza Esporte Clube</a>, agremiação fundada em 18 de outubro de 1918 por Alcides Santos, com alvorada festiva na sede do Pici, iluminação tricolor em monumentos públicos da Capital e sessões solenes nas casas legislativas (<a href=\"https://www12.senado.leg.br/noticias/materias/2019/10/17/senado-homenageia-o-fortaleza-esporte-clube-por-seu-centenario\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Senado Notícias</a>).","c":["Esportes"],"l":1},{"id":"ce-2018-10-0371","y":2018,"m":10,"d":"19","h":"O governador Camilo Santana entrega à Coordenadoria Integrada de Operações Aéreas (<a href=\"https://www.ce.gov.br/2018/10/19/com-entrega-de-dois-novos-helicopteros-para-ciopaer-ceara-passa-a-ter-terceira-maior-frota-policial-de-aeronaves-do-brasil/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ciopaer</a>) dois novos helicópteros biturbina Airbus H135 (Fênix 08 e Fênix 09), equipados com UTI aérea e óculos de visão noturna, destinando uma aeronave para a base de Quixadá e outra para Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2018-10-0372","y":2018,"m":10,"d":"26","h":"É sancionada a Lei Estadual nº 16.672 (DOE de 30/10/2018), denominando Prefeito Roseo Bezerra o trecho da rodovia CE-269 que interliga a rodovia federal BR-116 à CE-371, no município de Jaguaribara.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2018-10-0373","y":2018,"m":10,"d":"28","h":"No segundo turno da eleição presidencial de 2018, Jair Messias Bolsonaro (PSL) é eleito Presidente da República Federativa do Brasil, enquanto no Estado do Ceará o candidato Fernando Haddad (PT) obtém ampla maioria, com 71,11% dos votos válidos do eleitorado cearense.","c":["Política e Instituições"],"l":0},{"id":"ce-2018-11-0374","y":2018,"m":11,"d":"10","h":"No Estádio Germano Krüger, no município de Ponta Grossa (PR), o Fortaleza Esporte Clube, sob a direção técnica do ex-goleiro Rogério Ceni, derrota o Avaí (SC) por 1 a 0 e sagra-se Campeão Brasileiro da Série B de 2018 com duas rodadas de antecedência, conquistando o inédito troféu nacional no ano em que celebra o seu centenário de fundação (1918–2018).","c":["Esportes"],"l":0},{"id":"ce-2018-11-0375","y":2018,"m":11,"d":"14","h":"Em Sobral, o governador Camilo Santana inaugura o novo <a href=\"https://www.ce.gov.br/2018/11/14/governo-do-ceara-inaugura-centro-socioeducativo-de-sobral/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro Socioeducativo de Sobral</a>, construído no bairro Jatobá sob gestão da Superintendência do Sistema Estadual de Atendimento Socioeducativo (Seas).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-11-0376","y":2018,"m":11,"d":"21","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16676.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.676</a> (DOE de 23/11/2018), que altera a Organização Judiciária do Estado para criar a Vara de Crimes contra a Ordem Tributária da Comarca de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2018-11-0377","y":2018,"m":11,"d":"29","h":"O prefeito de Fortaleza, Roberto Cláudio, entrega à população as obras de requalificação integral e duplicação da Avenida Aguanambi, com pistas exclusivas para transporte coletivo no padrão BRT (Bus Rapid Transit), ciclovia segregada, calçadas acessíveis e nova passarela para pedestres sobre a via, interligando a zona central à rodovia BR-116 (tendo os serviços complementares finais concluídos em <a href=\"https://g1.globo.com/ce/ceara/noticia/2018/12/26/avenida-aguanambi-sera-entregue-no-proximo-sabado-29-segundo-seinf.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">29 de dezembro</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-12-0378","y":2018,"m":12,"d":"06","h":"Falece às 08h30min, aos 99 anos de idade, em Fortaleza, em virtude de falência de múltiplos órgãos, o empresário, economista (UFC), industrial e ex-senador da República <a href=\"https://g1.globo.com/ce/ceara/noticia/2018/12/06/morre-o-empresario-cearense-jose-dias-de-macedo-aos-99-anos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Dias de Macêdo (J. Macêdo)</a>. Fundador do Grupo J. Macêdo, conglomerado pioneiro na indústria de moagem de trigo e manufatura de massas e biscoitos no Nordeste e no Brasil, foi líder empresarial histórico na Federação das Indústrias do Estado do Ceará (FIEC) e na Confederação Nacional da Indústria (CNI). No campo público, exerceu os mandatos de deputado federal (1959–1967) e senador pelo Ceará (1983–1987), condecorado com a Medalha da Abolição, Medalha do Mérito Industrial e o Troféu Sereia de Ouro. O Governador do Estado decreta luto oficial de três dias em todo o Ceará. O velório realiza-se na Capela do Palácio da Abolição e o sepultamento no Cemitério Parque da Paz. Era natural de Camocim, CE, nascido a 08/08/1919.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-12-0379","y":2018,"m":12,"d":"07","h":"O governador Camilo Santana sanciona leis estaduais de toponímia (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leisordinariascompiladas.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">DOE de 10/12/2018</a>): Lei nº 16.686, denominando Elpídio Alves de Oliveira a rodovia CE-278; e Lei nº 16.689, denominando Francisco Nogueira de Queiroz o trecho da rodovia CE-269 que liga o município de Potiretama à divisa com o Estado do Rio Grande do Norte.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-12-0380","y":2018,"m":12,"d":"14","h":"Em sessão solene no Pavilhão Oeste do Centro de Eventos do Ceará, em Fortaleza, o Tribunal Regional Eleitoral do Ceará (TRE-CE), presidido pela desembargadora Nailde Pinheiro Nogueira, diploma solenemente os eleitos no pleito de 2018: o governador Camilo Santana, a vice-governadora Izolda Cela, os senadores Cid Gomes e Eduardo Girão, bem como os deputados federais e estaduais titulares. Na mesma data, o governador sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16697.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.697</a> (Programa de Educação Fiscal) e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16698.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.698</a> (Companhia de Participação e Gestão de Ativos do Ceará – CearaPar).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2018-12-0381","y":2018,"m":12,"d":"18","h":"Falece em Fortaleza, aos 85 anos, o professor universitário, pesquisador e geógrafo <a href=\"https://www.institutodoceara.org.br/socio/caio-lossio-botelho/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Caio Lóssio Botelho. Doutor e livre-docente em Geografia Humana, membro efetivo do Instituto do Ceará, membro d</a>a Academia Cearense de Ciências e professor titular da UFC e da Universidade Estadual do Ceará (<a href=\"https://www.uece.br/noticias/nota-de-pesar-pelo-falecimento-do-professor-caio-lossio-botelho/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">UECE</a>), dedicou sua vida acadêmica aos estudos da climatologia, semiárido e recursos hídricos cearenses, com expressiva produção bibliográfica sobre as secas no Nordeste. Nascera em Juazeiro do Norte, CE, a 19 de abril de 1933.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-12-0382","y":2018,"m":12,"d":"19","h":"O presidente do Tribunal de Justiça do Estado do Ceará (TJCE), desembargador Francisco Gladyson Pontes, inaugura as novas instalações da Sala da Assistência Militar e presta <a href=\"https://www.tjce.jus.br/noticias/comissao-de-seguranca-presta-homenagem-in-memoriam-a-desembargadora-helena-lucia/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">homenagem póstuma à desembargadora Helena Lúcia Soares</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-12-0383","y":2018,"m":12,"d":"21","h":"Em cerimônia litúrgica na Catedral Metropolitana de Fortaleza, parte das cinzas e restos mortais do cardeal franciscano <a href=\"https://g1.globo.com/ce/ceara/noticia/2018/12/21/restos-mortais-de-dom-aloisio-lorscheider-sao-sepultados-na-catedral-de-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dom Aloísio Lorscheider</a> (arcebispo metropolitano de Fortaleza entre 1973 e 1995, falecido em 2007) é depositada na cripta da Capela do Ressuscitado. Na mesma data, o governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16710.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.710</a>, dispondo sobre a reforma administrativa do Poder Executivo estadual para o quadriênio 2019–2022.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2018-12-0384","y":2018,"m":12,"d":"26 e 27","h":"O governador Camilo Santana sanciona expressivo conjunto de leis de toponímia e gestão para o interior cearense (DOE de 28/12/2018): <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16727.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei nº 16.727</a> (gestão do Hub de TIC pela ETICE); Lei nº 16.738, denominando José Moraes de Farias a CE-469 no trecho entre Queimados e Tucuns, em Crateús; Lei nº 16.750, denominando José Ferreira Lima (Zuza Ferreira) a CE-151 entre Baixio e Ipaumirim; Lei nº 16.757, denominando Gabino Marques de Sousa a Areninha de Mundaú, em Trairi; Lei nº 16.758, denominando Antônio Guedes Viana a rodovia entre Cedro e o distrito de Assunção; <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16760.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei nº 16.760</a>, denominando Jeová Brígido Roberto (\"Passo Preto\") a Areninha localizada no município de Morada Nova; Lei nº 16.763, denominando Prefeito Júlio Pinheiro Bastos a CE-243 entre Itapajé e Uruburetama; Lei nº 16.764, denominando Vereador João Barbosa o 4º trecho do Anel Viário de Juazeiro do Norte; Lei nº 16.774, denominando Ronnie Carlos de Carvalho a Areninha no município de Graça; e <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2018/16795.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei nº 16.795</a>, que estima a Receita e fixa a Despesa do Estado (LOA) para 2019.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2018-12-0385","y":2018,"m":12,"d":"31","h":"Morre aos 97 anos o engenheiro agrônomo, biofísico e pesquisador cearense <a href=\"https://www.abc.org.br/2019/01/08/morre-aos-97-anos-o-academico-manuel-mateus-ventura/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prof. Manuel Mateus Ventura</a>, fundador e diretor (1958–1968) do histórico Instituto de Química e Tecnologia (IQT) da UFC, professor emérito da Universidade de Brasília (UnB), comendador da Ordem Nacional do Mérito Científico e membro titular da Academia Brasileira de Ciências. Nascera em Fortaleza, CE, a 21 de junho de 1921.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-01-0386","y":2019,"m":1,"d":"01","h":"Passa a vigorar o novo valor do Salário Mínimo nacional, fixado em R$ 998,00 pelo Decreto Federal nº 9.661, de 1º de janeiro de 2019.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2019-01-0387","y":2019,"m":1,"d":"01","h":"Tomam posse para o segundo mandato consecutivo (quadriênio 2019–2022), em sessão solene na <a href=\"https://www2.al.ce.gov.br/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Assembleia Legislativa do Estado do Ceará</a> (ALCE) seguida de cerimônia de recondução no Palácio da Abolição, o governador reeleito Camilo Sobreira de Santana (PT) e a vice-governadora Maria Izolda Cela de Arruda Coelho (PDT). Na ocasião, é criada a Secretaria da Administração Penitenciária (SAP), assumida pelo policial civil Luís Mauro Albuquerque Araújo.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-01-0388","y":2019,"m":1,"d":"02","h":"Tem início uma onda de ataques criminosos coordenados por facções no Ceará contra ônibus, viadutos, prédios públicos e estabelecimentos comerciais em Fortaleza, Região Metropolitana e municípios do interior, em reação às novas diretrizes de rigor disciplinar no sistema prisional estadual, motivando o envio de tropas da Força Nacional de Segurança Pública a partir de 04 de janeiro.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2019-01-0389","y":2019,"m":1,"d":"02","h":"O governador Camilo Santana entrega 1.024 unidades habitacionais do <a href=\"https://www.ce.gov.br/cidades/2019/01/02/governo-do-ceara-entrega-1-024-unidades-do-orgulho-do-ceara-ii/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Residencial Orgulho do Ceará II</a>, na Região Metropolitana de Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-01-0390","y":2019,"m":1,"d":"08","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> publicadas no Diário Oficial do Estado (DOE) de 09 de janeiro de 2019: Lei nº 16.799, que denomina Olegário Macêdo Leite a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/rodovias/2019\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">rodovia estadual CE-153</a> no trecho entre a sede de Aurora e o distrito de Ingazeiras; Lei nº 16.802, que denomina Socorro Gomes a Escola de Ensino Médio em Tempo Integral de Quixelô; Lei nº 16.803, que denomina Antônio Bezerra Cavalcante o trecho da CE-351 entre Quiterianópolis e o distrito de Monte Sion, e Deputado Joaquim Noronha Mota o trecho entre Monte Sion e Parambu; Lei nº 16.804, que denomina Geovany Marcena Oliveira a Areninha de Quiterianópolis; Lei nº 16.808, que denomina Raimundo Martins Paiva a Areninha de Uruburetama; Lei nº 16.809, que denomina José Alves Noronha o trecho da CE-279 entre a BR-020 e o distrito de Novo Assis, em Parambu; Lei nº 16.811, que denomina Sebastião Paulino de Freitas a Areninha de Redenção; Lei nº 16.812, que denomina Marcos Antônio Nunes de Magalhães (Marquinhos) a Areninha de General Sampaio; Lei nº 16.813, que denomina Antônio Alfredo de Aguiar o trecho da CE-581 entre Frecheirinha e Araticum, em Ubajara; Lei nº 16.814, que denomina Francisco Marcos Farias Pedroza a Areninha de Nova Russas; e Lei nº 16.815, que denomina Escola de Ensino Médio Nossa Senhora do Livramento o estabelecimento de ensino médio do distrito de Parazinho, em Granja.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-01-0391","y":2019,"m":1,"d":"14","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.833</a> (DOE de 15/01/2019), dispondo sobre a exposição obrigatória do número da lei de denominação e do nome de seu autor nos prédios e logradouros públicos do Estado do Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-01-0392","y":2019,"m":1,"d":"18","h":"Morre em Fortaleza, aos 89 anos, o médico cardiologista <a href=\"https://acm.med.br/membro-view/82\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Raimundo Hélio Cirino Bessa</a>, ocupante da Cadeira nº 27 e ex-presidente da Academia Cearense de Medicina (biênio 1996–1998). Nascera em 09 de novembro de 1929. No mesmo dia, morre em Fortaleza o advogado e militar <a href=\"https://oabce.org.br/categoria/obituario/page/52/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Cel. Paulo Autran</a> (OAB-CE nº 17.906), sendo sepultado no Cemitério Parque da Paz.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-01-0393","y":2019,"m":1,"d":"22","h":"O prefeito Roberto Cláudio inaugura a <a href=\"https://fortaleza.ce.gov.br/noticias?start=17890\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">23ª Areninha de Fortaleza</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-01-0394","y":2019,"m":1,"d":"26","h":"O presidente da OAB-CE, Erinaldo Dantas, dá posse à nova diretoria da <a href=\"https://oabce.org.br/2019/01/diretoria-da-subseccao-juazeiro-do-norte-e-empossada/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Subsecção da OAB de Juazeiro do Norte.</a><br><a href=\"https://oabce.org.br/2019/01/diretoria-da-subseccao-juazeiro-do-norte-e-empossada/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">28 — O governador Camilo Santana e o prefeito Roberto Cláudio inaugura</a>m o <a href=\"https://www.ce.gov.br/vicegov/2022/03/30/inaugurado-onde-funcionou-antigo-ippoo-parque-dom-aloisio-lorscheider-representa-liberdade-e-lazer-para-fortalezenses/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Mercado das Flores</a>, em Fortaleza, pelo Programa Juntos por Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-01-0395","y":2019,"m":1,"d":"29","h":"Toma posse solene, às 19h, no Centro de Eventos do Ceará, em Fortaleza, a nova diretoria da <a href=\"https://marciatravessoni.com.br/galerias/nova-diretoria-da-oab-ce-toma-posse-em-solenidade-no-centro-de-eventos-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE)</a> para o triênio 2019–2021, presidida pelo advogado José Erinaldo Dantas Filho (Erinaldo Dantas) — eleito com 7.389 votos —, tendo como vice-presidente Ana Vládia Feitosa, secretário-geral Pedro Bruno Amorim, secretário-geral adjunto David Sombra Peixoto e tesoureiro Rodrigo da Costa, com a presença do presidente do Conselho Federal da OAB, Cláudio Lamachia.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-01-0396","y":2019,"m":1,"d":"30","h":"Toma posse na presidência da Academia Cearense de Letras (ACL), no Palácio da Luz, para o biênio 2019–2020, a escritora e professora da UFC Angela Maria Rossas Mota de Gutiérrez, tornando-se a primeira mulher a presidir a instituição em seus 125 anos de história.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-01-0397","y":2019,"m":1,"d":"31","h":"Toma posse a nova cúpula diretiva do <a href=\"https://www.tjce.jus.br/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Tribunal de Justiça do Estado do Ceará (TJCE)</a> para o biênio 2019–2021, tendo como presidente o desembargador Washington Luis Bezerra de Araújo, vice-presidente a desembargadora Maria Nailde Pinheiro Nogueira e corregedor-geral da Justiça o desembargador Teodoro Silva Santos.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-02-0398","y":2019,"m":2,"d":"01","h":"Instala-se na Assembleia Legislativa do Estado do Ceará (ALCE) a 30ª Legislatura Estadual (2019–2022), com a posse dos 46 deputados estaduais eleitos e a eleição da nova Mesa Diretora para o biênio 2019–2020, assumindo a presidência o médico e deputado José Sarto Nogueira Moreira (Dr. Sarto, PDT).","c":["Política e Instituições"],"l":0},{"id":"ce-2019-02-0399","y":2019,"m":2,"d":"01","h":"Toma posse na presidência da Câmara Municipal de Fortaleza (CMFor), para o biênio 2019–2020, o vereador Antônio Henrique da Silva (PDT).","c":["Política e Instituições"],"l":0},{"id":"ce-2019-02-0400","y":2019,"m":2,"d":"02","h":"Encerra-se em Juazeiro do Norte a tradicional Romaria de Nossa Senhora das Candeias, reunindo cerca de 250 mil romeiros na Basílica Santuário de Nossa Senhora das Dores e culminando na procissão luminosa.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-02-0401","y":2019,"m":2,"d":"06","h":"Morre em Fortaleza o advogado e escritor <a href=\"https://oabce.org.br/categoria/obituario/page/52/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dalton Marques Soares</a>, sendo sepultado no Cemitério São João Batista.","c":["Necrologia"],"l":1},{"id":"ce-2019-02-0402","y":2019,"m":2,"d":"09","h":"Morre o advogado <a href=\"https://oabce.org.br/categoria/obituario/page/52/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Espedito Luciano Arruda da Silva</a>, ex-vice-presidente da Subsecção da OAB Litoral Leste/Aracati na gestão 2016–2018, sendo sepultado no Cemitério Municipal de Fortim, CE.","c":["Necrologia"],"l":1},{"id":"ce-2019-02-0403","y":2019,"m":2,"d":"11","h":"Morrem em Fortaleza o advogado <a href=\"https://oabce.org.br/categoria/obituario/page/52/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Aderson Maia Nogueira</a> e o advogado e professor Heriberto Hermógenes Lopes.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-02-0404","y":2019,"m":2,"d":"15","h":"Morre em Fortaleza o advogado Raimundo Rebouças de Lima, sendo sepultado no Cemitério Parque da Paz.","c":["Necrologia"],"l":0},{"id":"ce-2019-03-0405","y":2019,"m":3,"d":"02 a 05","h":"Realiza-se o Carnaval de Fortaleza 2019, com desfiles das agremiações de maracatus, blocos, cordões e afoxés na Avenida Domingos Olímpio e programação cultural nos polos do Aterro da Praia de Iracema, Benfica (Praça da Gentilândia), Mercado dos Pinhões, Mocinha e Passeio Público.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2019-03-0406","y":2019,"m":3,"d":"06","h":"O governador Camilo Santana sanciona duas leis estaduais de denominação publicadas no DOE de 07 de março de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 16.844, que denomina Paulo Marcelo Martins Rodrigues a Escola de Saúde Pública do Ceará (ESP/CE), em Fortaleza; e Lei nº 16.846, que denomina Aeroporto Regional de Canoa Quebrada Dragão do Mar o Aeroporto do Polo Turístico de Canoa Quebrada, localizado no município de Aracati.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-03-0407","y":2019,"m":3,"d":"07","h":"O Governo do Ceará entrega <a href=\"https://www.ce.gov.br/sop/tag/proares-iii/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">três novas Areninhas</a> no interior do Estado.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-03-0408","y":2019,"m":3,"d":"13","h":"O prefeito Roberto Cláudio inaugura o <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-inaugura-binario-no-itaperi\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Binário do Itaperi</a>, requalificando as ruas José Meneleu e Dr. Manoel Teófilo, em Fortaleza.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-03-0409","y":2019,"m":3,"d":"20","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.854</a> (DOE de 22/03/2019), denominando Maria Leal Teixeira a Escola de Ensino Médio da localidade de São Paulinho, no município de Acopiara.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-03-0410","y":2019,"m":3,"d":"25","h":"Comemora-se a Data Magna do Ceará, alusiva aos 135 anos da abolição da escravatura na Província do Ceará (25 de março de 1884), com solenidades cívicas na Assembleia Legislativa e programação alusiva à Medalha da Abolição.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-03-0411","y":2019,"m":3,"d":"25","h":"Morre em Fortaleza, aos 75 anos, o professor da UFC e da UECE, historiador, doutor pela USP e bispo da Igreja Católica Ortodoxa <a href=\"https://www.institutodoceara.org.br/socio/francisco-adegildo-ferrer/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Adegildo Férrer</a>, sócio efetivo do Instituto do Ceará (Histórico, Geográfico e Antropológico), no qual tomara posse em 24 de abril de 2013, membro da ALMECE e presidente da Academia Cearense de Filosofia, Ciências e Tecnologia. Nascera em Cariús, CE, a 14 de março de 1944.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-03-0412","y":2019,"m":3,"d":"30","h":"O Instituto do Ceará (Histórico, Geográfico e Antropológico) realiza assembleia geral solene no Palácio Jeremias Arruda, em Fortaleza, celebrando os 132 anos de sua fundação (04 de março de 1887).","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-04-0413","y":2019,"m":4,"d":"02","h":"O governador Camilo Santana sanciona duas leis estaduais de toponímia rodoviária publicadas no DOE de 04 de abril de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/rodovias/2019\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE Rodovias</a>): Lei nº 16.857, que denomina Othoniel Leite Teixeira a rodovia CE-153 no trecho que liga Aurora a Lavras da Mangabeira; e Lei nº 16.858, que denomina Expedito de Oliveira Leite o trecho da CE-384 entre o entroncamento da BR-116 e a sede do município de Mauriti.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-04-0414","y":2019,"m":4,"d":"06","h":"Morre em Fortaleza, na madrugada de sábado, aos 75 anos, o desembargador aposentado <a href=\"https://www.tjce.jus.br/institucional/ex-presidente/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Arísio Lopes da Costa</a>, ex-presidente do Tribunal de Justiça do Estado do Ceará (TJCE) no biênio 2011–2013 e ex-vice-presidente no biênio 2009–2011. Bacharel em Direito pela UFC (1969), ingressara na magistratura em 1971 e ascendera ao TJCE em 19 de outubro de 2000. O Poder Judiciário decretou luto oficial de três dias, e o sepultamento ocorreu no Cemitério Parque da Paz (<a href=\"https://sindojus-ce.org.br/noticias/oficiais-de-justica-lamentam-o-falecimento-do-desembargador-arisio-lopes/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SINDOJUS-CE</a>, <a href=\"https://acmag.org.br/2019/04/nota-de-pesar-pelo-falecimento-do-desembargador-aposentado-jose-arisio-lopes-da-costa/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ACM</a>). Nascera em Mombaça, CE, a 21 de maio de 1943, filho de Manoel Costa Sobrinho e Maria Generosa Lopes da Costa.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-04-0415","y":2019,"m":4,"d":"08","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/6887\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 875</a>, denominando Rua Manuel Pereira Pinto uma via do bairro Antônio Bezerra, anteriormente conhecida como Rua Panamá.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-04-0416","y":2019,"m":4,"d":"10","h":"Toma posse na Cadeira nº 9 da Academia Cearense de Letras (ACL), cujo patrono é Fausto Barreto, o educador e empresário Tales de Sá Cavalcante, sucedendo ao poeta Genuíno Sales.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-04-0417","y":2019,"m":4,"d":"13","h":"Comemora-se o aniversário de 293 anos de emancipação política de Fortaleza, com programação artística e cultural promovida pela Prefeitura no Aterro da Praia de Iracema e nos equipamentos históricos da Capital.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2019-04-0418","y":2019,"m":4,"d":"15","h":"O governador Camilo Santana sanciona duas leis rodoviárias (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/rodovias/2019\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE Rodovias</a>): Lei nº 16.861, que denomina José Euclides Ferreira Gomes Júnior a Avenida Perimetral, entre a CE-178 e a BR-222, no município de Sobral; e Lei nº 16.869 (DOE de 16/04/2019), que denomina Padre Alcides Tres o trecho da CE-467 entre a sede de Monsenhor Tabosa e o distrito de Nossa Senhora do Livramento.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-04-0419","y":2019,"m":4,"d":"21","h":"Na Arena Castelão, o Fortaleza Esporte Clube vence o Ceará Sporting Club por 1 a 0 (gol de Araruna), após também vencer o primeiro jogo da decisão por 2 a 0, e sagra-se Campeão Cearense de Futebol de 2019, conquistando o seu 42º título estadual.","c":["Esportes"],"l":0},{"id":"ce-2019-04-0420","y":2019,"m":4,"d":"24","h":"Morre em Fortaleza, aos 72 anos, o médico internista e escritor <a href=\"http://acm.med.br/membro-view/161\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Sérgio Gomes de Matos</a>, membro titular da Cadeira nº 52 da Academia Cearense de Medicina (empossado em 24/11/2005). Nascera em 22 de agosto de 1946.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-05-0421","y":2019,"m":5,"d":"06","h":"Morre em Fortaleza, às 18h30min, no Hospital São Carlos, aos 68 anos, o advogado e vereador de Fortaleza no exercício do terceiro mandato <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-municipal-de-fortaleza-decreta-luto-oficial-de-3-dias-pelo-falecimento-do-vereador-luciram-girao\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Luciram Girão Sales</a> (PDT), ex-diretor do Desafio Jovem do Ceará. A Câmara Municipal de Fortaleza decretou luto oficial de três dias, realizando-se o sepultamento em Maranguape, CE. Nascera em 25 de maio de 1950.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-05-0422","y":2019,"m":5,"d":"10","h":"O governador Camilo Santana sanciona duas leis estaduais de denominação publicadas no DOE de 10 de maio de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 16.872, que denomina Rodovia Prefeito Henrique Antônio Fonseca da Mota a CE-257, no trecho que liga Capistrano a Aratuba; e Lei nº 16.879, que denomina Raimundo Célio Rodrigues a Escola Estadual de Educação Profissional de Pacatuba.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-05-0423","y":2019,"m":5,"d":"15","h":"Estudantes, professores e servidores das universidades e institutos públicos (UFC, Unilab, UFCA, IFCE e UECE) realizam grandes manifestações no Centro de Fortaleza (concentração na Praça da Gentilândia e caminhada até a Praça do Ferreira) e em municípios do interior em defesa da educação pública e contra o contingenciamento de verbas das universidades federais.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-05-0424","y":2019,"m":5,"d":"23","h":"O governador Camilo Santana sanciona quatro leis estaduais de denominação (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 16.882 (DOE de 23/05/2019), que denomina Manoel Arão de Andrade a praça localizada na Estação Juscelino Kubitschek do Metrô de Fortaleza; Lei nº 16.884 (DOE de 24/05/2019), que denomina Jeová Costa Lima a Escola Estadual de Educação Profissional de Russas; Lei nº 16.888 (DOE de 24/05/2019), que denomina José Mariano Filho a rodovia CE-189 entre Ipueiras e Ararendá; e Lei nº 16.889 (DOE de 24/05/2019), que denomina Antônio Adil de Mendonça Filho o prédio-sede da Regional do Detran-CE no município de Iguatu.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-05-0425","y":2019,"m":5,"d":"29","h":"No Estádio Almeirão, em João Pessoa (PB), o Fortaleza Esporte Clube, comandado pelo técnico Rogério Ceni, vence o Botafogo-PB por 1 a 0 (gol de Wellington Paulista) e conquista pela primeira vez em sua história o título de Campeão da Copa do Nordeste de 2019 de forma invicta na fase final.","c":["Esportes"],"l":0},{"id":"ce-2019-05-0426","y":2019,"m":5,"d":"29","h":"O prefeito Roberto Cláudio entrega a primeira etapa das obras de requalificação da Avenida Beira-Mar de Fortaleza, compreendendo o trecho do Mercado dos Peixes, no Mucuripe, com nova pavimentação, calçadão e urbanização paisagística.","c":["Política e Instituições"],"l":0},{"id":"ce-2019-05-0427","y":2019,"m":5,"d":"31","h":"Toma posse no Tribunal de Justiça do Estado do Ceará (TJCE) o desembargador <a href=\"https://www.tjce.jus.br/noticias/tribunal-de-justica-do-ceara-decreta-luto-pela-morte-do-desembargador-antonio-padua-silva/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Antônio Pádua Silva</a>, eleito pelo Tribunal Pleno em 16 de maio de 2019 pelo critério de merecimento. No mesmo dia, em Juazeiro do Norte, o prefeito Arnon Bezerra inaugura a <a href=\"https://www.flaviopintonews.com.br/2019/05/prefeito-arnon-bezerra-entrega-alameda.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Alameda Juazeiro</a>, novo polo gastronômico e de convivência no Centro da cidade.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-06-0428","y":2019,"m":6,"d":"02","h":"Realiza-se em Barbalha o tradicional cortejo do Pau da Bandeira de Santo Antônio, abrindo os festejos do padroeiro do município no Cariri cearense, reconhecidos como Patrimônio Cultural Imaterial do Brasil pelo IPHAN.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2019-06-0429","y":2019,"m":6,"d":"04","h":"Toma posse na presidência do Tribunal Regional Eleitoral do Ceará (TRE-CE), para o biênio 2019–2021, o desembargador Haroldo Correia de Oliveira Máximo, assumindo a vice-presidência e Corregedoria Regional Eleitoral o desembargador Inácio de Alencar Cortez Neto.","c":["Política e Instituições"],"l":0},{"id":"ce-2019-06-0430","y":2019,"m":6,"d":"09","h":"Morre em Fortaleza, aos 94 anos, a professora da UFC, pedagoga, mestre pela Universidade da Pensilvânia, bacharel em Direito e historiadora <a href=\"https://www.institutodoceara.org.br/socio/zelia-sa-viana-camurca/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Zélia de Sá Viana Camurça (Zélia Camurça)</a>, sócia efetiva do Instituto do Ceará (Histórico, Geográfico e Antropológico) desde 09 de abril de 1968. Nascera em Fortaleza, CE, a 16 de dezembro de 1924, filha de Tertuliano Vieira e Sá e de Enoe Vieira do Nascimento e Sá.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-06-0431","y":2019,"m":6,"d":"10","h":"Em Quixadá, o governador Camilo Santana inaugura a nova <a href=\"https://www.ce.gov.br/sop/tag/proares-iii/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Areninha de Quixadá</a> e autoriza a restauração de trecho da rodovia CE-265. Na mesma data, em Fortaleza, o prefeito Roberto Cláudio inaugura novo <a href=\"https://fortaleza.ce.gov.br/noticias/tag/Inaugura%C3%A7%C3%A3o?start=10\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro de Educação Infantil (CEI)</a> no bairro Prefeito José Walter.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-06-0432","y":2019,"m":6,"d":"12","h":"Morre no Crato, CE, às 4h30min, aos 101 anos, o <a href=\"https://diocesedecrato.org/a-musica-que-toca-agora-no-ceu-morre-mons-agio-moreira-aos-101-anos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Monsenhor Ágio Augusto Moreira (Padre Ágio)</a>, decano do clero da Diocese de Crato, educador, músico e fundador da Sociedade Lírica do Belmonte (Solibel), sendo sepultado na capela do abrigo no bairro Belmonte. Nascera em Assaré, CE, a 05 de fevereiro de 1918.","c":["Necrologia"],"l":1},{"id":"ce-2019-06-0433","y":2019,"m":6,"d":"16","h":"Morre em Fortaleza, no Hospital São Mateus, aos 84 anos, o ator, diretor, radialista e teatrólogo <a href=\"https://diariodonordeste.verdesmares.com.br/verso/morre-haroldo-serra-um-dos-grandes-nomes-do-teatro-cearense-aos-84-anos-1.2112064\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Haroldo Serra</a>, fundador do histórico grupo teatral Comédia Cearense em 1957, diretor do Teatro Universitário da UFC e agraciado com o Troféu Sereia de Ouro (2002). O velório ocorreu no Theatro José de Alencar e o sepultamento no Cemitério Parque da Paz. Nascera em Tamboril, CE, a 06 de novembro de 1934.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-06-0434","y":2019,"m":6,"d":"18","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.909</a> (DOE de 19/06/2019), denominando Jaime Tomaz de Aquino a Escola de Ensino Médio da localidade de Forquilha, em Beberibe.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-06-0435","y":2019,"m":6,"d":"27","h":"O governador Camilo Santana sanciona duas leis rodoviárias publicadas no DOE de 01 de julho de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/rodovias/2019\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE Rodovias</a>): Lei nº 16.914, que denomina Antônio Manoel Lopes Neto a CE-156 entre Ladeira Grande (Maranguape) e Palmácia; e Lei nº 16.915, que denomina José Gessy Torquato o trecho da CE-187 entre Várzea do Giló (Ipu) e Martinslândia (Guaraciaba do Norte).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-07-0436","y":2019,"m":7,"d":"01","h":"O Governo do Ceará entrega 234 unidades habitacionais do <a href=\"https://www.ce.gov.br/cidades/tag/dende/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Residencial Dona Yolanda Queiroz</a>, na Comunidade do Dendê, bairro Edson Queiroz, em Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-07-0437","y":2019,"m":7,"d":"08","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/16924.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.924</a> (DOE de 08/07/2019), que denomina José Claudino Sales a rodovia CE-267, no trecho entre a sede de Novo Oriente e a divisa com o Piauí.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-07-0438","y":2019,"m":7,"d":"09","h":"O governador Camilo Santana sanciona quatro leis estaduais de denominação publicadas no DOE de 10 de julho de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 16.925, que denomina \"Aba Katu\" a Escola Indígena de Ensino Fundamental e Médio da localidade de Rajado, em Monsenhor Tabosa; Lei nº 16.926, que denomina Antônio Sampaio Couto a CE-390 entre Jardim e Penaforte; Lei nº 16.928, que denomina Monsenhor Ágio Augusto Moreira a Vila da Música, no distrito de Belmonte, no Crato; e Lei nº 16.930, que denomina Sandra Carvalho Costa a Escola Estadual de Educação Profissional de Jijoca de Jericoacoara.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-07-0439","y":2019,"m":7,"d":"12","h":"O prefeito Roberto Cláudio e o governador Camilo Santana assinam convênio para o início das obras de aterro hidráulico (engorde da faixa de praia) da Avenida Beira-Mar de Fortaleza, no trecho entre o espigão da Rua João Cordeiro e o espigão da Avenida Desembargador Moreira, com investimento previsto de R$ 70 milhões.","c":["Política e Instituições"],"l":0},{"id":"ce-2019-07-0440","y":2019,"m":7,"d":"20","h":"Realiza-se em Juazeiro do Norte a missa campal da Romaria pelos 85 anos de falecimento do Padre Cícero Romão Batista (20 de julho de 1934), no largo da Capela do Perpétuo Socorro.","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-07-0441","y":2019,"m":7,"d":"25","h":"Morre em Fortaleza o economista e professor titular aposentado da Faculdade de Economia, Administração, Atuária e Contabilidade (FEAAC) da Universidade Federal do Ceará (UFC) José Dantas da Silveira, um dos docentes históricos do Curso de Pós-Graduação em Economia (CAEN/UFC).","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-07-0442","y":2019,"m":7,"d":"31","h":"O governador Camilo Santana, a primeira-dama Onélia Santana e o prefeito Zé Ailton Brasil inauguram a <a href=\"https://www.newscariri.com.br/2019/07/governo-do-ceara-inaugura-praca-mais-infancia-no-crato\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Praça Mais Infância no município do Crato</a>. No mesmo dia, em Sobral, o prefeito Ivo Gomes inaugura a nova <a href=\"https://sobral.ce.gov.br/informes/relevantes?start=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Escola de Tempo Integral no distrito de Rafael Arruda.</a>","c":["Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-08-0443","y":2019,"m":8,"d":"05","h":"O governador Camilo Santana inaugura as novas instalações do <a href=\"https://www.pm.ce.gov.br/2019/08/05/governo-do-ceara-inaugura-novo-complexo-do-comando-de-policiamento-de-choque-da-pmce/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Complexo do Comando de Policiamento de Choque (CPChoque)</a> da Polícia Militar do Ceará, no bairro Praia do Futuro, em Fortaleza.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-08-0444","y":2019,"m":8,"d":"06","h":"Morre em Fortaleza, pela manhã, aos 72 anos, em decorrência de complicações pós-cirúrgicas, o advogado, jurista, mestre pela PUC-RJ, professor titular aposentado e ex-diretor da Faculdade de Direito da Universidade Federal do Ceará (UFC) <a href=\"https://fadir.ufc.br/pt/luto-morre-o-professor-alvaro-melo-filho-ex-diretor-da-faculdade-de-direito/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Álvaro Melo Filho</a>, membro efetivo do Instituto do Ceará, da Academia Nacional de Direito Desportivo (ANDD) e da Corte Arbitral do Esporte (CAS, Suíça), redator do texto-base do art. 217 da Constituição Federal de 1988, coautor das Leis Zico e Pelé e referência internacional em Direito Desportivo (<a href=\"https://www.cob.org.br/comunicacao/noticias/1-nota-de-pesar--dr--alvaro-melo-filho1\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">COB</a>). A Reitoria da UFC decretou luto oficial de três dias. Nascera a 31 de julho de 1947.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-08-0445","y":2019,"m":8,"d":"15","h":"A Academia Cearense de Letras (ACL), primeira academia literária do Brasil (fundada em 15 de agosto de 1894), celebra seu Jubileu de 125 anos (Quasquicentenário) em sessão magna comemorativa no Theatro José de Alencar, sob a presidência da acadêmica Angela Gutiérrez, com lançamento de edição especial da Revista da Academia Cearense de Letras e outorga da Medalha Barão de Studart.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-08-0446","y":2019,"m":8,"d":"19","h":"O presidente da República Jair Bolsonaro nomeia o professor titular da Faculdade de Direito e advogado <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/08/19/bolsonaro-nomeia-nome-menos-votado-em-consulta-publica-como-novo-reitor-da-universidade-federal-do-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Cândido Lustosa Bittencourt de Albuquerque (Cândido Albuquerque)</a> — terceiro colocado na consulta prévia à comunidade universitária e integrante da lista tríplice ao lado de Custódio Almeida e Geraldo Barbosa — para o cargo de reitor da Universidade Federal do Ceará (UFC) no quadriênio 2019–2023.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-08-0447","y":2019,"m":8,"d":"22","h":"O professor <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/08/28/alvo-de-protestos-reitor-ainda-nao-conseguiu-despachar-na-ufc-uma-semana-apos-ser-empossado.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Cândido Albuquerque</a> toma posse no cargo de reitor da Universidade Federal do Ceará (UFC) em cerimônia realizada na sede do Ministério da Educação (MEC), em Brasília, sucedendo a Henry de Holanda Campos.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-08-0448","y":2019,"m":8,"d":"23","h":"Em virtude de protestos estudantis no prédio da Reitoria no Benfica, a solenidade de transmissão de cargo para o novo reitor da UFC, <a href=\"https://diariodonordeste.verdesmares.com.br/metro/solenidade-de-transferencia-de-cargo-de-novo-reitor-da-ufc-muda-de-local-apos-atos-na-reitoria-1.2140037\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Cândido Albuquerque</a>, realiza-se no auditório da Federação das Indústrias do Estado do Ceará (FIEC), em Fortaleza, despachando o reitor pela primeira vez na Reitoria em <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/08/29/novo-reitor-da-ufc-despacha-pela-primeira-vez-na-reitoria-apos-nomeacao-de-cargo.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">29 de agosto</a>.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-08-0449","y":2019,"m":8,"d":"24","h":"O governador Camilo Santana inaugura as novas instalações da sede da <a href=\"https://tvj1.com.br/regional/noticias/governador-inaugura-neste-sabado-24-novas-instalacoes-da-sede-regional-do-detran-em-iguatu.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Unidade Regional do Detran-CE no município de Iguatu</a> (denominada Antônio Adil de Mendonça Filho), atendendo a 16 municípios da região Centro-Sul.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-08-0450","y":2019,"m":8,"d":"25","h":"O prefeito Roberto Cláudio entrega a requalificação da <a href=\"https://fortaleza.ce.gov.br/noticias/categoria/fortaleza?start=1715\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Praça Waldemar Falcão</a>, no Centro de Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-08-0451","y":2019,"m":8,"d":"27","h":"O governador Camilo Santana sanciona duas leis estaduais de denominação publicadas no DOE de 28 de agosto de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 16.956, que denomina João Alves de Lima o túnel da rodovia CE-040 na interseção com o Anel Viário; e Lei nº 16.963, que denomina Francisco Ivens de Sá Dias Branco o Complexo do Comando de Policiamento de Choque (CPChoque), em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-08-0452","y":2019,"m":8,"d":"30","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 16.968</a> (DOE de 30/08/2019), disciplinando a competência da Assembleia Legislativa do Ceará para denominar bens públicos estaduais executados em regime de convênio ou parceria com os municípios.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-09-0453","y":2019,"m":9,"d":"03","h":"O governador Camilo Santana inaugura a urbanização da margem esquerda do Trecho IV do <a href=\"https://www.cidades.ce.gov.br/2019/09/03/governo-do-ceara-inaugura-trecho-urbanizado-do-maranguapinho/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Rio Maranguapinho</a>, em Maracanaú, na Região Metropolitana de Fortaleza.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-09-0454","y":2019,"m":9,"d":"04","h":"O prefeito Roberto Cláudio inaugura o <a href=\"https://fortaleza.ce.gov.br/noticias/categoria/fortaleza?start=1715\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">63º Ecoponto de Fortaleza</a>, no bairro Siqueira. Na mesma semana, começam a atingir o litoral cearense as primeiras <a href=\"https://www.ce.gov.br/sema/2019/12/03/manchas-de-oleo-no-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">manchas de petróleo cru</a> do grave derramamento ambiental registrado ao longo de toda a costa do Nordeste brasileiro.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-09-0455","y":2019,"m":9,"d":"15","h":"Encerra-se em Juazeiro do Norte a grande Romaria de Nossa Senhora das Dores, padroeira da cidade, com procissão dos carros de romeiros e multidão no entorno da Basílica Santuário.","c":["Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-09-0456","y":2019,"m":9,"d":"24","h":"O governador Camilo Santana sanciona sete leis estaduais de denominação publicadas nos DOE de 26 e 27 de setembro de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 16.983, que denomina Luiz de França Filho a Areninha de Paracuru; Lei nº 16.984, que denomina Adones Manoel Damasceno a Areninha de Barbalha; Lei nº 16.991, que denomina Irmã Tereza Cristina a Escola de Ensino Médio do Campo no Assentamento Nova Canaã, distrito de Manituba, em Quixeramobim; Lei nº 16.993, que denomina Antônio Gualberto de Sales a rodovia CE-354 entre o entroncamento da BR-222 e o distrito de São Joaquim, em Umirim; Lei nº 16.999, que denomina Vereador Benedito Alves Carneiro a Areninha de Barroquinha; Lei nº 17.000, que denomina Vereador Aureliano Ribeiro a Areninha de Russas; e Lei nº 17.001, que denomina Antônio Leite Cavalcante a Areninha de Guaraciaba do Norte.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-09-0457","y":2019,"m":9,"d":"27","h":"Realiza-se no Theatro José de Alencar, em Fortaleza, a solenidade de entrega da <a href=\"https://diariodonordeste.verdesmares.com.br/metro/trofeu-sereia-de-ouro-2019-homenageia-quatro-personalidades-em-solenidade-no-theatro-jose-de-alencar-1.2155214\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">49ª edição do Troféu Sereia de Ouro</a>, outorgada pelo Grupo Edson Queiroz / Sistema Verdes Mares (em noite que também celebrou os 40 anos da Acert), agraciando quatro personalidades cearenses (<a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-prestigia-cerimonia-do-49-trofeu-sereia-de-ouro\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Fortaleza</a>): o cientista e engenheiro eletricista Fernando de Mendonça (natural de Guaramiranga, fundador e 1º diretor do INPE); a desembargadora Maria Iracema Martins do Vale (ex-presidente do TJCE e do TRE-CE e conselheira do CNJ); o artesão do couro e Mestre da Cultura Espedito Velozo de Carvalho (Mestre Espedito Seleiro, radicado em Nova Olinda); e o médico pediatra e presidente do IPREDE Francisco Sulivan Bastos Mota (Sulivan Mota).","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-09-0458","y":2019,"m":9,"d":"28","h":"O prefeito Roberto Cláudio inaugura o <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-inaugura-binario-do-bom-jardim\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Binário do Bom Jardim</a>, requalificando as ruas Pedro Martins e São Francisco, em Fortaleza.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-10-0459","y":2019,"m":10,"d":"05 a 07","h":"O avanço das <a href=\"https://www1.folha.uol.com.br/ambiente/2019/10/manchas-de-oleo-interditam-principal-praia-de-fortaleza.shtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">manchas de óleo no litoral cearense</a> provoca a interdição de trechos da Praia do Futuro e a retirada de mais de <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/10/07/mais-500-litros-de-oleo-sao-retirados-de-cinco-praias-de-fortaleza-diz-prefeitura.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">500 litros de petróleo cru em cinco praias de Fortaleza</a> pelas equipes de limpeza e defesa ambiental.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-10-0460","y":2019,"m":10,"d":"10","h":"A Secretaria do Meio Ambiente do Ceará (Sema), a Semace e o Ibama instituem <a href=\"https://www.ce.gov.br/sema/2019/10/10/grupo-de-trabalho-define-acoes-de-combate-a-mancha-de-oleo-no-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Grupo de Trabalho de combate às manchas de óleo</a>, realizando mutirão de limpeza na <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/10/10/praia-em-fortaleza-recebe-acao-de-limpeza-para-retirar-manchas-de-oleo.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Praia da Sabiaguaba</a>, em Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-10-0461","y":2019,"m":10,"d":"10","h":"O governador Camilo Santana sanciona a Lei Estadual nº 17.016 (DOE de 14/10/2019), que denomina José Ney Alves Feitosa a Areninha de Jardim, juntamente com amplo pacote de 36 <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de denominação</a> de equipamentos no interior (DOE de 14/10/2019), incluindo: Lei nº 17.009 (Praça Mais Infância Francisco Alves Sobrinho, em Acopiara); Lei nº 17.011 (Praça Mais Infância Célio Roberto Tavares, em Granja); Lei nº 17.019 (Terminal Rodoviário Prefeito Eliezer Arruda, em Granja); Lei nº 17.024 (Praça de Eventos Adauto Fonteles do Nascimento, no Preá, em Cruz); Lei nº 17.040 (Escola de Ensino Médio Luizete Albano de Freitas Menezes, em Campestre, Chorozinho); e as Leis nº 17.010, 17.012 a 17.015, 17.017, 17.018, 17.020 a 17.022, 17.034 a 17.038 e 17.044 a 17.059, que denominam as Areninhas e Miniareninhas estaduais em Várzea Alegre, Jucás, Horizonte, São Benedito, Cariré, Farias Brito, Iracema, Itarema, Nova Olinda, Araripe, Cariús, Independência, Marco, Meruoca, Santana do Cariri, Missão Velha, Acarape, Novo Oriente, Caririaçu, Porteiras, Penaforte, Cedro, Mauriti, Tarrafas, Aurora, Salitre, Campos Sales, Ipueiras, Antonina do Norte, Barreira e Piquet Carneiro.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-10-0462","y":2019,"m":10,"d":"15","h":"Às 10h28min, desaba o Edifício Andrea, prédio residencial de sete pavimentos localizado no cruzamento das ruas Tibúrcio Cavalcante e Tomás Acioli, no bairro Dionísio Torres, em Fortaleza. A operação de busca e salvamento conduzida pelo Corpo de Bombeiros Militar do Ceará, com apoio da Defesa Civil e voluntários, estende-se por 103 horas ininterruptas, resultando no resgate com vida de 7 pessoas sob os escombros e na confirmação de 9 vítimas fatais.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2019-10-0463","y":2019,"m":10,"d":"23","h":"O governador Camilo Santana sanciona oito leis de denominação publicadas no DOE de 24 de outubro de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 17.072, que denomina Geraldo Gomes de Azevedo a CE-354 no trecho do Contorno de Itapipoca; e as Leis nº 17.067 a 17.070 e 17.081 a 17.083, que denominam as Areninhas estaduais de Brejo Santo (José Nicodemos Gomes), Itapiúna (José Evilásio Antunes Coelho), Ibaretama (Antônio Marcos da Silva), Reriutaba (Gerardo Henrique de Araújo), Santa Quitéria (Francisco Magalhães de Mesquita), Quixelô (Raimundo Gomes de Oliveira) e Caridade (Mário Wilson Tavares).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-10-0464","y":2019,"m":10,"d":"24","h":"O prefeito Roberto Cláudio e o governador Camilo Santana inauguram a <a href=\"https://unifor.br/-/prefeitura-de-fortaleza-inaugura-academia-do-professor\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Academia do Professor Darcy Ribeiro</a>, equipamento voltado à formação continuada e assistência aos professores da rede municipal, na Rua Dona Leopoldina, no Centro de Fortaleza. Na mesma data, as manchas de óleo atingem a praia de <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/10/24/manchas-de-oleo-atingem-a-praia-de-canoa-quebrada-um-dos-principais-destinos-turisticos-do-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Canoa Quebrada</a>, em Aracati, elevando para <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/10/26/sobe-para-26-o-numero-de-praias-atingidas-por-manchas-de-oleo-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">26 o número de praias cearenses afetadas</a> até 26 de outubro.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-10-0465","y":2019,"m":10,"d":"29","h":"Morre em Fortaleza o professor Salenilson Cézar de Souza, docente do Departamento de Matemática da Universidade Federal do Ceará (UFC).","c":["Necrologia","Cultura, Educação e Religião"],"l":0},{"id":"ce-2019-10-0466","y":2019,"m":10,"d":"31","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/12830\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 897</a> (publicado no DOM nº 16.623, de 05/11/2019), denominando Avenida Geógrafo Antônio Ribeiro Zaranza uma via pública no bairro Cajazeiras, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-11-0467","y":2019,"m":11,"d":"08","h":"É inaugurado em Juazeiro do Norte, com a presença do prefeito Arnon Bezerra, o <a href=\"https://unileao.edu.br/2019/11/08/complexo-esportivo-da-unileao-comeca-a-atender-comunidade-academica-da-instituicao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Complexo Esportivo da Unileão</a>.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-11-0468","y":2019,"m":11,"d":"09","h":"O Governo do Ceará e a Prefeitura de Sobral (prefeito Ivo Gomes) entregam a urbanização do <a href=\"https://www.ce.gov.br/cidades/2019/11/07/governo-do-ceara-entrega-o-parque-pajeu-em-sobral/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Parque Pajeú</a>, contemplando a Areninha Manoel Pereira de Farias (Manoel Manchão) e a Praça Francisca Lindalva de Lima Constância.","c":["Política e Instituições"],"l":1},{"id":"ce-2019-11-0469","y":2019,"m":11,"d":"12","h":"Morre em Fortaleza, aos 90 anos, no Hospital da Unimed, em decorrência de pneumonia, o advogado, jornalista, cientista político, procurador federal, ex-prefeito de Granja e ex-deputado federal pelo Ceará por seis mandatos consecutivos (1995–2019) <a href=\"https://g1.globo.com/ce/ceara/noticia/2019/11/12/morre-ex-deputado-federal-cearense-vicente-arruda-aos-90-anos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Vicente Ferreira de Arruda Coelho (Vicente Arruda)</a>. O velório realizou-se na Funerária Ternura e o sepultamento no Cemitério Parque da Paz. Nascera em Granja, CE, a <a href=\"https://www2.al.ce.gov.br/legislativo/tramit2021/pl520_21.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">17 de maio de 1929</a>. No mesmo dia, o prefeito Roberto Cláudio inaugura a <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-inaugura-a-12-mini-areninha-da-capital\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">12ª Mini Areninha de Fortaleza</a> (Edgar Mendes Filho).","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-11-0470","y":2019,"m":11,"d":"14","h":"O governador Camilo Santana sanciona três leis estaduais de denominação publicadas no DOE de 19 de novembro de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 17.095, que denomina Raimundo Felipe Sobrinho o Centro Cearense de Idiomas (CCI) no município de Iguatu; Lei nº 17.106, que denomina José Holanda Cunha o trecho da CE-269 entre Alto Santo e o distrito de Castanhão; e Lei nº 17.108, que denomina Nilon de Oliveira Barroso o ginásio poliesportivo da comunidade de Figueiredo, em Jaguaruana.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-11-0471","y":2019,"m":11,"d":"26","h":"O prefeito Roberto Cláudio e o governador Camilo Santana entregam a conclusão da nova torre hospitalar do Instituto Doutor José Frota (IJF 2), no Centro de Fortaleza, ampliando o complexo de urgência e emergência com mais 203 leitos, centro cirúrgico e unidades de terapia intensiva distribuidos em cinco pavimentos.","c":["Política e Instituições"],"l":0},{"id":"ce-2019-11-0472","y":2019,"m":11,"d":"29","h":"No Palácio da Abolição, em Fortaleza, o governador Camilo Santana preside a solenidade de outorga da <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-participa-da-cerimonia-de-entrega-da-medalha-da-abolicao\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha da Abolição 2019</a>, mais alta comenda do Estado do Ceará, agraciando (<a href=\"https://marciatravessoni.com.br/galerias/medalha-da-abolicao-agraciou-seis-personalidades-importantes-para-o-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Márcia Travessoni, CBMCE): a escritor</a>a e presidente da ACL Angela Maria Rossas Mota de Gutiérrez; o ex-senador e ex-presidente do Congresso Nacional Carlos Mauro Cabral Benevides (Mauro Benevides); o empresário Edson Carvalho Ventura; a desembargadora Maria Iracema Martins do Vale; o sacerdote Pe. Reginaldo Manzotti; a presidente da Casa de Vovó Dedé Regina Marta Albuquerque Barbosa; e o Corpo de Bombeiros Militar do Estado do Ceará (CBMCE), pela atuação heroica no resgate das vítimas do Edifício Andrea. No mesmo dia, o prefeito Roberto Cláudio inaugura a primeira etapa do <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-inaugura-a-primeira-etapa-do-trinario-da-avenida-duque-de-caxias\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Trinário da Avenida Duque de Caxias</a> (ruas Meton de Alencar e Clarindo de Queiroz), no Centro de Fortaleza.","c":["Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-12-0473","y":2019,"m":12,"d":"03","h":"Boletim conjunto da Sema, Semace e Ibama confirma que todas as praias monitoradas no litoral cearense encontram-se limpas e sem novos registros de <a href=\"https://www.ce.gov.br/sema/2019/12/03/manchas-de-oleo-no-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">manchas de óleo</a> após três meses de incidentes ambientais.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-12-0474","y":2019,"m":12,"d":"06","h":"Morre em Fortaleza, na sexta-feira, aos 83 anos, o contabilista, empresário da educação, ex-vereador de Fortaleza (eleito em 1970 e 1972) e ex-deputado estadual <a href=\"https://blogdoedisonsilva.com.br/2019/12/10/morte-de-ex-deputado-levanta-sessao-plenaria-na-assembleia-legislativa/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Pedro de Sales Nunes</a>, sendo sepultado no Cemitério Parque da Paz e homenageado com o levantamento da sessão plenária da Assembleia Legislativa em 10 de dezembro. Nascera em São Luís do Curu, CE, a 18 de janeiro de 1936.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2019-12-0475","y":2019,"m":12,"d":"09","h":"Morre em Iguatu, CE, aos 94 anos, <a href=\"https://www.diocesedeiguatu.org.br/dom-jose-mauro-ramalho-de-alarcon-e-santiago/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dom José Mauro Ramalho de Alarcón e Santiago</a>, primeiro bispo diocesano de Iguatu (sagrado em 1962 e titular até 2000) e bispo emérito, sendo sepultado na Catedral de São José de Iguatu em 11 de dezembro (<a href=\"https://www.arquidiocesedefortaleza.org.br/nota-de-falecimento-de-dom-jose-mauro-ramalho-de-alarcon-e-santiago/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Arquidiocese de Fortaleza</a>). Nascera em Russas, CE, a 14 de maio de 1925.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2019-12-0476","y":2019,"m":12,"d":"12","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.121</a> (DOE de 16/12/2019), denominando Raimunda Mourão Resende o Centro de Educação Infantil do distrito de Livramento, em Ipueiras.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-12-0477","y":2019,"m":12,"d":"13","h":"O prefeito Roberto Cláudio inaugura a <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-roberto-claudio-inaugura-nova-via-conectando-o-bairro-montese-a-regiao-do-aeroporto-de-fortaleza\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">nova via Rua Narcílio Andrade</a>, conectando o bairro Montese à Avenida Senador Carlos Jereissati (região do Aeroporto Internacional de Fortaleza).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-12-0478","y":2019,"m":12,"d":"14","h":"Em Sobral, o governador Camilo Santana e o prefeito Ivo Gomes inauguram a <a href=\"https://www.ce.gov.br/cidades/2019/12/13/governo-do-ceara-inaugura-centro-de-tratamento-de-residuos-em-sobral/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Central de Tratamento de Resíduos (CTR)</a>, consorciada para atender 17 municípios da Região Norte. No mesmo dia, em Fortaleza, o prefeito Roberto Cláudio inaugura a <a href=\"https://www.fortaleza.ce.gov.br/noticias?page=669&start=15135\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Areninha da Granja Portugal</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-12-0479","y":2019,"m":12,"d":"20","h":"O governador Camilo Santana sanciona quatro leis estaduais de denominação publicadas no DOE de 23 de dezembro de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Leis nº 17.139 a 17.141, que denominam as Areninhas estaduais em Croatá (José Antônio de Sousa), Aracati (Antônio Marcos da Silva) e Assaré (Francisco de Assis Mendes); e Lei nº 17.146, que denomina Francisca Cândido Lopes a CE-593 entre a sede de Orós e o distrito de Santarém.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-12-0480","y":2019,"m":12,"d":"24","h":"É assassinado a tiros pelas costas na manhã da véspera de Natal, enquanto fazia caminhada nas proximidades da parede do Açude Junco, na zona rural do município, o prefeito de Granjeiro, no Cariri cearense, <a href=\"https://diariodonordeste.verdesmares.com.br/metro/advogado-rebate-acusacoes-de-fraude-contra-prefeito-assassinado-joao-do-povo-1.2191356\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">João Gregório Neto, conhecido como João do Povo</a> (PL), aos 54 anos, crime político de grande repercussão estadual (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/08/27/justica-aceita-denuncia-contra-17-pessoas-por-morte-do-prefeito-de-granjeiro-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 CE</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2019-12-0481","y":2019,"m":12,"d":"27","h":"O governador Camilo Santana sanciona três leis estaduais de denominação publicadas no DOE de 30 de dezembro de 2019 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2019/e2019.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 17.155, que denomina Gerardo de Assis Barros a Areninha de Itaiçaba; Lei nº 17.163, que denomina Agenor Gomes de Araújo o Centro de Convenções do município de Iguatu; e Lei nº 17.164, que denomina Maria das Dores Pereira Alves a Praça Mais Infância localizada no município de Iguatu.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2019-12-0482","y":2019,"m":12,"d":"30","h":"O governador Camilo Santana e o prefeito Roberto Cláudio entregam as obras de urbanização e requalificação da <a href=\"https://www.ce.gov.br/cidades/2019/12/30/governo-e-prefeitura-entregam-revitalizacao-da-lagoa-da-parangaba/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lagoa da Parangaba</a>, em Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2020-01-0483","y":2020,"m":1,"d":"01","h":"Entra em vigor o novo valor do salário mínimo nacional de R$ 1.039,00 mensais, fixado pela Medida Provisória nº 916, de 31 de dezembro de 2019 (posteriormente reajustado para R$ 1.045,00 a partir de 1º de fevereiro pela Medida Provisória nº 919, de 30 de janeiro de 2020).","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2020-01-0484","y":2020,"m":1,"d":"02","h":"O governador Camilo Sobreira de Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.165</a> (DOE de 02/01/2020), que reconhece formalmente a existência, a contribuição histórica e os direitos dos povos indígenas no Estado do Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-01-0485","y":2020,"m":1,"d":"09","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.168, 17.169, 17.171 e 17.173</a> (DOE de 09/01/2020), criando a Delegacia Municipal de Marco, instituindo a Comenda Ceará de Dança e a Semana do Laço Branco, e autorizando parceria financeira com a Academia Cearense de Letras (ACL) e o Instituto do Ceará (Histórico, Geográfico e Antropológico).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-01-0486","y":2020,"m":1,"d":"14 e 15","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.175, 17.176, 17.178 e 17.179</a> (DOE de 15 e 16/01/2020), fortalecendo o Programa para Superação da Extrema Pobreza Infantil, a Política Estadual de Estímulo ao Empreendedorismo Feminino, o Selo Empresa Sustentável e as Casas Comunitárias de Sementes Crioulas.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-02-0487","y":2020,"m":2,"d":"01","h":"Passa a vigorar o valor definitivo do salário mínimo nacional de 2020 em R$ 1.045,00 mensais, nos termos da Medida Provisória nº 919, de 30 de janeiro de 2020.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2020-02-0488","y":2020,"m":2,"d":"13","h":"Morre em Fortaleza o jornalista cearense <a href=\"https://diariodonordeste.verdesmares.com.br/verso/morre-o-jornalista-cearense-chico-alves-1.2210803\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Alves (Chico Alves)</a>, ex-diretor de redação do jornal Tribuna do Ceará e ex-chefe da Assessoria de Comunicação do Tribunal de Justiça do Estado do Ceará (TJCE). O velório ocorreu na Funerária Ternura e o sepultamento em 14 de fevereiro no Cemitério Parque da Paz.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2020-02-0489","y":2020,"m":2,"d":"18 a 29","h":"Eclode no Ceará o <a href=\"https://pt.wikipedia.org/wiki/Crise_de_seguran%C3%A7a_p%C3%BAblica_no_Cear%C3%A1_em_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">motim de policiais e bombeiros militares</a> (declarado ilegal pelo Poder Judiciário em 17 de fevereiro), com ocupação de batalhões e paralisação de viaturas na Capital e no Interior (<a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/entenda-o-movimento-grevista-dos-policiais-militares-do-ceara\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Câmara Municipal de Fortaleza</a>). Em 19 de fevereiro, no município de Sobral, o senador licenciado e ex-governador <a href=\"https://g1.globo.com/ce/ceara/noticia/2020/02/20/cronologia-do-motim-de-policiais-militares-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Cid Ferreira Gomes (PDT) é atingido por dois disparos de arma de fogo</a> ao tentar desobstruir com uma retroescavadeira o portão do 3º Batalhão da Polícia Militar ocupado por amotinados (<a href=\"https://g1.globo.com/ce/ceara/noticia/2021/06/22/35-policiais-sao-indiciados-por-participar-de-ato-que-baleou-senador-cid-gomes-durante-greve-da-policia-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Em 20 de fevereiro, o Governo Federal decreta Operação de Garantia da Lei e da Ordem (GLO) com o emprego de 2,5 mil militares das Forças Armadas e da Força Nacional no Ceará, encerrando-se a paralisação em 1º de março após acordo interinstitucional (<a href=\"https://www1.folha.uol.com.br/poder/2020/02/foi-imaturidade-dos-meninos-diz-lider-de-motim-sobre-toque-de-recolher-no-ce.shtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Folha de S.Paulo</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-02-0490","y":2020,"m":2,"d":"19","h":"Morre em Fortaleza o magistrado <a href=\"https://www.tjce.jus.br/noticias/nota-de-falecimento-36/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Josias Menescal Lima de Oliveira</a>, juiz de Direito titular da 12ª Vara Cível da Comarca de Fortaleza (ingressara na magistratura em 1992, atuando em Campos Sales e Caucaia antes da Capital), sendo velado na Funerária Ethernus e cremado no Cemitério Parque da Saudade, em Caucaia.","c":["Necrologia"],"l":1},{"id":"ce-2020-03-0491","y":2020,"m":3,"d":"15","h":"A Secretaria da Saúde do Estado do Ceará (Sesa) confirma oficialmente os <a href=\"https://brasil.elpais.com/sociedade/2020-04-09/fortaleza-lidera-taxa-de-novos-casos-de-coronavirus-nas-capitais-e-ceara-ja-requisita-leitos-de-hospitais-privados.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">três primeiros casos de infecção pelo novo coronavírus (Covid-19) no Estado do Ceará</a>, diagnosticados em moradores de Fortaleza que haviam retornado de viagens internacionais.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-03-0492","y":2020,"m":3,"d":"16 e 19","h":"O governador Camilo Santana edita o primeiro decreto de emergência em saúde pública (16 de março, data instituída posteriormente pela <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei nº 17.248/2020</a> como Dia Estadual de Combate à Pandemia da Covid-19) e, em 19 de março, decreta o fechamento de comércios, escolas e serviços não essenciais em todo o território cearense para conter a transmissão comunitária.","c":["Política e Instituições"],"l":1},{"id":"ce-2020-03-0493","y":2020,"m":3,"d":"23","h":"O Governo do Estado do Ceará requisita administrativamente as instalações do privado <a href=\"https://brasil.elpais.com/sociedade/2020-04-09/fortaleza-lidera-taxa-de-novos-casos-de-coronavirus-nas-capitais-e-ceara-ja-requisita-leitos-de-hospitais-privados.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hospital Leonardo Da Vinci</a>, no bairro Aldeota, em Fortaleza, convertendo-o em unidade hospitalar de referência exclusiva para pacientes com Covid-19 sob gestão do ISGH. Na mesma data, é sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.183</a> (DOE de 23/03/2020), que promove a reestruturação remuneratória para praças e oficiais da Polícia Militar e do Corpo de Bombeiros Militar do Ceará.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-03-0494","y":2020,"m":3,"d":"24 e 26","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.186</a> (que autoriza a criação da Fundação Regional de Saúde – Funsaúde) e as Leis Estaduais nº 17.189, 17.190 e 17.191 (DOE de 27/03/2020), que denominam Estélio Gomes Araújo a Areninha de Chaval, João Bosco Bandeira Silva a Areninha Tipo II de Ereré e José Holanda Pinheiro a Areninha Tipo II de Deputado Irapuan Pinheiro. Em 26 de março, a Sesa confirma o primeiro óbito por Covid-19 no Estado do Ceará.","c":["Necrologia","Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-03-0495","y":2020,"m":3,"d":"28","h":"Morre em Fortaleza, aos 93 anos de idade, em decorrência de complicações pós-cirúrgicas, o coronel da reserva do Exército, empresário e líder político <a href=\"https://g1.globo.com/ce/ceara/noticia/2020/03/29/morre-o-ex-deputado-federal-cearense-humberto-bezerra.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Humberto Bezerra de Menezes (Humberto Bezerra)</a>. Irmão gêmeo do ex-governador Adauto Bezerra, formou-se pela Academia Militar das Agulhas Negras (AMAN), foi prefeito municipal de Juazeiro do Norte (1963–1966), deputado federal pelo Ceará por dois mandatos (1967–1971 e 1975–1979), vice-governador do Estado do Ceará no governo César Cals (1971–1975), secretário estadual para Assuntos Municipais (1975–1978) e presidente do BicBanco (<a href=\"https://diariodonordeste.verdesmares.com.br/politica/morre-humberto-bezerra-ex-vice-governador-do-ceara-1.2227966\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste, Wikipédia). A Prefeitura de Juazeiro do Norte e o Governo do Estad</a>o decretaram luto oficial de três dias. Nascera em Juazeiro do Norte, CE, a 03 de julho de 1926.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2020-03-0496","y":2020,"m":3,"d":"29","h":"Morre em Fortaleza, aos 71 anos de idade, a desembargadora aposentada do Tribunal de Justiça do Estado do Ceará (TJCE) <a href=\"https://www.tjce.jus.br/noticias/nota-de-falecimento-37/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Gladys Lima Vieira</a>. Ingressara na magistratura em 24 de outubro de 1986 em Parambu, atuando em Camocim, Acopiara, Quixadá e nas Varas Cível, de Família e de Sucessões de Fortaleza até ascender ao TJCE em 2013. Nascera em Fortaleza, CE, a 19 de agosto de 1948.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2020-03-0497","y":2020,"m":3,"d":"02","h":"Morre em Fortaleza, aos 43 anos de idade, vítima de complicações da Covid-19, o médico radiologista Dr. Hermes Roberto Radtke, primeiro profissional da Medicina a falecer em decorrência da pandemia do novo coronavírus no Estado do Ceará (<a href=\"https://www.arce.ce.gov.br/wp-content/uploads/sites/53/2020/04/Coluna-do-Eliomar-Coronav%C3%ADrus-Jornal-O-Povo-02.04.2020.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Jornal O Povo / Blog do Eliomar de Lima — Acervo Arce</a>; <a href=\"https://g1.globo.com/ce/ceara/noticia/2020/04/03/medico-de-43-anos-morre-com-suspeita-de-covid-19-em-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Nascera no Rio Grande do Sul, em 1976, radicando-se profissionalmente na capital cearense.","c":["Necrologia"],"l":1},{"id":"ce-2020-04-0498","y":2020,"m":4,"d":"03 a 17","h":"O governador Camilo Santana sanciona pacote de leis estaduais de proteção social e saúde pública durante a pandemia (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 17.195 (cria a Autoridade Reguladora da Qualidade dos Serviços de Saúde – ARQS); Lei nº 17.196 (pagamento das contas de água e energia para consumidores de baixa renda); Lei nº 17.199 (concede o Título de Cidadão Cearense ao presidente do TJCE, Des. Washington Luis Bezerra de Araújo); Lei nº 17.202 (distribuição de botijões de gás às famílias vulneráveis); e Lei nº 17.205 (auxílio alimentação aos alunos da rede pública estadual).","c":["Política e Instituições"],"l":1},{"id":"ce-2020-04-0499","y":2020,"m":4,"d":"10","h":"Morre no Hospital São Camilo, em Iguatu, aos 66 anos de idade, vítima da Covid-19, a médica ginecologista e obstetra Dra. Lúcia Dantas Abrantes, profissional de destacada atuação na saúde pública da região Centro-Sul do Ceará, sendo o primeiro óbito confirmado pela doença no Município de Iguatu (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/04/11/medica-de-66-anos-morre-com-covid-19-em-iguatu-no-interior-do-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Nascera em João Pessoa, PB, em 1953.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-04-0500","y":2020,"m":4,"d":"11","h":"Morre no município de Boa Viagem, onde é sepultado, o magistrado <a href=\"https://www.tjce.jus.br/noticias/nota-de-falecimento-39/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Washington Luís Terceiro Vieira</a>, juiz titular do 11º Juizado Especial Cível de Fortaleza.","c":["Necrologia"],"l":1},{"id":"ce-2020-04-0501","y":2020,"m":4,"d":"14","h":"Morre em hospital de Fortaleza, aos 70 anos de idade, vítima de complicações da Covid-19, o bispo e religioso sacramentino <a href=\"https://g1.globo.com/ce/ceara/noticia/2020/04/14/arcebispo-emerito-dom-aldo-pagotto-morre-em-hospital-de-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dom Aldo di Cillo Pagotto, SSS</a>, ex-bispo diocesano de Sobral (1998–2004) e arcebispo emérito da Paraíba (2004–2016), que residia na Comunidade Nossa Senhora de Guadalupe, em Fortaleza (<a href=\"https://www.arquidiocesedefortaleza.org.br/nota-de-falecimento-de-dom-aldo/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Arquidiocese de Fortaleza</a>, <a href=\"https://pt.wikipedia.org/wiki/Aldo_Pagotto\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Nascera em Santa Bárbara d'Oeste, SP, a 16 de setembro de 1949.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-04-0502","y":2020,"m":4,"d":"20","h":"Morre em Fortaleza, aos 75 anos de idade, o desembargador aposentado Francisco Suenon Bastos Mota, magistrado do Tribunal de Justiça do Estado do Ceará (TJCE), onde ingressara na carreira em 1979 e ascendera ao Tribunal Pleno em 2008, tendo exercido o cargo de ouvidor-geral do Poder Judiciário cearense e presidido a 1ª Câmara Criminal. Nascera em Cedro, CE, a 09/07/1944 (<a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-falecimento-do-desembargador-aposentado-francisco-suenon-bastos-mota/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TJCE — Nota de Pesar</a>).","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2020-04-0503","y":2020,"m":4,"d":"20","h":"Entra em funcionamento no gramado do Estádio Municipal Presidente Vargas (PV), no bairro Benfica, o <a href=\"https://brasil.elpais.com/sociedade/2020-04-09/fortaleza-lidera-taxa-de-novos-casos-de-coronavirus-nas-capitais-e-ceara-ja-requisita-leitos-de-hospitais-privados.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hospital de Campanha do Estádio Presidente Vargas</a>, implantado pela Prefeitura de Fortaleza com 204 leitos para assistência a pacientes acometidos pela Covid-19.","c":["Esportes","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-05-0504","y":2020,"m":5,"d":"08","h":"Entra em vigor em Fortaleza o decreto de isolamento social rígido (lockdown), editado pelo governador Camilo Santana e pelo prefeito Roberto Cláudio para conter o pico da primeira onda da pandemia da Covid-19 na Capital.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2020-05-0505","y":2020,"m":5,"d":"18","h":"Morre em hospital particular de Fortaleza, aos 52 anos de idade, vítima de complicações da Covid-19, o pastor evangélico Florêncio Nunes Neto, conhecido como Pastor Neto Nunes, presidente da Convenção das Igrejas Evangélicas Assembleia de Deus no Estado do Ceará (CIMADEC), líder do Ministério Canaã em Fortaleza e ex-candidato a prefeito municipal de Fortaleza no pleito de 2008 pelo PMN. Nascera em Fortaleza, CE, a 03/05/1968 (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/05/18/pastor-neto-nunes-presidente-da-assembleia-de-deus-no-ceara-morre-com-covid-19.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-05-0506","y":2020,"m":5,"d":"19","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.210 a nº 17.215</a> (DOE de 20/05/2020), estabelecendo a obrigatoriedade do uso de máscaras de proteção facial em estabelecimentos públicos e privados e o repasse de EPIs às Santas Casas e hospitais filantrópicos do Ceará.","c":["Política e Instituições"],"l":1},{"id":"ce-2020-05-0507","y":2020,"m":5,"d":"29","h":"Morre no Hospital Geral da Unimed, em Fortaleza, aos 91 anos de idade, vítima de complicações da Covid-19, o cantor, compositor e violonista Evaldo Gouveia de Oliveira, consagrado artística e nacionalmente como Evaldo Gouveia, um dos maiores nomes da música popular brasileira e do samba-canção. Iniciara a carreira artística na Rádio Iracema de Fortaleza e integrara o histórico Trio Nagô (ao lado de Mário Alves e Epaminondas de Sousa), notabilizando-se na parceria musical com Jair Amorim e Adelino Moreira como autor de clássicos como \"Sentimental Demais\", \"Alguém Me Disse\", \"Brigas\", \"O Trovador\", \"Que Queres Tu de Mim\" e \"Bloco da Solidão\". O sepultamento ocorreu no Cemitério Parque da Paz, em Fortaleza. Nascera em Orós, CE (criado desde os três meses de idade em Iguatu, CE), a 08/08/1928 (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/05/29/cantor-e-compositor-evaldo-gouveia-morre-de-covid-19-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>; <a href=\"https://agenciabrasil.ebc.com.br/geral/noticia/2020-05/morre-aos-91-anos-o-compositor-cearense-evaldo-gouveia\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Agência Brasil</a>).","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-06-0508","y":2020,"m":6,"d":"01","h":"Tem início a Fase de Transição do Plano Responsável de Abertura das Atividades Econômicas e Comportamentais no Ceará após a redução sustentada dos indicadores da primeira onda da pandemia.","c":["Infraestrutura, Saúde e Sociedade"],"l":0},{"id":"ce-2020-06-0509","y":2020,"m":6,"d":"05","h":"Morre em Fortaleza o delegado federal aposentado, jornalista, historiador e genealogista <a href=\"https://www.institutodoceara.org.br/socio/geova-lemos-cavalcante/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Geová Lemos Cavalcante</a>, filho de Adauto Vieira Cavalcante e Adelaide Lemos Cavalcante. Bacharel em Direito pela UFC (1967), exerceu o cargo de superintendente regional da Polícia Federal no Ceará, Paraná, Alagoas e Acre, foi membro da Associação Cearense de Imprensa e sócio efetivo do Instituto do Ceará (Histórico, Geográfico e Antropológico), no qual tomara posse em 24 de abril de 2013, deixando obras como Pedra Branca – Século XIX, Cronologia da Criação da Diocese de Fortaleza, Dom Antônio de Almeida Lustosa e Genealogia Cearense – Catálogo de Fontes.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-06-0510","y":2020,"m":6,"d":"21","h":"Morre em hospital de Fortaleza, aos 81 anos de idade, vítima de complicações da Covid-19, o advogado, pecuarista e político Marconi José Figueiredo de Alencar (conhecido como Marconi Alencar), bacharel em Direito pela UFC, ex-prefeito municipal de Araripe (1962–1966) e ex-deputado à Assembleia Legislativa do Estado do Ceará por quatro legislaturas consecutivas (1971–1987), onde exerceu a 1ª Secretaria da Mesa Diretora. Nascera em Juazeiro do Norte, CE, a 21/03/1939 (<a href=\"https://www.al.ce.gov.br/noticias/ex-deputado-estadual-marconi-alencar-falece-em-fortaleza\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE — Nota de Pesar</a>).","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-06-0511","y":2020,"m":6,"d":"27","h":"O Governo do Estado do Ceará decreta isolamento social rígido (lockdown) nos municípios de Juazeiro do Norte, Crato, Barbalha, Brejo Santo (na Região do Cariri), Iguatu (no Centro-Sul), Crateús (no Sertão dos Inhamuns) e Tianguá (na Serra da Ibiapaba), além da manutenção das restrições severas em Sobral, para conter o avanço da Covid-19 no interior cearense (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/06/26/camilo-anuncia-isolamento-social-rigido-em-sete-municipios-do-interior-do-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-06-0512","y":2020,"m":6,"d":"29","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.229 e nº 17.230</a> (DOE de 29/06/2020), alterando a cobrança da tarifa da Cagece para atividades não essenciais durante a pandemia e suspendendo a queima de fogueiras tradicionais em períodos epidêmicos. No mesmo mês, instituições cearenses lideradas pela Escola de Saúde Pública do Ceará (ESP/CE), Sesa, FIEC/SENAI, UFC, Unifor e Esmaltec apresentam o <a href=\"https://unifor.br/-/cientistas-responsaveis-pelo-capacete-elmo-recebem-medalha-da-abolicao-maior-honraria-do-ceara\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Capacete de Respiração Assistida Elmo</a>, inovação médica cearense não invasiva que reduziu em 60% a necessidade de intubação em leitos de Covid-19.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-06-0513","y":2020,"m":6,"d":"09","h":"Morre em Fortaleza, aos 73 anos de idade, o desembargador Jucid Peixoto do Amaral, integrante do Tribunal de Justiça do Estado do Ceará (TJCE) desde fevereiro de 2011, ex-juiz presidente da 5ª Vara do Júri da Comarca de Fortaleza e professor do Curso de Direito da Universidade de Fortaleza (Unifor). O sepultamento realizou-se no Cemitério Parque da Paz, em Fortaleza. Nascera em Fortaleza, CE, a 16/07/1946 (<a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-falecimento-do-desembargador-jucid-peixoto-do-amaral/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TJCE — Nota de Pesar</a>; <a href=\"https://g1.globo.com/ce/ceara/noticia/2020/07/09/morre-desembargador-do-ceara-jucid-peixoto-do-amaral-aos-73-anos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-07-0514","y":2020,"m":7,"d":"10 e 13","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.234</a> (obrigatoriedade do uso de máscaras em espaços públicos), a Lei Estadual nº 17.235 (DOE de 14/07/2020, que denomina Manoel Rodrigues Pinheiro de Andrade – Neco da Pedra Verde o trecho da CE-473 que liga a BR-226 ao distrito de Assunção, em Solonópole), a Lei Estadual nº 17.236 (Dia Estadual em Memória dos Cidadãos que Faleceram em Decorrência da Covid-19) e a Lei Estadual nº 17.237 (denomina Adilma Mendes Alencar o CEI construído no município de Salitre). No dia 13, o prefeito Roberto Cláudio sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/12924\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.007</a> (DOM nº 16.812, de 29/07/2020), que denomina Túnel Francisco Antônio Martins Nogueira o túnel localizado na Avenida General Osório de Paiva, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-07-0515","y":2020,"m":7,"d":"12","h":"Morre em hospital particular de Fortaleza, aos 75 anos de idade, vítima de complicações da Covid-19, o empresário e político Antônio Gomes Guimarães, ex-prefeito municipal de Aquiraz (gestão 2013–2016). Nascera no Ceará, em 1945 (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/07/12/ex-prefeito-de-aquiraz-antonio-guimaraes-morre-com-covid-19-em-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-07-0516","y":2020,"m":7,"d":"18","h":"Nas semifinais do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série A de 2020</a> (retomado sob protocolo sanitário sem público após paralisação em março), o Guarany Sporting Club, de Sobral, encerra sua participação como a equipe do interior mais bem colocada na classificação geral (4º lugar geral), conquistando a <a href=\"https://www.futebolcearense.com.br/2020/campeoes.asp?cod_categoria=18\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Padre Cícero de 2020</a> (Campeão do Interior).","c":["Esportes"],"l":1},{"id":"ce-2020-07-0517","y":2020,"m":7,"d":"20","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.240</a> (DOE de 20/07/2020), que institui no âmbito do Poder Executivo o Conselho de Governadores do Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-08-0518","y":2020,"m":8,"d":"04","h":"No Estádio de Pituaçu, em Salvador (BA), o Ceará Sporting Club, comandado pelo técnico Guto Ferreira, vence novamente o Esporte Clube Bahia por 1 a 0 (gol do zagueiro Klaus, após ter vencido o jogo de ida por 3 a 1 em 1º de agosto, com gols de Fernando Sobral, Cléber e Mateus Gonçalves) e sagra-se <a href=\"https://pt.wikipedia.org/wiki/Copa_do_Nordeste_de_Futebol_de_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Bicampeão da Copa do Nordeste de 2020 de forma invicta</a> (repetindo o feito invicto de 2015).","c":["Esportes"],"l":1},{"id":"ce-2020-08-0519","y":2020,"m":8,"d":"14 e 21","h":"O governador Camilo Santana sanciona três <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 17 e 25/08/2020): Lei nº 17.262 (denomina José Pedrosa Filho – Zé Filho o CEI localizado em Nova Russas); Lei nº 17.265 (denomina Adalberto Fernandes Luna o CEI no município de Jucás); e Lei nº 17.270 (denomina Antônio Laerte Guedes o trecho da rodovia CE-371 entre o entroncamento com a CE-168 e o distrito de Flamengo, em Saboeiro).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-08-0520","y":2020,"m":8,"d":"25","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/12963\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 929</a>, que denomina Rua Nilo Firmeza (em homenagem ao pintor e museólogo Estrigas) logradouro público localizado no bairro Mondubim, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-09-0521","y":2020,"m":9,"d":"11 e 14","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia e patrimônio cultural</a> (DOE de 14 e 15/09/2020): Lei nº 17.281 (declara como grande destaque cultural e turístico a Estátua do Padre Cícero, em Juazeiro do Norte); Lei nº 17.283 (denomina Rosalina Otaviano Dias o CEI no município de Cedro); Lei nº 17.288 (denomina Pedro Araújo Castro a Areninha localizada em Tamboril); Lei nº 17.289 (denomina Maria Mendes da Silva a Areninha localizada em Ipaporanga); Lei nº 17.290 (denomina Vereador José Batista Filho – Zezinho Batista a EEEP situada em Alto Santo); e Lei nº 17.291 (implantação do Parque José Euclides, em Sobral).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-09-0522","y":2020,"m":9,"d":"16 a 25","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.293</a> (Memorial Virtual das Vítimas da Covid-19), a Lei Estadual nº 17.294 (reconhece o Zoológico do Santuário de São Francisco, em Canindé, como espaço de destacada relevância histórica e cultural), a Lei Estadual nº 17.298 (denomina Alderi Duarte Belo a Areninha do Campo do Cancão, no bairro Vila Velha, em Fortaleza), a Lei Estadual nº 17.299 (institui a Rota do Café no Maciço de Baturité) e a Lei Estadual nº 17.305 (cria a Delegacia de Repressão aos Crimes Cibernéticos – DRCC na Polícia Civil do Ceará).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2020-10-0523","y":2020,"m":10,"d":"06","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.311</a> (DOE de 08/10/2020, indenização para obras de contenção na Encosta do Seminário do Crato) e a Lei Estadual nº 17.314, que denomina Leandro Lopes de Sousa a Escola de Ensino Médio localizada no distrito de Barra, no município de Aiuaba.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-10-0524","y":2020,"m":10,"d":"21","h":"Na partida de volta da final do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série A de 2020</a>, disputada na Arena Castelão sem público, o Fortaleza Esporte Clube, comandado pelo técnico Rogério Ceni, derrota novamente o Ceará Sporting Club por 1 a 0 (gol de Tinga aos 15 minutos do segundo tempo, após vitória tricolor por 2 a 1 no jogo de ida em 30 de setembro, com gols de Bruno Melo e Tinga) e sagra-se Bicampeão Cearense de Futebol (2019–2020), alcançando o seu 43º título estadual.","c":["Esportes"],"l":1},{"id":"ce-2020-10-0525","y":2020,"m":10,"d":"30","h":"Morre no Hospital São Mateus, em Fortaleza, aos 95 anos de idade, o jurista, constitucionalista, cientista político, jornalista e professor emérito da Faculdade de Direito da Universidade Federal do Ceará (UFC) <a href=\"https://g1.globo.com/ce/ceara/noticia/2020/10/30/jurista-paulo-bonavides-morre-aos-95-anos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Paulo Fernandes Bonavides (Paulo Bonavides)</a>. Reconhecido internacionalmente como o decano do Direito Constitucional brasileiro, doutor honoris causa pela Universidade de Lisboa e pela Unifor (<a href=\"https://unifor.br/-/universidade-de-fortaleza-lamenta-morte-do-professor-paulo-bonavides\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Unifor</a>), titular da Cadeira nº 23 da Academia Cearense de Letras (ACL), sócio efetivo do <a href=\"https://www.institutodoceara.org.br/socio/paulo-fernandes-bonavides/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará</a> e membro da Academia Cearense de Letras Jurídicas, deixou obras clássicas como Do Estado Liberal ao Estado Social (1953), Ciência Política (1967), Curso de Direito Constitucional e Teoria Constitucional da Democracia Participativa (<a href=\"https://pt.wikipedia.org/wiki/Paulo_Bonavides\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). O Governo do Ceará e o Conselho Federal da OAB decretaram luto oficial de três dias (<a href=\"https://blogdoedisonsilva.com.br/2020/10/30/governo-do-ceara-oab-nacional-e-oab-ce-decretam-luto-oficial-em-razao-do-falecimento-de-paulo-bonavides/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Edison Silva</a>). Nascera em Patos, PB, a 10 de maio de 1925.","c":["Necrologia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-11-0526","y":2020,"m":11,"d":"05","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.330</a> (DOE de 06/11/2020), que denomina oficialmente o município de Quixeramobim como a \"Capital do Leite\" no Estado do Ceará, e a Lei Estadual nº 17.332, que inclui no Calendário Oficial a Festa de Nossa Senhora do Carmo na Vila de Flores, em Tauá.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-11-0527","y":2020,"m":11,"d":"15","h":"Realiza-se o 1º turno das <a href=\"https://g1.globo.com/ce/ceara/eleicoes/2020/noticia/2020/11/15/prefeitos-eleitos-no-ceara-em-2020-confira-os-candidatos-vitoriosos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Eleições Municipais de 2020 nos 184 municípios cearenses</a> (adiado de outubro para novembro pela Emenda Constitucional nº 107/2020 em razão da pandemia): em Fortaleza, habilitam-se ao 2º turno o deputado estadual e presidente da ALCE José Sarto Nogueira Moreira (PDT, 457.622 votos / 35,73%) e o deputado federal Capitão Wagner Sousa Gomes (PROS, 426.803 votos / 33,32%), ficando a deputada federal Luizianne Lins (PT) em 3º lugar (224.892 votos / 17,56%) (<a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%A3o_municipal_de_Fortaleza_em_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>); em Caucaia, qualificam-se ao 2º turno o prefeito Naumi Amorim (PSD) e o deputado estadual Vitor Valim (PROS); no interior do Estado, são eleitos em turno único: em Sobral, o prefeito reeleito Ivo Ferreira Gomes (PDT, 59,23%); em Juazeiro do Norte, o vereador e policial civil Glêdson Lima Bezerra (Podemos, 38,18%, derrotando o prefeito Arnon Bezerra); no Crato, o prefeito reeleito José Ailton de Sousa Brasil (Zé Ailton Brasil, PT, 58,69%); em Maracanaú, Roberto Soares Pessoa (PSDB, 66,32%); em Quixadá, o médico Ricardo José Araújo Silveira (PSD, 50,82%); em Iguatu, o prefeito reeleito Ednaldo de Lavor Couras (PSD); em Aracati, o prefeito reeleito Bismarck Costa Lima Pinheiro Maia (PDT); em Crateús, o prefeito reeleito Marcelo Machado (SD); em Russas, Sávio Gurgel Nogueira (PDT); em Canindé, a prefeita reeleita Maria do Rosário Araújo Pedrosa Ximenes (Rosário Ximenes, DEM); e em Tauá, Patrícia Pequeno Costa Gomes de Aguiar (PSD).","c":["Política e Instituições"],"l":1},{"id":"ce-2020-11-0528","y":2020,"m":11,"d":"23","h":"Morre no Hospital Regional do Cariri (HRC), em Juazeiro do Norte, vítima de complicações da Covid-19, apenas oito dias após haver sido reeleito para o seu quarto mandato parlamentar na eleição de 15/11/2020, o vereador e ex-vice-prefeito municipal de Assaré Edson Silva (PT). Nascera em Assaré, CE (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/11/23/vereador-reeleito-em-assare-no-ceara-morre-com-covid-19-oito-dias-apos-eleicao.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-11-0529","y":2020,"m":11,"d":"20","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.335</a> (DOE de 23/11/2020), que denomina Dom Aloísio Lorscheider o novo Centro de Desporto e Cultura (Parque Urbano) construído no bairro Itaperi, em Fortaleza, na área do antigo Instituto Penal Professor Olavo Oliveira I (IPPOO I).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2020-11-0530","y":2020,"m":11,"d":"29","h":"Realiza-se o 2º turno das Eleições Municipais de 2020 em Fortaleza e em Caucaia: em Fortaleza, o médico e deputado estadual <a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%A3o_municipal_de_Fortaleza_em_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Sarto Nogueira Moreira (Dr. Sarto, PDT)</a>, tendo o sociólogo José Élcio Batista (PSB) como vice-prefeito, é eleito Prefeito de Fortaleza com 668.652 votos (51,69% dos votos válidos), derrotando o deputado federal Capitão Wagner Sousa Gomes (PROS), que obteve 624.892 votos (48,31%) (<a href=\"https://blogdoedisonsilva.com.br/2020/11/29/jose-sarto-e-o-futuro-prefeito-de-fortaleza-ele-venceu-capitao-wagner-com-uma-diferenca-de-63-760-votos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Edison Silva</a>); em Caucaia, o deputado estadual e comunicador Vitor Pereira Valim (PROS) é eleito Prefeito Municipal no 2º turno com 83.588 votos (51,08%), superando o prefeito Naumi Amorim (PSD, 80.045 votos / 48,92%).","c":["Política e Instituições"],"l":1},{"id":"ce-2020-11-0531","y":2020,"m":11,"d":"15","h":"Nos municípios-polo do <strong>Maciço de Baturité</strong>, são eleitos em 15/11/2020: em <strong>Baturité</strong>, o empresário <strong>Herberlh Freitas Reis Mota</strong> (<strong>Herberlh Mota</strong>, PL), com 7.419 votos (36,72% dos votos válidos), derrotando Ivo Júnior (PSB, 30,94%) (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/11/16/herberlh-mota-do-pl-e-eleito-prefeito-de-baturite.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); e em <strong>Redenção</strong>, <strong>Davi de Oliveira Benevides</strong> (<strong>Davi Benevides</strong>, PDT), reeleito com 15.047 votos (83,35% dos votos válidos) (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/11/15/davi-benevides-do-pdt-e-eleito-prefeito-de-redencao.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2020-12-0532","y":2020,"m":12,"d":"07 e 11","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 07, 10 e 11/12/2020): Lei nº 17.336 (denomina Ana Ester Jucá Maia Soares o trecho da CE-292 que liga Missão Velha ao Aeroporto de Juazeiro do Norte); Lei nº 17.340 (Areninha Gleydson Cardoso de Carvalho, em Martinópole); Lei nº 17.341 (denomina João Sotero Veras a orla praiana do distrito de Bitupitá, em Barroquinha); Lei nº 17.342 (Areninha Francisco Lairton Rodrigues dos Santos, em Uruoca); Lei nº 17.343 (Areninha Vicente Benício de Vasconcelos, em Moraújo); Lei nº 17.344 (CEI Lemir Xavier Cruz, em Missão Velha); e Lei nº 17.351, que denomina Francisco Humberto Bezerra o trecho do Anel Viário do Cariri referente ao Contorno de Juazeiro do Norte, desde o viaduto entre Juazeiro do Norte e Crato até o entroncamento com a CE-060 no acesso a Barbalha.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-12-0533","y":2020,"m":12,"d":"08","h":"Na final em jogo único do <a href=\"https://futebolcearense.com.br/2020/noticia_ver.asp?id=11917\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série B de 2020</a>, a Associação Desportiva Recreativa Cultural Icasa, de Juazeiro do Norte, derrota o Crato Esporte Clube pelo placar de 2 a 0 e sagra-se campeã da Segunda Divisão estadual (seu terceiro título na categoria, após 2003 e 2010), assegurando ambas as equipes caririenses o retorno à Série A do Campeonato Cearense de 2021 (<a href=\"https://pt.wikipedia.org/wiki/Associa%C3%A7%C3%A3o_Desportiva_Recreativa_Cultural_Icasa\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>).","c":["Esportes"],"l":1},{"id":"ce-2020-12-0534","y":2020,"m":12,"d":"10","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13011\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 940</a> (DOM nº 16.926, de 14/12/2020), que denomina Rua Vicente Paraibano a antiga Rua Malmequer, localizada no bairro Serrinha, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-12-0535","y":2020,"m":12,"d":"25","h":"Morre em hospital particular de Fortaleza, aos 60 anos de idade, vítima de complicações da Covid-19, o radialista, jornalista, empresário da comunicação e político Normando Sóracles Gonçalves, fundador do portal de notícias Site Miséria (sediado em Juazeiro do Norte), diretor da Rádio Progresso de Juazeiro e ex-vereador à Câmara Municipal de Juazeiro do Norte por dois mandatos. Nascera em Cajazeiras, PB, em 1960 (<a href=\"https://g1.globo.com/ce/ceara/noticia/2020/12/25/radialista-e-ex-vereador-de-juazeiro-do-norte-normando-soracles-morre-de-covid-19.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2020-12-0536","y":2020,"m":12,"d":"27","h":"Pelas oitavas de final do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Brasileiro_de_Futebol_de_2020_-_S%C3%A9rie_D\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Brasileiro de Futebol da Série D de 2020</a>, após empatar o jogo de ida por 2 a 2 no Maranhão, o Floresta Esporte Clube derrota a Sociedade Esportiva Juventude Samas (MA) por 2 a 0 e avança às quartas de final (\"jogo do acesso\") contra o América Futebol Clube (RN), garantindo em janeiro de 2021 o inédito acesso à Série C nacional e o vice-campeonato brasileiro da Série D da temporada 2020 (<a href=\"https://www.futebolcearense.com.br/2020/noticia_ver.asp?id=12136\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Federação Cearense de Futebol</a>; <a href=\"https://agenciabrasil.ebc.com.br/esportes/noticia/2021-01/floresta-ce-vence-america-rn-e-fica-perto-de-subir-serie-c\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Agência Brasil</a>).","c":["Esportes"],"l":1},{"id":"ce-2020-12-0537","y":2020,"m":12,"d":"28","h":"O prefeito municipal de Fortaleza, Roberto Cláudio Rodrigues Bezerra, sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.069, de 28/12/2020</a> (DOM de 30/12/2020), que denomina de Cantor e Compositor Evaldo Gouveia uma avenida no Município de Fortaleza, em homenagem póstuma ao artista cearense falecido em 29/05/2020 (<a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SAPL CMFor</a>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-12-0538","y":2020,"m":12,"d":"29","h":"O prefeito Roberto Cláudio Rodrigues Bezerra sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.072, de 29/12/2020</a> (DOM de 30/12/2020), que denomina de Jurista Paulo Bonavides uma praça pública localizada no bairro Luciano Cavalcante, em Fortaleza, em homenagem póstuma ao constitucionalista falecido em 30/10/2020 (<a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SAPL CMFor</a>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2020-12-0539","y":2020,"m":12,"d":"15 a 30","h":"O governador Camilo Santana sanciona o último bloco de leis estaduais de 2020 (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2020/e2020.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): Lei nº 17.353 (CEI Mais Infância Sofia de Abreu Cordeiro, em Maranguape); Lei nº 17.359 (transferência de recursos ao Instituto do Ceará e à Academia Cearense de Letras); Lei nº 17.364 (LOA 2021); Lei nº 17.365 (Areninha Francisco Alves Costa, em Orós); Lei nº 17.366 (denomina João Gentil Júnior a ponte sobre o Rio Pacoti na CE-025); Lei nº 17.369 (EEEP Maria Madeiro Dias, em Monsenhor Tabosa); Lei nº 17.373 (denomina Luzia Brito de Sousa o trecho da CE-594 que liga a CE-265 ao Açude dos Pinheiros, em Ibicuitinga); Lei nº 17.374 (Terminal Rodoviário Elesbão Ferreira Gomes, em Itarema); Lei nº 17.375 (declara de destacada relevância histórico-cultural a Ermida da Mãe Rainha, em Morada Nova); e Lei nº 17.377 (DOE de 30/12/2020), tornando permanente o programa de auxílio financeiro aos catadores de materiais recicláveis do Estado do Ceará.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-01-0540","y":2021,"m":1,"d":"01","h":"Passa a vigorar o novo salário mínimo nacional de R$ 1.100,00 (mil e cem reais), correspondente ao valor diário de R$ 36,67 e horário de R$ 5,00, fixado originalmente pela Medida Provisória nº 1.021/2020 e converted na <a href=\"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14158.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Federal nº 14.158, de 02/06/2021</a>.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-01-0541","y":2021,"m":1,"d":"01","h":"Em solenidade híbrida no Plenário Fausto Arruda da Câmara Municipal de Fortaleza (CMFor), tomam posse os 43 vereadores eleitos para a 19ª Legislatura (2021–2024) e é reeleito presidente do Legislativo Municipal, em chapa única para o biênio 2021–2022, o vereador Antônio Henrique da Silva (PDT), compondo-se a Mesa Diretora com Adail Fernandes Vieira Júnior (1º vice-presidente), Ana Paula Brandão da Silva Farias (2ª vice-presidente), Francisco Eudes Ferreira Bringel (3º vice-presidente), Julierme Lima de Sena (1º secretário), Guilherme de Figueiredo Sampaio (2º secretário) e Kátia Maria Rodrigues de Sousa (3ª secretária). Ato contínuo, perante a edilidade e com participação virtual do governador Camilo Sobreira de Santana, tomam posse no cargo de prefeito municipal de Fortaleza o médico José Sarto Nogueira Moreira (Dr. Sarto, PDT) e, como vice-prefeito, o sociólogo José Élcio Batista (PSB), seguindo para cerimônia de transmissão de cargo no Paço Municipal (<a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/vereadores-tomam-posse-para-a-19a-legislatura-na-camara-municipal\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">CMFor</a>, <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13091\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SAPL CMFor – Ato da Mesa nº 1/2021</a>, <a href=\"https://oestadoce.com.br/fortaleza-296/prefeito-jose-sarto-destaca-desafios-e-avancos-de-sua-gestao-em-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2021-01-0542","y":2021,"m":1,"d":"01","h":"Tomam posse para o quadriênio 2021–2024 os prefeitos, vice-prefeitos e vereadores eleitos nos municípios do interior cearense: em Sobral, o prefeito reeleito Ivo Ferreira Gomes (PDT) e a vice-prefeita Christianne Marie Aguiar Coelho, juntamente com os 21 vereadores da Câmara Municipal (<a href=\"https://g1.globo.com/ce/ceara/noticia/2021/01/01/prefeito-e-vereadores-de-sobral-tomam-posse-veja-lista-de-eleitos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Juazeiro do Norte, o prefeito eleito Glêdson Lima Bezerra (Podemos) e o vice-prefeito Giovanni Sampaio Gondim (<a href=\"https://pt.wikipedia.org/wiki/Gl%C3%AAdson_Lima_Bezerra\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>); e, no Crato, o prefeito reeleito José Ailton de Sousa Brasil (Zé Ailton Brasil, PT) e o vice-prefeito André Barreto Esmeraldo, ao lado dos 19 vereadores da Câmara Municipal (<a href=\"https://g1.globo.com/ce/ceara/noticia/2021/01/01/prefeito-e-vereadores-de-crato-tomam-posse-veja-lista-de-eleitos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2021-01-0543","y":2021,"m":1,"d":"04","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.378</a> (DOE de 04/01/2021), que institui no âmbito do Estado do Ceará o Programa Cientista-Chefe como política pública permanente, e a Lei Estadual nº 17.379 (DOE de 04/01/2021), que dispõe sobre a transformação de cargos vagos efetivos de magistrados e servidores do Poder Judiciário do Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-01-0544","y":2021,"m":1,"d":"05","h":"É sancionada pelo governador Camilo Santana a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.380</a> (DOE de 05/01/2021), que consolida e atualiza o marco legal do Programa Mais Infância Ceará.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-01-0545","y":2021,"m":1,"d":"07","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.382</a> (DOE de 08/01/2021), que altera os anexos referentes aos municípios de Tabuleiro do Norte e Alto Santo na Lei Estadual nº 16.821/2019, sobre a descrição dos limites intermunicipais no Ceará.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2021-01-0546","y":2021,"m":1,"d":"11","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.383</a> (DOE de 11/01/2021), que cria o Programa Estadual Agente Jovem Ambiental (AJA), destinado à inclusão social e ambiental de jovens nos 184 municípios cearenses.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2021-01-0547","y":2021,"m":1,"d":"13","h":"O prefeito José Sarto sanciona em Fortaleza a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13055\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária nº 11.073</a> (normas de bem-estar animal), a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13053\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária nº 11.075</a> (uso de prédios da rede municipal de ensino para ensaios de quadrilhas juninas e grupos culturais) e a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária nº 11.077</a>, que torna obrigatória a inclusão do nome do bairro nas placas indicativas dos logradouros públicos de Fortaleza. Na mesma data, morre em Fortaleza, aos 71 anos, vítima de complicações da Covid-19, o médico e empresário <a href=\"https://diariodonordeste.verdesmares.com.br/metro/medico-trajano-almeida-morre-por-complicacoes-da-covid-19-em-fortaleza-1.3032714\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Trajano Augusto de Almeida Filho</a>, diretor-proprietário da Clínica Trajano Almeida, no bairro Aldeota.","c":["Necrologia","Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-01-0548","y":2021,"m":1,"d":"17","h":"Morre em Fortaleza, aos 60 anos, vítima de câncer, o ex-deputado estadual e ex-vereador <a href=\"https://g1.globo.com/ce/ceara/noticia/2021/01/17/morre-o-ex-deputado-cearense-roberto-mesquita.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Roberto Mesquita da Silveira Júnior</a> (PSD). Filho de Roberto Lucena da Silveira e criado em General Sampaio, atuou como diretor do Desafio Jovem do Ceará, elegeu-se vereador de Fortaleza em 2008 e exerceu dois mandatos consecutivos como deputado estadual na Assembleia Legislativa do Ceará (2011–2018) (<a href=\"https://www2.al.ce.gov.br/legislativo/tramit2021/pl8_21.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE – PL nº 8/2021</a>). Seu corpo foi velado na Funerária Ethernus e sepultado no Cemitério Parque da Paz, em Fortaleza. Nascera em Baturité, CE, a 28 de março de 1960.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2021-01-0549","y":2021,"m":1,"d":"18","h":"Com a chegada ao Aeroporto Internacional de Fortaleza – Pinto Martins do primeiro lote de 218 mil doses da vacina CoronaVac (Sinovac/Instituto Butantan), tem início no Hospital Estadual Leonardo Da Vinci, em Fortaleza, a <a href=\"https://www.ce.gov.br/2021/01/18/ceara-inicia-vacinacao-contra-a-covid-19/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">campanha de vacinação contra a Covid-19 no Ceará</a>, na presença do governador Camilo Santana, do prefeito José Sarto e do secretário estadual da Saúde Carlos Roberto Martins Sobrinho (Dr. Cabeto). A técnica de enfermagem <a href=\"https://diariodonordeste.verdesmares.com.br/metro/tecnica-de-enfermagem-recebe-primeira-vacina-contra-covid-19-no-ceara-e-comemora-e-muita-emocao-1.3034980\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Silvana Souza Reis</a>, de 51 anos, torna-se a primeira pessoa vacinada em solo cearense, iniciando-se simultaneamente a distribuição aérea pela Ciopaer para Sobral, Juazeiro do Norte, Crato, Iguatu, Quixadá, Canindé, Crateús, Tauá, Aracati, Russas e demais regiões de saúde do Estado (<a href=\"https://oestadoce.com.br/fortaleza-296/gestao-sarto-mudancas-e-realizacoes-na-capital/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-01-0550","y":2021,"m":1,"d":"23","h":"Morre em Fortaleza, aos 62 anos, vítima de complicações da Covid-19, o contabilista e político <a href=\"https://diariodonordeste.verdesmares.com.br/politica/morre-ex-prefeito-de-bela-cruz-carlos-antonio-vitima-da-covid-19-1.3071781\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ted Rocha Pontes</a>. Filho do ex-prefeito de Caucaia Juaci Sampaio Pontes e de Ana Rocha Pontes, foi vereador e presidente da Câmara Municipal de Caucaia (1983–1990) e deputado estadual por dois mandatos na Assembleia Legislativa do Ceará (1991–1998) (<a href=\"https://mapacultural.secult.ce.gov.br/files/project/5018/deputados-estaduais-23-legislatura-1991-1994.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE/INESP</a>). Nascera em Caucaia, CE, a 28 de outubro de 1958.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2021-01-0551","y":2021,"m":1,"d":"27","h":"Morre aos 88 anos, vítima de complicações da Covid-19, o político caririense <a href=\"https://diariodonordeste.verdesmares.com.br/politica/morre-ex-prefeito-de-bela-cruz-carlos-antonio-vitima-da-covid-19-1.3071781\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Carlos Alberto da Cruz</a>, que exerceu cinco mandatos como deputado estadual na Assembleia Legislativa do Ceará e foi prefeito municipal de Juazeiro do Norte por três gestões (1989–1992, 1997–2000 e 2001–2004).","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2021-01-0552","y":2021,"m":1,"d":"29","h":"Em sessão solene conduzida a partir do Palácio da Justiça no Cambeba, tomam posse os novos dirigentes do <a href=\"https://www.tjce.jus.br/noticias/nova-presidente-do-tribunal-de-justica-vai-aliar-tecnologia-com-humanizacao-dos-servicos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Tribunal de Justiça do Estado do Ceará (TJCE)</a> para o biênio 2021–2023: a desembargadora Maria Nailde Pinheiro Nogueira no cargo de presidente da Corte, o desembargador Antônio Abelardo Benevides Moraes como vice-presidente e o desembargador Paulo Airton Albuquerque Filho como corregedor-geral da Justiça.","c":["Política e Instituições"],"l":1},{"id":"ce-2021-01-0553","y":2021,"m":1,"d":"30","h":"Morre em Fortaleza, aos 71 anos, vítima de complicações da Covid-19, o ex-vereador <a href=\"https://diariodonordeste.verdesmares.com.br/politica/morre-ex-prefeito-de-bela-cruz-carlos-antonio-vitima-da-covid-19-1.3071781\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Eurivá Matias (Titico)</a>, que exerceu quatro mandatos parlamentares na Câmara Municipal de Fortaleza a partir de 1989. Nascera em Fortaleza, CE, a 12 de junho de 1949.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2021-02-0554","y":2021,"m":2,"d":"01","h":"Na sessão solene de abertura do ano legislativo da 30ª Legislatura, toma posse a nova Mesa Diretora da Assembleia Legislativa do Estado do Ceará (ALCE) para o biênio 2021–2022, presidida pelo deputado <a href=\"https://diariodonordeste.verdesmares.com.br/politica/evandro-leitao-e-eleito-presidente-da-assembleia-legislativa-do-ceara-por-unanimidade-1.3020095\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Evandro Sá Barreto Leitão</a> (PDT), tendo como 1º vice-presidente Fernando Santana (PT), 2º vice-presidente Danniel Oliveira (MDB), 1º secretário Antônio Granja (PDT), 2º secretário Audic Mota (PSB), 3ª secretária Érika Amorim (PSD) e 4º secretário Apóstolo Luiz Henrique (PP), ocasião em que o governador Camilo Santana apresenta a mensagem governamental anual (<a href=\"https://g1.globo.com/ce/ceara/noticia/2021/02/01/assembleia-legislativa-do-ceara-e-camara-de-fortaleza-iniciam-as-atividades-de-2021-sessoes-vao-ser-hibridas.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2021-02-0555","y":2021,"m":2,"d":"04","h":"Morre em Fortaleza, aos 83 anos, o historiador, professor universitário e pesquisador <a href=\"https://www.institutodoceara.org.br/socio/pedro-alberto-de-oliveira-silva/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Pedro Alberto de Oliveira Silva</a>. Filho de Antônio Alberto da Silva e Rita de Oliveira Silva, graduado em História pela Faculdade Católica de Filosofia do Ceará (1961) e mestre pela UFPE (1976), lecionou na UFC e na Unifor e foi sócio efetivo do Instituto do Ceará (Histórico, Geográfico e Antropológico) desde 04 de dezembro de 1974, deixando obras como Pequena História da Telefonia no Ceará (1982) e A Escravidão no Ceará: O Trabalho Escravo e a Abolição (1986). Nascera em Fortaleza, CE, a 24 de julho de 1937.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-02-0556","y":2021,"m":2,"d":"10","h":"Morre no Hospital São Miguel, na cidade do Crato, aos 87 anos, vítima de complicações da Covid-19, o empresário e político <a href=\"https://www.ceara1.com.br/noticias/saude/corona-virus/513705/ex-prefeito-de-crato-morre-aos-87-anos-por-complicacoes-da-covid-19.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Moacir Siqueira (\"Joinha\")</a>, que exerceu o cargo de prefeito municipal do Crato entre 1998 e 2000. Nascera em São José do Egito, PE, a 14 de agosto de 1933.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-02-0557","y":2021,"m":2,"d":"14","h":"Na decisão em jogo único da <a href=\"https://pt.wikipedia.org/wiki/Ta%C3%A7a_Fares_Lopes_de_2020\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Fares Lopes</a> (edição de 2020, concluída em fevereiro de 2021 em virtude da pandemia), disputada no Estádio Domingão, em Horizonte, o Ferroviário Atlético Clube derrota o Icasa, de Juazeiro do Norte, por 1 a 0 (gol de Berguinho aos 38 minutos do segundo tempo), conquistando seu segundo título da competição e garantindo vaga na Copa do Brasil.","c":["Esportes"],"l":1},{"id":"ce-2021-02-0558","y":2021,"m":2,"d":"22","h":"Morre no Hospital da Unimed, em Fortaleza, aos 80 anos, vítima de complicações da Covid-19, o médico cirurgião e político <a href=\"https://sindojus-ce.org.br/noticias/sindojus-lamenta-a-morte-pela-covid-19-do-medico-e-ex-vereador-de-fortaleza-iraguassu-teixeira/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Iraguassú Teixeira</a>. Graduado em Medicina pela UFC, atuou por 51 anos no Instituto Dr. José Frota (IJF), chefiou o departamento médico do Ceará Sporting Club e exerceu sete mandatos consecutivos como vereador de Fortaleza pelo PDT (1989–2016). A Câmara Municipal de Fortaleza decretou luto oficial de três dias. Nascera em Canindé, CE, a 07 de janeiro de 1941.","c":["Necrologia","Esportes","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-02-0559","y":2021,"m":2,"d":"23","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.384</a> (DOE de 24/02/2021), que concede o Título de Cidadão Cearense ao vice-prefeito de Fortaleza José Élcio Batista, bem como as Leis Estaduais nº 17.385, 17.386 e 17.387, instituindo medidas emergenciais de amparo ao setor cultural e de eventos.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-02-0560","y":2021,"m":2,"d":"26","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.388 a nº 17.392</a> (DOE de 26/02/2021), dispondo sobre a reestruturação das carreiras da Polícia Civil e da Perícia Forense do Estado do Ceará (Pefoce).","c":["Política e Instituições"],"l":1},{"id":"ce-2021-02-0561","y":2021,"m":2,"d":"27","h":"O governador Camilo Santana entrega virtualmente <a href=\"https://g1.globo.com/ce/ceara/noticia/2021/02/27/hgf-vai-ter-novos-22-leitos-de-uti-para-covid-19-e-crateus-recebe-10-unidades-de-terapia-intensiva.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">10 novos leitos de UTI no Hospital Geral de Crateús e 22 novos leitos de UTI no Hospital Geral de Fortaleza (HGF)</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-03-0562","y":2021,"m":3,"d":"02","h":"Morre em Fortaleza, vítima de complicações da Covid-19, o compositor, letrista e produtor musical cearense <a href=\"https://diariodonordeste.verdesmares.com.br/verso/morre-o-compositor-cearense-eason-nascimento-1.3054278\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Eason Nascimento</a>, autor dos álbuns Recado, Passarinho e Vivo a Sonhar.","c":["Necrologia"],"l":1},{"id":"ce-2021-03-0563","y":2021,"m":3,"d":"03","h":"O governador Camilo Santana e o prefeito José Sarto anunciam a decretação de isolamento social rígido (lockdown) em Fortaleza a partir de 05 de março (estendido para todo o Ceará em 11 de março), restringindo o funcionamento presencial às atividades essenciais diante da segunda onda da pandemia da Covid-19 (<a href=\"https://g1.globo.com/ce/ceara/noticia/2021/03/03/camilo-decreta-fechamento-de-atividades-nao-essenciais-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/negocios/novo-decreto-de-camilo-prorroga-lockdown-no-ceara-flexibilizacao-comeca-dia-12-de-abril-1.3068964\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-03-0564","y":2021,"m":3,"d":"04","h":"A Mesa Diretora da Câmara Municipal de Fortaleza promulga a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13064\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Emenda à Lei Orgânica nº 19</a>, e o governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.401</a> (DOE de 05/03/2021), concedendo o Título de Cidadã Cearense à professora da UFC Dolores Aronovich Aguero (Lola Aronovich).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-03-0565","y":2021,"m":3,"d":"09","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.403</a> (DOE de 09/03/2021), que denomina Dr. Luciano de Arruda Coelho o novo Aeroporto Regional de Sobral, e entrega <a href=\"https://www.ce.gov.br/saude/2021/03/10/com-entregas-em-iguatu-governo-do-ceara-chega-a-3-540-leitos-para-covid-19-entre-uti-e-enfermaria/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">21 novos leitos para tratamento da Covid-19 no município de Iguatu</a>.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-03-0566","y":2021,"m":3,"d":"10","h":"Morre em Fortaleza, vítima de complicações da Covid-19, o ex-vereador <a href=\"https://diariodonordeste.verdesmares.com.br/politica/morre-ex-prefeito-de-bela-cruz-carlos-antonio-vitima-da-covid-19-1.3071781\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Carlos Alberto Dutra da Silva (Carlos Dutra)</a>, que exerceu três mandatos na Câmara Municipal de Fortaleza. Na mesma data, o prefeito José Sarto entrega <a href=\"https://www.fortaleza.ce.gov.br/noticias/sarto-entrega-36-leitos-para-tratamento-de-pacientes-com-covid-19-numero-na-rede-municipal-chega-a-644\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">36 novos leitos no Hospital e Maternidade Dra. Zilda Arns (Hospital da Mulher)</a>.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-03-0567","y":2021,"m":3,"d":"12","h":"As águas da transposição do Rio São Francisco (Eixo Norte), após ingressarem no Ceará por Jati e percorrerem o Cinturão das Águas do Ceará (CAC) e os rios Salgado e Jaguaribe, <a href=\"https://agenciaeconordeste.com.br/recursos-hidricos/aguas-do-sao-francisco-chegam-ao-castanhao-e-garantem-abastecimento-de-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">chegam oficialmente ao Açude Castanhão</a>, garantindo a segurança hídrica do maior reservatório do Estado e da Região Metropolitana de Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-03-0568","y":2021,"m":3,"d":"15","h":"O governador Camilo Santana sanciona quatro <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 16/03/2021): Lei nº 17.414 (Areninha Aurino Eduardo da Silva, em Ocara); Lei nº 17.415 (Centro de Esportes Jacob Bezerra Lima, em Crateús); Lei nº 17.416 (denomina Valdemar Arruda Cavalcante a rodovia CE-168 entre Mombaça e Pedra Branca); e Lei nº 17.417 (Areninha Abner Porfírio Sampaio, em Tururu).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-03-0569","y":2021,"m":3,"d":"16 e 23","h":"O prefeito José Sarto sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13076\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária nº 11.085</a> (Escola de Tempo Integral Major Ashton Guilherme da Silva), a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária nº 11.086</a> (Memorial do Futsal José Milton Bezerra da Cunha no Ginásio Aécio de Borba) e a Lei Ordinária nº 11.097 (Centro de Memória Frei Tito de Alencar Lima, no Centro de Fortaleza). No dia 23, é sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.428</a> (DOE de 24/03/2021), instituindo o auxílio social Vale Gás (<a href=\"https://blogdoeliomar.com/lula-prorroga-auxilio-gas-ate-2031/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Eliomar de Lima</a>).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-03-0570","y":2021,"m":3,"d":"25","h":"Nas comemorações da Data Magna do Ceará (137 anos da Abolição da Escravatura na Província), o governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.432</a> (DOE de 25/03/2021), instituindo a reserva de 20% das vagas para candidatos negros nos concursos públicos e seleções do Poder Executivo estadual.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-04-0571","y":2021,"m":4,"d":"03","h":"Morre em Fortaleza, na madrugada de Sábado de Aleluia, aos 94 anos, vítima de complicações da Covid-19, o coronel da reserva do Exército, empresário e líder político <a href=\"https://portaldoservidor.al.ce.gov.br/noticias/al-decreta-luto-oficial-pela-morte-do-ex-governador-adauto-bezerra\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Adauto Bezerra de Menezes (Adauto Bezerra)</a>, conhecido na historiografia política como \"o último dos coronéis\" do Ceará (ao lado de Virgílio Távora e César Cals). Irmão gêmeo de Humberto Bezerra (falecido em março de 2020), formou-se pela AMAN, foi deputado estadual por quatro legislaturas consecutivas (1959–1975) e presidente da Assembleia Legislativa, governador do Estado do Ceará (1975–1978), deputado federal mais votado do Estado (1979–1983), vice-governador do Ceará (1983–1985), superintendente da SUDENE (1990–1991) e fundador do BicBanco (<a href=\"https://pt.wikipedia.org/wiki/Adauto_Bezerra\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Foi sepultado no Cemitério Parque da Paz, em Fortaleza, sob luto oficial de três dias. Nascera em Juazeiro do Norte, CE, a 03 de julho de 1926. Na mesma data, morre por complicações da Covid-19 o prefeito reeleito do município de Palhano, <a href=\"https://pt.wikipedia.org/wiki/Palhano\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ivanildo Nunes da Silva (\"Dinho do Zé do Honório\")</a>.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2021-04-0572","y":2021,"m":4,"d":"10","h":"Morre no Hospital São José, em Fortaleza, aos 56 anos, vítima de complicações da Covid-19, o jornalista <a href=\"https://diariodonordeste.verdesmares.com.br/metro/morre-jornalista-fernando-ribeiro-aos-56-anos-por-complicacoes-da-covid-19-1.3071415\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Fernando Ribeiro</a>, decano da cobertura policial e de segurança pública no Estado, ex-editor de Polícia do Diário do Nordeste e comentarista da TV Verdes Mares (<a href=\"https://g1.globo.com/ce/ceara/noticia/2021/04/10/jornalista-fernando-ribeiro-morre-com-covid-em-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Na mesma data, morre em Fortaleza, aos 58 anos, vítima da Covid-19, o ex-prefeito de Bela Cruz <a href=\"https://diariodonordeste.verdesmares.com.br/politica/morre-ex-prefeito-de-bela-cruz-carlos-antonio-vitima-da-covid-19-1.3071781\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Carlos Antônio Vasconcelos Carvalho</a>.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-04-0573","y":2021,"m":4,"d":"17","h":"Morre em Fortaleza, aos 71 anos, vítima de complicações da Covid-19, o jornalista, publicitário, escritor, professor universitário e pesquisador da cultura popular cearense <a href=\"https://pt.wikipedia.org/wiki/Gilmar_de_Carvalho\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Gilmar Cavalcante de Carvalho (Gilmar de Carvalho)</a>. Bacharel em Direito (1972) e em Comunicação Social (1973) pela UFC, mestre pela Metodista-SP e doutor em Comunicação e Semiótica pela PUC-SP (1998), foi professor associado do Curso de Jornalismo da UFC e autor de mais de cinquenta livros fundamentais sobre xilogravura, literatura de cordel, rabeca, reisados e mestres da cultura do Cariri, agraciado com o Prêmio Rodrigo Melo Franco de Andrade (IPHAN, 2014) e a Medalha Mário de Andrade (2017) (<a href=\"https://jornalismo.ufc.br/post/para-lembrar-gilmar-de-carvalho\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">UFC</a>, <a href=\"https://unifor.br/-/tv-unifor-exibe-documentario-em-homenagem-ao-professor-e-pesquisador-gilmar-de-carvalho\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Unifor</a>). Nascera em Sobral, CE, a 30 de agosto de 1949.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-04-0574","y":2021,"m":4,"d":"20","h":"O governador Camilo Santana sanciona três <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 22/04/2021): Lei nº 17.449 (Areninha Zenilso Valdemiro da Silva, em Icapuí); Lei nº 17.451 (Delegacia de Polícia Civil Manuel Arlindo de Souza, em Pacujá); e Lei nº 17.452 (Areninha Francisco de Paula Alves Sousa, em Tamboril).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-04-0575","y":2021,"m":4,"d":"21","h":"O prefeito José Sarto entrega, no Terminal do Siqueira, a <a href=\"https://www.fortaleza.ce.gov.br/noticias/sarto-entrega-13-base-do-samu-no-bairro-siqueira\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">13ª base descentralizada do SAMU 192 de Fortaleza</a>.","c":["Política e Instituições"],"l":1},{"id":"ce-2021-05-0576","y":2021,"m":5,"d":"01 e 08","h":"Realiza-se a decisão da <a href=\"https://pt.wikipedia.org/wiki/Copa_do_Nordeste_de_Futebol_de_2021\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa do Nordeste de 2021</a> entre Ceará Sporting Club e Esporte Clube Bahia: após vencer o jogo de ida por 1 a 0 no Estádio de Pituaçu, em Salvador, em 01 de maio (gol de Jael), o Ceará é superado por 2 a 1 no jogo de volta na Arena Castelão, em 08 de maio, e por 4 a 2 nos pênaltis, ficando com o vice-campeonato regional (<a href=\"https://portalesportivo.net/mais-campeonatos/outros-campeonatos/bahia-vence-o-ceara-nos-penaltis-e-ganha-a-copa-do-nordeste-2021\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Portal Esportivo</a>).","c":["Esportes"],"l":1},{"id":"ce-2021-05-0577","y":2021,"m":5,"d":"03 e 06","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.459, 17.463, 17.466, 17.467 e 17.472</a> (DOE de 03 e 07/05/2021), denominando equipamentos em Senador Sá, Umirim e Brejo Santo e reconhecendo a Banda de Música Padre Cícero (Juazeiro do Norte) e a Estátua de São Francisco das Chagas (Canindé). No dia 04, o Fortaleza Esporte Clube anuncia a contratação do treinador argentino <a href=\"https://pt.wikipedia.org/wiki/Juan_Pablo_Vojvoda\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Juan Pablo Vojvoda</a>.","c":["Esportes","Política e Instituições"],"l":1},{"id":"ce-2021-05-0578","y":2021,"m":5,"d":"16","h":"Morre em Fortaleza o magistrado <a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-juiz-michel-pinheiro/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Michel Pinheiro</a>, juiz titular do 3º Juizado Especial Cível de Fortaleza e ex-presidente da Associação Cearense de Magistrados (ACM), sendo sepultado no Cemitério Parque da Paz.","c":["Necrologia"],"l":1},{"id":"ce-2021-05-0579","y":2021,"m":5,"d":"17","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.485, 17.487 e 17.493</a> (DOE de 19/05/2021), denominando a EEEP João Jackson Lobo Guerra (em Itatira), o CEI Jucileide Rodrigues Sales (em Independência) e a Areninha Francisca Elaine Mesquita Farias (em Catunda). Na mesma data, o Pacajus Esporte Clube conquista de forma inédita a <a href=\"https://pt.wikipedia.org/wiki/Ta%C3%A7a_Padre_C%C3%ADcero\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Padre Cícero de 2021</a> (Campeão do Interior).","c":["Esportes","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-05-0580","y":2021,"m":5,"d":"18 a 24","h":"O prefeito José Sarto sanciona as Leis Ordinárias Municipais nº 11.104, 11.107, 11.108, <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13109?display\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">11.113</a> (que denomina Dr. José Iraguassú Teixeira o Posto de Saúde da Floresta, no bairro Álvaro Weyne) e 11.114 (<a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SAPL CMFor</a>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-05-0581","y":2021,"m":5,"d":"23","h":"Na final em partida única do Campeonato Cearense da Série A de 2021, disputada na Arena Castelão com portões fechados, o Fortaleza Esporte Clube empata em 0 a 0 com o Ceará Sporting Club e, beneficiado pela melhor campanha geral, sagra-se <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/fortaleza-empata-com-ceara-e-se-sagra-tricampeao-cearense-em-2021-1.3089184\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">tricampeão cearense de futebol de forma invicta (2019–2020–2021)</a>, conquistando o 44º título estadual de sua história (<a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2021\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>).","c":["Esportes"],"l":1},{"id":"ce-2021-05-0582","y":2021,"m":5,"d":"25 e 31","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.495 e nº 17.513</a>, denominando o CEI Antônia Aguiar Neri (no distrito de Ubaúna, em Coreaú) e a Areninha Marino Araújo Monteiro (em Jijoca de Jericoacoara).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-06-0583","y":2021,"m":6,"d":"04","h":"Em sessão solene virtual, tomam posse os novos dirigentes do <a href=\"https://cn7.com.br/empossados-novos-presidente-e-vice-do-tre-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Tribunal Regional Eleitoral do Ceará (TRE-CE)</a> para o biênio 2021–2023: o desembargador Inácio de Alencar Cortez Neto como presidente e o desembargador Raimundo Nonato Silva Santos como vice-presidente e corregedor regional eleitoral (<a href=\"https://direitoce.com.br/novos-dirigentes-do-tre-ce-tomarao-posse-em-evento-virtual/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">DireitoCE</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2021-06-0584","y":2021,"m":6,"d":"07","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.523 e nº 17.526</a> (DOE de 08/06/2021), instituindo a Rota Cariri e o subsídio compartilhado ao transporte coletivo de Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2021-06-0585","y":2021,"m":6,"d":"10","h":"No primeiro Clássico-Rei da história válido pela <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Fortaleza_Esporte_Clube_de_2021\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa do Brasil</a> (jogo de volta da 3ª fase, após empate por 1 a 1 na ida), o Fortaleza Esporte Clube vence o Ceará Sporting Club por 3 a 0 na Arena Castelão (gols de Felipe e David duas vezes) e avança às oitavas de final.","c":["Esportes"],"l":1},{"id":"ce-2021-06-0586","y":2021,"m":6,"d":"15 a 29","h":"O governador Camilo Santana sanciona pacote de leis estaduais (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE</a>): <a href=\"https://www2.al.ce.gov.br/legislativo/tramit2021/pl8_21.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei nº 17.529</a> (denomina Deputado Roberto Mesquita a EEEP de General Sampaio); Lei nº 17.530 (Título de Cidadão Cearense a Dom Gilberto Pastana, bispo do Crato); Lei nº 17.532 (denomina Monsenhor Murilo de Sá Barreto e Beata Maria de Araújo as estações do Teleférico do Horto Padre Cícero, em Juazeiro do Norte); Lei nº 17.536 (Escola de Ensino Médio Adahil Barreto Cavalcante, em Cariús); Lei nº 17.543 (EEEP Antônio Ribeiro da Silva Filho, em São Luís do Curu); e Lei nº 17.547 (institui a Rota das Falésias no Litoral Leste).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-07-0587","y":2021,"m":7,"d":"06 e 07","h":"O governador Camilo Santana entrega <a href=\"https://www.bombeiros.ce.gov.br/2021/07/06/corpo-de-bombeiros-recebe-do-governo-do-ceara-137-equipamentos-e-viaturas/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">137 viaturas e equipamentos ao Corpo de Bombeiros Militar</a> e <a href=\"https://www.ce.gov.br/2021/07/07/governo-do-ceara-entrega-844-armas-de-fogo-as-forcas-de-seguranca-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">844 armas de fogo às forças de segurança</a>, sancionando a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.552</a> (CEI Manoel Cardozo dos Santos, em Uruoca).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-07-0588","y":2021,"m":7,"d":"15","h":"O prefeito José Sarto inaugura a <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeitura-de-fortaleza-entrega-celula-de-protecao-comunitaria-no-centro\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Célula de Proteção Comunitária da Praça da Lagoinha</a>, no Centro de Fortaleza.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-07-0589","y":2021,"m":7,"d":"20 e 22","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.566</a> (Areninha Lucimário Nunes Caitano, em Maracanaú), a Lei Estadual nº 17.569 (Programa Mais Empregos Ceará) e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/17572.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.572</a> (Programa \"Ceará Educa Mais\").","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2021-08-0590","y":2021,"m":8,"d":"01","h":"Pela última rodada do quadrangular final do <a href=\"https://torcidak.com.br/maracana-vence-iguatu-e-conquista-o-titulo-da-serie-b-do-cearense-floresta-escapa-do-rebaixamento/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série B de 2021</a>, o Maracanã Esporte Clube, de Maracanaú, derrota a Associação Desportiva Iguatu por 3 a 1 e conquista o título da Segunda Divisão estadual, garantindo tanto o campeão Maracanã quanto o vice-campeão Iguatu o acesso à Série A do Campeonato Cearense de 2022 (<a href=\"https://pt.wikipedia.org/wiki/Segunda_divis%C3%A3o_do_Campeonato_Cearense_de_Futebol_Masculino\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>).","c":["Esportes"],"l":1},{"id":"ce-2021-08-0591","y":2021,"m":8,"d":"02 e 03","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.575, 17.576, 17.592 e 17.600</a>, institucionalizando o CPRAIO da PMCE e denominando a Areninha Professor Eduardo Gabriel de Jesus Brito (em Pacujá) e a rodovia CE-388 Vicente de Paulo Rodrigues Paiva (entre Assaré e Altaneira).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-08-0592","y":2021,"m":8,"d":"04","h":"O governador Camilo Santana inaugura, no Complexo Penitenciário de Aquiraz, a <a href=\"https://www.ce.gov.br/2021/08/04/governo-do-ceara-entrega-a-primeira-unidade-prisional-de-seguranca-maxima-do-estado/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">primeira Unidade Prisional de Segurança Máxima do Estado do Ceará</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-08-0593","y":2021,"m":8,"d":"09","h":"Morre em Fortaleza, aos 77 anos, vítima de problemas cardíacos, o advogado, empresário e político <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/morre-o-ex-deputado-estadual-antonio-tavares-aos-77-anos-em-fortaleza-1.3120733\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Antônio Leite Tavares</a>. Filho de João Leite Tavares e Joana Benício de Luna, graduou-se em Direito pela UFC (1969), exerceu seis mandatos de deputado estadual na Assembleia Legislativa do Ceará (incluindo a Constituinte de 1989), foi prefeito municipal do Barro (1989–1991), secretário estadual da Justiça (1991) e conselheiro do extinto Tribunal de Contas dos Municípios (TCM-CE) (<a href=\"https://mapacultural.secult.ce.gov.br/files/project/5018/deputados-estaduais-23-legislatura-1991-1994.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE/INESP</a>). Nascera no Barro, CE, a 11 de junho de 1944.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-08-0594","y":2021,"m":8,"d":"10 a 13","h":"A Câmara Municipal de Fortaleza promulga os <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos nº 952, 954, 955, 957, 959 e 961</a>, denominando unidades de saúde, creches e praças nos bairros Granja Lisboa, Prefeito José Walter, Parangaba, Barroso e Bom Jardim.","c":["Política e Instituições"],"l":1},{"id":"ce-2021-08-0595","y":2021,"m":8,"d":"11","h":"O governador Camilo Santana e a vice-governadora Izolda Cela inauguram, no município de São Benedito, o <a href=\"https://www.ce.gov.br/2021/08/11/governo-do-ceara-entrega-campus-ibiapaba-da-universidade-estadual-vale-do-acarau-e-abre-nova-perspectiva-a-estudantes-da-regiao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campus Ibiapaba da Universidade Estadual Vale do Acaraú (UVA)</a>.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-08-0596","y":2021,"m":8,"d":"20 e 26","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.619, 17.623, 17.627, 17.628 e 17.632</a> (denominando a Avenida Contorno Luís Guimarães na CE-187 em São Benedito, a EEEP Lúcia Helena Viana Ribeiro em Horizonte, a Areninha Edmilson Pereira Pinho em Madalena e o CEI Tânia Maria Lima da Silva em Santa Quitéria), além dos <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos nº 964 e 965</a> da CMFor.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-09-0597","y":2021,"m":9,"d":"01","h":"O governador Camilo Santana inaugura em Canindé as obras de restauração de 55 km da <a href=\"https://www.ce.gov.br/casacivil/2021/09/01/governo-do-ceara-inaugura-trecho-da-ce-257-que-liga-caninde-e-santa-quiteria/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">rodovia estadual CE-257</a> (trecho Canindé–Salitre) e sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.635</a>, regulamentando a Zona de Amortecimento do Parque Estadual do Cocó.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-09-0598","y":2021,"m":9,"d":"08","h":"O governador Camilo Santana inaugura a pavimentação da <a href=\"https://www.itaicaba.ce.gov.br/informa/79/inaugurada-a-ce-371-rodovia-estadual-que-liga-arac\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">rodovia estadual CE-371, interligando Aracati e Itaiçaba</a>, e sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia e patrimônio cultural</a> (DOE de 10 e 13/09/2021): Lei nº 17.640 (Areninha Sérgio Apolinário Pereira – Mestre Dinda, em Barbalha); Lei nº 17.643 (denomina José Frutuoso Câmara Neto a CE-527, em Aquiraz); Lei nº 17.647 (Banda de Música de Iguatu); Lei nº 17.651 (Museu de Paleontologia Plácido Cidade Nuvens, em Santana do Cariri); Lei nº 17.652 (denomina Prefeito Ananias Granja a CE-273, em Jaguaribara); Lei nº 17.657 (Avenida do Contorno Claudionor Francelino Ribeiro, em Farias Brito); e Lei nº 17.659 (Banda de Música Maestro Orlando Leite, em Russas).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-09-0599","y":2021,"m":9,"d":"13 e 14","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.668</a> (que confere ao Crato o título de \"Capital do Agronegócio do Estado do Ceará\") e a Lei Estadual nº 17.669 (que torna permanente o programa social Vale Gás).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2021-09-0600","y":2021,"m":9,"d":"15","h":"Pela partida de volta das quartas de final da Copa do Brasil de 2021, na Arena Castelão (após empate em 2 a 2 no Morumbi), o Fortaleza Esporte Clube derrota o São Paulo Futebol Clube por 3 a 1 (gols de Ronald, Ángelo Henríquez e David) e alcança, pela primeira vez em sua história, as <a href=\"https://www.gazetaesportiva.com/campeonatos/copa-do-brasil/fortaleza-atropela-o-sao-paulo-e-faz-historia-avancando-a-semifinal-da-copa-do-brasil/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">semifinais da Copa do Brasil</a>.","c":["Esportes"],"l":1},{"id":"ce-2021-09-0601","y":2021,"m":9,"d":"17","h":"O governador Camilo Santana e a vice-governadora Izolda Cela inauguram a nova sede da <a href=\"https://www.ce.gov.br/seduc/2021/09/17/governo-do-ceara-entrega-nova-escola-de-ensino-medio-para-beneficiar-juventude-do-vila-velha-em-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Escola de Ensino Médio Hilza Diogo de Oliveira</a>, no bairro Vila Velha, em Fortaleza.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-09-0602","y":2021,"m":9,"d":"28","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 30/09/2021): Lei nº 17.680 (denomina José Flaviano Feitosa Nunes – Velinha a ciclovia entre Crato, Juazeiro do Norte e Barbalha); Lei nº 17.682 (Areninha Cícero Alves Tavares em Brejo Santo); Lei nº 17.683 (denomina Pastor Antônio Gabriel da Silva trecho da CE-187 em Novo Oriente); Lei nº 17.686 (Areninha Procurador José Wilson Sales Júnior, em Fortaleza); Lei nº 17.688 (Dia da Preta Tia Simoa); Lei nº 17.693 (Areninha Carlos Eduardo Leandro Bezerra em Pacoti); e Lei nº 17.695 (Areninha Pedro Laurindo Veras em Bitupitá, Barroquinha).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-10-0603","y":2021,"m":10,"d":"02","h":"Após mais de dezoito meses de portões fechados em decorrência da pandemia de Covid-19, ocorre na Arena Castelão o <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Fortaleza_Esporte_Clube_de_2021\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">retorno gradual de público vacinado aos estádios cearenses</a>.","c":["Esportes"],"l":1},{"id":"ce-2021-10-0604","y":2021,"m":10,"d":"13","h":"O governador Camilo Santana, a primeira-dama Onélia Santana e o prefeito José Sarto inauguram, no bairro João XXIII, em Fortaleza, o primeiro <a href=\"https://www.ce.gov.br/vicegov/2021/10/13/complexo-mais-infancia-e-inaugurado-e-vai-oferecer-lazer-e-capacitacao-profissional-para-comunidades-de-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Complexo Social Mais Infância do Ceará</a>, denominado Educadora Maria de Lourdes Moreira Leite Lima.","c":["Política e Instituições"],"l":1},{"id":"ce-2021-10-0605","y":2021,"m":10,"d":"15","h":"A vice-governadora Izolda Cela e o prefeito Glêdson Bezerra inauguram em Juazeiro do Norte o <a href=\"https://www.ce.gov.br/2021/10/15/governo-do-ceara-inaugura-centro-socioeducativo-padre-cicero-focado-na-ressocializacao-de-adolescentes-do-cariri/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro Socioeducativo Padre Cícero</a>. Na mesma data, são sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.707, 17.708, 17.709 e 17.714</a> (DOE de 18/10/2021), denominando Deputado Ted Rocha Pontes a rodovia CE-090 entre o Icaraí e o Cumbuco, em Caucaia, e reconhecendo a Ponte Metálica Demócrito Rocha sobre o Rio Jaguaribe, em Iguatu.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-10-0606","y":2021,"m":10,"d":"17","h":"Pelas quartas de final do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Brasileiro_de_Futebol_de_2021_-_S%C3%A9rie_D\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Brasileiro da Série D de 2021</a>, em Araraquara (SP), o Futebol Clube Atlético Cearense empata em 0 a 0 com a Ferroviária e vence nos pênaltis por 4 a 3, conquistando o acesso inédito à Série C do Campeonato Brasileiro de 2022.","c":["Esportes"],"l":1},{"id":"ce-2021-10-0607","y":2021,"m":10,"d":"22","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.728</a> (DOE de 25/10/2021), que denomina Antônio Carlos Gomes Belchior o Complexo Cultural Estação das Artes, situado na Praça da Estação, no Centro de Fortaleza (<a href=\"https://revistacontinente.com.br/edicoes/270/um-novo-lugar-para-a-arte\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Revista Continente</a>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-10-0608","y":2021,"m":10,"d":"27","h":"Na partida de volta das semifinais da <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Fortaleza_Esporte_Clube_de_2021\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa do Brasil de 2021</a>, na Arena Castelão, o Fortaleza Esporte Clube encerra sua campanha histórica no 3º lugar geral da competição diante do Atlético Mineiro.","c":["Esportes"],"l":1},{"id":"ce-2021-10-0609","y":2021,"m":10,"d":"29","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 29/10/2021): Lei nº 17.733 (denomina General Tibúrcio a CE-232 entre Viçosa do Ceará e Tianguá); Lei nº 17.735 (denomina Deputado Welington Landim a duplicação da CE-293 entre Missão Velha e a BR-116); Lei nº 17.736 (Areninha Pedro Ricardo de Matos em Russas); Lei nº 17.737 (denomina Vereador Zezinho Cândido trecho da CE-276 em Iracema); e Leis nº 17.740, 17.741 e 17.742 (Areninhas em Granja).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-11-0610","y":2021,"m":11,"d":"03 e 10","h":"A Câmara Municipal de Fortaleza promulga a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=6&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Resolução nº 1.675</a> (denominando Central da Cidadania Vereador José Iraguassú Teixeira o setor de atendimento do Legislativo Municipal) e o Decreto Legislativo nº 977 (Praça Francisco Pinto de Sousa, no Bom Jardim).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-11-0611","y":2021,"m":11,"d":"05","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.746, 17.747, 17.750 e 17.751</a> (DOE de 05/11/2021), denominando oficialmente Arena Mauro Sampaio – O Romeirão o estádio multiuso reconstruído em Juazeiro do Norte e Deputado Oriel Guimarães Nunes a sede regional do Detran-CE em Icó, além de inaugurar o <a href=\"https://www.ce.gov.br/vicegov/2021/10/13/complexo-mais-infancia-e-inaugurado-e-vai-oferecer-lazer-e-capacitacao-profissional-para-comunidades-de-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Complexo Social Mais Infância do Cristo Redentor</a>, em Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2021-11-0612","y":2021,"m":11,"d":"07","h":"Morre em Fortaleza o juiz de Direito aposentado <a href=\"https://g1.globo.com/ce/ceara/noticia/2021/11/07/morre-o-juiz-aposentado-luiz-bessa-neto.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Luiz Bessa Neto</a>, ex-titular da 1ª Vara de Execuções Penais e Corregedoria dos Presídios da Comarca de Fortaleza, sendo sepultado no Cemitério Parque da Paz (<a href=\"https://www.tjce.jus.br/newstopics/nota-de-pesar/page/2/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TJCE</a>).","c":["Necrologia"],"l":1},{"id":"ce-2021-11-0613","y":2021,"m":11,"d":"11","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.757</a> (Programa Cuidar Melhor da Saúde) e seis leis de toponímia (DOE de 12/11/2021): Leis nº 17.758, 17.762, 17.763, 17.764, 17.767 e 17.770 (denominando equipamentos em Senador Pompeu, Iguatu, Monsenhor Tabosa, Alto Santo, Cedro e Fortaleza).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-11-0614","y":2021,"m":11,"d":"17","h":"Nas eleições gerais da <a href=\"https://oabce.org.br/2021/11/erinaldo-dantas-e-reeleito-para-presidencia-da-oab-ce-para-o-trienio-2022-2024/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE)</a>, o advogado José Erinaldo Dantas Filho, ao lado da vice-presidente Christiane do Vale Leitão, é reeleito presidente da instituição para o triênio 2022–2024 com 7.226 votos (51,98%) (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/erinaldo-dantas-e-reeleito-presidente-da-oab-ce-por-mais-tres-anos-1.3160567\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2021-11-0615","y":2021,"m":11,"d":"23","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 25 e 26/11/2021): Lei nº 17.778 (Semana Estadual João Nogueira Jucá); Lei nº 17.779 (Areninha Antônio Bezerra de Lima – Antônio Preá, em Juazeiro do Norte); Lei nº 17.780 (Areninha José Pedro da Silva, em Milagres); Lei nº 17.784 (Areninha Ipojucan César Pereira Maciel, em Icó); Lei nº 17.791 (sede Regional do Detran-CE João Leite Moreira, em Brejo Santo); Lei nº 17.793 (Areninha Antônio Ivonildo da Silva, em Aracoiaba); Lei nº 17.799 (Letreiro de Guaramiranga com mosaico em homenagem ao ex-governador Adauto Bezerra); Lei nº 17.800 (Praça Mais Infância Dr. José Mauro Castelo Branco Sampaio, em Juazeiro do Norte); e Lei nº 17.801 (CCI Padre Antônio Cláudio de Oliveira, em Camocim).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-11-0616","y":2021,"m":11,"d":"28","h":"Na final em jogo único da <a href=\"https://pt.wikipedia.org/wiki/Ta%C3%A7a_Fares_Lopes\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Fares Lopes de 2021</a>, a Associação Desportiva Recreativa Cultural Icasa, de Juazeiro do Norte, derrota o Caucaia Esporte Clube por 1 a 0, conquistando o bicampeonato da competição (2014 e 2021) e assegurando vaga na Copa do Brasil de 2022 (<a href=\"https://www.flaviopintonews.com.br/2021/11/icasa-vence-caucaia-e-campeao-da-fares.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Flávio Pinto News</a>).","c":["Esportes"],"l":1},{"id":"ce-2021-12-0617","y":2021,"m":12,"d":"02","h":"Na decisão em jogo único do <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/guarani-de-juazeiro-e-campeao-cearense-da-serie-c-apos-vencer-o-gremio-nos-penaltis-1.3166597\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série C de 2021</a>, o Guarani Esporte Clube (Guarani de Juazeiro) empata em 0 a 0 no tempo regulamentar com o Grêmio Recreativo Pague Menos, de Fortaleza, e vence nos pênaltis por 3 a 0, sagrando-se campeão invicto da Terceira Divisão estadual e garantindo ambas as equipes o acesso à Série B de 2022 (<a href=\"https://safece.org.br/guarani-de-juazeiro-e-campeao-cearense-da-serie-c/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Safecê</a>). Na mesma data, a Câmara Municipal de Fortaleza promulga sete Decretos Legislativos de toponímia: nº 979, 985, 986, 988, <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13293\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">989, 990 e 99</a>1 (<a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=5&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SAPL CMFor</a>).","c":["Esportes","Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2021-12-0618","y":2021,"m":12,"d":"03","h":"Pela 36ª rodada do Campeonato Brasileiro da Série A de 2021, diante de 45.398 pagantes na Arena Castelão, o Fortaleza Esporte Clube derrota o Juventude por 1 a 0 (gol de Valentín Depietri) e garante, de maneira inédita para o futebol cearense, <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/fortaleza-vence-juventude-e-conquista-classificacao-inedita-para-libertadores-1.3166508\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">classificação para a Copa Libertadores da América de 2022</a>.","c":["Esportes"],"l":1},{"id":"ce-2021-12-0619","y":2021,"m":12,"d":"05","h":"Na partida de volta da final do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_Feminino\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense de Futebol Feminino de 2021</a>, no Estádio Franzé Morais, em Itaitinga, o Ceará Sporting Club (\"Meninas do Vozão\") empata em 3 a 3 com o Fortaleza Esporte Clube (após vencer a ida por 2 a 1) e conquista de forma invicta seu terceiro título estadual na categoria feminina (2018, 2019 e 2021).","c":["Esportes"],"l":1},{"id":"ce-2021-12-0620","y":2021,"m":12,"d":"08 e 10","h":"O governador Camilo Santana sanciona amplo pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 09, 10 e 14/12/2021): Lei nº 17.810 (Complexo Social Mais Infância Padre Gaetan Minette de Tillesse – Padre Caetano, no Cristo Redentor, em Fortaleza); Lei nº 17.811 (Escola de Ensino Médio Raimundo Nonato Carlos dos Santos, em Beberibe); Lei nº 17.812 (CEI José Lira Rodrigues, em Orós); Lei nº 17.813 (CEI Caleb Vieira Soares, em Quiterianópolis); Lei nº 17.814 (Areninha João Saraiva Feitosa, em Caririaçu); Lei nº 17.815 (CRAS Raimundo Lopes da Cruz, em Santana do Cariri); Lei nº 17.817 (Avenida João Batista Fujita, em Fortaleza); Lei nº 17.825 (Areninha Dr. Robson Sobreira, em Iguatu); Lei nº 17.826 (denomina José Lopes Rodrigues a CE-580 entre a sede de Quixadá e o distrito de Custódio); Lei nº 17.827 (Areninha Professor João Filho, em Pedra Branca); Leis nº 17.829 a 17.831 (equipamentos em Chaval, Itarema e Martinópole); e Lei nº 17.832 (denomina Vice-Prefeito Manoel Luís de Alcântara o Contorno de Ibiapina na CE-187).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-12-0621","y":2021,"m":12,"d":"09","h":"Pela 38ª e última rodada do Campeonato Brasileiro da Série A de 2021, perante 51.125 pagantes na Arena Castelão, o Fortaleza Esporte Clube vence de virada o Bahia por 2 a 1 e encerra o certame na histórica <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/fortaleza-vence-bahia-na-arena-castelao-e-decreta-rebaixamento-dos-baianos-a-serie-b-1.3169265\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">4ª colocação geral, com 58 pontos</a>, melhor campanha de um clube nordestino na história da Série A por pontos corridos, enquanto o Ceará Sporting Club encerra a competição no 11º lugar (50 pontos), garantindo vaga na Copa Sul-Americana de 2022.","c":["Esportes"],"l":1},{"id":"ce-2021-12-0622","y":2021,"m":12,"d":"15 a 23","h":"A Câmara Municipal de Fortaleza promulga os Decretos Legislativos nº 992, 993, 995, 997, 998, 999, 1.000, 1.005, <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13327\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">1.006</a>, 1.007 e 1.008 e o prefeito José Sarto sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=5&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária nº 11.209</a>, denominando logradouros, escolas e Areninhas na Capital. No dia 21, o prefeito José Sarto inaugura a requalificação integral do Parque da Liberdade – <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeitura-de-fortaleza-entrega-requalificacao-da-cidade-da-crianca-2\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Cidade da Criança</a>, no Centro de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2021-12-0623","y":2021,"m":12,"d":"27","h":"Morre em Fortaleza, aos 89 anos, o advogado criminalista, professor universitário e escritor <a href=\"https://pt.wikipedia.org/wiki/Francisco_Ernando_Uch%C3%B4a_Lima\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Ernando Uchôa Lima</a>. Bacharel pela Faculdade de Direito da UFC, presidiu a Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE) por dois biênios consecutivos (1989–1993) e exerceu a presidência nacional do Conselho Federal da OAB (1995–1998), além de ter sido membro titular da Academia Brasileira de Direito Criminal e da Academia Cearense de Retórica (<a href=\"https://www.migalhas.com.br/quentes/357148/ernando-uchoa-lima-ex-presidente-da-oab-morre-aos-89-anos\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Migalhas</a>, <a href=\"https://oabce.org.br/historia/category/ex-presidentes/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Memorial da OAB-CE</a>). Nascera em Fortaleza, CE, a 20 de abril de 1932.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2021-12-0624","y":2021,"m":12,"d":"29 e 30","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2021/LEIS2021.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.857</a> (Programa Ceará Filmes), a Lei Estadual nº 17.860 (LOA 2022) e as Leis Estaduais nº 17.871 e 17.872 (revisão geral da remuneração dos servidores estaduais).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-01-0625","y":2022,"m":1,"d":"01","h":"Entra em vigor o novo valor do salário mínimo nacional de R$ 1.212,00, fixado pela Medida Provisória nº 1.091, de 30 de dezembro de 2021, posteriormente convertida na <a href=\"https://www12.senado.leg.br/noticias/materias/2022/06/02/salario-minimo-de-r-1-212-e-promulgado\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Federal nº 14.358</a>, promulgada em 1º de junho de 2022 e publicada no Diário Oficial da União de 2 de junho de 2022.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-01-0626","y":2022,"m":1,"d":"03","h":"Toma posse solene, no auditório da <a href=\"https://oabce.org.br/2022/01/em-posse-solene-oab-ceara-decide-manter-valor-da-anuidade-para-advocacia/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE)</a>, a diretoria eleita para o triênio 2022–2024, encabeçada pelo presidente reeleito José Erinaldo Dantas Filho (Erinaldo Dantas) e pela vice-presidente Christiane do Vale Leitão, ao lado de David Sombra Peixoto (secretário-geral), Rafael Ponte (secretário-geral adjunto) e Camila Ferreira (tesoureira) (<a href=\"https://blogdoedisonsilva.com.br/2022/01/04/presidente-reeleito-da-oab-ceara-e-empossado-para-trienio-2022-2024/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Edison Silva</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-01-0627","y":2022,"m":1,"d":"04","h":"O governador Camilo Sobreira de Santana sanciona amplo pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de denominação de equipamentos públicos e reconhecimento cultural</a> (publicadas no Diário Oficial do Estado de 6 de janeiro de 2022): Lei nº 17.876, que denomina Maria Nilza Luz Sampaio o Centro de Educação Infantil (CEI) no distrito de Campos Belos, em Caridade; Lei nº 17.878, que denomina Dinho Nunes a Areninha de Palhano; Lei nº 17.879, que denomina José Hugo Câmara Monteiro Coêlho (Dr. Zé Hugo) a rodovia CE-169, ligando Tejuçuoca a Canindé; Lei nº 17.880, que denomina Francisco Luzardo Silva do Carmo a Areninha da Vila Antonico, em Quixelô; Lei nº 17.881, que confere ao município de Alto Santo o título de \"Terra da Poesia\"; Lei nº 17.882, que denomina Raimundo Pio a Areninha da sede de Missão Velha; Lei nº 17.885, que reconhece de relevante interesse cultural a Banda Filarmônica São José, de Barbalha; Lei nº 17.886, que confere a Morada Nova o título de \"Terra do Vaqueiro\"; Lei nº 17.887, que denomina Josué Saraiva de Freitas a Areninha de Saboeiro; Lei nº 17.888, que denomina Estrada Sérgio Gonçalves de Lima o trecho da CE-060 em Mombaça; Lei nº 17.890, que inclui no Roteiro Turístico e Religioso do Estado o Monumento de Nossa Senhora de Fátima e o Mosteiro dos Jesuítas, em Baturité; Lei nº 17.891, que denomina Rodovia Iracema Uchoa o trecho da CE-354 entre Umirim e Pentecoste; Lei nº 17.892, que denomina Rodovia Francisco das Chagas Carvalho Citó o trecho da CE-176 entre Santa Teresa e Bom Jesus, em Tauá; e Lei nº 17.893, que denomina Francisco Bel Moreira a Areninha Tipo II em Paraipaba (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/equipamentospublicos/indice2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALCE Equipamentos Públicos</a>).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-01-0628","y":2022,"m":1,"d":"05","h":"Em sessão solene virtual do Colégio de Procuradores de Justiça do <a href=\"https://mpce.mp.br/manuel-pinheiro-e-reconduzido-ao-cargo-de-procurador-geral-de-justica-do-estado-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ministério Público do Estado do Ceará (MPCE)</a>, o promotor de Justiça Manuel Pinheiro Freitas é reconduzido ao cargo de Procurador-Geral de Justiça do Estado do Ceará para o biênio 2022–2023.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-01-0629","y":2022,"m":1,"d":"07","h":"O prefeito de Fortaleza, José Sarto Nogueira Moreira, sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13357\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.225</a>, dispondo sobre ordenamento e denominação no âmbito do Município de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-01-0630","y":2022,"m":1,"d":"11","h":"O governador Camilo Santana sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (publicadas no Diário Oficial do Estado de 11 e 12 de janeiro de 2022): Lei nº 17.898, que denomina Ramal Ferroviário Walderi das Chagas Farrapo o trecho entre Varjota e Sobral; Lei nº 17.900, que denomina Cícero César Pinheiro dos Santos a Areninha Tipo II da localidade de Boa Nova, em Parambu; Lei nº 17.901, que denomina Francisco Sidimar Ferreira Sombra a rodovia CE-522, no distrito de Flores, em Russas; Lei nº 17.902, que denomina José Ricardo Silveira a rodovia CE-596; Lei nº 17.903, que denomina Professor Gilmar de Carvalho o Museu de Arte Popular dos Mestres e Mestras da Cultura do Ceará; Lei nº 17.904, que denomina Sala Izaíra Silvino o foyer do Theatro José de Alencar, em Fortaleza; Lei nº 17.905, que denomina Deputado Vicente Arruda a rodovia estadual planejada 216, no município de Granja; e Lei nº 17.915, que denomina João Alberto Adeodato a sede regional do Detran-CE em Sobral.","c":["Esportes","Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-01-0631","y":2022,"m":1,"d":"18","h":"Morre em Fortaleza, aos 95 anos de idade, o primeiro bailarino do Ceará, coreógrafo e professor <a href=\"https://diariodonordeste.verdesmares.com.br/verso/hugo-bianchi-primeiro-bailarino-do-ceara-morre-aos-95-anos-1.3181960\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hugo Bianchi</a>. Formado em balé clássico no Rio de Janeiro com Eros Volúsia nas décadas de 1950 e 1960, participou da fundação do Teatro Experimental de Arte (TEA), coreografou para a Comédia Cearense e fundou, em 1968, a tradicional Academia de Dança Hugo Bianchi, tendo sido agraciado com o Troféu Sereia de Ouro em 2006 (<a href=\"https://spcd.com.br/memoria/figuras-da-danca/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SPCD</a>). Nascera em Fortaleza, CE, em 1926.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-01-0632","y":2022,"m":1,"d":"26","h":"Morre em Fortaleza, aos 90 anos de idade, no Hospital São Mateus, em decorrência de complicações pulmonares e renais, o decano do rádio cearense, radialista, jornalista e ex-deputado estadual constituinte <a href=\"https://diariodonordeste.verdesmares.com.br/metro/morre-aos-90-anos-o-radialista-narcelio-limaverde-1.3184879\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Narcélio Sobreira Limaverde</a>. Filho do pioneiro do rádio José Limaverde Sobrinho e de Maria Cristina Sobreira Limaverde, iniciou a carreira em 1954 na Ceará Rádio Clube (PRE-9), atuou na TV Ceará Canal 2, Rádio Dragão do Mar, Rádio Uirapuru, Rádio Assunção, Sistema Verdes Mares (Rádio Verdes Mares e TV Diário) e na Rádio FM Assembleia, além de ter exercido mandato de deputado estadual constituinte na Assembleia Legislativa do Ceará (1987–1990) (<a href=\"https://portaldoservidor.al.ce.gov.br/noticias/morre-comunicador-e-ex-deputado-narcelio-limaverde\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALECE</a>, <a href=\"https://pt.wikipedia.org/wiki/Narc%C3%A9lio_Limaverde\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Nascera em Fortaleza, CE, a 08 de agosto de 1931.","c":["Necrologia","Esportes","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-02-0633","y":2022,"m":2,"d":"09","h":"O governador Camilo Santana sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.918</a> (DOE de 11/02/2022), que denomina Maria Neli Sobreira de Oliveira o Centro de Formação de Professores do Estado, localizado em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-02-0634","y":2022,"m":2,"d":"10","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.924</a> (DOE de 10/02/2022), regulamentando os critérios para o rateio aos professores da rede pública estadual dos recursos oriundos dos precatórios do antigo Fundo de Manutenção e Desenvolvimento do Ensino Fundamental e de Valorização do Magistério (Fundef).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2022-02-0635","y":2022,"m":2,"d":"15","h":"Ao completar um ano do início de sua construção no Campus do Itaperi da Universidade Estadual do Ceará (UECE), em Fortaleza, as obras do <a href=\"https://www.ce.gov.br/2022/02/15/com-um-ano-de-obras-hospital-universitario-do-ceara-alcanca-42-de-construcao-concluida/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hospital Universitário do Ceará (HUC)</a> atingem 42% de execução física concluída.","c":["Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-02-0636","y":2022,"m":2,"d":"16","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.928, nº 17.929 e nº 17.930</a> (DOE de 17/02/2022), dispondo sobre denominações de equipamentos públicos e reconhecimentos patrimoniais no Estado. Na mesma semana, a Prefeitura de Fortaleza e o Governo do Estado entregam o novo trecho urbanizado do <a href=\"https://www.ce.gov.br/vicegov/2022/03/30/inaugurado-onde-funcionou-antigo-ippoo-parque-dom-aloisio-lorscheider-representa-liberdade-e-lazer-para-fortalezenses/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Parque Rachel de Queiroz</a>, na zona oeste da Capital.","c":["Política e Instituições"],"l":1},{"id":"ce-2022-02-0637","y":2022,"m":2,"d":"23","h":"A Câmara Municipal de Fortaleza promulga os <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=5&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos nº 1.011 a nº 1.015</a>, destacando-se o Decreto Legislativo nº 1.015, que aprova o indicativo de denominação de Professor Agerson Tabosa Pinto para a Escola de Ensino Médio em Tempo Integral (EEMTI) situada no bairro Siqueira, em Fortaleza. Na mesma data, morre em Fortaleza o jornalista e escritor cearense <a href=\"https://www.al.ce.gov.br/noticias/tres-projetos-do-executivo-e-19-de-parlamentares-tramitam-na-al\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Fernando Pontes.</a>","c":["Necrologia","Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-03-0638","y":2022,"m":3,"d":"08","h":"Nas comemorações do Dia Internacional da Mulher, o governador Camilo Santana e a vice-governadora Izolda Cela inauguram, em Juazeiro do Norte, a <a href=\"https://www.ce.gov.br/2022/03/08/primeira-casa-da-mulher-cearense-e-inaugurada-em-um-8-de-marco-historico/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">primeira Casa da Mulher Cearense do interior do Estado</a> (denominada Arlete de Souza Negrão), equipamento integrado de acolhimento e proteção às mulheres vítimas de violência no Cariri (O Estado). Na mesma data, em Fortaleza, é inaugurado o novo complexo da <a href=\"https://mpce.mp.br/mpce-participa-de-inauguracao-do-novo-complexo-da-procuradoria-especial-da-mulher-da-assembleia-legislativa/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Procuradoria Especial da Mulher da Assembleia Legislativa.</a><br><a href=\"https://mpce.mp.br/mpce-participa-de-inauguracao-do-novo-complexo-da-procuradoria-especial-da-mulher-da-assembleia-legislativa/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">10 — É sancionad</a>a a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 17.967</a> (DOE de 10/03/2022), que denomina Maria de Lourdes Moreira Leite Lima o espaço Cidade Mais Infância, instalado no Centro de Eventos do Ceará, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-03-0639","y":2022,"m":3,"d":"17","h":"O governador Camilo Santana sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.970 a nº 17.979</a> (DOE de 17/03/2022): Lei nº 17.970 (institui a Comenda Violeta Arraes); Lei nº 17.971 (oficializa a denominação do Hospital Estadual Leonardo da Vinci, em Fortaleza); Lei nº 17.974 (denomina Estação Bom Jesus e Estação Cruzeiro do Caldas as estações do Teleférico do Caldas, em Barbalha); Lei nº 17.975 (denomina Professor Paulo Bonavides o Centro Integrado de Segurança Pública – Cisp, em Fortaleza); Lei nº 17.976 (denomina Madre Maria Carmelina Feitosa o Campus de Medicina da URCA, no Crato); Lei nº 17.977 (denomina Wilson Brandão a Escola de Pesca do Instituto do Mar, em Fortaleza); Lei nº 17.978 (denomina Maria José Santos Ferreira Gomes a rodovia de acesso ao novo Aeroporto Regional de Sobral); e Lei nº 17.979 (denomina José Sobreira de Amorim o Anel Viário do Cariri, em Juazeiro do Norte).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-03-0640","y":2022,"m":3,"d":"18","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 17.981 a nº 17.983</a> (DOE de 21/03/2022), denominando Lourival Gondim o Hospital Municipal de Jardim e Deputado Dr. Nodge Nogueira Diógenes a Areninha do município de Alto Santo.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-03-0641","y":2022,"m":3,"d":"25","h":"Nas comemorações da Data Magna do Ceará (138 anos da abolição da escravatura na Província), o governador Camilo Santana e a vice-governadora Izolda Cela realizam, no Palácio da Abolição, a solenidade de entrega da <a href=\"https://www.fortaleza.ce.gov.br/noticias/medalha-da-abolicao-reconhece-nove-cearenses-de-destaque-no-periodo-de-2020-a-2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha da Abolição</a> (referente ao período 2020–2022), condecorando: a equipe multidisciplinar criadora do <a href=\"https://unifor.br/-/cientistas-responsaveis-pelo-capacete-elmo-recebem-medalha-da-abolicao-maior-honraria-do-ceara\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Capacete de Respiração Assistida Elmo</a> (representada por Marcelo Alcantara, Cleber Rabelo, Eduardo Gurgel, Beto Studart, Ricardo Cavalcante e Edson Queiroz Neto); a secretária da Proteção Social Maria do Perpétuo Socorro França Pinto; o artesão Mestre Espedito Seleiro; o humorista Tom Cavalcante; a presidente do TJCE desembargadora Maria Nailde Pinheiro Nogueira; o ativista e presidente nacional da CUFA Francisco José Pereira de Lima (Preto Zezé); a jogadora de futsal Amanda Lyssa de Oliveira Crisóstomo (Amandinha); o senador e ex-governador Cid Ferreira Gomes; e o presidente da FIEC José Ricardo Montenegro Cavalcante.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-03-0642","y":2022,"m":3,"d":"27","h":"O Governo do Estado do Ceará inaugura o <a href=\"https://www.ce.gov.br/vicegov/2022/03/30/inaugurado-onde-funcionou-antigo-ippoo-parque-dom-aloisio-lorscheider-representa-liberdade-e-lazer-para-fortalezenses/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Parque Dom Aloísio Lorscheider</a>, erguido na área de 4,3 hectares onde funcionou o antigo Instituto Penal Professor Olavo Oliveira (IPPOO I), no bairro Itaperi, em Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-03-0643","y":2022,"m":3,"d":"28","h":"É inaugurada em Juazeiro do Norte, pelo governador Camilo Santana e pela vice-governadora Izolda Cela, a <a href=\"https://www.ce.gov.br/2022/03/29/inaugurada-em-juazeiro-do-norte-arena-romeirao-e-o-estadio-mais-moderno-no-interior-do-brasil/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Arena Romeirão</a> (antigo Estádio Mauro Sampaio), reconstruída como arena multiuso para 17 mil espectadores, em solenidade marcada por partida festiva entre o combinado de atletas históricos de Ceará e Fortaleza e a Seleção do Cariri (<a href=\"https://diariodonordeste.verdesmares.com.br/opiniao/colunistas/alexandre-mota/arena-romeirao-tera-combinado-de-ceara-e-fortaleza-x-selecao-do-cariri-em-inauguracao-1.3207127\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-03-0644","y":2022,"m":3,"d":"29","h":"O governador Camilo Santana sanciona pacote de leis estaduais (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis nº 17.987 a nº 18.003</a>, DOE de 29 a 31/03/2022), destacando-se: Lei nº 17.988 (denomina Professora Toinha Camilo a sede da CREDE 20, em Brejo Santo); Lei nº 17.991 (denomina Edifício Mário Lima Júnior o prédio administrativo da ZPE Ceará, em São Gonçalo do Amarante); e Lei nº 17.996 (denomina Sérvulo Esmeraldo o Centro Cultural do Cariri, no Crato).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-03-0645","y":2022,"m":3,"d":"30","h":"É inaugurado no Centro de Fortaleza, nas instalações restauradas da histórica Estação Ferroviária Doutor João Felipe (edificada entre 1872 e 1880), o <a href=\"https://www.ce.gov.br/secult/2022/03/30/governo-do-estado-entrega-complexo-cultural-estacao-das-artes-belchior-apos-obras-de-restauro-e-modernizacao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Complexo Cultural Estação das Artes Belchior</a>, integrado pelo Mercado AlimentaCE, pelo Centro de Design do Ceará (KUYA), pelo Museu Ferroviário e pelo prédio da Pinacoteca do Ceará (<a href=\"https://www.fortaleza.ce.gov.br/noticias/entrega-do-complexo-cultural-estacao-das-artes-belchior-inicia-novo-capitulo-do-centro-de-fortaleza\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Fortaleza</a>). Na mesma data, a Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=5&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.022</a>, que denomina Professor Gilmar de Carvalho a Biblioteca da Vila das Artes, em Fortaleza.","c":["Esportes","Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-03-0646","y":2022,"m":3,"d":"31","h":"É inaugurado na Avenida Barão de Studart, nº 410, no bairro Meireles, em Fortaleza, o novo anexo e complexo do <a href=\"https://www.ce.gov.br/secult/2022/04/01/complexo-do-museu-da-imagem-e-do-som-do-ceara-chico-albuquerque-e-inaugurado-com-tecnologia-de-ponta/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Museu da Imagem e do Som do Ceará – MIS Chico Albuquerque</a>, dotado de salas imersivas, laboratórios de digitalização e restauro, biblioteca e reserva técnica. Na mesma data, é sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.008</a> (DOE de 31/03/2022), que institui a Comenda Hugo Bianchi de Dança.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-04-0647","y":2022,"m":4,"d":"01","h":"Em seu último dia à frente do Poder Executivo estadual, o governador Camilo Santana e a vice-governadora Izolda Cela inauguram, pela manhã, o novo <a href=\"https://www.ce.gov.br/2022/04/01/novo-aeroporto-regional-de-sobral-e-entregue-para-impulsionar-o-desenvolvimento-regional/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Aeroporto Regional de Sobral – Luciano de Arruda Coelho</a>, com pista de 1.800 metros, e, à noite, no bairro Batateiras, na cidade do Crato, o <a href=\"https://centroculturaldocariri.cultura.ce.gov.br/sobre/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro Cultural do Cariri Sérvulo Esmeraldo</a>, implantado em área de mais de 50 mil metros quadrados. Na mesma data, é sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.012</a> (Lei Orgânica da Cultura do Estado do Ceará, que institui o Sistema Estadual da Cultura – SIEC).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-04-0648","y":2022,"m":4,"d":"02","h":"Marco histórico na política cearense: em sessão solene extraordinária realizada no Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará, conduzida pelo presidente deputado Evandro Sá Barreto Leitão, após a leitura da carta de renúncia de Camilo Sobreira de Santana (que se desincompatibiliza para concorrer ao Senado Federal), toma posse como Governadora Constitucional do Estado do Ceará a professora e psicóloga sobralense <a href=\"https://www.cmfor.ce.gov.br/2022/04/02/izolda-cela-toma-posse-como-governadora-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Izolda Cela de Arruda Coelho (Izolda Cela)</a>, tornando-se a primeira mulher a assumir como Governadora titular em toda a história do Ceará (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2022/noticia/2022/04/02/posse-de-izolda-cela-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Na mesma data, em Sobral, a professora <a href=\"https://www.uva.ce.gov.br/2022/04/02/izabelle-montalverne-inicia-mandato-como-reitora-da-uva/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Izabelle Mont'Alverne</a> inicia mandato como Reitora da Universidade Estadual Vale do Acaraú (UVA). Ainda no mesmo dia, morre em Fortaleza, aos 65 anos, o escritor, poeta, ensaísta, crítico literário e professor universitário <a href=\"https://diariodonordeste.verdesmares.com.br/verso/morre-o-escritor-cearense-carlos-emilio-correa-lima-1.3212500\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Carlos Emílio Corrêa Lima</a>, graduado e mestre em Letras pela UFC e doutor pela UFRN, cofundador da revista literária O Saco (1976), editor de Letras & Artes (Prêmio APCA 1990) e autor de Cachoeira das Eras (<a href=\"https://pt.wikipedia.org/wiki/Carlos_Em%C3%ADlio_Corr%C3%AAa_Lima\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Nascera em Fortaleza, CE, em 1956.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-04-0649","y":2022,"m":4,"d":"03","h":"Perante mais de 60 mil torcedores na Arena Castelão, em Fortaleza, o Fortaleza Esporte Clube, comandado pelo técnico argentino Juan Pablo Vojvoda, derrota o Sport Club do Recife por 1 a 0 (gol de Yago Pikachu, de pênalti, após empate de 1 a 1 no jogo de ida na Arena de Pernambuco) e sagra-se <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/fortaleza-vence-sport-e-e-bicampeao-da-copa-do-nordeste-1.3212927\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">bicampeão da Copa do Nordeste de 2022</a> de forma invicta.","c":["Esportes"],"l":1},{"id":"ce-2022-04-0650","y":2022,"m":4,"d":"05","h":"O Ceará Sporting Club estreia na fase de grupos da <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Cear%C3%A1_Sporting_Club_de_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Sul-Americana de 2022</a> vencendo o tradicional Club Atlético Independiente, da Argentina, por 2 a 1, na Arena Castelão.","c":["Esportes"],"l":1},{"id":"ce-2022-04-0651","y":2022,"m":4,"d":"07","h":"Em marco inédito para o futebol cearense, o Fortaleza Esporte Clube realiza sua estreia histórica na fase de grupos da <a href=\"https://diariodonordeste.verdesmares.com.br/opiniao/colunistas/andre-almeida/2022-o-ano-magico-para-o-fortaleza-e-tragico-para-o-ceara-1.3299145\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Libertadores da América</a> na Arena Castelão, enfrentando o Colo-Colo, do Chile.","c":["Esportes"],"l":1},{"id":"ce-2022-04-0652","y":2022,"m":4,"d":"24","h":"Na Arena Castelão, o Fortaleza Esporte Clube goleia o Caucaia Esporte Clube por 4 a 0 (gols de Silvio Romero, Yago Pikachu duas vezes e Ronald, após empate de 0 a 0 no jogo de ida) e conquista de forma invicta o <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/tetracampeao-fortaleza-goleia-caucaia-e-fatura-o-campeonato-cearense-2022-1.3221953\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">tetracampeonato estadual consecutivo (2019–2020–2021–2022)</a>, alcançando seu 45º título do Campeonato Cearense da Série A, enquanto o Caucaia sagra-se vice-campeão estadual inédito e campeão da Taça Padre Cícero (Campeão do Interior).","c":["Esportes"],"l":1},{"id":"ce-2022-04-0653","y":2022,"m":4,"d":"28","h":"A governadora Izolda Cela sanciona pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de denominação</a> (DOE de 28/04/2022), entre as quais a Lei nº 18.037, que denomina Erivanda de Lima Medeiros o auditório da Casa da Mulher Cearense em Juazeiro do Norte, e a Lei nº 18.050, que denomina Professor Paulo Freire o Centro Administrativo da Secretaria da Educação do Estado do Ceará (SEDUC), no bairro Cambeba, em Fortaleza. Na mesma data, a Câmara Municipal de Fortaleza outorga a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=5&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha Boticário Ferreira</a> à presidente do TJCE, desembargadora Maria Nailde Pinheiro Nogueira.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-04-0654","y":2022,"m":4,"d":"29","h":"Morre em Fortaleza, aos 73 anos de idade, o médico psiquiatra, professor titular aposentado da Faculdade de Medicina da UFC, escritor e poeta <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/morre-antonio-mourao-cavalcante-medico-professor-e-ex-candidato-a-vice-prefeito-de-fortaleza-1.3224664\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Antônio Mourão Cavalcante</a>, pioneiro da reforma psiquiátrica e da saúde mental comunitária no Ceará, parceiro histórico do <a href=\"https://movimentosaudemental.org/2022/04/30/padre-rino-e-equipe-do-movimento-sauda-o-grande-mestre-antonio-mourao-em-sua-partida-para-a-eternidade/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Movimento Saúde Mental do Bom Jardim</a> e ex-candidato a vice-prefeito de Fortaleza. Nascera no Ceará em 1948.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-05-0655","y":2022,"m":5,"d":"02","h":"A Santa Sé, no Vaticano, anuncia oficialmente a data de 24 de outubro de 2022 para a cerimônia de beatificação da jovem mártir cearense <a href=\"https://pt.wikipedia.org/wiki/Menina_Benigna\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Benigna Cardoso da Silva (Menina Benigna)</a>, martirizada aos 13 anos em 24 de outubro de 1941 em Santana do Cariri (<a href=\"https://contextonoticias.com.br/benigna-cardoso-sera-beatificada-em-24-de-outubro-aniversario-de-seu-martirio/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Contexto Notícias</a>).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-05-0656","y":2022,"m":5,"d":"05","h":"Morre em Fortaleza, aos 89 anos de idade, o médico, fundador da Rádio Cultura dos Inhamuns e político <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/aos-90-anos-morre-julio-rego-ex-prefeito-de-taua-e-ex-presidente-da-assembleia-legislativa-1.3226936\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Júlio Gonçalves Rêgo</a>, ex-prefeito de Tauá, deputado estadual por seis legislaturas, ex-secretário de Estado da Saúde (1973–1974), ex-presidente da Assembleia Legislativa do Estado do Ceará (biênio 1991–1993, qualidade em que assumiu interinamente o Governo do Estado) e conselheiro e ex-presidente do Tribunal de Contas do Estado do Ceará (biênio 1996–1997) (<a href=\"https://portaldoservidor.al.ce.gov.br/noticias/plenario-da-alece-faz-um-minuto-de-silencio-pela-morte-do-ex-deputado-julio-rego\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALECE</a>, <a href=\"https://blogdoedisonsilva.com.br/2022/05/05/morre-julio-rego-um-dos-politicos-serios-do-estado-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Edison Silva</a>). Seu corpo foi sepultado em Tauá, CE, onde nascera em 1932.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-05-0657","y":2022,"m":5,"d":"16","h":"A governadora Izolda Cela inaugura, em Limoeiro do Norte, o <a href=\"https://www.limoeirodonorte.ce.gov.br/informa/840/servi-o-de-hemodin-mica-do-hospital-regional-do-va\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Serviço de Hemodinâmica do Hospital Regional do Vale do Jaguaribe (HRVJ)</a>, passando a atender emergências cardiovasculares de alta complexidade no Vale do Jaguaribe.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-05-0658","y":2022,"m":5,"d":"18","h":"A governadora Izolda Cela sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.065 a nº 18.075</a> (DOE de 19/05/2022), contemplando denominações de escolas, estradas e Areninhas no interior do Estado.","c":["Política e Instituições"],"l":1},{"id":"ce-2022-05-0659","y":2022,"m":5,"d":"21","h":"Após reforma completa do gramado, arquibancadas, iluminação em LED e vestiários promovida pela Prefeitura de Fortaleza, é reinaugurado o <a href=\"https://ne45.com.br/2022/05/19/reinauguracao-do-pv-ferroviario-ingressos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Estádio Municipal Presidente Vargas (PV)</a>, no bairro Benfica, com a partida entre o Ferroviário Atlético Clube e o Botafogo-PB, válida pela Série C do Campeonato Brasileiro (<a href=\"https://diariodonordeste.verdesmares.com.br/jogada/quando-pv-tera-capacidade-maxima-disponivel-prefetura-de-fortaleza-estima-nova-data-1.3243739\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Esportes"],"l":1},{"id":"ce-2022-05-0660","y":2022,"m":5,"d":"25","h":"Noite histórica do futebol cearense na América do Sul: em Santiago do Chile, no Estádio Monumental David Arellano, o Fortaleza Esporte Clube derrota o Colo-Colo por 4 a 3 e torna-se o <a href=\"https://diariodonordeste.verdesmares.com.br/opiniao/colunistas/andre-almeida/2022-o-ano-magico-para-o-fortaleza-e-tragico-para-o-ceara-1.3299145\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">primeiro clube cearense a avançar às oitavas de final da Copa Libertadores da América</a>. Na mesma noite, em Avellaneda, na Argentina, o Ceará Sporting Club derrota o Independiente por 2 a 0 e classifica-se às oitavas de final da <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Cear%C3%A1_Sporting_Club_de_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Sul-Americana</a> com a melhor campanha da história da fase de grupos do torneio (100% de aproveitamento em seis jogos).","c":["Esportes"],"l":1},{"id":"ce-2022-06-0661","y":2022,"m":6,"d":"08","h":"A governadora Izolda Cela sanciona pacote de leis estaduais de toponímia (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis nº 18.088 a nº 18.100</a>, DOE de 08 e 09/06/2022), denominando equipamentos educacionais, rodoviários e esportivos em municípios do interior cearense.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2022-06-0662","y":2022,"m":6,"d":"23","h":"A governadora Izolda Cela sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.111 a nº 18.122</a> (DOE de 24/06/2022), denominando equipamentos públicos estaduais.","c":["Política e Instituições"],"l":1},{"id":"ce-2022-06-0663","y":2022,"m":6,"d":"30","h":"A governadora Izolda Cela inaugura dois importantes equipamentos públicos no interior do Estado: pela manhã, em Quixeramobim, no Sertão Central, entrega o restauro e requalificação da histórica <a href=\"https://reporterceara.com.br/2022/06/30/casa-de-antonio-conselheiro-e-inaugurada-em-quixeramobim/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Casa de Antônio Conselheiro</a> (imóvel onde nasceu Antônio Vicente Maciel), transformada em equipamento cultural da <a href=\"https://www.ce.gov.br/secult/institucional/rece/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Rede Pública de Espaços e Equipamentos Culturais do Ceará (Rece/Secult-CE)</a>; e, em Sobral, na Região Norte, inaugura a <a href=\"https://www.blogrobertomoreira.com/2022/05/casa-da-mulher-cearense-atendimento-da.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Casa da Mulher Cearense Maria José Santos Ferreira Gomes</a>, segunda unidade regionalizada de enfrentamento à violência de gênero no interior cearense.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-07-0664","y":2022,"m":7,"d":"01","h":"Morre em Fortaleza, aos 63 anos de idade, o desembargador do Tribunal de Justiça do Estado do Ceará (TJCE) <a href=\"https://www.tjce.jus.br/noticias/tribunal-de-justica-do-ceara-decreta-luto-pela-morte-do-desembargador-antonio-padua-silva/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Antônio Pádua Silva</a>. Magistrado de carreira desde outubro de 1987, atuou nas comarcas de Aracoiaba, Redenção, Itapiúna, Pacajus, Baturité, Crateús, Acopiara e na 5ª Vara de Execução Fiscal de Fortaleza, tendo tomado posse como desembargador do TJCE em 31 de maio de 2019, onde integrava a 2ª Câmara Criminal e coordenava a Estratégia Nacional de Justiça e Segurança Pública (Enasp) (<a href=\"https://sindojus-ce.org.br/noticias/sindicato-dos-oficiais-de-justica-lamenta-a-morte-do-desembargador-antonio-padua-silva/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Sindojus-CE</a>). Foi sepultado no Cemitério Parque da Paz, em Fortaleza, sob luto oficial de três dias decretado pelo Poder Judiciário. Nascera em Missão Velha, CE, em 1958, filho de Clodomir Silva Lima e Francisca Tilde Silva.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-07-0665","y":2022,"m":7,"d":"06","h":"Pelas oitavas de final da Copa Sul-Americana, o Ceará Sporting Club vence o The Strongest, da Bolívia, por 3 a 0 na Arena Castelão (após vitória de 2 a 1 na altitude de La Paz), avançando às <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Cear%C3%A1_Sporting_Club_de_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">quartas de final do torneio continental</a>. No dia seguinte (07 de julho), o Fortaleza Esporte Clube encerra sua primeira participação na Copa Libertadores da América nas oitavas de final diante do Estudiantes de La Plata, na Argentina.","c":["Esportes"],"l":1},{"id":"ce-2022-07-0666","y":2022,"m":7,"d":"13","h":"No primeiro Clássico-Rei eliminatório da história das oitavas de final da Copa do Brasil, disputado na Arena Castelão, o Fortaleza Esporte Clube classifica-se às quartas de final no placar agregado por 2 a 1 sobre o Ceará Sporting Club (<a href=\"https://diariodonordeste.verdesmares.com.br/opiniao/colunistas/alexandre-mota/fortaleza-elimina-ceara-e-supera-meta-na-copa-do-brasil-de-2022-1.3255611\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Esportes"],"l":1},{"id":"ce-2022-07-0667","y":2022,"m":7,"d":"18","h":"Em meio à sucessão estadual, o Diretório do PDT homologa em convenção o nome do ex-prefeito de Fortaleza Roberto Cláudio Rodrigues Bezerra como candidato ao Governo do Estado em detrimento da candidatura à reeleição da governadora em exercício Izolda Cela, provocando o rompimento histórico da aliança estadual entre PT e PDT (<a href=\"https://oestadoce.com.br/politica/camilo-santana-pt-sai-em-defesa-de-izolda-celas-apos-presidente-do-pdt-minimizar-a-forca-eleitoral-da-atual-governadora/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>, <a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%B5es_estaduais_no_Cear%C3%A1_em_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Nos dias 21 e 26 de julho, a governadora Izolda Cela desfilia-se do PDT e sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.145 a nº 18.180</a> (DOE de 22 e 27/07/2022).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-07-0668","y":2022,"m":7,"d":"30","h":"Convenção eleitoral da coligação liderada pelo Partido dos Trabalhadores (PT), realizada em Fortaleza, homologa as candidaturas do deputado estadual Elmano de Freitas da Costa (PT) ao Governo do Estado do Ceará, de Jade Afonso Romero (MDB) a vice-governadora e do ex-governador Camilo Sobreira de Santana (PT) ao Senado Federal (<a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%B5es_estaduais_no_Cear%C3%A1_em_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-08-0669","y":2022,"m":8,"d":"01","h":"O Guarani Esporte Clube, de Juazeiro do Norte, empata com o Barbalha Futebol Clube na rodada decisiva e conquista o título de campeão do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2023\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série B de 2022</a> (seu terceiro título da divisão de acesso, após 2004 e 2006), assegurando, ao lado do vice-campeão Barbalha, o acesso à Série A estadual de 2023.","c":["Esportes"],"l":1},{"id":"ce-2022-08-0670","y":2022,"m":8,"d":"04","h":"A governadora Izolda Cela sanciona o pacote de <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.181 a nº 18.191</a> (DOE de 05/08/2022), dispondo sobre denominações de equipamentos públicos e reconhecimentos culturais.","c":["Política e Instituições"],"l":1},{"id":"ce-2022-08-0671","y":2022,"m":8,"d":"10","h":"Na Arena Castelão, diante de mais de 58 mil torcedores, o Ceará Sporting Club vence o São Paulo Futebol Clube por 2 a 1 no tempo normal pelas quartas de final da <a href=\"https://pt.wikipedia.org/wiki/Temporada_do_Cear%C3%A1_Sporting_Club_de_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Sul-Americana</a>, sendo superado na disputa de pênaltis por 4 a 3.","c":["Esportes"],"l":1},{"id":"ce-2022-08-0672","y":2022,"m":8,"d":"17","h":"A Câmara Municipal de Fortaleza promulga novos <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=4&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos e Leis Ordinárias de denominação de logradouros</a>, e a governadora Izolda Cela sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.192 a nº 18.203.</a>","c":["Política e Instituições"],"l":1},{"id":"ce-2022-09-0673","y":2022,"m":9,"d":"14","h":"A governadora Izolda Cela sanciona pacote de leis estaduais de denominação e utilidade pública (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis nº 18.204 a nº 18.214</a>, DOE de 15/09/2022).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-10-0674","y":2022,"m":10,"d":"02","h":"Realiza-se o primeiro turno das <a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%B5es_estaduais_no_Cear%C3%A1_em_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Eleições Gerais de 2022 no Estado do Ceará</a>. Para o Governo do Estado, é eleito em primeiro turno o deputado estadual Elmano de Freitas da Costa (PT), tendo como vice-governadora Jade Afonso Romero (MDB), pela coligação \"Ceará Cada Vez Mais Forte\", com 2.808.300 votos (54,02% dos votos válidos), derrotando Capitão Wagner Sousa Gomes (União Brasil, 1.649.213 votos, 31,72%) e Roberto Cláudio Rodrigues Bezerra (PDT, 734.976 votos, 14,14%). Para o Senado Federal, o ex-governador Camilo Sobreira de Santana (PT) é eleito com a maior votação da história política do Ceará, somando 3.389.513 votos (69,80% dos votos válidos). Na eleição presidencial no Ceará, Luiz Inácio Lula da Silva (PT) obtém 3.578.355 votos (65,91%), contra 1.377.827 votos (25,38%) de Jair Messias Bolsonaro (PL) e 369.513 votos (6,80%) de Ciro Ferreira Gomes (PDT). São igualmente eleitos os 22 deputados federais e os 46 deputados estaduais da 31ª Legislatura (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/elmano-jade-camilo-e-parlamentares-eleitos-no-ceara-sao-diplomados-pelo-tre-1.3313201\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-10-0675","y":2022,"m":10,"d":"24","h":"Em histórica solenidade pontifícia realizada no Parque de Exposições Pedro Felício Cavalcanti, na cidade do Crato, perante dezenas de milhares de romeiros do Cariri e autoridades como a governadora Izolda Cela e o ex-governador Camilo Santana, o representante do Papa Francisco, Cardeal Dom Leonardo Ulrich Steiner, procede à leitura da Carta Apostólica de beatificação de <a href=\"https://www.ce.gov.br/2022/10/24/beatificacao-da-menina-benigna-revela-historias-de-fe-ceara-tera-santuario-em-santana-do-cariri/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Benigna Cardoso da Silva (Menina Benigna)</a>, nascida em Santana do Cariri a 15 de outubro de 1928 e martirizada a 24 de outubro de 1941, aos 13 anos, proclamando-a oficialmente a primeira Beata da história do Ceará (<a href=\"https://diariodonordeste.verdesmares.com.br/ceara/menina-benigna-e-beatificada-no-cariri-nesta-segunda-feira-24-1.3292755\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://diocesedecrato.org/martir-benigna-cardoso-em-santana-do-cariri-fieis-celebram-memoria-da-beata-vestida-de-chita/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diocese de Crato</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-10-0676","y":2022,"m":10,"d":"30","h":"Realiza-se o segundo turno da <a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%B5es_estaduais_no_Cear%C3%A1_em_2022\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">eleição presidencial de 2022</a>. No Estado do Ceará, Luiz Inácio Lula da Silva (PT), eleito Presidente da República, obtém 3.807.891 votos (69,97% dos votos válidos), contra 1.634.477 votos (30,03%) de Jair Messias Bolsonaro (PL).","c":["Política e Instituições"],"l":1},{"id":"ce-2022-11-0677","y":2022,"m":11,"d":"01","h":"A governadora Izolda Cela sanciona pacote de leis estaduais de denominação (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis nº 18.220 a nº 18.228</a>, DOE de 04/11/2022): Lei nº 18.221 (denomina Maria José de Queiroz Bessa a Praça Mais Infância na Cohab, em Beberibe); Lei nº 18.222 (denomina Yara Guerra Silva a EEMTI na localidade de Garrote, em Caucaia); Lei nº 18.225 (denomina Rodovia Mamede Coelho de Matos o trecho da CE-253 entre Tejuçuoca e General Sampaio); Lei nº 18.226 (denomina Maria Zaíra de Almeida Matos o CEI na comunidade de Açude dos Pinheiros, em Ibicuitinga); Lei nº 18.227 (denomina Manoel Ubiratan Cavalcante Pinheiro a segunda creche de Solonópole); e Lei nº 18.228 (concede o Título de Cidadão Cearense a Dimas Humberto Silva Barreira).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-11-0678","y":2022,"m":11,"d":"04","h":"Em solenidade de gala no Theatro José de Alencar, em Fortaleza, com a presença da governadora Izolda Cela, o Grupo Edson Queiroz e o Sistema Verdes Mares realizam a entrega do <a href=\"https://diariodonordeste.verdesmares.com.br/verso/trofeu-sereia-de-ouro-2022-homenageia-quatro-personalidades-em-solenidade-no-theatro-jose-de-alencar-1.3292583\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Troféu Sereia de Ouro de 2022</a> (celebrando o cinquentenário da comenda) a quatro personalidades cearenses (<a href=\"https://pt.wikipedia.org/wiki/Sereia_de_Ouro\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>, <a href=\"https://www.trf5.jus.br/index.php/noticias/leitura-de-noticias?/id=324480\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TRF5</a>): o desembargador federal do TRF da 5ª Região Cid Marconi Gurgel de Souza; o médico dermatologista e sanitarista Darival Bringel Olinda; o cartunista, ilustrador, jornalista e escritor Hermínio Macedo Castelo Branco (Mino Castelo Branco); e o industrial e presidente da FIEC José Ricardo Montenegro Cavalcante (Ricardo Cavalcante).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-11-0679","y":2022,"m":11,"d":"07","h":"Com gol marcado aos 47 minutos do segundo tempo, a equipe feminina do Fortaleza Esporte Clube (as \"Leoas\") vence o Clássico-Rainha diante do Ceará Sporting Club e conquista o título de campeã do <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/com-gol-aos-47-do-2-tempo-fortaleza-vence-classico-rainha-e-conquista-campeonato-cearense-feminino-1.3298203\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense de Futebol Feminino de 2022.</a><br><a href=\"https://diariodonordeste.verdesmares.com.br/jogada/com-gol-aos-47-do-2-tempo-fortaleza-vence-classico-rainha-e-conquista-campeonato-cearense-feminino-1.3298203\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">09 — A Associação dos Desportistas de Pacatuba vence o Crateús Esporte Clube na fina</a>l e sagra-se campeã do <a href=\"https://safece.org.br/pacatuba-e-crateus-garantem-vaga-na-2a-divisao-do-campeonato-cearense/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série C de 2022</a>, conquistando ambos os clubes o acesso à Série B estadual de 2023. Na mesma noite, pela penúltima rodada do Campeonato Brasileiro da Série A, o Ceará Sporting Club sofre revés diante do Avaí em Florianópolis e é rebaixado à Série B nacional após cinco temporadas consecutivas na elite (<a href=\"https://diariodonordeste.verdesmares.com.br/opiniao/colunistas/andre-almeida/2022-o-ano-magico-para-o-fortaleza-e-tragico-para-o-ceara-1.3299145\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Esportes"],"l":1},{"id":"ce-2022-11-0680","y":2022,"m":11,"d":"12","h":"Na rodada final do hexagonal em pontos corridos da Taça Fares Lopes de 2022, o Pacajus Esporte Clube derrota o Guarany de Sobral e conquista de forma inédita o título de campeão da <a href=\"https://safece.org.br/pacajus-e-campeao-da-taca-fares-lopes-e-conquista-vaga-na-copa-do-brasil-2023/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Fares Lopes de 2022</a> (tendo o Maracanã Esporte Clube como vice-campeão), garantindo vaga na Copa do Brasil de 2023.","c":["Esportes"],"l":1},{"id":"ce-2022-11-0681","y":2022,"m":11,"d":"13","h":"Na última rodada do Campeonato Brasileiro da Série A de 2022, o Fortaleza Esporte Clube derrota o Santos Futebol Clube por 2 a 0 na Vila Belmiro, em Santos (SP), encerrando a competição no 8º lugar geral com 55 pontos — após ter permanecido as 19 rodadas do primeiro turno na zona de rebaixamento, feito inédito na história dos pontos corridos — e classificando-se pelo segundo ano consecutivo para a <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/vojvoda-encerra-seu-ciclo-no-fortaleza-com-trajetoria-marcada-por-recordes-e-titulos-1.3660380\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Libertadores da América</a>.","c":["Esportes"],"l":1},{"id":"ce-2022-12-0682","y":2022,"m":12,"d":"03","h":"A governadora Izolda Cela inaugura, no Complexo Cultural Estação das Artes Belchior, na Praça da Estação, no Centro de Fortaleza, a <a href=\"https://ne9.com.br/pinacoteca-do-ceara-abre-as-portas-ao-povo-cearense-neste-sabado-3/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Pinacoteca do Ceará</a>, um dos maiores e mais modernos museus de artes visuais do País, instalado nos antigos galpões da RFFSA com pavilhões expositivos, ateliês de restauro e reserva técnica climatizada, abrindo ao público com a megamostra \"Bonito Pra Chover\" (homenageando Chico da Silva, Aldemir Martins, Antonio Bandeira e Leonilson) e a exposição \"Se Arruance\" (<a href=\"https://revistacontinente.com.br/edicoes/270/um-novo-lugar-para-a-arte\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Revista Continente</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2022-12-0683","y":2022,"m":12,"d":"04","h":"Morre em Fortaleza, aos 75 anos de idade, o economista, estatístico, sociólogo e professor titular aposentado da Universidade Federal do Ceará (UFC) <a href=\"https://www.adufc.org.br/2022/12/05/nota-de-pesar-adufc-lamenta-morte-do-prof-assuero-ferreira-da-pos-graduacao-em-sociologia-da-ufc-aos-75-anos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Assuéro Ferreira</a>. Graduado em Ciências Estatísticas, mestre em Economia (CAEN/UFC) e doutor em Sociologia pela UFC, ingressou no Departamento de Teoria Econômica da FEAAC/UFC em 1973, atuou no Programa de Pós-Graduação em Sociologia e como consultor da Capes, do CNPq e do Banco do Nordeste (BNB/ETENE), sendo sepultado no Cemitério Parque da Paz (<a href=\"https://feaac.ufc.br/pt/nota-de-pesar-13/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">FEAAC/UFC</a>). Nascera em 1947.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2022-12-0684","y":2022,"m":12,"d":"16","h":"Em solenidade conduzida pelo presidente do Tribunal Regional Eleitoral do Ceará (TRE-CE), desembargador Inácio de Alencar Cortez Neto, na sede da Justiça Eleitoral em Fortaleza, são <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/elmano-jade-camilo-e-parlamentares-eleitos-no-ceara-sao-diplomados-pelo-tre-1.3313201\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">diplomados o governador eleito Elmano de Freitas da Costa (PT), a vice-governadora eleita Jade Afonso Romero (MDB) e o senador eleito Camilo Sobreira de Santana (PT)</a> — anunciado na mesma semana como futuro Ministro de Estado da Educação —, além dos 22 deputados federais e 46 deputados estaduais eleitos.","c":["Política e Instituições"],"l":1},{"id":"ce-2022-12-0685","y":2022,"m":12,"d":"28","h":"Em seus últimos atos administrativos à frente do Palácio da Abolição, a governadora Izolda Cela inaugura, no bairro Planalto Renascer, em Quixadá, a <a href=\"https://www.tjce.jus.br/noticias/tjce-da-inicio-as-atividades-do-recem-inaugurado-juizado-da-mulher-de-quixada/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Casa da Mulher Cearense do Sertão Central</a>, terceira unidade regionalizada do interior cearense, e sanciona, até 30 de dezembro, o último pacote de leis estaduais do exercício de 2022 (até a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2022/LEIS2022.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.302</a>, DOE de 30/12/2022).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-01-0686","y":2023,"m":1,"d":"01","h":"Entra em vigor em todo o território nacional, com reflexo direto nos pisos previdenciários e na administração pública cearense, o salário mínimo mensal de R$ 1.302,00 (valor diário de R$ 43,40 e horário de R$ 5,92), fixado pela <a href=\"https://www.sampaiomartins.adv.br/post/salario-minimo-2023\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medida Provisória nº 1.143, de 12 de dezembro de 2022</a> (posteriormente substituída a partir de 1º de maio pela Lei Federal nº 14.663, de 28 de agosto de 2023).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-01-0687","y":2023,"m":1,"d":"01","h":"Em sessão solene realizada no Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará (ALECE), tomam posse o governador eleito Elmano de Freitas da Costa (PT) e a vice-governadora Jade Afonso Romero (MDB) para o quadriênio 2023–2026. Em seguida, no Palácio da Abolição, a governadora Maria Izolda Cela de Arruda Coelho — primeira mulher a chefiar o Poder Executivo estadual — realiza a transmissão oficial do cargo ao novo mandatário (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/elmano-de-freitas-toma-posse-como-governador-do-ceara-neste-domingo-1-1.3318491\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste – Posse</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/saude-paciencia-luz-do-discernimento-e-coragem-diz-izolda-cela-a-elmano-em-transmissao-do-cargo-1.3318941\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste – Transmissão de Cargo</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2023-01-0688","y":2023,"m":1,"d":"01","h":"Toma posse na presidência da Câmara Municipal de Fortaleza (CMFor), para o biênio 2023–2024, o vereador Gardel Ferreira Rolim (PDT), fisioterapeuta e gestor hospitalar que coordenara a implantação do Hospital Regional Norte (HRN), em Sobral. Compõem a Mesa Diretora os vereadores Paulo Martins (1º vice-presidente), Renan Colares (2º vice-presidente), Cláudia Gomes (3ª vice-presidente), Bruno Mesquita (1º secretário), Fábio Rubens (2º secretário) e Kátia Rodrigues (3ª secretária) (<a href=\"https://www.cmfor.ce.gov.br/2023/01/01/gardel-rolim-toma-posse-como-presidente-da-camara-municipal-de-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">CMFor</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/gardel-rolim-toma-posse-como-presidente-da-camara-municipal-de-fortaleza-1.3319011\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-01-0689","y":2023,"m":1,"d":"01","h":"A professora <a href=\"https://www.ce.gov.br/cee/presidentes/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ada Pimentel Gomes Fernandes Vieira</a>, ex-secretária da Educação de Sobral (1997–2000), inicia o seu segundo mandato consecutivo na presidência do Conselho Estadual de Educação do Ceará (CEE).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-01-0690","y":2023,"m":1,"d":"01 e 02","h":"O ex-governador do Ceará e senador eleito Camilo Sobreira de Santana (PT) é empossado em Brasília pelo presidente Luiz Inácio Lula da Silva como <a href=\"https://g1.globo.com/ce/ceara/educacao/noticia/2023/01/01/camilo-santana-toma-posse-como-ministro-da-educacao.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ministro de Estado da Educação</a>, assumindo formalmente a pasta em 02 de janeiro em cerimônia na qual é oficializada a ex-governadora do Ceará Maria Izolda Cela de Arruda Coelho no cargo de Secretária-Executiva do Ministério da Educação (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/camilo-santana-assume-o-ministerio-da-educacao-no-governo-lula-nesta-segunda-2-1.3319188\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://agenciabrasil.ebc.com.br/educacao/noticia/2023-01/ministro-anuncia-equipe-para-secretarias-e-orgaos-do-mec\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Agência Brasil</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2023-01-0691","y":2023,"m":1,"d":"03","h":"É sancionada pelo governador Elmano de Freitas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18303.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.303</a> (DOE de 04/01/2023), que institui o piso salarial do advogado em exercício profissional na iniciativa privada no Estado do Ceará, e, pelo prefeito José Sarto, a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13593\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.335</a>, dispondo sobre o sistema de transporte por plataformas digitais e táxis em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-01-0692","y":2023,"m":1,"d":"03","h":"Morre em hospital particular de Fortaleza, aos 50 anos de idade, em decorrência de fibrose pulmonar, a cantora e compositora <a href=\"https://g1.globo.com/ce/ceara/noticia/2023/01/03/morre-cantora-rita-de-cassia-compositora-de-meu-vaqueiro-meu-peao.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Rita de Cássia Oliveira dos Reis (Rita de Cássia)</a>. Uma das mais prolíficas autoras da história do forró eletrônico, com mais de 500 composições gravadas por bandas como Mastruz com Leite, Aviões do Forró e Banda Som do Norte (ao lado do irmão Redondo), imortalizou clássicos como \"Meu Vaqueiro, Meu Peão\" (1993), \"Saga de um Vaqueiro\" e \"Jeito de Amar\". Seu corpo foi velado e sepultado em 04 de janeiro no cemitério municipal de sua terra natal (<a href=\"https://diariodonordeste.verdesmares.com.br/entretenimento/e-hit/rita-de-cassia-e-sepultada-em-alto-santo-sua-terra-natal-nesta-quarta-feira-4-1.3320257\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://pt.wikipedia.org/wiki/Rita_de_C%C3%A1ssia_(compositora\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>)). Nascera em Alto Santo, CE, a 08 de agosto de 1972.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-01-0693","y":2023,"m":1,"d":"05","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18304.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.304</a> (DOE de 05/01/2023), que reconhece oficialmente o município de Viçosa do Ceará, na Serra da Ibiapaba, como a \"Capital Cearense da Cachaça\".","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2023-01-0694","y":2023,"m":1,"d":"11","h":"Morre em Fortaleza a terapeuta ocupacional e professora universitária <a href=\"https://mpce.mp.br/nota-de-pesar-30/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lucila Bonfim</a>, coordenadora do Serviço de Atendimento ao Adulto e à Pessoa Idosa da Assembleia Legislativa do Estado do Ceará (ALECE), sendo sepultada no Cemitério Parque da Paz.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2023-01-0695","y":2023,"m":1,"d":"13","h":"Morre em Fortaleza, aos 76 anos de idade, o engenheiro agrônomo, professor titular do Departamento de Estatística e ex-reitor da Universidade Federal do Ceará (UFC) <a href=\"https://memorialufc.com.br/?page_id=112\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Roberto Cláudio Frota Bezerra</a>, filho de Prisco Bezerra e Otacília Frota Bezerra e pai do ex-prefeito de Fortaleza Roberto Cláudio Rodrigues Bezerra e do suplente de senador Prisco Rodrigues Bezerra. Na UFC, foi pró-reitor de Planejamento e reitor por dois mandatos consecutivos (1995–2003), além de membro do Conselho Nacional de Educação (CNE) e agraciado com a Medalha Iracema (2021) (<a href=\"https://www.sct.ce.gov.br/2023/01/13/nota-de-pesar-roberto-claudio-frota-bezerra/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">SECITECE</a>, <a href=\"https://blogdoedisonsilva.com.br/2023/01/14/e-cremado-o-corpo-do-ex-reitor-da-ufc-roberto-claudio/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Edison Silva</a>). O Governo do Estado decretou luto oficial de três dias, e seu corpo foi velado no Salão Nobre da Reitoria da UFC, no Benfica, e cremado em 14 de janeiro. Nascera em Fortaleza, CE, a 23 de julho de 1946.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-01-0696","y":2023,"m":1,"d":"14","h":"Realiza-se no campus do Instituto Federal do Ceará (IFCE), no município de Quixadá (Sertão Central), o <a href=\"https://www.ce.gov.br/secult/2023/01/10/quixada-recebe-o-27o-encontro-dos-profetas-das-chuva/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">XXVII Encontro dos Profetas da Chuva, reunindo sertanejos e observadores da natureza para o anúncio das previsões da quadra chuvosa d</a>e 2023 (<a href=\"https://diariodonordeste.verdesmares.com.br/ceara/da-acao-de-formigas-a-estrela-dalva-profetas-do-ceara-anunciam-previsoes-das-chuvas-para-2023-1.3322678\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-01-0697","y":2023,"m":1,"d":"31","h":"Em sessão solene do Pleno realizada no auditório do TRE-CE, toma posse a nova diretoria do <a href=\"https://www.tjce.jus.br/noticias/pleno-do-tjce-empossa-novos-dirigentes-do-judiciario-estadual-para-bienio-2023-2025/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Tribunal de Justiça do Estado do Ceará (TJCE)</a> para o biênio 2023–2025, integrada pelo desembargador Antônio Abelardo Benevides Moraes (natural de Mombaça, CE) como presidente, pelo desembargador Heráclito Vieira de Sousa Neto como vice-presidente e pela desembargadora Maria Edna Martins como corregedora-geral da Justiça.","c":["Política e Instituições"],"l":1},{"id":"ce-2023-02-0698","y":2023,"m":2,"d":"01","h":"Instala-se solenemente na Assembleia Legislativa do Estado do Ceará (ALECE) a 31ª Legislatura Estadual (2023–2027), com a posse dos 46 deputados estaduais eleitos em outubro de 2022 e a reeleição por unanimidade do deputado <a href=\"https://correiodasemana.com/site/evandro-leitao-e-reeleito-presidente-da-alece/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Evandro Sá Barreto Leitão</a> para a presidência da Casa no biênio 2023–2024. Na mesma data, a Câmara Municipal de Fortaleza reabre os trabalhos legislativos da 19ª Legislatura (<a href=\"https://portalterradaluz.com.br/noticias/politica-camara-municipal-de-fortaleza-reabre-trabalhos-com-posse-quatro-novos-vereadores/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Portal Terra da Luz</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2023-02-0699","y":2023,"m":2,"d":"07","h":"Pela 5ª e última rodada da primeira fase do Campeonato Cearense da Série A, no Estádio Presidente Vargas (PV), o Ceará Sporting Club vence o Clássico-Rei contra o Fortaleza Esporte Clube por 2 a 1 e conquista a <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2023\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Pedro Basílio 2023</a>, conferida ao clube de melhor campanha na fase classificatória.","c":["Esportes"],"l":1},{"id":"ce-2023-02-0700","y":2023,"m":2,"d":"15 e 17","h":"O governador Elmano de Freitas sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18305.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.305</a> (legislação tributária do ICMS), a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18410.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.310</a> (reforma administrativa do Poder Executivo), a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18311.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.311</a> (Plano Estadual de Redução das Filas de Cirurgias Eletivas) e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18312.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.312</a> (que cria o Programa Ceará Sem Fome).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-02-0701","y":2023,"m":2,"d":"23 e 24","h":"O Pleno do TJCE e o Pleno do TRE-CE elegem os desembargadores <a href=\"https://www.tjce.jus.br/noticias/pleno-elege-membros-efetivos-e-suplente-do-tribunal-regional-eleitoral-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Raimundo Nonato Silva Santos e Francisco Gladyson Pontes</a> como futuros presidente e vice-presidente/corregedor da Justiça Eleitoral cearense (<a href=\"https://direitoce.com.br/novos-presidente-e-vice-presidente-do-tre-ce-sao-eleitos-por-aclamacao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">DireitoCE</a>).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-02-0702","y":2023,"m":2,"d":"18","h":"Tem início no município serrano de <strong>Guaramiranga</strong>, no Maciço de Baturité, a 24ª edição do tradicional <strong>Festival Jazz & Blues</strong>, reunindo mais de 20 atividades culturais entre concertos, oficinas e debates durante o período de Carnaval (<a href=\"https://diariodonordeste.verdesmares.com.br/verso/festival-de-jazz-e-blues-em-guaramiranga-2023-veja-programacao-de-hoje-sabado-18-1.3336526\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>).","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-03-0703","y":2023,"m":3,"d":"03","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18313.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.313</a> (DOE de 03/03/2023), que cria o Comando de Prevenção e Apoio às Comunidades (COPAC) na estrutura da Polícia Militar do Ceará (PMCE).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2023-03-0704","y":2023,"m":3,"d":"06","h":"Pela 5ª rodada do Quadrangular do Rebaixamento do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2023\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série A</a>, o Guarani Esporte Clube (de Juazeiro do Norte) e o Pacajus Esporte Clube sofrem descenso para a Série B estadual de 2024.","c":["Esportes"],"l":1},{"id":"ce-2023-03-0705","y":2023,"m":3,"d":"16","h":"É sancionada em Fortaleza a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13610\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.349</a>, instituindo a Gestão para Resultados no Poder Executivo Municipal.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2023-03-0706","y":2023,"m":3,"d":"18","h":"Ao concluir sua participação nas semifinais do Campeonato Cearense da Série A na 3ª colocação geral do certame, a Associação Desportiva Iguatu sagra-se bicampeã cearense do Interior, conquistando a <a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=16407\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Padre Cícero de 2023</a> e garantindo vaga na Série D do Campeonato Brasileiro de 2024.","c":["Esportes"],"l":1},{"id":"ce-2023-03-0707","y":2023,"m":3,"d":"20 a 23","h":"O governador Elmano de Freitas sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18315.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.315</a> (Estatuto do Magistério), a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18320.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.320</a> (estrutura do MPCE), a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18325.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.325</a> (TCE-CE) e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18329.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.329</a> (DOE de 24/03/2023), que declara de destacada relevância cultural e religiosa as tradicionais Romarias realizadas no município de Juazeiro do Norte.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-03-0708","y":2023,"m":3,"d":"27","h":"Morre em Fortaleza, aos 84 anos de idade, o professor <a href=\"https://dema.ufc.br/pt/nota-de-pesar-falecimento-do-professor-aposentado-do-dema-ibere-guimaraes-aguiar/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Iberê Guimarães Aguiar</a>, docente aposentado do Departamento de Estatística e Matemática Aplicada (DEMA) da Universidade Federal do Ceará (UFC).","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-03-0709","y":2023,"m":3,"d":"28","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13619\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.092</a> (DOM nº 17.551, de 29/03/2023), que denomina Vereador Alberto Gomes de Queiroz a Escola de Tempo Integral localizada na Rua Zezé Diogo, no bairro Cais do Porto, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-03-0710","y":2023,"m":3,"d":"22","h":"O governador Elmano de Freitas sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18321.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.321, de 22/03/2023</a>, que reestrutura o quadro de Promotorias de Justiça do Ministério Público do Estado do Ceará (MPCE) nas comarcas de entrância final (<strong>Juazeiro do Norte</strong>, <strong>Crato</strong>, <strong>Sobral</strong>, <strong>Quixadá</strong>, Iguatu, Tauá, Caucaia, Maracanaú e Fortaleza), de entrância intermediária (incluindo <strong>Baturité</strong>, <strong>Aracoiaba</strong>, <strong>Canindé</strong>, <strong>Quixeramobim</strong>, <strong>Boa Viagem</strong>, <strong>Senador Pompeu</strong>, <strong>Mombaça</strong>, <strong>Limoeiro do Norte</strong>, <strong>Russas</strong>, <strong>Morada Nova</strong>, <strong>Aracati</strong>, <strong>Barbalha</strong>, <strong>Brejo Santo</strong>, <strong>Itapipoca</strong>, <strong>Camocim</strong>, <strong>Acaraú</strong> e <strong>Tianguá</strong>) e de entrância inicial (incluindo <strong>Redenção</strong> com vinculação a <strong>Acarape</strong> e <strong>Barreira</strong>, <strong>Pacoti</strong> com vinculação a <strong>Guaramiranga</strong> e <strong>Palmácia</strong>, <strong>Mulungu</strong> com vinculação a <strong>Aratuba</strong>, <strong>Capistrano</strong> com vinculação a <strong>Itapiúna</strong>, e <strong>Ocara</strong>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-04-0711","y":2023,"m":4,"d":"01","h":"No primeiro jogo da decisão do <a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2023\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série A de 2023</a>, disputado na Arena Castelão perante 32.698 pagantes, o Fortaleza Esporte Clube derrota o Ceará Sporting Club por 2 a 1, com gols de Lucas Sasha e Caio Alexandre para o Fortaleza, e Danilo Barcelos para o Ceará.","c":["Esportes"],"l":1},{"id":"ce-2023-04-0712","y":2023,"m":4,"d":"06","h":"Morre em Fortaleza o jornalista <a href=\"https://www.sindjorce.org.br/nota-de-pesar-francisco-souto-paulino/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Souto Paulino</a>, graduado em Comunicação Social pela UFC.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-04-0713","y":2023,"m":4,"d":"08","h":"Em tarde histórica na Arena Castelão, diante de 56.491 espectadores, o Fortaleza Esporte Clube, treinado pelo argentino Juan Pablo Vojvoda, empata em 2 a 2 com o Ceará Sporting Club no segundo jogo da final estadual — gols de Erick e Janderson para o Ceará, e de Juan Martín Lucero (de pênalti) e Calebe (aos 42 minutos do segundo tempo) para o Tricolor —, fechando o placar agregado em 4 a 3 e sagrando-se <a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=15187\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Pentacampeão Cearense de Futebol (2019, 2020, 2021, 2022 e 2023)</a>, feito inédito em seus 104 anos de fundação, além de alcançar seu 46º título estadual (<a href=\"https://fortaleza1918.com.br/category/campeonato-cearense/2023/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Fortaleza EC</a>).","c":["Esportes"],"l":1},{"id":"ce-2023-04-0714","y":2023,"m":4,"d":"10","h":"É sancionada pelo governador Elmano de Freitas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18342.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.342</a> (DOE de 12/04/2023), que denomina Emídio José de Almeida Neto o Centro de Educação Infantil (CEI) construído no município de Acopiara.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-04-0715","y":2023,"m":4,"d":"16","h":"Pela última rodada do Quadrangular Final do <a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=15221\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série B de 2023</a>, disputada na Arena Romeirão, em Juazeiro do Norte, o Horizonte Futebol Clube derrota o Icasa por 2 a 1 (gols de Leozinho e Dieguinho) e conquista o título de campeão cearense da Série B de 2023 (Taça Cristiano Cortez), enquanto o Floresta Esporte Clube vence o Guarany de Sobral por 3 a 0 no Estádio do Junco, em Sobral, sagrando-se vice-campeão e garantindo, ao lado do Horizonte, o acesso para a Série A estadual de 2024 (<a href=\"https://diariodonordeste.verdesmares.com.br/jogada/horizonte-icasa-e-floresta-disputam-titulo-da-serie-b-do-cearense-e-acessos-veja-cenarios-1.3357921\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://ne45.com.br/2023/04/16/horizonte-bate-icasa-e-e-campeao-da-serie-b-do-cearense-floresta-e-vice-e-tambem-sobe/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">NE45</a>).","c":["Esportes"],"l":1},{"id":"ce-2023-04-0716","y":2023,"m":4,"d":"20 e 26","h":"São sancionadas a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13634\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Complementar Municipal nº 354</a> em Fortaleza e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18350.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.350</a> (DOE de 26/04/2023), que denomina Benones Cardoso de Morais a Areninha construída no município de Cariús.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2023-05-0717","y":2023,"m":5,"d":"01","h":"Passa a vigorar em todo o País o novo valor do salário mínimo nacional de R$ 1.320,00 mensais, estabelecido pela Medida Provisória nº 1.172/2023, convertida na <a href=\"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14663.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Federal nº 14.663, de 28 de agosto de 2023</a>.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-05-0718","y":2023,"m":5,"d":"03","h":"O Ceará Sporting Club sagra-se <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/sport-x-ceara-confira-horario-onde-assistir-palpites-e-provaveis-escalacoes-1.3364087\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">tricampeão da Copa do Nordeste</a> (após os títulos invictos de 2015 e 2020) ao derrotar o Sport Club do Recife na disputa por pênaltis por 4 a 2, no Estádio da Ilha do Retiro, no Recife (PE), com duas cobranças defendidas pelo goleiro Richard, após vitória alvinegra por 2 a 1 na ida na Arena Castelão (em 19 de abril) e placar de 1 a 0 para os pernambucanos no tempo normal da volta (<a href=\"https://www.lance.com.br/copa-do-nordeste/ceara-nos-penaltis-vence-sport-e-fatura-a-copa-do-nordeste.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lance!</a>). Na mesma data, o prefeito José Sarto sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13640\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.360</a>, instituindo o novo Código de Ética dos Agentes Públicos de Fortaleza.","c":["Esportes","Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-05-0719","y":2023,"m":5,"d":"18","h":"São sancionadas pelo governador Elmano de Freitas duas leis estaduais de toponímia no Interior (DOE de 19/05/2023): a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18369.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.369</a>, que denomina Professor Raimundo Uraktan Gadelha o CEI no município de Tabuleiro do Norte; e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18370.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.370</a>, que denomina Francisco Pinto de Melo a estrada que interliga o Balneário de Carnaubal à rodovia CE-323, na Serra da Ibiapaba.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-05-0720","y":2023,"m":5,"d":"19","h":"Em solenidade conduzida pelo governador Elmano de Freitas em Fortaleza, o Governo do Estado do Ceará faz a entrega da <a href=\"https://g1.globo.com/ce/ceara/noticia/2023/05/19/quatro-homenageados-recebem-a-medalha-da-abolicao-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha da Abolição 2023</a> a quatro personalidades (<a href=\"https://diariodonordeste.verdesmares.com.br/ceara/medalha-da-abolicao-2023-homenageia-personalidades-da-politica-economia-judiciario-e-religiao-1.3371249\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>): o engenheiro, ex-deputado estadual e ex-diretor-geral do DNOCS Eudoro Walter de Santana; o Arcebispo Metropolitano de Fortaleza Dom José Antonio Aparecido Tosi Marques; a ministra do Tribunal Superior do Trabalho (TST) Kátia Magalhães Arruda; e o industrial Vilmar Ferreira, fundador do Grupo Aço Cearense.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-06-0721","y":2023,"m":6,"d":"02","h":"Em sessão solene realizada na nova sede do Tribunal Regional Eleitoral do Ceará (TRE-CE), em Fortaleza, tomam posse como novos dirigentes da Justiça Eleitoral cearense para o biênio 2023–2025 o desembargador <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/desembargador-raimundo-nonato-silva-santos-toma-posse-como-novo-presidente-do-tre-ce-1.3376807\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Raimundo Nonato Silva Santos</a> no cargo de presidente e o desembargador Francisco Gladyson Pontes nos cargos acumulados de vice-presidente e corregedor regional eleitoral (<a href=\"https://acmag.org.br/2023/06/firmo-aqui-o-compromisso-de-dialogar-com-a-associacao-de-magistrados-afirma-desembargador-raimundo-nonato-silva-santos-durante-posse-no-tre-ce/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ACM</a>, <a href=\"https://blogdoedisonsilva.com.br/2023/06/03/novos-presidente-e-vice-presidente-do-tribunal-regional-eleitoral-do-ceara-tomam-posse/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Edison Silva</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2023-06-0722","y":2023,"m":6,"d":"04","h":"Abre-se oficialmente em Barbalha, na Região do Cariri, a tradicional <a href=\"https://www.anuariodoceara.com.br/cariri/religiosidade/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Festa do Pau da Bandeira de Santo Antônio</a>, iniciando o calendário dos grandes festejos juninos do Interior cearense.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-06-0723","y":2023,"m":6,"d":"07","h":"O Governo do Estado do Ceará inaugura no município de Quixadá a nova sede regional do <a href=\"https://www.ce.gov.br/2023/06/07/sertao-central-recebe-nova-sede-de-unidade-de-monitoramento-eletronico-de-pessoas-e-alternativas-penais/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Núcleo de Monitoração Eletrônica de Pessoas e Alternativas Penais do Sertão Central</a>.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-06-0724","y":2023,"m":6,"d":"19","h":"São sancionadas pelo governador Elmano de Freitas três leis estaduais (DOE de 20/06/2023): a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18392.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.392</a>, que denomina Vicente Antenor Ferreira Gomes Filho o trecho da rodovia CE-240 entre Parra (Trairi) e Itapipoca; a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18393.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.393</a>, que reconhece oficialmente a cidade de Alto Santo como a \"Capital Cearense do Forró\"; e a Lei Estadual nº 18.394, que denomina José Nestor Epaminondas Freire a Areninha construída no município de Cariré.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-07-0725","y":2023,"m":7,"d":"03","h":"O Governo do Estado do Ceará inaugura a unidade do <a href=\"https://www.ce.gov.br/2023/07/03/governo-do-ceara-inaugura-vapt-vupt-no-centro-de-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Vapt Vupt Centro</a>, instalada no Shopping Central, no Centro de Fortaleza.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-07-0726","y":2023,"m":7,"d":"05","h":"O município de Sobral, principal polo da Região Norte do Estado, celebra solenemente os <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/sobral-veja-historia-da-cidade-o-que-fazer-e-por-que-ela-e-a-princesinha-do-norte-1.3383950\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">250 anos de sua fundação</a> (elevação à categoria de vila em 5 de julho de 1773 como Vila Distinta e Real de Sobral), com programação histórico-cultural, inaugurações e concerto na margem esquerda do Rio Acaraú (<a href=\"https://reporterceara.com.br/2023/07/05/sobral-celebra-250-anos-nesta-quarta-feira-5/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Repórter Ceará</a>).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-07-0727","y":2023,"m":7,"d":"05","h":"Morre em Fortaleza, aos 82 anos de idade, o magistrado e desembargador aposentado do Tribunal de Justiça do Estado do Ceará (TJCE) <a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-des-aposentado-celso-albuquerque-macedo/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Celso Albuquerque Macêdo</a>. Bacharel em Direito pela UFC, ingressou na magistratura em 1974 em Tamboril, atuou em Pacatuba, Pentecoste, Russas, Caucaia e na 10ª Vara de Família de Fortaleza, ascendendo ao TJCE em 26 de outubro de 2006 (<a href=\"https://intellgest-sigl-media.s3.amazonaws.com/media/sigg/public/materialegislativa/2023/3180/pl_91-2023.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Câmara Municipal de Russas</a>). Seu corpo foi velado na Funerária Ternura e sepultado no Cemitério Parque da Paz, em Fortaleza. Nascera no Sítio Barbatão, em Acopiara, CE, a 16 de janeiro de 1941.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-07-0728","y":2023,"m":7,"d":"06","h":"São sancionadas em Fortaleza a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13671\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Complementar Municipal nº 363</a>, que cria a Procuradoria Especial da Mulher na Câmara Municipal de Fortaleza, e a Lei Complementar Municipal nº 361 (Iplanfor).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-07-0729","y":2023,"m":7,"d":"11 e 13","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18420.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.420</a> (DOE de 12/07/2023), que denomina Antônio Tavares Alves a Escola Estadual do Campo no Distrito de Targinos, em Canindé; a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18423.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.423</a> (DOE de 14/07/2023), que denomina Neusa Peixoto o CEI construído em Jaguaribara; e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18425.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.425</a>, que declara de relevância histórica e turística o Pontal do Padre Cícero, em Farias Brito.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-07-0730","y":2023,"m":7,"d":"29","h":"Morre no município de Quixeramobim, aos 101 anos de idade, o comerciante tradicional <a href=\"https://diariodonordeste.verdesmares.com.br/regiao/morre-seu-miguel-balbino-comerciante-tradicional-de-quixeramobim-aos-101-anos-1.3398692\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Miguel Eloi da Silva (\"Seu Miguel Balbino\").</a>","c":["Necrologia"],"l":1},{"id":"ce-2023-08-0731","y":2023,"m":8,"d":"01","h":"O governador Elmano de Freitas sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18445.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.445, de 01/08/2023</a> (DOE de 02/08/2023), de autoria do deputado Romeu Aldigueri, que denomina de <strong>Deputado Peixoto de Alencar</strong> a sede da Unidade Regional do Departamento Estadual de Trânsito (Detran-CE) no Município de <strong>Baturité</strong>, em homenagem ao radialista, jornalista e ex-deputado estadual representante do Maciço de Baturité (<a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/pl4472023.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">ALECE</a>).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-08-0732","y":2023,"m":8,"d":"03","h":"O presidente da República Luiz Inácio Lula da Silva e o ministro da Educação Camilo Santana assinam o decreto de nomeação do professor <a href=\"https://blogdoedisonsilva.com.br/2023/08/03/custodio-almeida-e-confirmado-como-novo-reitor-da-ufc/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Custódio Luís Silva de Almeida</a> — primeiro colocado na consulta à comunidade acadêmica e na lista tríplice do CONSUNI — como novo reitor da Universidade Federal do Ceará (UFC) para o quadriênio 2023–2027 (<a href=\"https://www.correiobraziliense.com.br/euestudante/ensino-superior/2023/08/5115153-lula-nomeia-novo-reitor-da-universidade-federal-do-ceara.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Correio Braziliense</a>).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-08-0733","y":2023,"m":8,"d":"12","h":"Em partida única da final do <a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=15823\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série C de 2023</a>, disputada no Estádio Moraisão, em Maranguape, o Maranguape Futebol Clube vence o Cariri Football Club (de Juazeiro do Norte) por 1 a 0 (gol de Guilherme aos 44 minutos do primeiro tempo), sagrando-se campeão cearense da Série C de 2023 e garantindo ambas as agremiações o acesso para a Série B de 2024 (<a href=\"https://www.ocuriosodofutebol.com.br/2023/08/maranguape-bate-o-cariri-e-conquista-o.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Curioso do Futebol</a>).","c":["Esportes"],"l":1},{"id":"ce-2023-08-0734","y":2023,"m":8,"d":"18","h":"A Fundação Edson Queiroz inaugura no <a href=\"https://unifor.br/espaco-cultural\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Espaço Cultural da Universidade de Fortaleza (Unifor)</a> a 22ª Unifor Plástica, celebrando os 50 anos do salão de artes visuais.","c":["Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-08-0735","y":2023,"m":8,"d":"23","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18458.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.458</a> (DOE de 24/08/2023), que reconhece a cachaça de alambique produzida no Ceará como de relevante interesse cultural do Estado.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2023-08-0736","y":2023,"m":8,"d":"25","h":"Em cerimônia histórica realizada na Concha Acústica da Reitoria da Universidade Federal do Ceará (UFC), no bairro Benfica, em Fortaleza, com a presença do ministro da Educação Camilo Santana e do governador Elmano de Freitas, toma posse solenemente como 16º reitor da UFC para o quadriênio 2023–2027 o filósofo e professor titular <a href=\"https://www.adufc.org.br/2023/08/28/quadrienio-2023-2027-custodio-almeida-e-empossado-reitor-da-ufc-em-grande-ato-pela-democracia-na-concha-acustica/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Custódio Luís Silva de Almeida</a>, dando posse à engenheira química e professora titular Diana Cristina Silva de Azevedo no cargo de vice-reitora (<a href=\"https://ppgpsf.ufc.br/pt/o-reitor-custodio-almeida-toma-posse-na-concha-acustica-em-cerimonia-historica-e-cheia-de-simbolismo/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">UFC</a>).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-08-0737","y":2023,"m":8,"d":"30","h":"Em partida disputada no Estádio Morenão, na cidade de Iguatu, a Associação Desportiva Iguatu conquista de maneira inédita o título da <a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=15900\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Fares Lopes de 2023</a> ao vencer o Ferroviário Atlético Clube por 2 a 1 no tempo regulamentar e superar a equipe coral na disputa por pênaltis por 8 a 7, assegurando vaga na Copa do Brasil de 2024 (<a href=\"https://www.ferroviario.com.br/2023/08/31/ferrao-finaliza-a-disputa-da-taca-fares-lopes-com-o-vice-campeonato/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ferroviário AC</a>, <a href=\"https://radioasabranca.com.br/iguatu-e-campeao-da-taca-fares-lopes-ao-vencer-o-ferroviario-nos-penaltis/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Rádio Asa Branca</a>).","c":["Esportes"],"l":1},{"id":"ce-2023-09-0738","y":2023,"m":9,"d":"16","h":"Em tarde memorável no Estádio Presidente Vargas (PV), em Fortaleza, o Ferroviário Atlético Clube, comandado pelo técnico Paulinho Kobayashi, vence a Ferroviária de Araraquara (SP) por 2 a 1 (após empate em 0 a 0 no jogo de ida) e sagra-se <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/ferroviario-x-ferroviaria-pela-final-da-serie-d-confira-horario-onde-assistir-palpites-e-provavei-1.3418550\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Bicampeão Brasileiro da Série D de 2023 de forma invicta</a> (24 partidas, 15 vitórias e 9 empates), tornando-se o primeiro clube do futebol brasileiro a conquistar duas vezes a Quarta Divisão nacional (2018 e 2023) (<a href=\"https://esportenewsmundo.com.br/ferroviario-vence-ferroviaria-e-conquista-bicampeonato-da-serie-d/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Esporte News Mundo</a>).","c":["Esportes"],"l":1},{"id":"ce-2023-09-0739","y":2023,"m":9,"d":"19","h":"São sancionadas pelo governador Elmano de Freitas três leis estaduais de denominação de equipamentos no Interior (DOE de 21/09/2023): <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18471.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.471</a> (Areninha José Juraci Lobo em Lago do Mato, Itatira); <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18472.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.472</a> (CEI Gerardo Batista Nunes no Distrito de Bandeira, Itatira); e <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18476.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.476</a> (CEI Sebastião Leite de Lima em Aurora). Na mesma data, o prefeito José Sarto sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13697\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.392</a>, regulamentando o piso salarial da enfermagem na rede municipal de Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-09-0740","y":2023,"m":9,"d":"21","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13708\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.119</a> (DOM nº 17.670, de 27/09/2023), que denomina José Dilson Vasconcelos de Menezes o Posto de Saúde Siqueira, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-09-0741","y":2023,"m":9,"d":"22","h":"Em noite de gala no Theatro José de Alencar, em Fortaleza, o Sistema Verdes Mares / Grupo Edson Queiroz promove a entrega da <a href=\"https://diariodonordeste.verdesmares.com.br/verso/trofeu-sereia-de-ouro-homenageia-quatro-personalidades-em-solenidade-no-theatro-jose-de-alencar-1.3417054\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">51ª edição do Troféu Sereia de Ouro</a> a quatro personalidades de destaque do Ceará (<a href=\"https://g1.globo.com/ce/ceara/noticia/2023/08/03/trofeu-sereia-de-ouro-2023-homenageia-quatro-personalidades-de-destaque-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>): o ministro da Educação e ex-governador Camilo Sobreira de Santana; o cantor e compositor José Ednardo Soares Costa Sousa (Ednardo); o empresário José Roberto Nogueira (fundador da Brisanet, natural de Pereiro, CE); e a professora e filantropa Regina Barbosa, fundadora e presidente da Casa de Vovó Dedé. Na mesma data, a Câmara Municipal de Fortaleza outorga a <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-outorga-a-medalha-boticario-ferreira-ao-deputado-federal-idilvan-alencar\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha Boticário Ferreira ao deputado federal Antônio Idilvan de Lima Alencar</a> (seguida das entregas a <a href=\"https://www.cmfor.ce.gov.br/2023/09/25/camara-outorga-a-medalha-boticario-ferreira-ao-dr-jose-iramar-da-rocha-moreira/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dr. José Iramar da Rocha Moreira</a> em 25/09 e ao industrial <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-outorga-a-medalha-boticario-ferreira-ao-industrial-francisco-claudio-saraiva-leao-dias-branco\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Cláudio Saraiva Leão Dias Branco</a> em 28/09).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-10-0742","y":2023,"m":10,"d":"11","h":"O Papa Francisco acolhe o pedido de renúncia, por limite canônico de idade, apresentado por Dom José Antonio Aparecido Tosi Marques e nomeia como novo <a href=\"https://www.arquidiocesedefortaleza.org.br/saiba-como-sera-o-rito-de-posse-e-quem-falara-para-dom-gregorio-paixao-osb/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Arcebispo Metropolitano de Fortaleza</a> o monge beneditino Dom Gregório Ben Lâmed Paixão, OSB, até então bispo diocesano de Petrópolis (RJ).","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-10-0743","y":2023,"m":10,"d":"24","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13741\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.139</a> (DOM nº 17.690, de 27/10/2023), que denomina Alcir Roosevelt Leadebal a Escola-Areninha construída no bairro Messejana, em Fortaleza.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-10-0744","y":2023,"m":10,"d":"28","h":"Em fato inédito para o futebol cearense, o Fortaleza Esporte Clube disputa a grande final da <a href=\"https://pt.wikipedia.org/wiki/Final_da_Copa_Sul-Americana_de_2023\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Sul-Americana de 2023</a> — primeira decisão continental da história de um clube do Estado — no Estádio Domingo Burgueño Miguel, em Maldonado, no Uruguai. Após empate em 1 a 1 no tempo normal e na prorrogação diante da Liga Deportiva Universitaria (LDU), de Quito (gols de Juan Martín Lucero para o Fortaleza e Lisandro Alzugaray para a LDU), a equipe tricolor é superada nos pênaltis por 4 a 3, sagrando-se vice-campeã continental (<a href=\"https://www.estadao.com.br/esportes/futebol/ldu-bate-fortaleza-nos-penaltis-e-e-campea-da-copa-sul-americana/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Estadão</a>).","c":["Esportes"],"l":1},{"id":"ce-2023-10-0745","y":2023,"m":10,"d":"30","h":"São sancionadas pelo governador Elmano de Freitas três leis estaduais de toponímia e patrimônio cultural (DOE de 01/11/2023): a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18545.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.545</a>, que denomina Belízio Chagas Lima o trecho da rodovia CE-574 no município de Cedro; a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18547.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.547, que denomina Professor Manuel Eduardo Pinheiro Campos o CEI no Distrito de Água Verde, em Guaiúba</a>; e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18553.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.553</a>, que institui o município de Jaguaribe como a \"Capital Cearense da Renda de Filé\".","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-11-0746","y":2023,"m":11,"d":"13 e 17","h":"O governador Elmano de Freitas sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18564.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.564</a> (DOE de 14/11/2023), que denomina Professora Margarida Maria de Abreu Silva o CEI localizado no Distrito de Jaibaras, em Sobral, e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18574.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.574</a> (DOE de 20/11/2023), que denomina João Mendes Rátis a Areninha no Distrito do Tabuleiro dos Mendes, em Antonina do Norte.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-11-0747","y":2023,"m":11,"d":"21","h":"O Governo do Estado do Ceará lança o programa <a href=\"https://www.ce.gov.br/2023/11/21/ceara-por-elas-estado-firma-parceria-com-municipios-para-ampliar-rede-de-protecao-e-apoio-as-mulheres/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ceará por Elas</a>, firmando pactuação com os municípios do Interior para interiorizar a rede de enfrentamento à violência contra a mulher.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-11-0748","y":2023,"m":11,"d":"29","h":"É sancionada pelo governador Elmano de Freitas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18608.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.608</a> (DOE de 01/12/2023), que denomina Dra. Francisca Graci Gomes Aguiar a Casa da Mulher Cearense construída no município de Tauá, nos Inhamuns. Na mesma data, na decisão em jogo único do <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/camp-cearense-final-fortaleza-x-ceara-veja-horario-palpites-e-onde-assitir-1.3448852\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense de Futebol Feminino de 2023</a>, disputada na Arena Castelão, o Ceará Sporting Club (\"Meninas do Vozão\") sagra-se campeão cearense feminino (4º título estadual) ao empatar em 1 a 1 com o Fortaleza Esporte Clube e vencer nos pênaltis por 3 a 1 (<a href=\"https://meuvozao.com/noticias-do-ceara/ceara-fortaleza-titulo-feminino/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Meu Vozão</a>).","c":["Esportes","Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-12-0749","y":2023,"m":12,"d":"04","h":"O Governo do Estado do Ceará inicia as obras de construção do novo <a href=\"https://www.ce.gov.br/2023/12/04/iniciada-a-construcao-do-novo-mercado-publico-de-barbalha-equipamento-que-deve-fortalecer-a-economia-caririense/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Mercado Público de Barbalha</a>, na Região do Cariri.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2023-12-0750","y":2023,"m":12,"d":"09","h":"Morre em Fortaleza, aos 19 anos de idade, a estudante de Direito <a href=\"https://g1.globo.com/ce/ceara/noticia/2023/12/09/morre-sofia-filha-do-prefeito-de-caucaia-vitor-valim-que-passou-por-transplante-de-figado.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Sofia Valim</a>, filha do prefeito de Caucaia Vitor Valim e de Gaída Dias, após transplante de fígado de urgência.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2023-12-0751","y":2023,"m":12,"d":"12","h":"É sancionada pelo governador Elmano de Freitas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18620.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.620</a> (DOE de 15/12/2023), que denomina Antônio José dos Santos (Seu Toinho Verônica) o CEI localizado no município de Tarrafas.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2023-12-0752","y":2023,"m":12,"d":"15","h":"Em solene concelebração eucarística realizada às 18h na Catedral Metropolitana de Fortaleza, toma posse canônica como 7º Arcebispo Metropolitano de Fortaleza o monge beneditino <a href=\"https://g1.globo.com/ce/ceara/noticia/2023/12/15/dom-gregorio-paixao-toma-posse-como-arcebispo-de-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dom Gregório Ben Lâmed Paixão, OSB</a> (natural de Aracaju, SE), sucedendo a Dom José Antonio Aparecido Tosi Marques (<a href=\"https://www.arquidiocesedefortaleza.org.br/saiba-como-sera-o-rito-de-posse-e-quem-falara-para-dom-gregorio-paixao-osb/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Arquidiocese de Fortaleza</a>). Na mesma data, a Câmara Municipal de Fortaleza outorga a <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-outorga-a-medalha-boticario-ferreira-ao-vereador-licenciado-e-deputado-estadual-guilherme-sampaio-pt\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha Boticário Ferreira ao deputado estadual Guilherme de Figueiredo Sampaio</a>.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2023-12-0753","y":2023,"m":12,"d":"17","h":"O presidente da Assembleia Legislativa do Estado do Ceará, deputado estadual <a href=\"https://fr.wikipedia.org/wiki/Evandro_Leit%C3%A3o\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Evandro Sá Barreto Leitão</a>, filia-se oficialmente ao Partido dos Trabalhadores (PT) em solenidade partidária em Fortaleza.","c":["Política e Instituições"],"l":1},{"id":"ce-2023-12-0754","y":2023,"m":12,"d":"20","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18645.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.645</a> (DOE de 21/12/2023), que denomina Antônio José do Nascimento a Areninha localizada no Distrito de Lisieux, em Santa Quitéria.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2023-12-0755","y":2023,"m":12,"d":"22","h":"Morre em Fortaleza, aos 79 anos de idade, por falência múltipla dos órgãos após enfrentar a doença de Alzheimer, o ex-futebolista, treinador e dirigente esportivo <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/dimas-filgueiras-ex-jogador-e-treinador-do-ceara-morre-aos-79-anos-1.3458685\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dimas Filgueiras Filho</a>, imortalizado na crônica esportiva cearense como o \"Soldado Alvinegro\". Ex-zagueiro do Botafogo-RJ, do Fortaleza (1971–1972) e do Ceará Sporting Club (1972–1976), dedicou mais de 46 anos ininterruptos de trabalho ao Alvinegro de Porangabuçu como atleta, auxiliar, supervisor e treinador em 504 partidas oficiais, conduzindo o clube a títulos estaduais e ao histórico vice-campeonato da Copa do Brasil de 1994 (<a href=\"https://www.verminososporfutebol.com.br/dimas-filgueiras-completa-40-anos-no-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Verminosos por Futebol</a>). Seu corpo foi cremado em Fortaleza. Nascera no Rio de Janeiro, RJ, a 13 de maio de 1944.","c":["Necrologia","Esportes"],"l":1},{"id":"ce-2023-12-0756","y":2023,"m":12,"d":"26 a 28","h":"O prefeito José Sarto sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13813\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.423</a> (LOA 2024 de Fortaleza) e a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13809\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Complementar Municipal nº 389</a>, enquanto o governador Elmano de Freitas sanciona a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18647.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.647</a> (DOE de 29/12/2023), que denomina José Barreto Sampaio a avenida de acesso ao Monumento de Santo Antônio, em Barbalha, e a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2023/18648.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.648</a>, que denomina Vicente Fiuza de Menezes a Areninha localizada em Várzea Alegre.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-01-0757","y":2024,"m":1,"d":"01","h":"Entra em vigor o novo valor do salário mínimo nacional, fixado em R$ 1.412,00 mensais (R$ 47,07 diários e R$ 6,42 por hora), nos termos do <a href=\"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/decreto/d11864.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Federal nº 11.864, de 27 de dezembro de 2023.</a><br><a href=\"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/decreto/d11864.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">02 e 03 — O governador Elmano de Freitas sanciona quatr</a>o <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 03 e 04/01/2024): Lei nº 18.669 (denomina Maria de Jesus Nascimento – Dona Dijé a brinquedopraça de Jijoca de Jericoacoara); Lei nº 18.670 (denomina Engenheiro Agrônomo e Extensionista José Correia de Araújo a Gerência Regional da EMATERCE em Itapipoca); Lei nº 18.672 (denomina Doutor José de Oliveira Garcia a Areninha do distrito de Sucesso, em Tamboril); e Lei nº 18.673 (denomina Francisca Rodrigues da Silva o CEI de Lagoa das Pedras, em Croatá).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-01-0758","y":2024,"m":1,"d":"30","h":"Realiza-se na sede do Palácio da Luz, em Fortaleza, a Assembleia Geral Ordinária de abertura do ano cultural de 2024 do <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará (Histórico, Geográfico e Antropológico)</a>, presidida pelo Gen. Júlio Lima Verde Campos de Oliveira, ocasião em que é declarada vaga de sócio efetivo pela renúncia de Affonso Taboza Pereira, comunicada a passagem de Paulo Elpídio de Menezes Neto para a categoria de sócio remido e empossada a consócia Ana Paula Cavalcante Alencar da Silva como 1ª secretária.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-02-0759","y":2024,"m":2,"d":"01","h":"Morre em Fortaleza, aos 44 anos de idade, vítima de complicações de um câncer, o <a href=\"https://www.adufc.org.br/2024/02/01/nota-de-pesar-adufc-lamenta-morte-precoce-do-prof-osmar-goncalves-ica-ufc-nesta-quinta-1o-aos-44-anos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prof. Dr. Osmar Gonçalves dos Reis Filho</a>, professor associado do Curso de Cinema e Audiovisual do Instituto de Cultura e Arte da Universidade Federal do Ceará (ICA/UFC) e coordenador do Laboratório de Estudos de Imagem e Som (IMAGO). Nascera em Ribeirão Preto, SP, em 1979.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-02-0760","y":2024,"m":2,"d":"14","h":"Morre no Hospital São Camilo, em Fortaleza, aos 62 anos de idade, em decorrência de complicações pulmonares, o humorista, ator, diretor de televisão e ex-vereador de Fortaleza <a href=\"https://pt.wikipedia.org/wiki/Paulo_Di%C3%B3genes\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Paulo Osmar dos Santos Diógenes (Paulo Diógenes)</a>, intérprete desde a década de 1980 da célebre personagem \"Raimundinha\", ícone do humor cearense (G1 Ceará, <a href=\"https://www1.folha.uol.com.br/cotidiano/2024/04/mortes-rendeu-boas-gargalhadas-com-sua-personagem-raimundinha.shtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Folha de S.Paulo</a>). Exerceu mandato de vereador na Câmara Municipal de Fortaleza de 2013 a 2016 (PSD) e coordenou a Coordenadoria de Políticas Públicas para a Diversidade Sexual do Município (2017–2019). Nascera no Rio de Janeiro, RJ, a 12 de abril de 1961, sendo criado desde a infância em Fortaleza.","c":["Necrologia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-02-0761","y":2024,"m":2,"d":"21","h":"São sancionadas pelo governador Elmano de Freitas e publicadas no DOE do mesmo dia quatro <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a>: Lei nº 18.681 (denomina Antônio Enéas de Assis a rodovia CE-581 entre a BR-402 e Córrego das Varas, em Acaraú); Lei nº 18.685 (Areninha José Pereira de Oliveira – Zé de Doca, em Itarema); Lei nº 18.686 (EEMTI José de Fátima Gomes – Zé do Egídio, em Forquilha); e Lei nº 18.687 (denomina Domingos Sávio de Aguiar a rodovia CE-240, entre Moraújo e Coreaú).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-02-0762","y":2024,"m":2,"d":"22","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13842\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.240</a> (DOM de 05/03/2024), que denomina Praça Vereador Evaldo Lima o logradouro público no bairro Jangurussu, e o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13843\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.241</a>, que denomina Praça Antônio Alfeuzuíno de Oliveira (Sr. Antônio) o espaço público no bairro Messejana.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-02-0763","y":2024,"m":2,"d":"27","h":"Em sessão solene realizada no Palácio da Luz, toma posse como sócio efetivo do <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará</a> o magistrado e escritor Gilson da Costa Moreira, ocupando a vaga aberta pelo falecimento de Eduardo de Castro Bezerra Neto.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-02-0764","y":2024,"m":2,"d":"28","h":"São sancionadas e publicadas no DOE de 29/02/2024 as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.693 e nº 18.694</a>, que denominam José Avelino Fonteles a passagem molhada sobre o Rio Acaraú, em Acaraú, e Radialista Edvar Júnior (Chicotinho) a Areninha do bairro São Francisco, em Aracati.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-03-0765","y":2024,"m":3,"d":"04","h":"O <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará</a> celebra em sessão solene o 137º aniversário de sua fundação (04 de março de 1887), com o lançamento oficial do Tomo CXXXVII (referente ao ano de 2023) da Revista do Instituto do Ceará.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-03-0766","y":2024,"m":3,"d":"14","h":"São sancionadas pelo governador Elmano de Freitas e publicadas no DOE de 18/03/2024 as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.702, nº 18.703 e nº 18.704</a>, denominando Jornalista e Radialista Roberto Moreira a Brinquedopraça do bairro Jurema (em Caucaia), Dr. Francisco de Assis Clementino o Hospital Polo de Aracoiaba e Francisca Alzenira Pinheiro (Tia Alzenira) o CEI de Solonópole.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-03-0767","y":2024,"m":3,"d":"21","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13858\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.245</a> (DOM de 09/04/2024), que denomina Praça Francisco Rabelo de Mesquita o logradouro público no bairro Mondubim.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-03-0768","y":2024,"m":3,"d":"22","h":"Morre em Fortaleza, aos 76 anos de idade, o poeta, dramaturgo, jornalista, folclorista, professor universitário e pesquisador da cultura popular <a href=\"https://diariodonordeste.verdesmares.com.br/verso/dramaturgo-e-pesquisador-oswald-barroso-morre-aos-76-anos-1.3492444\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Raimundo Oswald Cavalcante Barroso (Oswald Barroso)</a>. Filho do poeta e jornalista Antônio Girão Barroso e de Alba Cavalcante Barroso, doutor em Sociologia pela UFC e professor da UECE, publicou mais de 30 livros e peças teatrais fundamentais sobre os reisados, o teatro popular tradicional e a dramaturgia cearense, como Reis de Congo (1997) e Teatro como Encantamento (2013) (<a href=\"https://pt.wikipedia.org/wiki/Oswald_Barroso\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Nascera em Fortaleza, CE, a 23 de dezembro de 1947.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-03-0769","y":2024,"m":3,"d":"27","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 18.716</a> (DOE de 27/03/2024), que denomina Comendador Ananias Arruda a brinquedopraça instalada na Praça Padre Mororó, na sede de Baturité.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2024-04-0770","y":2024,"m":4,"d":"05","h":"Morre em Fortaleza, aos 62 anos de idade, a <a href=\"https://www.adufc.org.br/2024/04/05/nota-de-pesar-adufc-lamenta-morte-da-profa-monica-magalhaes-docente-da-ufc-e-referencia-na-area-de-linguistica/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Profª. Dra. Mônica Magalhães Cavalcante</a>, professora titular do Departamento de Letras Vernáculas da Universidade Federal do Ceará (UFC), líder do Grupo de Pesquisa Protexto e referência nacional em Linguística Textual (<a href=\"https://pt.wikipedia.org/wiki/M%C3%B4nica_Cavalcante\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>), sendo sepultada no Cemitério Parque da Paz. Nascera em Fortaleza, CE, a 24 de fevereiro de 1962.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-04-0771","y":2024,"m":4,"d":"06","h":"O Ceará Sporting Club sagra-se campeão do <a href=\"https://www.opovo.com.br/esportes/futebol/times/ceara/2024/04/06/ceara-vence-o-fortaleza-nos-penaltis-e-e-campeao-do-campeonato-cearense-2024.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série A de 2024</a> (conquistando o seu 46º título estadual) ao derrotar o Fortaleza Esporte Clube na cobrança de pênaltis por 3 a 2, após empate em 1 a 1 no tempo regulamentar (gols de Saulo Mineiro para o Ceará e Lucero para o Fortaleza), diante de 57.887 torcedores na Arena Castelão; pela campanha como melhor equipe do interior (3º colocado geral), o Maracanã Esporte Clube conquista a Taça Padre Cícero de 2024 (<a href=\"https://pt.wikipedia.org/wiki/Campeonato_Cearense_de_Futebol_de_2024\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-04-0772","y":2024,"m":4,"d":"11 e 25","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.729, nº 18.732 e nº 18.763</a> (DOE de 12 e 26/04/2024), denominando o CEI Antônio Edmilson de Lima (em Pacajus), a rodovia CE-564 Radialista Mardônio Sampaio (em Viçosa do Ceará) e a EEMTI Professora Vanda Cidade (no bairro Cidade 2000, em Fortaleza).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-04-0773","y":2024,"m":4,"d":"23","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13874\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.249</a> (DOM de 02/05/2024), que denomina Praça Radialista Gomes Farias o logradouro público no bairro Demócrito Rocha.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-04-0774","y":2024,"m":4,"d":"27","h":"O Centro de Formação de Atletas do Tirol conquista o título inédito do <a href=\"https://ge.globo.com/ce/futebol/times/tirol/noticia/2024/04/27/tirol-vence-o-cariri-e-e-campeao-da-serie-b-do-cearense-2024.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série B de 2024</a> ao vencer o Cariri Football Club (de Juazeiro do Norte) por 3 a 0 na final única disputada no Estádio Presidente Vargas (PV), garantindo ambas as equipes o acesso à Série A estadual de 2025 (<a href=\"https://futebolcearense.com.br/adm/noticias/visualizar.php?id=11417\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Federação Cearense de Futebol</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-05-0775","y":2024,"m":5,"d":"03","h":"Em solenidade realizada às 19h no Palácio da Abolição, em Fortaleza, o governador Elmano de Freitas faz a entrega da <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/cinco-personalidades-e-uma-entidade-recebem-medalha-da-abolicao-2024-veja-agraciados-1.3508016\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha da Abolição 2024</a> a cinco personalidades e uma instituição (<a href=\"https://www.ceara.gov.br/2024/05/03/medalha-da-abolicao-homenageia-cinco-personalidades-e-uma-entidade-por-relevantes-servicos-prestados-ao-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Governo do Estado do Ceará</a>): o ministro da Educação e ex-governador Camilo Sobreira de Santana; o cineasta e produtor Luiz Carlos Barreto Borges; o jornalista, escritor e biógrafo João Carlos Peixoto de Lira Neto (Lira Neto); o bispo emérito de Limoeiro do Norte Dom Raimundo Edmilson da Cruz; a empresária e presidente da Cerbras Ana Lúcia Bastos Mota; e a Congregação Franciscana do Convento de Santo Antônio de Canindé.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-05-0776","y":2024,"m":5,"d":"07 e 21","h":"O governador Elmano de Freitas sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.786, 18.787, 18.812 e 18.814</a> (DOE de 08 e 22/05/2024), denominando José Ferreira da Silva (Zé Marreiro) a base da CIOPAER de Crateús, Sargento PM Francisco de Assis da Silva a base do CPRAIO em Jardim, Jornalista, Advogado e Escritor Ivonildo Lavor o campus do IFCE em Mauriti e Raimundo Maciel de Figueiredo a rodovia CE-265 entre Morada Nova e Ibicuitinga.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-05-0777","y":2024,"m":5,"d":"09 e 27","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13890\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.253</a> (Praça Francisco Nogueira da Silva – Bezerra, no Bonsucesso) e o prefeito José Sarto sanciona a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.464</a> (Areninha Maria de Fátima Rodrigues de Sousa, no Panamericano).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-05-0778","y":2024,"m":5,"d":"29","h":"Em Assembleia Geral Ordinária do <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará</a>, o arquiteto, urbanista e historiador José Henrique de Almeida Braga é eleito por unanimidade para o quadro de sócios efetivos da instituição (tomando posse em 27 de junho).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-06-0779","y":2024,"m":6,"d":"05 e 18","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.854, 18.857 e 18.882</a> (DOE de 06 e 19/06/2024), denominando o viaduto Antônio Elismar Pinto da Cunha no entroncamento da CE-085 com a CE-156 (em Paracuru), a brinquedopraça Joaquim Norberto de Oliveira (no distrito de Juá, em Quixadá) e o CEI Francisco Breno Bezerra Bastos (em Irauçuba).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-06-0780","y":2024,"m":6,"d":"09","h":"O Fortaleza Esporte Clube conquista o <a href=\"https://ge.globo.com/al/futebol/copa-do-nordeste/jogo/09-06-2024/crb-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">tricampeonato da Copa do Nordeste</a> (após os títulos de 2019 e 2022) ao derrotar o Clube de Regatas Brasil (CRB) na disputa por pênaltis por 5 a 4, no Estádio Rei Pelé, em Maceió (AL), após vitória tricolor por 2 a 0 no jogo de ida na Arena Castelão (em 05 de junho) e revés por 2 a 0 no tempo normal da volta, igualando o Ceará Sporting Club com três títulos regionais (<a href=\"https://pt.wikipedia.org/wiki/Copa_do_Nordeste_de_Futebol_de_2024\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-06-0781","y":2024,"m":6,"d":"12","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13915?display\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.258</a> (DOM de 24/06/2024), que denomina Praça Francisco Aldenir Pinheiro (Mestre Aldenir) o logradouro público no bairro Pici.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-06-0782","y":2024,"m":6,"d":"16","h":"Morre em Fortaleza, aos 66 anos de idade, o <a href=\"https://portaldoservidor.al.ce.gov.br/noticias/morre-ex-deputado-estadual-e-conselheiro-do-tce-ce-alexandre-figueiredo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dr. Luís Alexandre Albuquerque Figueiredo de Paula Pessoa (Alexandre Figueiredo)</a>, advogado, administrador, ex-deputado estadual por dois mandatos (1987–1995, incluindo a Constituinte de 1989), ex-secretário estadual dos Recursos Hídricos e conselheiro decano do Tribunal de Contas do Estado do Ceará (TCE-CE), corte que integrou por trinta anos (desde 1994) e presidiu nos biênios 1998–1999 e 2002–2003 (<a href=\"https://oabce.org.br/2024/06/nota-de-pesar-alexandre-figueiredo/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">OAB-CE, Wikipédia). Nascera e</a>m Sobral, CE, a 23 de março de 1958.","c":["Necrologia"],"l":1},{"id":"ce-2024-06-0783","y":2024,"m":6,"d":"19","h":"Morre em Fortaleza, aos 75 anos de idade, a desembargadora aposentada <a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-desa-aposentada-maria-vilauba-fausto-lopes/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Vilauba Fausto Lopes</a>, que ingressou na magistratura cearense em 1984, ascendeu ao Tribunal de Justiça do Estado do Ceará (TJCE) em 29 de janeiro de 2016 e exerceu a Coordenadoria da Infância e Juventude (<a href=\"https://www.tjce.jus.br/desa-maria-vilauba-fausto-lopes/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TJCE</a>), sendo sepultada no Cemitério Parque da Paz. Nascera em Icó, CE, a 02 de janeiro de 1949. No mesmo dia, morre em Fortaleza o juiz de direito aposentado <a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-juiz-aposentado-jose-de-castro-andrade/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José de Castro Andrade</a>, ex-titular da 3ª Vara do Júri da Comarca de Fortaleza, sepultado no Cemitério São João Batista.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2024-06-0784","y":2024,"m":6,"d":"22","h":"Morre em Fortaleza a <a href=\"https://www.adufc.org.br/2024/06/23/nota-de-pesar-morre-profa-tania-araujo-docente-aposentada-da-ufc-cantora-compositora-e-uma-das-fundadoras-da-adufc/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Profª. Tânia Barbosa Cabral de Araújo (Tânia Araújo)</a>, professora aposentada da UFC, uma das fundadoras da ADUFC-Sindicato e cantora e compositora integrante da geração do Pessoal do Ceará e do álbum histórico Massafeira Livre (1979), sendo sepultada no Cemitério Jardim Metropolitano, no Eusébio.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-06-0785","y":2024,"m":6,"d":"27","h":"O Governo do Estado do Ceará realiza no Palácio da Abolição a cerimônia oficial de abertura das comemorações do <a href=\"https://www.sintafce.org.br/governo-do-ceara-abre-bicentenario-da-confederacao-do-equador-nesta-quinta-feira-27/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Bicentenário da Confederação do Equador no Ceará (1824–2024)</a>.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-07-0786","y":2024,"m":7,"d":"04","h":"O Grupo Edson Queiroz anuncia oficialmente que o <a href=\"https://g1.globo.com/ce/ceara/noticia/2024/07/04/trofeu-sereia-de-ouro-anuncia-realizacao-bienal.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Troféu Sereia de Ouro passa a ter periodicidade bienal</a>, programando a 52ª edição para setembro de 2025. Na mesma data, são sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.918 e nº 18.921</a> (DOE de 05/07/2024), denominando o CEI Maria das Graças Ferreira Gomes (em Miraíma) e a base do CPRAIO Doutor Audízio Girão (em Morada Nova).","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-07-0787","y":2024,"m":7,"d":"16 e 23","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.938 e nº 18.940</a> (EEMTI Antônio Ferreira Gomes em Itapajé e Areninha José Airton Teixeira em Orós) e a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Ordinária Municipal nº 11.473</a> (Areninha João Carlos Augusto no bairro Rodolfo Teófilo, em Fortaleza).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2024-07-0788","y":2024,"m":7,"d":"25","h":"Em sessão histórica na sede do <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará</a>, em Fortaleza, são recebidas as urnas funerárias com os restos mortais do jurisconsulto cearense Clóvis Beviláqua (autor do Código Civil Brasileiro de 1916) e de sua esposa, a escritora Amélia Carolina de Freitas Beviláqua, em traslado do Rio de Janeiro para sua terra natal, Viçosa do Ceará.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-08-0789","y":2024,"m":8,"d":"01 e 05","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.969 e nº 18.972</a> (passarela Monsenhor João Olímpio Castello Branco na CE-060 em Maracanaú e EEMTI Vereador Francisco Enedilton Carneiro de Messias no distrito de Flores, em Russas) e promulgado o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.262</a> da CMFor (Praça Francisco Assis Chateaubriand, na Cidade dos Funcionários).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2024-08-0790","y":2024,"m":8,"d":"15","h":"Morre em Fortaleza, aos 61 anos de idade, a <a href=\"https://www.adufc.org.br/2024/08/16/nota-de-pesar-adufc-lamenta-morte-da-profa-elidihara-trigueiro-feaac-ufc-referencia-na-politica-de-assistencia-estudantil/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Profª. Elidihara Trigueiro Guimarães</a>, docente da FEAAC/UFC e ex-pró-reitora interina de Assuntos Estudantis da UFC, sendo sepultada no Cemitério Parque da Paz.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-08-0791","y":2024,"m":8,"d":"18","h":"O Quixadá Futebol Clube sagra-se campeão invicto do <a href=\"https://ge.globo.com/ce/futebol/campeonato-cearense/noticia/2024/08/18/quixada-vence-o-crato-e-e-campeao-invicto-da-serie-c-do-cearense.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série C de 2024</a> ao vencer o Crato Esporte Clube por 2 a 0 na final única realizada no Estádio Abilhão, em Quixadá (gols de Gleryston e Índio), assegurando ambas as equipes o acesso à Série B estadual de 2025 (<a href=\"https://futebolcearense.com.br/adm/noticias/visualizar.php?id=11702\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Federação Cearense de Futebol</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-08-0792","y":2024,"m":8,"d":"26 e 27","h":"Celebra-se o <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Bicentenário da Proclamação da República do Ceará e adesão formal à Confederação do Equador</a> (26 de agosto de 1824 – 26 de agosto de 2024), com seminário histórico no Instituto do Ceará e lançamento do Tomo Especial O Ceará na Confederação do Equador.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-08-0793","y":2024,"m":8,"d":"28","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 18.990 e nº 18.991</a> (DOE de 29/08/2024), denominando a Areninha Professor Francisco Célio da Silva (no distrito de Ibicuitaba, em Aracati) e a Areninha Maria de Fátima Rodrigues de Oliveira (no distrito de Taperuaba, em Sobral).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-08-0794","y":2024,"m":8,"d":"31","h":"Morre em Fortaleza, aos 94 anos de idade, o historiador, professor e genealogista <a href=\"https://www.institutodoceara.org.br/socio/francisco-fernando-saraiva-camara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Fernando Saraiva Câmara</a>, sócio efetivo decano do Instituto do Ceará (empossado em 17 de outubro de 1975), membro da Academia Cearense de Retórica, da Academia Sobralense de Estudos e Letras e da Academia Quixeramobinense de Letras, e autor de Álbum genealógico das Famílias Silva Câmara e Saraiva Leão (1975) e A Missão Ibiapaba (1979). Nascera em Quixeramobim, CE, a 24 de agosto de 1930.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-09-0795","y":2024,"m":9,"d":"06","h":"A Assembleia Legislativa do Estado do Ceará (ALECE) celebra os <a href=\"https://fundacaosintaf.org.br/alece-celebra-200-anos-da-confederacao-do-equador-com-audiencia-publica-e-exposicao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">200 anos da Confederação do Equador</a> com audiência pública e abertura de exposição histórico-documental.","c":["Política e Instituições"],"l":1},{"id":"ce-2024-09-0796","y":2024,"m":9,"d":"11 e 26","h":"São sancionadas pelo governador Elmano de Freitas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.005, 19.007, 19.035 e 19.037</a> (DOE de 12 e 27/09/2024), denominando o CEI Maria Socorro de Mesquita (em Aprazível, Sobral), a Areninha José Nogueira de Castro (em Solonópole), a Areninha Francisco de Assis da Silva (em Sobral) e a Areninha Raimundo Nonato de Souza (no Sítio Melancias, em Barbalha). No dia 19, a CMFor promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/13977?display\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.269</a> (Praça Francisco Édson Barbosa, no Jangurussu).","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-10-0797","y":2024,"m":10,"d":"06","h":"Realiza-se nos 184 municípios cearenses o 1º turno das Eleições Municipais de 2024: em Fortaleza, qualificam-se para o 2º turno André Fernandes de Moura (PL, 562.305 votos / 40,20%) e Evandro Sá Barreto Leitão (PT, 480.174 votos / 34,33%), ficando o prefeito José Sarto (PDT) em 3º lugar (164.402 votos / 11,75%) e Capitão Wagner (União Brasil) em 4º lugar (159.426 votos / 11,40%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/06/andre-fernandes-pl-e-evandro-leitao-pt-disputam-2-turno-em-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Caucaia, habilitam-se ao 2º turno Naumi Amorim (PSD, 38,42%) e Waldemir Catanho (PT, 24,67%) (<a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%A3o_municipal_de_Caucaia_em_2024\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>); em Sobral, Oscar Spíndola Rodrigues Júnior (União Brasil) é eleito prefeito com 65.138 votos (52,42%), derrotando a ex-governadora Izolda Cela (PSB, 47,58%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-oscar-rodrigues-do-uniao-e-eleito-prefeito-de-sobral-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Juazeiro do Norte, Glêdson Lima Bezerra (Podemos) torna-se o primeiro prefeito reeleito da história do município com 83.514 votos (53,23%) (<a href=\"https://nocariritem.com.br/andre-barreto-pt-e-eleito-prefeito-do-crato/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">No Cariri Tem</a>); no Crato, André Barreto Esmeraldo (PT) é eleito prefeito com 35.747 votos (48,74%); em Maracanaú, Roberto Soares Pessoa (União Brasil) é reeleito com 86.976 votos (62,83%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-roberto-pessoa-do-uniao-e-eleito-prefeito-de-maracanau-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Barbalha, Guilherme Saraiva (PT, reeleito com 58,19%); em Quixadá, Ricardo Silveira (PSD, reeleito com 69,24%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-ricardo-silveira-do-psd-e-eleito-prefeito-de-quixada-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Iguatu, Roberto Costa Filho (PSDB, eleito com 49,29%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-roberto-filho-do-psdb-e-eleito-prefeito-de-iguatu-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Crateús, Janaína Carla Farias (PT, eleita com 54,36%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-janaina-farias-do-pt-e-eleita-prefeita-de-crateus-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Aracati, Roberta Cardoso de Bismarck (Podemos, eleita com 57,20%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-roberta-de-bismarck-do-pode-e-eleita-prefeita-de-aracati-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Russas, Sávio Gurgel Nogueira (PSB, reeleito com 84,69%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-savio-do-psb-e-eleito-prefeito-de-russas-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Canindé, Francisco Jardel Sousa (PSB, eleito com 56,45%) (<a href=\"https://pt.wikipedia.org/wiki/Elei%C3%A7%C3%A3o_municipal_de_Canind%C3%A9_em_2024\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>); e em Tauá, Patrícia Aguiar (PSD, reeleita com 70,03%) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-patricia-aguiar-do-psd-e-eleita-prefeito-de-taua-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2024-10-0798","y":2024,"m":10,"d":"10","h":"O Tribunal Pleno do Tribunal de Justiça do Estado do Ceará (TJCE) elege a nova Mesa Diretora para o biênio 2025–2027, sagrando-se eleito presidente o desembargador <a href=\"https://www.tjce.jus.br/noticias/desembargador-heraclito-vieira-e-eleito-presidente-do-tjce-para-o-bienio-2025-2027-saiba-quem-sao-os-novos-gestores/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Heráclito Vieira de Sousa Neto</a>, ao lado do desembargador Francisco Mauro Ferreira Liberato (vice-presidente) e da desembargadora Marlúcia de Araújo Bezerra (corregedora-geral).","c":["Política e Instituições"],"l":1},{"id":"ce-2024-10-0799","y":2024,"m":10,"d":"15 e 16","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.270</a> (Praça Francisco Xavier de Oliveira – Chico da Tapioqueira, na Sapiranga) e o governador Elmano de Freitas sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.051 e nº 19.053</a> (rodovia CE-311 Raimundo Rodrigues da Rocha em Granja e Policlínica Regional Doutor José Simões dos Santos em Crateús).","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-10-0800","y":2024,"m":10,"d":"27","h":"Realiza-se o 2º turno das Eleições Municipais de 2024 em Fortaleza e em Caucaia: em Fortaleza, na disputa eleitoral mais acirrada da história da Capital (decidida por 10.838 votos), o deputado estadual e presidente da ALECE <a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/27/evandro-leitao-e-eleito-prefeito-em-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Evandro Sá Barreto Leitão (Evandro Leitão, PT)</a>, tendo Gabriella Pequeno Costa Gomes de Aguiar (Gabriella Aguiar, PSD) como vice-prefeita, é eleito Prefeito de Fortaleza de virada com 716.133 votos (50,38% dos votos válidos), derrotando o deputado federal André Fernandes de Moura (PL), que obteve 705.295 votos (49,62%) (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/com-10-mil-votos-de-diferenca-fortaleza-tem-a-eleicao-para-prefeito-mais-acirrada-em-24-anos-1.3575988\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>); em Caucaia, <a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/27/naumi-amorim-psd-e-eleito-prefeito-em-caucaia.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Naumi Gomes de Amorim (PSD)</a> é eleito Prefeito Municipal com 109.835 votos (60,40%), superando Waldemir Catanho (PT, 39,60%).","c":["Política e Instituições"],"l":1},{"id":"ce-2024-10-0801","y":2024,"m":10,"d":"06","h":"No 1º turno das Eleições Municipais de 2024 nos polos do <strong>Maciço de Baturité</strong> e do <strong>Vale do Jaguaribe</strong>, destacam-se as vitórias de <strong>Herberlh Freitas Reis Mota</strong> (<strong>Herberlh Mota</strong>, Republicanos), reeleito prefeito de <strong>Baturité</strong> com 18.058 votos (79,52% dos votos válidos) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-herberlh-mota-do-republicanos-e-eleito-prefeito-de-baturite-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); <strong>Sávio Gurgel Nogueira</strong> (PSB), reeleito prefeito de <strong>Russas</strong> com 39.856 votos (84,69% dos votos válidos) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-savio-do-psb-e-eleito-prefeito-de-russas-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); <strong>Dilmara Amaral Silva</strong> (PRD), eleita prefeita de <strong>Limoeiro do Norte</strong> (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-dilmara-do-prd-e-eleita-prefeita-de-limoeiro-do-norte-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); e <strong>Naiara Castro</strong> (PSB), eleita prefeita de <strong>Morada Nova</strong> com 24.429 votos (50,88% dos votos válidos) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/10/07/eleicoes-2024-naiara-castro-do-psb-e-eleita-prefeita-de-morada-nova-no-1o-turno.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2024-11-0802","y":2024,"m":11,"d":"06","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.069 e nº 19.070</a> (DOE de 07/11/2024), denominando a Areninha Monsenhor Luís Ximenes de Aragão (em Jaibaras, Sobral) e a rodovia CE-240 Padre João Mendes Lira (entre Uruburetama e Itapipoca).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-11-0803","y":2024,"m":11,"d":"08","h":"Morre em Fortaleza, aos 88 anos de idade, o advogado civilista <a href=\"https://www.tjce.jus.br/noticias/nota-de-pesar-advogado-jose-feliciano-de-carvalho/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dr. José Feliciano de Carvalho</a>, ex-presidente da Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE) no triênio 1993–1995 e ex-secretário de Segurança Pública do Estado do Ceará, sendo velado no Complexo Ethernus. Nascera em Viçosa do Ceará, CE, a 20 de novembro de 1935.","c":["Necrologia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-11-0804","y":2024,"m":11,"d":"12 e 21","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/14031\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.279</a> (Praça Antônio Simplício Gomes, no bairro Pedras) e o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/14038\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.281</a> (Praça Vereador Carlos Mesquita, no bairro Antônio Bezerra). No dia 21, a escritora e jornalista Ângela Barros Leal Farias é eleita para o quadro de sócios efetivos do <a href=\"https://www.institutodoceara.org.br/revista/Rev-apresentacao/RevPorAno/2024/2024-25-Atas-das-Sessoes.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Instituto do Ceará</a>.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-11-0805","y":2024,"m":11,"d":"18","h":"Pela 37ª rodada do Campeonato Brasileiro da Série B, o Ceará Sporting Club vence o América Mineiro por 1 a 0 (gol de Saulo Mineiro) diante de <a href=\"https://oestadoce.com.br/esportes/ceara-registra-o-maior-publico-da-historica-da-arena-castelao-em-vitoria-sobre-o-america-mg/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">63.908 torcedores na Arena Castelão</a>, estabelecendo o maior público da história de 51 anos do estádio desde sua inauguração em 1973 (<a href=\"https://ge.globo.com/ce/futebol/times/ceara/noticia/2024/11/18/ceara-x-america-mg-quebra-recorde-historico-de-publico-da-arena-castelao.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Globo Esporte</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-11-0806","y":2024,"m":11,"d":"19","h":"Em pleito realizado na Capital e nas subsecções do Interior, a advogada <a href=\"https://oabce.org.br/2024/11/christiane-leitao-e-eleita-a-primeira-mulher-presidente-da-oab-ce/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Christiane do Vale Leitão</a> é eleita a primeira mulher presidente da história de 91 anos da Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE) para o triênio 2025–2027, ao lado do vice-presidente David Sombra Peixoto, obtendo 10.662 votos (58,28%) (<a href=\"https://g1.globo.com/ce/ceara/noticia/2024/11/19/christiane-leitao-e-eleita-primeira-mulher-presidente-da-oab-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2024-11-0807","y":2024,"m":11,"d":"24","h":"Pela 38ª e última rodada do <a href=\"https://ge.globo.com/sp/campinas-e-regiao/futebol/brasileirao-serie-b/jogo/24-11-2024/guarani-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Brasileiro da Série B de 2024</a>, o Ceará Sporting Club empata em 0 a 0 com o Guarani em Campinas (SP), encerrando o certame na 4ª colocação com 64 pontos e conquistando o acesso de retorno à Série A do Campeonato Brasileiro de 2025.","c":["Esportes"],"l":1},{"id":"ce-2024-11-0808","y":2024,"m":11,"d":"27","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.088 e nº 19.091</a> (DOE de 28/11/2024), denominando a Policlínica Regional Doutor Francisco das Chagas Vasconcelos (em Santana do Acaraú) e a EEMTI Professor Francisco de Assis Silva (em Pedra Branca).","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-12-0809","y":2024,"m":12,"d":"01","h":"O Fortaleza Esporte Clube sagra-se campeão invicto da 1ª edição do <a href=\"https://ge.globo.com/ce/futsal/noticia/2024/12/01/fortaleza-vence-o-apodi-na-prorrogacao-e-e-campeao-do-brasileiro-de-futsal.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Brasileiro de Futsal (CBFS) de 2024</a> ao vencer o Apodi Futsal (RN) por 3 a 2 na prorrogação (gols de Rômulo, Jé e Valdin), diante de 10.118 torcedores na Arena do Centro de Formação Olímpica (CFO), em Fortaleza (<a href=\"https://www.opovo.com.br/esportes/futebol/times/fortaleza/2024/12/01/fortaleza-vence-apodi-na-prorrogacao-e-e-campeao-do-brasileiro-de-futsal.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Povo</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-12-0810","y":2024,"m":12,"d":"02","h":"O Plenário 13 de Maio da Assembleia Legislativa do Estado do Ceará (ALECE) elege a nova Mesa Diretora para o biênio 2025–2026, sagrando-se eleito presidente, por 44 votos, o deputado estadual <a href=\"https://www.al.ce.gov.br/noticias/romeu-aldigueri-e-eleito-presidente-da-alece-para-o-bienio-2025-2026\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Romeu Aldigueri de Arruda Coelho</a> (PDT) (<a href=\"https://blogdoeliomar.com/romeu-aldigueri-e-eleito-presidente-da-assembleia-legislativa-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Eliomar de Lima</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2024-12-0811","y":2024,"m":12,"d":"07","h":"O Ferroviário Atlético Clube conquista o tricampeonato da <a href=\"https://futebolcearense.com.br/adm/noticias/visualizar.php?id=11867\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Fares Lopes de 2024</a> (após os títulos de 2018 e 2020) ao vencer o Floresta Esporte Clube por 2 a 0 no tempo normal e por 7 a 6 na disputa por pênaltis, no Estádio Presidente Vargas (PV), garantindo vaga na Copa do Brasil de 2025 (<a href=\"https://ge.globo.com/ce/futebol/copa-fares-lopes/jogo/07-12-2024/floresta-ferroviario.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Globo Esporte</a>).","c":["Esportes"],"l":1},{"id":"ce-2024-12-0812","y":2024,"m":12,"d":"08","h":"Pela 38ª e última rodada do <a href=\"https://ge.globo.com/ce/futebol/brasileirao-serie-a/jogo/08-12-2024/fortaleza-internacional.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Brasileiro da Série A de 2024</a>, o Fortaleza Esporte Clube derrota o Internacional por 3 a 0 na Arena Castelão, encerrando a competição no 4º lugar geral com 68 pontos (invicto como mandante nas 19 partidas em casa), estabelecendo o recorde histórico de pontuação de um clube nordestino nos pontos corridos e classificando-se para a fase de grupos da Copa Libertadores da América de 2025.","c":["Esportes"],"l":1},{"id":"ce-2024-12-0813","y":2024,"m":12,"d":"11","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/14065\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.292</a> (DOM de 19/12/2024), que denomina Praça Jornalista, Escritor e Professor Lustosa da Costa o logradouro público no bairro Guararapes.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2024-12-0814","y":2024,"m":12,"d":"14","h":"Morre em Fortaleza, aos 77 anos de idade, o médico patologista e professor universitário <a href=\"https://www.adufc.org.br/2024/12/16/nota-de-pesar-adufc-lamenta-morte-do-prof-teonas-carvalho-cipriano-aposentado-do-depto-de-patologia-e-medicina-legal/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dr. Teonas Carvalho Cipriano</a>, docente aposentado da Faculdade de Medicina da UFC. Nascera no Ceará em 1947.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2024-12-0815","y":2024,"m":12,"d":"16 e 30","h":"O governador Elmano de Freitas sanciona as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2024/LEIS2024.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.119, 19.122, 19.163 e 19.167</a> (DOE de 17 e 30/12/2024), denominando a EEMTI Poeta Patativa do Assaré (no Conjunto Palmeiras, em Fortaleza), o Hospital Regional do Vale do Salgado Prefeito José Maria Monteiro (em Icó) e o Centro Cultural do Cariri Jornalista e Radialista Narcélio Limaverde (no Crato).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2024-12-0816","y":2024,"m":12,"d":"25","h":"Morre em Fortaleza a escritora, filósofa e professora universitária <a href=\"https://www.adufc.org.br/2024/12/26/nota-de-pesar-adufc-lamenta-morte-da-prof-a-maria-terezinha-de-castro-callado-aposentada-do-curso-de-letras-alemao-da-ufc/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Dra. Maria Terezinha de Castro Callado</a>, docente aposentada do curso de Letras-Alemão da UFC, ex-coordenadora do Mestrado em Filosofia da UECE, doutora pela Universidade Livre de Berlim e autora de Walter Benjamin – A Experiência da Origem, sendo velada no Complexo Ethernus.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-01-0817","y":2025,"m":1,"d":"01","h":"Entra em vigor em todo o território nacional o novo salário mínimo de R$ 1.518,00 mensais (correspondente ao valor diário de R$ 50,60 e horário de R$ 6,90), nos termos do <a href=\"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/decreto/d12342.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Federal nº 12.342, de 30 de dezembro de 2024</a>, assinado pelo presidente da República Luiz Inácio Lula da Silva.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-01-0818","y":2025,"m":1,"d":"01","h":"Em solenidade realizada no plenário da Câmara Municipal de Fortaleza (CMFor) e seguida de transmissão de cargo no Paço Municipal, tomam posse o prefeito eleito de Fortaleza, Evandro Sá Barreto Leitão (Evandro Leitão, PT), e a vice-prefeita Gabriella Pequeno Costa Gomes de Aguiar (Gabriella Aguiar, PSD), para o quadriênio 2025–2028 (<a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/cmfor-empossa-prefeito-evandro-leitao-e-vice-prefeita-gabriella-aguiar\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Câmara Municipal de Fortaleza</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/prefeito-evandro-leitao-e-vice-gabriella-aguiar-tomam-posse-para-mandato-de-4-anos-na-prefeitura-de-fortaleza-1.3600718\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://oestadoce.com.br/politica/prefeito-vice-e-vereadores-eleitos-vao-tomar-posse-em-cerimonia-na-cmfor-saiba-como-sera/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>, <a href=\"https://blogdoeliomar.com/tem-inicio-a-solenidade-de-posse-de-evandro-e-gabriella/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Eliomar de Lima</a>, <a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2025/01/01/evandro-leitao-toma-posse-como-prefeito-de-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Na mesma sessão solene, tomam posse os 43 vereadores eleitos para a 20ª Legislatura e realiza-se a eleição e posse da nova Mesa Diretora da Câmara Municipal de Fortaleza para o biênio 2025–2026, assumindo a presidência o vereador Leonardo d'Almeida Couto Barreto (Leo Couto, PSB), tendo como 1º vice-presidente Adail Júnior (PDT) (<a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-municipal-inicia-2025-com-posse-dos-vereadores-prefeito-e-eleicao-da-mesa-diretora\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">CMFor</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2025-01-0819","y":2025,"m":1,"d":"01","h":"Tomam posse os prefeitos, vice-prefeitos e vereadores eleitos nos municípios da Região Metropolitana de Fortaleza e nos principais polos do interior do Ceará para o mandato 2025–2028: em Sobral, tomam posse o prefeito Oscar Spíndola Rodrigues Júnior (Dr. Oscar Rodrigues, União Brasil) e a vice-prefeita Maria Imaculada Dias Adeodato (Dra. Imaculada, MDB), encerrando a hegemonia política de quase três décadas do grupo Ferreira Gomes no município (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/oscar-rodrigues-e-dra-imaculada-sao-empossados-prefeito-e-vice-em-sobral-1.3600770\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2025/01/01/oscar-rodrigues-toma-posse-como-prefeito-de-sobral-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>, <a href=\"https://www.camarasobral.ce.gov.br/sessao/24/Ata_02_2025_0000001.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Câmara Municipal de Sobral</a>); em Juazeiro do Norte, tomam posse o prefeito reeleito Glêdson Lima Bezerra (Podemos) — primeiro chefe do Executivo municipal reeleito na história da cidade — e o vice-prefeito Tarso Magno Teixeira da Silva (PP) (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/prefeito-gledson-bezerra-vice-tarso-magno-e-vereadores-de-juazeiro-do-norte-sao-empossados-1.3600790\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>); no Crato, tomam posse no Crato Tênis Clube o prefeito André Barreto Esmeraldo (PT) e o vice-prefeito Francisco Leitão Moura (Dr. Leitão, PSB) (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/prefeito-vice-e-vereadores-do-crato-sao-empossados-1.3600604\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>); em Caucaia, tomam posse o prefeito Naumi Gomes de Amorim (PSD) e a vice-prefeita Priscila Menezes (MDB) (<a href=\"https://www.caucaia.ce.gov.br/informa/1574\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Caucaia</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/prefeito-naumi-amorim-vice-priscila-menezes-e-vereadores-de-caucaia-sao-empossados-1.3600811\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>); em Barbalha, Guilherme Cavalcante Saraiva (PT) (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2025/01/01/guilherme-saraiva-toma-posse-como-prefeito-de-barbalha-no-ceara.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Iguatu, Carlos Roberto Costa Filho (Roberto Filho, PSDB) e o vice-prefeito Antônio Ferreira de Souza (Francisco das Frutas, PSDB) (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/prefeito-roberto-filho-vice-francisco-das-frutas-e-vereadores-de-iguatu-sao-empossados-1.3600946\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>); em Quixadá, Ricardo José Araújo Silveira (PSD) e o vice-prefeito Marcelo Ventura (<a href=\"https://quixada.ce.gov.br/informa/755/ricardo-silveira-e-marcelo-ventura-tomam-posse-com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Quixadá</a>); em Crateús, Janaína Carla Farias (PT) e o vice-prefeito Dr. Nenzé (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/12/31/prefeita-de-crateus-ce-toma-posse-nesta-quarta-1o-veja-lista-de-vereadores-eleitos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Aracati, Roberta Cardoso de Bismarck (Roberta de Bismarck, Podemos — primeira mulher eleita prefeita do município) e a vice-prefeita Ana Mello (<a href=\"https://g1.globo.com/ce/ceara/eleicoes/2024/noticia/2024/12/31/prefeita-de-aracati-ce-toma-posse-nesta-quarta-1o-veja-lista-de-vereadores-eleitos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>); em Russas, Sávio Gurgel Nogueira (<a href=\"https://www.russas.ce.gov.br/secretaria.php?sec=14\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Russas</a>); em Canindé, Francisco Jardel Sousa (<a href=\"https://www.cmcaninde.ce.gov.br/wp-content/uploads/2025/04/1-sessao-extraordinaria.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Câmara Municipal de Canindé</a>); e em Tauá, Patrícia Pequeno Costa Gomes de Aguiar (Patrícia Aguiar, PSD, iniciando o seu quinto mandato à frente do Executivo municipal) (<a href=\"https://www.taua.ce.gov.br/institucional.php\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Tauá</a>).","c":["Esportes","Política e Instituições"],"l":1},{"id":"ce-2025-01-0820","y":2025,"m":1,"d":"02","h":"Toma posse na sede da Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE), em Fortaleza, a advogada Christiane do Vale Leitão como presidente da instituição para o triênio 2025–2027, tornando-se a primeira mulher a presidir a OAB-CE em 91 anos de história, ao lado do vice-presidente David Sombra Peixoto (<a href=\"https://oabce.org.br/2025/01/christiane-leitao-toma-posse-na-oab-ce-e-promete-gestao-democratica-e-voltada-a-advocacia/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">OAB-CE</a>, <a href=\"https://blogdoeliomar.com/oab-ce-christiame-leitao-primeira-mulher-presidente-da-entidade-toma-posse-em-janeiro/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Eliomar de Lima</a>, <a href=\"https://unifor.br/-/entrevista-nota-10-christiane-leitao-a-primeira-mulher-presidente-da-oab-ce\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Unifor</a>).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-01-0821","y":2025,"m":1,"d":"07","h":"Em solenidade realizada em Quixadá com a presença da presidente estadual Christiane do Vale Leitão, toma posse a advogada Emanuele Nobre como a primeira mulher a presidir a <a href=\"https://oabce.org.br/2025/01/historico-e-emocionante-posse-da-primeira-mulher-na-presidencia-da-oab-sertao-central-marca-nova-era-para-a-advocacia-da-regiao/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">OAB Subsecção Sertão Central</a> para o triênio 2025–2027.","c":["Política e Instituições"],"l":1},{"id":"ce-2025-01-0822","y":2025,"m":1,"d":"24","h":"Tem início no Centro de Eventos do Ceará, em Fortaleza, a edição comemorativa de 25 anos do festival de cultura pop e oriental <a href=\"https://www.sympla.com.br/evento/sana-2025-parte-1/2548320\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Sana 2025 – Parte 1, estendendo-se até o dia 26 de janeiro.</a><br><a href=\"https://www.sympla.com.br/evento/sana-2025-parte-1/2548320\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">30 — O prefeito de Fortaleza, Evandr</a>o Leitão, anuncia o plano operacional do Ciclo Carnavalesco e Pré-Carnaval de Fortaleza 2025, ampliando a descentralização dos polos culturais nas regionais da Capital (<a href=\"https://www.fortaleza.ce.gov.br/noticias?page=52&start=3615\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Fortaleza</a>).","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-01-0823","y":2025,"m":1,"d":"30","h":"Morre em Fortaleza, aos 62 anos de idade, em decorrência de um câncer, o psicólogo e professor universitário <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/morre-erasmo-ruiz-professor-da-uece-pioneiro-no-estudo-da-tanatologia-no-ceara-1.3612403\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Erasmo Miessa Ruiz</a>. Graduado em Psicologia pela Universidade de São Paulo (USP), mestre em Educação pela UFSCar e doutor em Educação pela Universidade Federal do Ceará (UFC), lecionou por 27 anos no curso de Psicologia e na pós-graduação em Saúde Coletiva da Universidade Estadual do Ceará (UECE), destacando-se como pioneiro nos estudos de Tanatologia, luto e cuidados paliativos no Ceará e criador do Laboratório de Estudos em Tanatologia e Humanização das Práticas em Saúde (LETHS). Foi sepultado no Cemitério Parque da Paz, em Fortaleza.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-01-0824","y":2025,"m":1,"d":"31","h":"Em sessão solene realizada na sede do Poder Judiciário estadual, no bairro Cambeba, em Fortaleza, toma posse a nova direção do <a href=\"https://www.tjce.jus.br/noticias/nova-direcao-do-tjce-toma-posse-com-compromisso-de-avancos-em-areas-essenciais-a-justica/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Tribunal de Justiça do Estado do Ceará (TJCE)</a> para o biênio 2025–2027, integrada pelo desembargador Heráclito Vieira de Sousa Neto (presidente), pelo desembargador Francisco Mauro Ferreira Liberato (vice-presidente) e pela desembargadora Marlúcia de Araújo Bezerra (corregedora-geral da Justiça) (<a href=\"https://www.tjce.jus.br/noticias/desembargador-heraclito-vieira-assume-presidencia-do-tjce-e-destaca-prioridades-de-sua-administracao-para-bienio-2025-2027/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TJCE Discurso</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2025-02-0825","y":2025,"m":2,"d":"01","h":"Em sessão preparatória realizada no Plenário 13 de Maio, em Fortaleza, toma posse a nova Mesa Diretora da Assembleia Legislativa do Estado do Ceará (ALECE) para o biênio 2025–2026 (3ª e 4ª sessões legislativas da 31ª Legislatura), sob a presidência do deputado Romeu Aldigueri de Arruda Coelho (PDT), tendo como 1º vice-presidente Danniel Oliveira (MDB), 2ª vice-presidente Larissa Gaspar (PT), 1º secretário De Assis Diniz (PT), 2º secretário Jeová Mota (PDT), 3º secretário Felipe Mota (União Brasil) e 4º secretário João Jaime (Progressistas) (<a href=\"https://g1.globo.com/ce/ceara/noticia/2025/02/01/nova-mesa-diretora-da-assembleia-legislativa-do-ceara-toma-posse-e-romeu-aldigueri-pdt-assume-presidencia-da-casa.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/romeu-aldigueri-toma-posse-como-presidente-da-alece-e-promete-mediacao-para-evitar-debates-eleitorais-antecipados-1.3612897\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://blogdoeliomar.com/aldigueri-e-eleito-presidente-da-alece-com-44-votos/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Eliomar de Lima</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2025-02-0826","y":2025,"m":2,"d":"04","h":"Realiza-se no Centro de Eventos do Ceará, em Fortaleza, a solenidade de posse festiva da diretoria da <a href=\"https://oabce.org.br/2025/01/oab-ce-realiza-posse-festiva-da-nova-gestao-no-dia-04-de-fevereiro/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ordem dos Advogados do Brasil – Secção Ceará (OAB-CE)</a> para o triênio 2025–2027, presidida por Christiane do Vale Leitão.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-02-0827","y":2025,"m":2,"d":"12","h":"O governador Elmano de Freitas assina no Palácio da Abolição <a href=\"https://www.ce.gov.br/2025/02/12/governador-elmano-de-freitas-assina-decreto-que-garante-assistencia-religiosa-em-hospitais-equipamentos-de-internacao-e-sistemas-socioeducativo-e-prisional/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">decreto que regulamenta a prestação de assistência religiosa</a> em hospitais públicos e privados, equipamentos de internação e unidades dos sistemas socioeducativo e prisional do Ceará, com a presença do bispo da Diocese do Crato, Dom Magnus Henrique Lopes.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-02-0828","y":2025,"m":2,"d":"13","h":"Morre em Fortaleza, aos 93 anos de idade, a farmacêutica, sanitarista e cientista <a href=\"https://unifor.br/-/nota-de-pesar-fundacao-edson-queiroz-lamenta-o-falecimento-da-profa.-dra.-maria-zelia-rouquayrol\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Zélia Rouquayrol</a>. Graduada em Farmácia pela UFPE e mestre em Saúde Pública pela Universidade de Tulane (EUA), foi Professora Emérita da Universidade Federal do Ceará (UFC), docente da Universidade de Fortaleza (Unifor), pesquisadora visitante da Universidade de Colúmbia e autora do clássico tratado Epidemiologia & Saúde (1986), obra de referência no ensino médico brasileiro. Era membro da Academia Cearense de Ciências, da Academia Cearense de Farmácia e Presidente de Honra da Academia Cearense de Saúde Pública, tendo sido agraciada com a Medalha do Mérito Científico Nacional Oswaldo Cruz (2009) e com o Troféu Sereia de Ouro (2013) (<a href=\"https://www.ce.gov.br/saude/2025/08/04/sesa-inaugura-centro-de-estudos-em-vigilancia-em-saude-do-ceara-maria-zelia-rouquayrol/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Governo do Ceará – Sesa</a>, <a href=\"https://pt.wikipedia.org/wiki/Maria_Z%C3%A9lia_Rouquayrol\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Wikipédia</a>). Nascera em Sertânia, PE, a 03 de setembro de 1931.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-02-0829","y":2025,"m":2,"d":"19","h":"O governador Elmano de Freitas lança no Palácio da Abolição o plano estadual de metas integradas de segurança pública no âmbito do programa <a href=\"https://www.ce.gov.br/2025/02/19/ceara-contra-o-crime-governador-elmano-de-freitas-anuncia-plano-de-metas-para-a-seguranca-publica/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">\"Ceará Contra o Crime\"</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-02-0830","y":2025,"m":2,"d":"21","h":"O Governo do Ceará anuncia investimento superior a R$ 400 milhões para a construção de <a href=\"https://www.ce.gov.br/vicegov/2025/02/21/governo-do-ceara-vai-destinar-mais-de-r-400-milhoes-para-fortalecer-protecao-social-nos-municipios/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">103 novos equipamentos de proteção social e desenvolvimento infantil</a> (CRAS, CEIs e Complexos Mais Infância) em 85 municípios cearenses.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-02-0831","y":2025,"m":2,"d":"23","h":"No Estádio Municipal Almir Dutra, em Maracanaú, o Maracanã Esporte Clube conquista pelo segundo ano consecutivo a <a href=\"https://www.futebolcearense.com.br/2020/noticia_ver.asp?id=17558\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Padre Cícero</a> (título de Campeão Cearense do Interior de 2025) ao vencer o Horizonte Futebol Clube por 1 a 0 (gol de Patuta), garantindo o placar agregado de 4 a 2 nas quartas de final do Campeonato Cearense.","c":["Esportes"],"l":1},{"id":"ce-2025-02-0832","y":2025,"m":2,"d":"28","h":"O governador Elmano de Freitas realiza a entrega de <a href=\"https://www.policiacivil.ce.gov.br/2025/02/28/governo-do-ceara-entrega-mais-155-viaturas-para-atuacao-da-pcce-em-todas-regioes-do-estado/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">155 novas viaturas para a Polícia Civil do Estado do Ceará (PCCE)</a>, destinadas ao reforço operacional de delegacias na Capital, Região Metropolitana e interior do Estado (<a href=\"https://oestadoce.com.br/edicao-do-dia/fortaleza-ceara-sexta-feira-28-de-fevereiro-sabado-e-domingo-1o-e-2-de-marco-de-2025-edicao-25-034/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>).","c":["Política e Instituições"],"l":1},{"id":"ce-2025-03-0833","y":2025,"m":3,"d":"15","h":"Na Arena Castelão, em Fortaleza, perante público de 36.589 espectadores, o Ceará Sporting Club vence o Fortaleza Esporte Clube por 1 a 0 no jogo de ida da final do <a href=\"https://www.lance.com.br/futebol-nacional/ceara-bate-o-fortaleza-e-larga-na-frente-na-decisao-do-cearense.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série A de 2025</a>, com gol assinalado de pênalti pelo volante Fernando Sobral aos 36 minutos do segundo tempo.","c":["Esportes"],"l":1},{"id":"ce-2025-03-0834","y":2025,"m":3,"d":"19","h":"No Dia de São José, padroeiro do Estado, o presidente da República Luiz Inácio Lula da Silva e o governador Elmano de Freitas, acompanhados do ministro da Educação Camilo Santana, do ministro da Saúde Alexandre Padilha e do prefeito Evandro Leitão, inauguram no campus do Itaperi da Universidade Estadual do Ceará (UECE), em Fortaleza, o <a href=\"https://www.ce.gov.br/saude/2025/03/19/hospital-universitario-do-ceara-e-inaugurado-e-se-destaca-como-um-dos-maiores-hospitais-publicos-do-brasil/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hospital Universitário do Ceará (HUC)</a>. Sob direção-geral da médica Ivelise Brasil e instalado em área de 78,6 mil metros quadrados com capacidade para 652 leitos e atendimento terciário em 31 especialidades, o equipamento consolida-se como um dos maiores hospitais públicos do País (<a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-evandro-participa-de-inauguracao-do-hospital-universitario-do-ceara-com-presidente-lula\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Prefeitura de Fortaleza</a>, <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/em-1-vinda-ao-ceara-em-2025-lula-inaugura-hospital-universitario-que-comeca-a-receber-pacientes-nesta-quarta-19-1.3631677\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://oestadoce.com.br/politica/lula-participa-de-inauguracao-do-hospital-da-uece-na-proxima-quarta-19-em-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>).","c":["Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-03-0835","y":2025,"m":3,"d":"22","h":"Na Arena Castelão, em Fortaleza, o Ceará Sporting Club empata em 1 a 1 com o Fortaleza Esporte Clube (gols de Lucas Sasha aos 14 minutos do segundo tempo para o Fortaleza e de Pedro Raul, de cabeça, aos 26 minutos do segundo tempo para o Ceará) no jogo de volta da decisão estadual e sagra-se <a href=\"https://agenciabrasil.ebc.com.br/esportes/noticia/2025-03/ceara-conquista-o-bicampeonato-cearense-apos-empate-com-o-fortaleza\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">bicampeão cearense de futebol de forma invicta</a> (2 a 1 no placar agregado), alcançando o 47º título estadual de sua história (<a href=\"https://diariodonordeste.verdesmares.com.br/jogada/ceara-x-fortaleza-veja-horario-onde-assistir-palpites-e-provaveis-escalacoes-1.3632622\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://www.cnnbrasil.com.br/esportes/futebol/pedro-raul-decide-e-ceara-e-bicampeao-estadual-em-cima-do-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">CNN Brasil</a>).","c":["Esportes"],"l":1},{"id":"ce-2025-03-0836","y":2025,"m":3,"d":"25","h":"Celebra-se no Estado o feriado civil da <a href=\"https://www.ce.gov.br/tag/data-magna/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Data Magna do Ceará</a>, alusivo ao transcurso dos 141 anos da Abolição da Escravatura na então Província do Ceará, ocorrida em 25 de março de 1884.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-04-0837","y":2025,"m":4,"d":"03","h":"É sancionada pelo governador Elmano de Freitas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 19.209</a> (DOE de 04/04/2025), que denomina Francisco Gladstone Pinto Lôbo a Escola Agrícola situada na Fazenda Dr. Paula Rodrigues. Na esfera municipal, a Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=2&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.296</a>, denominando Travessa Seleta logradouro público do bairro Antônio Bezerra, e outorga em sessão solene a <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-outorga-a-medalha-boticario-ferreira-ao-empresario-francisco-pinheiro-neto\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha Boticário Ferreira ao empresário Francisco Pinheiro Neto</a>.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-04-0838","y":2025,"m":4,"d":"04","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.218, nº 19.219 e nº 19.221</a> (DOE de 07/04/2025), que denominam, respectivamente: Professora Fernanda Maria Gomes de Amorim a Escola de Ensino Médio em Tempo Integral (EEMTI) localizada no bairro Messejana, em Fortaleza; José Firmino de Arruda a EEMTI localizada no distrito de Manhoso, em Viçosa do Ceará; e José Arteiro Rosa o Terminal Rodoviário do município de Tamboril. Na mesma data, é aberta no Centro de Eventos do Ceará, em Fortaleza, a <a href=\"https://www.ce.gov.br/setur/2025/04/14/bienal-do-livro-do-ceara-2025-atrai-mais-de-450-mil-visitantes-e-reforca-protagonismo-do-centro-de-eventos-como-polo-cultural-e-turistico/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">XV Bienal Internacional do Livro do Ceará</a>, realizada até 13 de abril com público recorde superior a 450 mil visitantes.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-04-0839","y":2025,"m":4,"d":"06","h":"Morre em Fortaleza, aos 90 anos de idade, a tabeliã e política <a href=\"https://www.al.ce.gov.br/noticias/49215-zelia-mota-trajetoria-e-legado-da-primeira-deputada-estadual-do-ceara\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Zélia Mota</a>. Titular de cartório em Itapajé e filiada à Aliança Renovadora Nacional (ARENA), entrou para a história política cearense ao ser eleita, em 1974 (com 15.106 votos), a primeira mulher deputada estadual do Ceará (legislatura 1975–1978), tendo exercido o cargo de 3ª secretária da Mesa Diretora da Assembleia Legislativa no biênio 1975–1976 (<a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/morre-maria-zelia-mota-primeira-deputada-estadual-do-ceara-aos-90-anos-1.3638223\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Diário do Nordeste</a>, <a href=\"https://oestadoce.com.br/nacional/morre-zelia-mota-a-primeira-mulher-eleita-deputada-estadual-no-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>, <a href=\"https://blogdoeliomar.com/zelia-mota-morre-a-primeira-deputada-estadual-do-ceara-aos-90-anos-de-idade/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Blog do Eliomar de Lima</a>, <a href=\"https://g1.globo.com/ce/ceara/noticia/2025/04/07/primeira-mulher-eleita-deputada-estadual-pelo-ceara-maria-zelia-mota-morre-aos-90-anos.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Nascera em Fortaleza, CE, a 20 de junho de 1934.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2025-04-0840","y":2025,"m":4,"d":"08","h":"Têm início as comemorações oficiais do centenário de nascimento do industrial e chanceler <a href=\"https://unifor.br/-/mostra-fotografica-marca-o-inicio-das-comemoracoes-do-centenario-de-edson-queiroz\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Edson Queiroz</a> (nascido em Cascavel, CE, a 12 de abril de 1925), com abertura de mostra fotográfica na Universidade de Fortaleza (Unifor), seguida de sessão solene conjunta do <a href=\"https://www12.senado.leg.br/noticias/videos/2025/04/empresario-cearense-edson-queiroz-e-homenageado-em-sessao-do-congresso\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Congresso Nacional</a> em Brasília no dia 09 de abril e sessão solene na <a href=\"https://unifor.br/-/sessao-solene-na-camara-municipal-de-fortaleza-celebra-o-centenario-de-edson-queiroz\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Câmara Municipal de Fortaleza</a>.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-04-0841","y":2025,"m":4,"d":"12","h":"No Estádio Presidente Vargas (PV), em Fortaleza, o Maranguape Futebol Clube conquista o título inédito do <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/maranguape-e-campeao-da-serie-b-do-cearense-apos-empate-emocionante-e-vitoria-nos-penaltis-1.3640326\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série B de 2025</a> ao empatar em 1 a 1 no tempo regulamentar com o Quixadá Futebol Clube e vencer a disputa por pênaltis, assegurando o retorno de ambas as agremiações à elite do futebol cearense em 2026 (<a href=\"https://oestadoce.com.br/esportes/maranguape-conquista-titulo-da-serie-b-do-campeonato-cearense/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">O Estado</a>).","c":["Esportes"],"l":1},{"id":"ce-2025-04-0842","y":2025,"m":4,"d":"15","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.225, nº 19.226 e nº 19.228</a> (DOE de 16/04/2025), que denominam, respectivamente: Pedro Ferreira de Souza a ponte localizada entre os municípios de São Gonçalo do Amarante (Siupé) e Paracuru; Raimundo Nonato de Freitas o CEI no bairro Campo, em Iracema; e Antonio Feitosa Neto a Delegacia de Polícia Civil do município de Barro.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-04-0843","y":2025,"m":4,"d":"26","h":"Morre em Fortaleza o advogado, jornalista, marchand e empresário gráfico <a href=\"https://unifor.br/-/nota-de-pesar-mauricio-xerez\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maurício Xerez</a>, ex-diretor do jornal Diário do Nordeste e proprietário da Gráfica ABC Fortaleza.","c":["Necrologia"],"l":1},{"id":"ce-2025-05-0844","y":2025,"m":5,"d":"02","h":"São sancionadas cinco <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia e patrimônio cultural</a> (DOE de 05 e 06/05/2025): Lei nº 19.236 (denomina Pedro Ferreira Magalhães a Brinquedopraça do distrito de Betânia, em Hidrolândia); Lei nº 19.238 (denomina Maria Raimunda do Espírito Santo Costa o CEI em Barbalha); Lei nº 19.239 (denomina Deputado Edísio Pacheco o Açude Gameleira, entre Itapipoca, Trairi e Tururu); Lei nº 19.241 (declara o poeta popular Antônio Gonçalves da Silva – Patativa do Assaré – Patrono da Cultura Popular Cearense); e Lei nº 19.242 (denomina Doutor Tabosa a Areninha no distrito de Canaã, em Trairi).","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-05-0845","y":2025,"m":5,"d":"04","h":"Pela fase de grupos do <a href=\"https://blogdoeliomar.com/confronto-entre-os-quatro-times-cearenses-pela-serie-d-do-brasileiro/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Brasileiro da Série D de 2025</a>, enfrentam-se os quatro representantes cearenses na competição (Maracanã Esporte Clube, Associação Desportiva Iguatu, Ferroviário Atlético Clube e Horizonte Futebol Clube), enquanto o Floresta Esporte Clube disputa a Série C nacional.","c":["Esportes"],"l":1},{"id":"ce-2025-05-0846","y":2025,"m":5,"d":"21","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 19.261</a> (DOE de 21/05/2025), que cria o Hospital e Maternidade da Polícia Militar do Ceará José Martiniano de Alencar (HPM), e a Lei Estadual nº 19.265 (DOE de 23/05/2025), que denomina Francisco Dário Martins a rodovia CE-323, no trecho que liga Carnaubal a Inhuçu, em São Benedito.","c":["Legislação e Toponímia","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-06-0847","y":2025,"m":6,"d":"01","h":"Com o tradicional cortejo cultural e carregamento do mastro até a Matriz de Santo Antônio, tem início no município de Barbalha a <a href=\"https://barbalha.ce.gov.br/informa/2351/cortejo-cultural-tradi-o-e-identidade-o-dia-do-pau\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">97ª edição da Festa do Pau da Bandeira de Santo Antônio</a>, estendendo-se até 13 de junho.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-06-0848","y":2025,"m":6,"d":"05","h":"São sancionadas cinco <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de denominação de equipamentos públicos</a> (DOE de 06 e 09/06/2025): Lei nº 19.272 (denomina Francisco Alves Marinho a estação do Metrofor no bairro Boa Vista, em Maracanaú); Lei nº 19.273 (denomina Maria Norma Maia Soares a Escola de Trânsito do Detran-CE em Sobral); Lei nº 19.278 (denomina Antonio Carneiro Lima a Areninha no distrito de Missi, em Irauçuba); Lei nº 19.280 (denomina José Ilo Alves Dantas a EEMTI localizada em Iguatu); e Lei nº 19.292 (denomina Francisco Aníbal Oliveira de Arruda Coelho a Escola de Tempo Integral no distrito de Timonha, em Granja).","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-06-0849","y":2025,"m":6,"d":"09","h":"São sancionadas seis <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 11/06/2025): Lei nº 19.302 (Areninha Francisco Teixeira Sales em Santa Luzia, Uruburetama); Lei nº 19.304 (CEI Flávio Alves de Souza Brito em Saboeiro); Lei nº 19.307 (Areninha Wellyr Victor Davi no distrito de Anil, Meruoca); Lei nº 19.308 (EEMTI Walquer Cavalcante Maia em Russas); Lei nº 19.309 (CEI Braz Gabriel de Sousa em Pacujá); e Lei nº 19.312 (Escola de Tempo Integral Hermenegildo Meneses da Silva no distrito de Aruaru, Morada Nova).","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-06-0850","y":2025,"m":6,"d":"12","h":"A Câmara Municipal de Fortaleza promulga os <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?page=2&assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos nº 1.314 e nº 1.315</a>, que denominam, respectivamente: Cristiano Pinho (em homenagem ao guitarrista e compositor cearense) a Escola Pública de Música de Fortaleza, no bairro Joaquim Távora; e Antônio Eudes Rodrigues Júnior a pista de skate situada no Ginásio Poliesportivo da Parangaba.","c":["Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-06-0851","y":2025,"m":6,"d":"13","h":"Morre em Fortaleza, aos 99 anos de idade, a educadora <a href=\"https://www2.al.ce.gov.br/legislativo/tramit2025/pl924_25.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Maria Aglaís Marques Albuquerque</a>, professora e diretora histórica da Escola Reunida Padre João Antônio, no município de Acopiara.","c":["Necrologia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-06-0852","y":2025,"m":6,"d":"24","h":"São sancionadas sete <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 25 e 27/06/2025): Lei nº 19.321 (Escola de Tempo Integral João Sotero Veras em Bitupitá, Barroquinha); Lei nº 19.324 (Escola Estadual Professora Raimunda de Araújo Menezes – Tia Mundinha, em Caucaia); Lei nº 19.325 (denomina Lorival Gondim a rodovia CE-060 entre Jardim e Barbalha); Lei nº 19.329 (Escola de Ensino Médio Francisco Djauma Félix Martins, em Acopiara); Lei nº 19.331 (Avenida do Contorno Urbano Assis Claudino, em Monsenhor Tabosa); Lei nº 19.338 (EEMTI José Pedrosa Júnior, em Nova Russas); e Lei nº 19.339 (denomina José Josimar de Sousa a rodovia CE-265 entre Morada Nova e o distrito de Dourado).","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-06-0853","y":2025,"m":6,"d":"24","h":"Morre em Fortaleza, aos 60 anos de idade, a engenheira civil e política <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/ex-vereadora-de-fortaleza-nelba-fortaleza-morre-aos-60-anos-1.3663435\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Nelba Aparecida Arrais Maia Fortaleza (Nelba Fortaleza)</a>. Exerceu dois mandatos consecutivos como vereadora de Fortaleza (eleita em 2000 e reeleita em 2004 com 15.562 votos) e atuou como secretária executiva regional na Capital, sendo sepultada no Cemitério Jardim Metropolitano, no Eusébio (<a href=\"https://divulgacandcontas.tse.jus.br/divulga/#/candidato/NORDESTE/CE/14422/8191/2008/13897\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">TSE</a>). Nascera em Limoeiro do Norte, CE, a 03 de agosto de 1964.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2025-06-0854","y":2025,"m":6,"d":"27","h":"O governador Elmano de Freitas vistoria em Crateús as obras de implantação do <a href=\"https://www.ce.gov.br/2025/06/27/governador-elmano-de-freitas-visita-obras-do-hospital-regional-de-crateus/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hospital Regional dos Sertões de Crateús</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-06-0855","y":2025,"m":6,"d":"30","h":"O Governo do Ceará assina em Varjota a ordem de serviço para a restauração de 39 km da <a href=\"https://www.ce.gov.br/2025/06/28/governo-do-ceara-autoriza-inicio-da-restauracao-da-ce-366-entre-varjota-e-santa-quiteria/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">rodovia CE-366</a>, entre Varjota e Santa Quitéria.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-07-0856","y":2025,"m":7,"d":"03","h":"Morre em Fortaleza, aos 97 anos de idade, o engenheiro civil, professor universitário e político <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/morre-jose-walter-cavalcante-ex-prefeito-de-fortaleza-1.3666779\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">José Walter Cavalcante</a>. Docente da Escola de Engenharia da Universidade Federal do Ceará (UFC) e ex-diretor da Rede de Viação Cearense (Estrada de Ferro de Baturité), exerceu o cargo de prefeito municipal de Fortaleza entre 1967 e 1971, gestão na qual concluiu o Ginásio Paulo Sarasate, implantou a Avenida José Bastos e construiu o Núcleo Habitacional Integrado do Mondubim, que deu origem ao bairro Prefeito José Walter (<a href=\"https://g1.globo.com/ce/ceara/noticia/2025/07/04/morre-jose-walter-cavalcante-ex-prefeito-de-fortaleza.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">G1 Ceará</a>). Nascera em Capistrano, CE, a 17 de julho de 1927.","c":["Necrologia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-07-0857","y":2025,"m":7,"d":"04","h":"São sancionadas seis <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 08/07/2025): Lei nº 19.349 (CCI Renner Emerson Braga Souza, em Paracuru); Lei nº 19.355 (EEMTI Vereador Francisco Airton Maia, no distrito de Ideal, Aracoiaba); Lei nº 19.356 (CEI Sávia Silvana Florindo, em Acaraú); Lei nº 19.357 (Escola de Ensino Médio Vereador Cesar Araújo Veras, em Camocim); Lei nº 19.365 (Anel Viário Prefeito José Firmino de Arruda, entre a CE-187 e a CE-232); e Lei nº 19.366 (Areninha Francisco Anjo de Souza, em Crateús).","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-07-0858","y":2025,"m":7,"d":"09","h":"Pelas quartas de final da Copa do Nordeste de 2025, o Ceará Sporting Club empata em 0 a 0 com o Sport Club do Recife na Ilha do Retiro e vence nos pênaltis por 4 a 2, avançando às <a href=\"https://www.cbf.com.br/futebol-brasileiro/noticias/detalhes/competicoes-campeonato-brasileiro-serie-b/confira-as-semifinais-da-copa-do-nordeste-2025\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">semifinais do torneio regional</a>, enquanto o Fortaleza Esporte Clube encerra sua participação diante do Bahia na Arena Fonte Nova (<a href=\"https://fortaleza1918.com.br/bahia-2x1-fortaleza-leao-deixa-a-copa-do-nordeste-nas-quartas-de-final/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Fortaleza 1918</a>).","c":["Esportes"],"l":1},{"id":"ce-2025-07-0859","y":2025,"m":7,"d":"14","h":"A Assembleia Legislativa do Estado do Ceará (ALECE), por meio do Centro Inclusivo para Atendimento e Desenvolvimento Infantil (Ciadi), inaugura <a href=\"https://www.al.ce.gov.br/noticias/50174-ciadi-inaugura-sala-sensorial-no-municipio-do-crato-e-promove-ampliacao-do-servico\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">sala sensorial no município do Crato</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-07-0860","y":2025,"m":7,"d":"18","h":"Realizam-se simultaneamente o festival <a href=\"https://diariodonordeste.verdesmares.com.br/ceara/sana-2025-parte-2-comeca-nesta-sexta-18-e-publico-ainda-pode-garantir-ingressos-1.3671171\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Sana 2025 – Parte 2</a> no Centro de Eventos do Ceará, em Fortaleza, e a <a href=\"https://www.ce.gov.br/2025/07/30/expocrato-2025-gera-mais-de-r-291-milhoes-em-receita-e-atrai-140-mil-visitantes-aponta-pesquisa-da-setur/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Expocrato 2025</a> no Parque de Exposições Pedro Felício Cavalcanti, no Crato.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-07-0861","y":2025,"m":7,"d":"25","h":"O governador Elmano de Freitas inaugura no município de Barro a <a href=\"https://www.policiacivil.ce.gov.br/2025/07/25/em-barro-populacao-recebe-nova-delegacia-e-centro-de-educacao-infantil/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">nova Delegacia Municipal da Polícia Civil e um Centro de Educação Infantil (CEI)</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-08-0862","y":2025,"m":8,"d":"04","h":"A Secretaria da Saúde do Estado do Ceará (Sesa) inaugura em Fortaleza o <a href=\"https://www.ce.gov.br/saude/2025/08/04/sesa-inaugura-centro-de-estudos-em-vigilancia-em-saude-do-ceara-maria-zelia-rouquayrol/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Centro de Estudos em Vigilância em Saúde do Ceará Maria Zélia Rouquayrol</a>.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-08-0863","y":2025,"m":8,"d":"12","h":"Na Arena Castelão, em Fortaleza, o Fortaleza Esporte Clube empata em 0 a 0 com o Club Atlético Vélez Sarsfield, da Argentina, na partida de ida das oitavas de final da <a href=\"https://www.capitalnews.com.br/esporte/fortaleza-frustra-torcida-e-empata-com-velez-nas-oitavas-da-libertadores/426408\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa Libertadores da América de 2025</a> (encerrando sua participação no jogo de volta em Buenos Aires em <a href=\"https://www.cnnbrasil.com.br/esportes/futebol/futebol-internacional/libertadores-da-america/fortaleza-e-derrotado-pelo-velez-e-da-adeus-a-libertadores/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">19 de agosto</a>).","c":["Esportes"],"l":1},{"id":"ce-2025-08-0864","y":2025,"m":8,"d":"17","h":"O Crateús Esporte Clube sagra-se tricampeão do <a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=18124\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense da Série C de 2025</a> ao vencer o Guarany Sporting Club (de Sobral) na decisão do certame, garantindo o acesso de ambas as equipes à Série B estadual de 2026.","c":["Esportes"],"l":1},{"id":"ce-2025-08-0865","y":2025,"m":8,"d":"19","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.394 e nº 19.395</a> (DOE de 20/08/2025), que denominam, respectivamente: Francisco Ferreira Gomes o trecho da rodovia CE-176 que interliga a BR-222 à CE-362 no distrito de Olho d'Água do Pajé, em Sobral; e Maria da Conceição Machado Lima (Tia Machadinha) o CEI localizado no município de Crateús.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-08-0866","y":2025,"m":8,"d":"20","h":"Na Arena Fonte Nova, em Salvador, o Ceará Sporting Club é superado pelo Bahia por 1 a 0 na semifinal da <a href=\"https://jornalgrandebahia.com.br/2025/08/bahia-vence-o-ceara-por-1x0-e-garante-vaga-na-final-inedita-da-copa-do-nordeste-contra-o-confianca/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Copa do Nordeste de 2025</a>.","c":["Esportes"],"l":1},{"id":"ce-2025-08-0867","y":2025,"m":8,"d":"21","h":"São sancionadas as <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Leis Estaduais nº 19.404, nº 19.405 e nº 19.407</a> (DOE de 25/08/2025), que denominam Lindomar de Melo Borges a Areninha no Assentamento Vida Nova/Aragão, em Miraíma; Professora Maria Risalva Paixão Freitas o CEI no Centro de Itapiúna; e declaram o compositor e regente Alberto Nepomuceno Patrono da Música Erudita Cearense.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-09-0868","y":2025,"m":9,"d":"05","h":"São sancionadas oito <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 05 e 09/09/2025): Lei nº 19.412 (EEMTI Antonio Silva Matos no distrito do Retiro, Tejuçuoca); Lei nº 19.416 (CEI Valéria Pontes Oliveira em Massapê); Lei nº 19.417 (EEMTI Maria Consuêlo de Oliveira em Quixeramobim); Lei nº 19.418 (Escola de Ensino Médio Raimunda Santeza Nunes em Tianguá); Lei nº 19.424 (denomina José Ilo Alves Dantas o Hospital Regional do Centro-Sul, em Iguatu); Lei nº 19.428 (Cinema Público Mestre Lucas Evangelista em Crateús); Lei nº 19.429 (Areninha Flávio da Silva André – Duda, em Canindé); e Lei nº 19.430 (Areninha Antonio Juscelio Bonfim em Curral Velho, Crateús).","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-09-0869","y":2025,"m":9,"d":"09","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.326</a>, que denomina Seu Milton a Areninha do Campo do Fortalezinha, no bairro Planalto Ayrton Senna.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2025-09-0870","y":2025,"m":9,"d":"12","h":"O governador Elmano de Freitas e o prefeito Jardel Sousa inauguram no Alto do Moinho, em Canindé, a primeira etapa das obras de requalificação do <a href=\"https://www.caninde.ce.gov.br/informa/1503/aviso-de-pauta-inaugura-o-da-primeira-etapa-do-com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Complexo da Estátua de São Francisco das Chagas</a>. Na mesma data, são sancionadas cinco <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 17/09/2025), destacando-se a Lei nº 19.447, que denomina Hospital Regional Dom Antônio Batista Fragoso o Hospital Regional localizado no município de Crateús, além das Leis nº 19.439, 19.445, 19.446 e 19.448.","c":["Legislação e Toponímia","Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-09-0871","y":2025,"m":9,"d":"15","h":"Encerra-se em Juazeiro do Norte a tradicional <a href=\"https://www.youtube.com/watch?v=iss4E1TyjBM\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Romaria de Nossa Senhora das Dores</a>, padroeira da Basílica Santuário, reunindo milhares de romeiros de todo o Nordeste.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-09-0872","y":2025,"m":9,"d":"18","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 19.456</a> (DOE de 19/09/2025), que denomina Joaquim Ferreira de Araújo Júnior a EEMTI localizada no município de Santa Quitéria.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2025-09-0873","y":2025,"m":9,"d":"20","h":"Tem início no Cineteatro São Luiz e no Cinema do Dragão, em Fortaleza, o <a href=\"https://www.ce.gov.br/secult/2025/08/26/com-apoio-da-secult-35o-cine-ceara-anuncia-filmes-selecionados-para-a-mostra-olhar-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">35º Cine Ceará – Festival Ibero-americano de Cinema</a>, realizado até 26 de setembro.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-09-0874","y":2025,"m":9,"d":"23 e 24","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/14241\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.331</a> (DOM nº 18.165, de 03/10/2025), denominando Rua Maria Almeida de Lima logradouro no bairro Jacarecanga, e o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.333</a>, denominando Dr. Sávio Caldas Alencar o Centro de Diagnóstico Girassol, no bairro Edson Queiroz.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2025-09-0875","y":2025,"m":9,"d":"26","h":"Em solenidade realizada no Salão Nobre Edson Queiroz do Ideal Clube, em Fortaleza, o Grupo Edson Queiroz realiza a entrega da <a href=\"https://diariodonordeste.verdesmares.com.br/verso/trofeu-sereia-de-ouro-homenageia-quatro-personalidades-em-solenidade-no-ideal-clube-1.3693635\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">52ª edição do Troféu Sereia de Ouro</a> à médica endocrinologista e pesquisadora Adriana Costa e Forti, à artista plástica e tapeceira Guiomar Marinho, ao empresário e educador Oto de Sá Cavalcante e ao empresário, ex-governador e ex-senador Tasso Ribeiro Jereissati (<a href=\"https://www.idealclube.com.br/post/ideal-volta-a-ser-palco-do-trof%C3%A9u-sereia-de-ouro\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Ideal Clube</a>).","c":["Esportes","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-09-0876","y":2025,"m":9,"d":"27","h":"Morre em Fortaleza, aos 46 anos de idade, vítima de parada cardíaca decorrente de infecção pulmonar fúngica, o ex-futebolista profissional <a href=\"https://g1.globo.com/ce/ceara/noticia/2025/09/28/ex-jogador-do-fortaleza-rabico-morre-aos-46-anos-apos-infeccao-pulmonar.ghtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Francisco Adailton Andrade de Farias (Rabicó)</a>, volante que se destacou pelo Fortaleza Esporte Clube (campeão cearense de 2005) e pelo Ceará Sporting Club, sendo sepultado no Cemitério Parque da Saudade, em Caucaia (<a href=\"https://www.ogol.com.br/jogador/rabico/150757\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">OGol</a>). Nascera em Quixadá, CE, a 05 de outubro de 1978.","c":["Necrologia","Esportes"],"l":1},{"id":"ce-2025-10-0877","y":2025,"m":10,"d":"01","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.336</a>, denominando \"Terminal Santuário da Fé\" o terminal aberto de ônibus localizado na Praça José de Alencar, no Centro.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2025-10-0878","y":2025,"m":10,"d":"03","h":"O Governo do Ceará inaugura a nova sede da <a href=\"https://www.ce.gov.br/2025/10/03/governo-do-ceara-entrega-nova-sede-da-escola-raimundo-gomes-de-carvalho-no-autran-nunes-em-fortaleza/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Escola de Ensino Médio Raimundo Gomes de Carvalho</a>, no bairro Autran Nunes, em Fortaleza. Na mesma data, a Câmara Municipal de Fortaleza entrega em sessão solene a <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-de-fortaleza-entrega-medalhas-boticario-ferreira-e-merito-juridico-municipal-em-sessao-solene-nesta-sexta\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha Boticário Ferreira ao empresário Francisco Ivens de Sá Dias Branco Júnior</a> e a Medalha do Mérito Jurídico Municipal José de Albuquerque Rocha ao juiz Manuel Clístenes de Façanha e Gonçalves.","c":["Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-10-0879","y":2025,"m":10,"d":"04","h":"Com a tradicional procissão de São Francisco pelas ruas da cidade, encerra-se em Canindé a <a href=\"https://santuariodecaninde.com/noticias-acontece/procissao-de-sao-francisco-encerra-a-festa-2025-e-nova-data-para-o-proximo-ano-e-anunciada/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Festa e Romaria de São Francisco das Chagas de 2025</a>, celebrando os 250 anos da chegada da imagem do padroeiro ao Santuário.","c":["Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-10-0880","y":2025,"m":10,"d":"06","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 19.466</a> (DOE de 07/10/2025), que reconhece oficialmente a cidade de Canindé como a \"Terra da Fé\" no Estado do Ceará, e a Lei Estadual nº 19.470, que denomina Gilberto Quirino de Sousa a Areninha no distrito de Várzea Nova, em Antonina do Norte.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2025-10-0881","y":2025,"m":10,"d":"17","h":"São sancionadas a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 19.488</a> (DOE de 20/10/2025), que denomina Francisco Marques de Araújo a Areninha localizada em Mombaça, e a Lei Estadual nº 19.493, que reconhece oficialmente o município de Juazeiro do Norte como a \"Capital da Fé\" do Estado do Ceará.","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2025-10-0882","y":2025,"m":10,"d":"21 e 22","h":"A Câmara Municipal de Fortaleza promulga os <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos nº 1.340, 1.343, 1.344 e 1.345, oficializando a denominação da Rua Ariano Suassuna e da Rua Patativa do Assaré (no Conjunto Palmeiras), da Avenida Padre Teodoro (no bairro Prefeito José Walter) e da Praça Nossa Senhora de Fátima do Vila Velha.</a><br><a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">23 — O prefeito Ricardo Silveira e a secretária estadual da Saúde Tânia Mara Coelho inauguram a nova ala cirúrgica e enfermarias d</a>o <a href=\"https://www.quixada.ce.gov.br/informa/894\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Hospital Municipal Eudásio Barroso, em Quixadá</a>.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-10-0883","y":2025,"m":10,"d":"29 e 30","h":"A Câmara Municipal de Fortaleza promulga os Decretos Legislativos nº 1.346, 1.347 e 1.348, denominando Raimundo Feitosa de Carvalho o CAPS Infantil no bairro Edson Queiroz, Professor Otacílio de Sá Pereira Bessa o CEI na Parangaba e CRAS Papa Francisco o equipamento socioassistencial no bairro Vila Velha.","c":["Política e Instituições"],"l":0},{"id":"ce-2025-11-0884","y":2025,"m":11,"d":"03","h":"O Governo do Ceará entrega <a href=\"https://www.ce.gov.br/2025/11/03/com-investimento-superior-a-r-115-milhoes-ceara-ganha-residencial-beneficiando-mais-de-2-mil-pessoas/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">empreendimento habitacional</a> beneficiando mais de 2 mil moradores na Capital.","c":["Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-11-0885","y":2025,"m":11,"d":"05","h":"São sancionadas quatro <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 06/11/2025): Lei nº 19.507 (Areninha Gerardo Tabosa Fernandes no distrito de Juá, Irauçuba); Lei nº 19.515 (EEMTI Professora Maria Ângela Fontenele em Camocim); Lei nº 19.522 (denomina Antônio Ademar Cidade a rodovia CE-588, Estrada do Pontal, em Santana do Cariri); e Lei nº 19.523 (EEMTI Padre Francisco de Assis Pitombeira, em Limoeiro do Norte). Na mesma data, são titulados <a href=\"https://especial.opovo.com.br/culturaemmovimento/noticias/patrimonio-imaterial-o-que-sao-e-o-fazem-os-mestres-da-cultura-do-ceara/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">12 novos Mestres da Cultura como Patrimônio Cultural Imaterial do Ceará</a>.","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-11-0886","y":2025,"m":11,"d":"06","h":"O prefeito Evandro Leitão inaugura o <a href=\"https://www.fortaleza.ce.gov.br/noticias/prefeito-evandro-leitao-inaugura-cei-no-autran-nunes-e-quadra-poliesportiva-no-conjunto-ceara\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">CEI Luizie Torquato Costa, no bairro Autran Nunes, e quadra poliesportiva no Conjunto Ceará</a>. Na mesma data, a Câmara Municipal de Fortaleza promulga os <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decretos Legislativos nº 1.349, 1.350 e 1.351</a>, denominando Maria Ivanolda Silva de Abreu o CEI no Parque São José, Rua Zolyde Mota Ribeiro no Itaperi e Fátima Maria Quezado Fernandes o Posto de Saúde na Praia do Futuro.","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-11-0887","y":2025,"m":11,"d":"15","h":"Morre em Fortaleza, aos 70 anos de idade, vítima de complicações de um Acidente Vascular Cerebral (AVC), o servidor público e político <a href=\"https://diariodonordeste.verdesmares.com.br/pontopoder/morre-aos-70-anos-ex-deputado-augustinho-moreira-1.3710088\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Antônio Augusto Moreira e Silva (Augustinho Moreira)</a>. Filho do ex-vereador Agostinho Moreira e irmão da ex-deputada Leda Moreira, exerceu múltiplos mandatos como vereador de Fortaleza e foi deputado estadual na Assembleia Legislativa do Estado do Ceará (ALECE). O corpo foi velado no Plenário 13 de Maio da ALECE e sepultado no Cemitério Jardim Metropolitano, no Eusébio (<a href=\"https://www1.folha.uol.com.br/poder/eleicoes/candidatos/2024/ce/vereador/augustinho-moreira-60002134617.shtml\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Acervo TSE</a>). Nascera em Fortaleza, CE, a 24 de março de 1955.","c":["Necrologia","Política e Instituições"],"l":1},{"id":"ce-2025-11-0888","y":2025,"m":11,"d":"18","h":"São sancionadas três <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais</a> (DOE de 18/11/2025): Lei nº 19.534 (denomina Francisco Maurício Sobrinho a ponte na CE-358 entre Limoeiro do Norte e Tabuleiro do Norte); Lei nº 19.539 (denomina Gerardo Lucena de Oliveira o trecho da CE-360 em Limoeiro do Norte); e Lei nº 19.545 (reconhece Nossa Senhora de Fátima como Padroeira da Região Metropolitana do Cariri).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2025-11-0889","y":2025,"m":11,"d":"19","h":"A Câmara Municipal de Fortaleza outorga a <a href=\"https://www.cmfor.ce.gov.br/comunicacao/noticias/camara-entrega-medalha-boticario-ferreira-ao-advogada-saulo-goncalves\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Medalha Boticário Ferreira ao advogado e procurador municipal Saulo Gonçalves Santos</a>.","c":["Política e Instituições"],"l":1},{"id":"ce-2025-11-0890","y":2025,"m":11,"d":"25","h":"No Estádio Presidente Vargas (PV), em Fortaleza, o Fortaleza Esporte Clube conquista o seu 4º título do <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/nos-penaltis-fortaleza-e-campeao-cearense-feminino-diante-do-ceara-1.3712956\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Campeonato Cearense de Futebol Feminino</a> ao derrotar o Ceará Sporting Club nos pênaltis por 4 a 3, após dois empates por 0 a 0 nas partidas de ida e volta.","c":["Esportes"],"l":1},{"id":"ce-2025-11-0891","y":2025,"m":11,"d":"27","h":"É sancionada a <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Lei Estadual nº 19.557</a> (DOE de 27/11/2025), que cria a Creche Escola do Poder Judiciário – Felisbela Benvinda Guimarães (CEPJ).","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-12-0892","y":2025,"m":12,"d":"04","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/14314\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.352</a> (DOM nº 18.213, de 12/12/2025), que denomina Avenida Professora Zélia Pinheiro Alam logradouro público situado entre os bairros Mondubim e Prefeito José Walter.","c":["Legislação e Toponímia","Política e Instituições"],"l":1},{"id":"ce-2025-12-0893","y":2025,"m":12,"d":"05","h":"No Estádio Municipal Almir Dutra, em Maracanaú, o Maracanã Esporte Clube conquista de forma inédita a <a href=\"https://diariodonordeste.verdesmares.com.br/jogada/com-gol-no-fim-maracana-vence-tirol-e-conquista-a-taca-fares-lopes-2025-1.3716182\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Taça Fares Lopes de 2025</a> (16ª edição) ao vencer na final única o Centro de Formação de Atletas do Tirol por 2 a 1 (gols de Jaílson e Everton Heleno para o Maracanã; Janeudo descontou para o Tirol), assegurando vaga na Copa do Brasil de 2026 (<a href=\"https://www.futebolcearense.com.br/2023/noticia.asp?id=18481\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Federação Cearense de Futebol</a>).","c":["Esportes"],"l":1},{"id":"ce-2025-12-0894","y":2025,"m":12,"d":"07","h":"Pela 38ª e última rodada do Campeonato Brasileiro da Série A de 2025, os resultados de Ceará Sporting Club (superado pelo Palmeiras por 3 a 1 na Arena Castelão) e Fortaleza Esporte Clube (superado pelo Botafogo por 4 a 2 no Rio de Janeiro) determinam o descenso simultâneo de ambas as agremiações cearenses (17º e 18º colocados, com 43 pontos) para a Série B nacional de 2026 (<a href=\"https://agenciabrasil.ebc.com.br/esportes/noticia/2025-12/fortaleza-e-ceara-sao-rebaixados-na-ultima-rodada-do-brasileirao-2025\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Agência Brasil</a>, <a href=\"https://www.cbf.com.br/futebol-brasileiro/tabelas/campeonato-brasileiro/serie-a/2025\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">CBF</a>).","c":["Esportes"],"l":1},{"id":"ce-2025-12-0895","y":2025,"m":12,"d":"08","h":"São sancionadas sete <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia e reconhecimento municipal</a> (DOE de 09/12/2025): Lei nº 19.561 (Areninha José Euton Rodrigues em Hidrolândia); Lei nº 19.562 (sede do BPRAIO Tenente José Hertz Viana em Caririaçu); Lei nº 19.563 (CETRAS Francisco Teles de Lima no Crato); Lei nº 19.565 (CEI Maria Araújo Sampaio Vidal – Baía, em Porteiras); Lei nº 19.568 (Escola em Tempo Integral Professora Tânia Maria Sampaio de Almeida em Russas); Lei nº 19.570 (CEI Professora Geny Eiry Diniz Nogueira em Milhã); e Lei nº 19.572, que reconhece oficialmente o município de Iguatu como a \"Capital Regional do Centro-Sul\" do Estado do Ceará.","c":["Legislação e Toponímia","Cultura, Educação e Religião"],"l":1},{"id":"ce-2025-12-0896","y":2025,"m":12,"d":"11 e 12","h":"A Câmara Municipal de Fortaleza promulga o <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Decreto Legislativo nº 1.354</a>, oficializando a Rua Dina Sfat no bairro Lagoa Redonda, e o governador Elmano de Freitas inaugura no Eusébio a <a href=\"https://www.ce.gov.br/2025/12/13/com-investimento-de-r-53-milhoes-eusebio-inaugura-escola-em-tempo-integral/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Escola de Ensino Fundamental em Tempo Integral Lucimar Gomes da Silva</a>.","c":["Legislação e Toponímia","Política e Instituições","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-12-0897","y":2025,"m":12,"d":"15","h":"São sancionadas quatro <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 16/12/2025): Lei nº 19.589 (CRAS Rosa Vieira Oliveira – Tia Rosa, em Caririaçu); Lei nº 19.590 (CEI Maria Zenilda Gonçalves Pinheiro em Brejo Santo); Lei nº 19.592 (Escola Estadual José de Anchieta e Silva em Pentecoste); e Lei nº 19.593 (denomina Comandante Maurocélio Rocha Pontes a rodovia CE-325 entre a BR-222 e o distrito de Jaibaras, em Sobral).","c":["Legislação e Toponímia","Cultura, Educação e Religião","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-12-0898","y":2025,"m":12,"d":"16 a 18","h":"A Câmara Municipal de Fortaleza promulga a <a href=\"https://sapl.fortaleza.ce.leg.br/norma/pesquisar?assuntos=35\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">Resolução nº 1.690</a> (denominando Espaço de Convivência Vereador Augustinho Moreira na sede do Legislativo) e os Decretos Legislativos nº 1.356 (Praça Neylson Gonçalves Dantas no Parque Del Sol), <a href=\"https://sapl.fortaleza.ce.leg.br/norma/14325\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">nº 1.358</a> (Praça Raimunda Targino Chaves na Sapiranga), nº 1.359 (Praça José Arnon Silva na Sapiranga), nº 1.361 (Rua João Gonçalves Primo na Vila União) e nº 1.366 (Praça 8 de Março no Mondubim).","c":["Política e Instituições"],"l":1},{"id":"ce-2025-12-0899","y":2025,"m":12,"d":"19","h":"São sancionadas dez <a href=\"https://www2.al.ce.gov.br/legislativo/legislacao5/leis2025/LEIS2025.htm\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">leis estaduais de toponímia</a> (DOE de 24/12/2025): Lei nº 19.616 (CEI Maria Amélia Martins Torres em Hidrolândia); Lei nº 19.620 (Areninha Massilon Rodrigues de Mesquita em Santa Quitéria); Lei nº 19.621 (EEMTI Isaías Gonçalves Damasceno em São Benedito); Lei nº 19.623 (Areninha Zaqueu da Silva Carvalho no Assentamento 25 de Maio, Madalena); Lei nº 19.624 (CEI Helena Arrais de Alencar em Antonina do Norte); Lei nº 19.625 (EEMTI Enéas Olímpio da Silva em Iracema); Lei nº 19.627 (CEI Luiz Gonçalves de Lima em Pereiro); Lei nº 19.628 (denomina Elimilton Barreto Nogueira dos Santos – Júnior Barreto o Trecho VI do Contorno do Anel Viário de Juazeiro do Norte); Lei nº 19.629 (sede da Defensoria Pública José Jean Pereira de Alencar em São Gonçalo do Amarante); e Lei nº 19.630 (CEI Francisca Pinheiro Chaves em Tabuleiro do Norte).","c":["Legislação e Toponímia"],"l":1},{"id":"ce-2025-12-0900","y":2025,"m":12,"d":"22","h":"O prefeito Evandro Leitão inaugura na Policlínica Dr. Luiz Carlos Fontenele, no bairro Passaré, o <a href=\"https://www.fortaleza.ce.gov.br/noticias/fortaleza-inclusiva-prefeito-evandro-leitao-inaugura-segundo-espaco-girassol-de-fortaleza-com-capacidade-de-7-mil-atendimentos-por-mes\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">segundo Espaço Girassol de Fortaleza</a>, voltado ao atendimento multiprofissional de crianças e adolescentes com Transtorno do Espectro Autista (TEA).","c":["Política e Instituições","Infraestrutura, Saúde e Sociedade"],"l":1},{"id":"ce-2025-12-0901","y":2025,"m":12,"d":"30","h":"O governador Elmano de Freitas realiza a entrega de <a href=\"https://www.ce.gov.br/2025/12/30/governo-do-ceara-entrega-82-fuzis-e-15-drones-a-policia-militar/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ef-link\">82 fuzis e 15 drones com tecnologia termográfica à Polícia Militar do Ceará (PMCE)</a>, encerrando o calendário administrativo de 2025.","c":["Política e Instituições"],"l":1}]};
